local P = LoreForeverPacks.Begin("LoreForever_Voice_Default_MoreQuests3")
P.transportVersion = 1
P.transport = {}
P.transport["quest:10"] = {
  hash = "1e76b2",
  fullHash = "1e76b2",
  text = "The Scrimshank Redemption. In Gadgetzan, Fizzledowser seeks news of his missing assistant, Junior Surveyor Scrimshank. Scrimshank went into the Gaping Chasm, southeast of town. Now Fizzledowser asks you to find Scrimshank or the surveying equipment. Senior Surveyor Fizzledowser has heard nothing from Junior Surveyor Scrimshank since he went into the Gaping Chasm. The last report from there spoke of more weird bugs. Fizzledowser wonders whether the bugs now hold two great regions of the desert.\n\nHe asks you to search for Scrimshank or, if Scrimshank is gone, the surveying equipment. Fizzledowser fears it may be all that remains.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_10-2a4e002c652a208f8c13/1-0000.mp3", duration = 36.884898, start = 0},
  },
}
P.transport["quest:1012"] = {
  hash = "9c30fc",
  fullHash = "9c30fc",
  text = "Insane Druids. In eastern Ashenvale, Kayneth Stillwind learns of a slaughter through a vision. The night elf sentinel is battling Forsaken toxins when the spirits of Dor'Danil Barrow Den's druids cry out in torment. While fighting the effects of Forsaken toxins in eastern Ashenvale, Kayneth Stillwind sees a massacre in a waking vision. Beneath the mounds of Dor'Danil Barrow Den, undead infiltrators poisoned the druids in their sleep and slaughtered them. The venom tore their souls from their bodies, leaving wild spirits shrieking in torment. Kayneth Stillwind asks you to quiet the suffering beneath Dor'Danil Barrow Den. The druids' phantoms were driven mad by their deaths and cannot find release in the underground chambers. Three leaders of their circle remain among the restless dead: Taneel Darkwood, Uthil Mooncall, and Mavoris Cloudsbreak. Lay them to rest, and the den may begin to heal from its defilement.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1012-c81ae5298bf1defba487/1-0000.mp3", duration = 61.5444898, start = 0},
  },
}
P.transport["quest:1021"] = {
  hash = "93e329",
  fullHash = "93e329",
  text = "Vile Satyr! Dryads in Danger!. In Ashenvale, Illiyana waits for word of her sisters, missing after setting out to recover a stolen relic. She asks passing Alliance travelers to find them in Xavian’s corrupted ruins. Dryad Illiyana waits in Ashenvale, fearing for her sisters. They went into the corrupted northern reaches of the forest to recover the Branch of Cenarius, a holy relic stolen by satyrs. They promised to return swiftly, but two days have passed without word. So Illiyana asks passing Alliance travelers to find them before it is too late.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1021-8f82ac1375fdbd07376b/1-0000.mp3", duration = 40.1502041, start = 0},
  },
}
P.transport["quest:1031"] = {
  hash = "1a4b7d",
  fullHash = "1a4b7d",
  text = "The Branch of Cenarius. In eastern Ashenvale, Anilia's final plea sends you to recover the Branch of Cenarius. Geltharis has taken the sacred relic, and Illiyana awaits its return. Near death, Anilia lies where you search eastern Ashenvale for missing dryads. Cenarius's wounded daughter points north toward the satyr ruins. With her last breaths, she names Geltharis as the one who took the Branch of Cenarius. She begs you to bring it back. Geltharis hides among the ancient elven ruins of Xavian. The satyrs are ancient servants of the Burning Legion. They prize relics tied to Cenarius as trophies, to defile and mock. Taking the branch from Geltharis answers Anilia's plea and helps defend Ashenvale's sacred plants from the corruption these servants spread.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1031-0cfb376b27b314a5b96e/1-0000.mp3", duration = 58.2269388, start = 0},
  },
}
P.transport["quest:1032"] = {
  hash = "69fc39",
  fullHash = "69fc39",
  text = "Satyr Slaying!. At the Shrine of Aessina, Illiyana calls Alliance champions against Ashenvale's satyrs. She grieves for her sister Anilia and asks you to bring back satyr horns as proof. Anilia's death has left Illiyana grieving at the Shrine of Aessina. Dryads are forest spirits bound to nature, often playful and serene, yet elusive to mortals. Anilia's brutal slaying shattered that calm. Now Illiyana calls on Alliance travelers to strike down the demonic beasts responsible. Once night elves, the satyrs were corrupted by demonic energy during the War of the Ancients. They lurk in defiled groves across Ashenvale and prey on the woods' inhabitants as servants of the Burning Legion. Their horns prove vengeance to Illiyana and mark a strike against the fel presence encroaching on eastern Ashenvale.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1032-7a7f3d9ee5ff3a49e147/1-0000.mp3", duration = 54.1518367, start = 0},
  },
}
P.transport["quest:1052"] = {
  hash = "d13edc",
  fullHash = "d13edc",
  text = "Down the Scarlet Path. Brother Anton sends you from Desolace to Southshore with a sealed letter for Raleigh the Devout. Your deeds against the undead are only the beginning; Lordaeron holds the plague's true danger. Brother Anton takes pride in the Scarlet Crusade's strongholds in Lordaeron. The Crusade claims cleansing bastions from Hearthglen to Tirisfal Glades. Your work against the undead in Desolace has proven you, Anton says. Yet the plague's true danger lies in Lordaeron. Brother Anton sends you to Southshore, a town in the Eastern Kingdoms, to find Raleigh the Devout, a crusader. Anton seals a letter with his mark. He says Raleigh will give you an escort to a place of honor within the Scarlet Monastery.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1052-e1694d109bec1734044f/1-0000.mp3", duration = 47.9869388, start = 0},
  },
}
P.transport["quest:110"] = {
  hash = "0898a4",
  fullHash = "0898a4",
  text = "Insect Part Analysis. In Gadgetzan, Fizzledowser needs word on the insect parts sent to Alchemist Pestlezugg. With Scrimshank lost, the Senior Surveyor is sorting his surveying gear and personal effects. Senior Surveyor Fizzledowser is putting Scrimshank's surveying gear and personal effects in order. He fears the bugs will claim more lives, so he sends you to Alchemist Pestlezugg in Gadgetzan. Learn whether Pestlezugg has finished processing the insect parts the surveyors sent. If they are ready, bring them back to Fizzledowser.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_110-0882533c979a13ec9e82/1-0000.mp3", duration = 32.757551, start = 0},
  },
}
P.transport["quest:1106"] = {
  hash = "06fca3",
  fullHash = "06fca3",
  text = "Martek the Exiled. At the Mirage Raceway, Fizzle Brassbolts seeks pistons strong enough for the engine he hopes will carry his car into the air. He sends you with a letter to Martek the Exiled, camped in the Badlands. After Salt Flat Venom, Fizzle tells you his new engine should make his car so fast it could fly. His trials have failed because he cannot forge pistons strong enough for the strain. He knows one smith who may help: Martek the Exiled, who knows more about metal than anyone. Martek camps far away in the Badlands with a goblin, and you carry Fizzle's letter to him.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1106-4b729638d9595515e77d/1-0000.mp3", duration = 35.6310204, start = 0},
  },
}
P.transport["quest:1107"] = {
  hash = "68f372",
  fullHash = "68f372",
  text = "Encrusted Tail Fins. At the Mirage Raceway, Wizzle Brassbolts fears the rocket car’s speed will tear it apart. Saltscale murloc tail fins from the Vile Reef off Stranglethorn Vale may protect it. Wizzle calls the rocket car the fastest thing on the Shimmering Flats. Yet friction may tear it apart. Its moving parts need a coating that is hard without being brittle and can resist salt corrosion. Otherwise, the flats will eat away at the car. The key ingredient is ten tail fins from the Saltscale murlocs at the Vile Reef off Stranglethorn Vale.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1107-fdcabbf66b5d5d875479/1-0000.mp3", duration = 34.5338776, start = 0},
  },
}
P.transport["quest:1108"] = {
  hash = "d22532",
  fullHash = "d22532",
  text = "Indurium. In the Badlands, Martek the Exiled seeks metal samples for Fizzle's car. Indurium is said to endure heat and stress, and Stonevault troggs sometimes carry flakes. Martek the Exiled stays in the Badlands for more than solitude. He thinks indurium might suit Fizzle's car because it is said to endure heat and stress. He wants samples for a test, with the forge ready. True indurium ore lies deep in Uldaman, but Stonevault troggs in the Badlands sometimes carry flakes. Martek asks for ten. The troggs roam the south-east slope of a rocky clump at Agmond's End, just south of the Valley of Fangs.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1108-9f33edebeb21b1671c81/1-0000.mp3", duration = 40.8816327, start = 0},
  },
}
P.transport["quest:1111"] = {
  hash = "51dabd",
  fullHash = "51dabd",
  text = "Wharfmaster Dizzywig. At the Mirage Raceway, Kravel Koalbeard sends you to Ratchet for parts the gnomes are waiting on. Kravel Koalbeard tends to the needs of the Mirage Raceway. A batch of parts reached Ratchet a week ago, and the gnomes are waiting. Since Kravel cannot make the journey himself, he asks you to carry his order. If you do, he promises more work with serious profit potential. Ratchet lies in the Barrens, where Kravel expects Wharfmaster Dizzywig to be at the docks. The goblin is the one you need to see. You carry Kravel's Parts Order there.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1111-aa75d348508e828f965a/1-0000.mp3", duration = 34.6906122, start = 0},
  },
}
P.transport["quest:1112"] = {
  hash = "42259a",
  fullHash = "42259a",
  text = "Parts for Kravel. At the Mirage Raceway, Kravel Koalbeard awaits the package you carry from Wharfmaster Dizzywig. Dizzywig sends a warning with it: Kravel must pay his tab before he can receive more special orders. Wharfmaster Dizzywig gives you a package for Kravel Koalbeard at the Mirage Raceway. The Raceway lies in the Shimmering Flats of Thousand Needles. Dizzywig asks you to carry a warning with the package: Kravel must pay what he owes before he can receive more special orders.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1112-be90d6b9ce363cb799a2/1-0000.mp3", duration = 32.5746939, start = 0},
  },
}
P.transport["quest:1114"] = {
  hash = "a0d40a",
  fullHash = "a0d40a",
  text = "Delivery to the Gnomes. Kravel Koalbeard sends Delicate Car Parts from the Mirage Raceway to Fizzle Brassbolts in the Shimmering Flats. Fizzle has waited a long time for them, and Kravel asks you to keep quiet about one small piece he removed. Kravel Koalbeard sends the parts to Fizzle Brassbolts, who has waited a long time for them. Kravel admits he removed one little piece from Fizzle's order. He says it is small and worthless, and that Fizzle will not miss it. Then he asks you to trust him and leave it unmentioned.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1114-85f68b9f0f617015476e/1-0000.mp3", duration = 31.7910204, start = 0},
  },
}
P.transport["quest:1115"] = {
  hash = "e5c3e1",
  fullHash = "e5c3e1",
  text = "The Rumormonger. At the Mirage Raceway, Kravel Koalbeard now has a question about Nazz Steamboil. The goblin racer pilot once used another name, and Kravel wonders whether the secret could bring profit. He sends you to Krazek in Booty Bay, who may know. Kravel Koalbeard says the goblins are next in line for a favor. He has heard that Nazz Steamboil, the goblin racer pilot, once used another name. Why did it change? Might Nazz be keeping a secret? Kravel believes Krazek knows the truth. You can find Krazek at the Salty Sailor Tavern in Booty Bay, at Stranglethorn's southern tip. Useful information might turn a profit.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1115-74d311ef146f2727764b/1-0000.mp3", duration = 40.3069388, start = 0},
  },
}
P.transport["quest:1116"] = {
  hash = "53b276",
  fullHash = "53b276",
  text = "Dream Dust in the Swamp. In the Swamp of Sorrows, Krazek asks you to gather ten specks of dream dust from dragon whelps. He contacts sources about Nazz while seeking dust for his snuff pouch. Bring it back to him for the information you seek. Krazek says that learning about Nazz is a considerable favor, and you have traveled a long way from the Shimmering Flats to ask. While he contacts sources, he asks you to gather ten specks of dream dust from dragon whelps in the Swamp of Sorrows. The dust is for his snuff pouch. Bring it back, and Krazek will give you the information you seek. Green dragons in the Swamp of Sorrows carry dream dust. Adolescent whelps and dreaming whelps can be found in the swamp’s south-western corner.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1116-66c9c400140066c14ed0/1-0000.mp3", duration = 45.0873469, start = 0},
  },
}
P.transport["quest:1117"] = {
  hash = "88d885",
  fullHash = "88d885",
  text = "Rumors for Kravel. At last, Krazek has a letter about Nazz Steamboil for you to carry to Kravel Koalbeard at the Mirage Raceway on the Shimmering Flats. Keep its origin secret. Krazek spent favors, a rare bottle of elven wine, and hours of deducing to learn about Nazz Steamboil. His letter holds very interesting bits about the goblin racer pilot. Krazek considers the letter too dangerous to use and leaves it to you, provided nobody learns where it came from. Carry it to Kravel Koalbeard on the Shimmering Flats.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1117-f56953fe31968e157245/1-0000.mp3", duration = 35.604898, start = 0},
  },
}
P.transport["quest:1118"] = {
  hash = "a2ac70",
  fullHash = "a2ac70",
  text = "Back to Booty Bay. At the Mirage Raceway, Kravel Koalbeard sends you back to Booty Bay with a letter and asks you to keep his scheme quiet. It is risky, but success could bring you both a bundle. This follows Rumors for Kravel. At the Mirage Raceway, Kravel Koalbeard trusts you to finish a job and keep silent. His new scheme is risky, but success could bring you both a bundle. He sends you back to Booty Bay, where his last job took you, to find Crank Fizzlebub and deliver a letter. If Crank needs help, do your best. Kravel says the effort will be worth it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1118-19b9d9af1c2626c5d64b/1-0000.mp3", duration = 42.3706122, start = 0},
  },
}
P.transport["quest:1119"] = {
  hash = "cb3193",
  fullHash = "cb3193",
  text = "Zanzil's Mixture and a Fool's Stout. At the Mirage Raceway, Kravel Koalbeard awaits a stout blended with Zanzil's Mixture. Crank Fizzlebub calls it Fool's Stout and believes Kravel needs it, so you carry it to him on the Shimmering Flats before it spoils. Crank Fizzlebub has blended Zanzil's Mixture into stout, making a potent drink he calls Fool's Stout. He believes Kravel needs it and wants to hear how it works. So you carry the drink to Kravel Koalbeard at the Mirage Raceway on the Shimmering Flats. Crank warns you not to keep the stout long. The mixture drives the yeast into high gear, and the drink will not stay fresh forever.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1119-5bba569cfe1620775ec4/1-0000.mp3", duration = 39.157551, start = 0},
  },
}
P.transport["quest:1120"] = {
  hash = "6d6a32",
  fullHash = "6d6a32",
  text = "Get the Gnomes Drunk. At the Mirage Raceway, Get the Gnomes Drunk begins with a test of Fool's Stout on a pit crew. Kravel Koalbeard gives you the stout for the Gnome Pit Boss nearby and warns that it will go bad eventually. Kravel Koalbeard asks you to test Fool's Stout on one of the pit crews. Choose the gnomes, and he gives you the stout for the Gnome Pit Boss nearby at the Mirage Raceway. That choice tips the races toward the goblins. Kravel warns you not to wait too long, since the stout will go bad eventually.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1120-13270e912d198cd4dbad/1-0000.mp3", duration = 30.955102, start = 0},
  },
}
P.transport["quest:1121"] = {
  hash = "837967",
  fullHash = "837967",
  text = "Get the Goblins Drunk. At the Mirage Raceway, Kravel Koalbeard asks you to test Fool's Stout on a pit crew. Choose the goblins and carry the stout to the nearby Goblin Pit Boss before it goes bad. Kravel Koalbeard gives you Fool's Stout to test on one of the pit crews. If you choose the goblins, take it to the nearby Goblin Pit Boss at the Mirage Raceway. That choice tips the races toward the gnomes. The stout will go bad eventually, so Kravel warns you not to dawdle.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1121-fe0e9cf659303f1f5e1f/1-0000.mp3", duration = 29.675102, start = 0},
  },
}
P.transport["quest:1122"] = {
  hash = "d7929c",
  fullHash = "d7929c",
  text = "Report Back to Fizzlebub. Kravel Koalbeard reports that the Fool's Stout worked and sends you to Booty Bay with news for Crank Fizzlebub. He has bet on the next race and hopes the pit crew you made drunk wrecked their own car. This follows your choice to make one pit crew drunk. Kravel Koalbeard says the Fool's Stout worked well. He's bet on the next race and hopes the pit crew you made drunk wrecked their own car. Take his note about the successful test to Crank Fizzlebub in Booty Bay. Crank will want the news, and Kravel hopes to get more stout for future races.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1122-571daa43a7593dffafa2/1-0000.mp3", duration = 37.1461224, start = 0},
  },
}
P.transport["quest:1127"] = {
  hash = "446eaf",
  fullHash = "446eaf",
  text = "Fool's Stout. In Booty Bay, travelers seek more Fool's Stout for the Shimmering Flats raceway. Crank Fizzlebub needs twelve flasks of Zanzil's mixture to brew another batch. Travelers bound for the gnomes at the raceway may find their Fool's Stout has expired before they arrive. In Booty Bay, Crank Fizzlebub can brew a replacement. The goblin needs twelve flasks of Zanzil's mixture, and offers compensation for fetching them, with a little extra for discretion.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1127-12d72e67bfa1ae49df2d/1-0000.mp3", duration = 30.9289796, start = 0},
  },
}
P.transport["quest:113"] = {
  hash = "d3b796",
  fullHash = "d3b796",
  text = "Insect Part Analysis. From Tanaris, Alchemist Pestlezugg sends an urgent warning to Gadgetzan. The danger threatens both places and may spread across southern Kalimdor. Alchemist Pestlezugg asks you to carry the report to Senior Surveyor Fizzledowser in Gadgetzan. The danger threatens Tanaris and Gadgetzan, and may spread across southern Kalimdor. It could reach all of Azeroth, and nothing suggests it will subside. Pestlezugg wants everyone who can read to know.\n\nFizzledowser is to make a duplicate for you, so you can share it freely with your allegiance.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_113-12d0f4056f76226dc8f4/1-0000.mp3", duration = 41.717551, start = 0},
  },
}
P.transport["quest:1137"] = {
  hash = "787b5c",
  fullHash = "787b5c",
  text = "News for Fizzle. In the Badlands, Martek the Exiled has news for Fizzle Brassbolts about indurium. You carry his message to the Mirage Raceway on the Shimmering Flats in Thousand Needles. Martek says indurium withstands heat remarkably well, so it may suit Fizzle's pistons. Flakes will not do; Fizzle needs real indurium ore, dug from deep within Uldaman at the Badlands' northern edge. Martek names Uldaman as indurium's true source. He sends his regards and asks you to repeat all he has told you to Fizzle Brassbolts.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1137-74a042f9883cc3161352/1-0000.mp3", duration = 34.3771429, start = 0},
  },
}
P.transport["quest:1147"] = {
  hash = "9e52f8",
  fullHash = "9e52f8",
  text = "The Swarm Grows. At Ironstone Camp, Moktar Krin says Belgrom wants the silithid driven back underground. His war party is too weakened to fight, so you are sent to the dig site south of camp to face them. Moktar Krin says Belgrom considers the silithid a threat and wants them driven back into the depths they came from. Moktar's war party has already killed the dwarves sent by the Explorers' League, but the fighters are in no state for another battle.\n\nThe dig site lies south of Ironstone Camp, and Moktar expects no more dwarves there. You are to kill the silithid Searchers, hive drones and invaders. Moktar's party cannot leave until the work is done.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1147-7c54de8a02a64a84ec1f/1-0000.mp3", duration = 41.2473469, start = 0},
  },
}
P.transport["quest:1148"] = {
  hash = "3f0010",
  fullHash = "3f0010",
  text = "Parts of the Swarm. In Thousand Needles, you find a cracked silithid carapace and see how tightly its plating is woven. Korran at the Crossroads wants to study more of these creatures. You find silithid chitin woven tighter than anything you have seen. The creature's body shows great strength and advanced development. Korran at the Crossroads wants to learn more about the creatures and their origins. He asks for one silithid heart, five silithid talons and three intact silithid carapaces.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1148-3c8f319386703c0a33ad/1-0000.mp3", duration = 29.8840816, start = 0},
  },
}
P.transport["quest:1166"] = {
  hash = "1260ef",
  fullHash = "1260ef",
  text = "Overlord Mok'Morokk's Concern. Overlord Mok'Morokk sends you south from Brackenwall Village to recover what he left at the Stonemaul clan's old home. He wants his grog, snuff and strongbox back. Mok'Morokk says Rexxar made him the mighty leader of the Stonemaul clan. He says he keeps his people safe. When big dragons came to the clan's old home and brought fire, he found them a new home here in Dustwallow. Mok'Morokk left the old home in such a hurry that he forgot his grog, snuff and strongbox. He points you south to the Den of Flame and the Stonemaul Ruins, certain his things are there. He says he is too busy leading the ogres to go himself.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1166-d2a1b1387ff8a7513fe8/1-0000.mp3", duration = 41.3257143, start = 0},
  },
}
P.transport["quest:1168"] = {
  hash = "582b95",
  fullHash = "582b95",
  text = "Army of the Black Dragon. In Brackenwall Village, the Army of the Black Dragon has left Tharg grieving and thirsting for vengeance. He blames Overlord Mok'Morokk for ordering the ogres to flee. Black dragons killed Tharg's wife along with many ogres. After Rexxar made Mok'Morokk Overlord, the new leader ordered the survivors to run until they reached Brackenwall Village. Tharg says ogres are poor at running and should fight instead. He believes Mok'Morokk thinks only of himself, though Mok'Morokk now tells all ogres to stay put and keep Brackenwall Village safe. Tharg calls the Stonemaul Ruins his home and likes the south. Brackenwall Village is no home to him. He wants revenge on the black dragon army and a return to the ruins, so he asks you to cut down Firemane Scouts and Firemane Ash Tails among its ranks.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1168-6d18838f633c9235bd20/1-0000.mp3", duration = 57.8089796, start = 0},
  },
}
P.transport["quest:1169"] = {
  hash = "45194b",
  fullHash = "45194b",
  text = "Identifying the Brood. In Brackenwall Village, Draz'Zilb seeks the beast that attacked the clan's old home. Draz'Zilb says Mok'Morokk clings to power while Tharg struggles with sorrow and vengeance, and asks you for fifteen searing tongues and fifteen searing hearts. Draz'Zilb says Mok'Morokk is consumed by power while Tharg wrestles with sorrow and a thirst for vengeance. In Draz'Zilb's view, no one else is trying to learn who attacked the clan's old home. The ogre speaks with care, though you might have expected a brute's words. Draz'Zilb asks you to take fifteen tongues and fifteen hearts from the whelps and hatchlings. The burned young belong to the black dragon army, and Draz'Zilb hopes their remains will reveal which beast sent her young into the ogres' home.\n\nIf the ogres learn what kind of beast they face, they may destroy their enemy for good and reclaim Stonemaul Village from ruin. Draz'Zilb says getting Mok'Morokk to leave the swamp will be a great labor of its own.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1169-257e5f2383b3514bafcd/1-0000.mp3", duration = 61.0481633, start = 0},
  },
}
P.transport["quest:1170"] = {
  hash = "c04f53",
  fullHash = "c04f53",
  text = "The Brood of Onyxia. Draz'Zilb fears Onyxia's brood has come for more than a siege against a few ogres. Draz'Zilb reports that Onyxia's brood has invaded Stonemaul Village. Onyxia is Deathwing's daughter, and her arrival troubles him. He is certain the brood seeks more than a siege against a few ogres. So you carry word to Overlord Mok'Morokk in Brackenwall Village, where he can take action.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1170-703844f030d39b7b1602/1-0000.mp3", duration = 26.88, start = 0},
  },
}
P.transport["quest:1171"] = {
  hash = "270d40",
  fullHash = "270d40",
  text = "The Brood of Onyxia. At Brackenwall Village, The Brood of Onyxia meets Overlord Mok'Morokk's denial. He says no black dragons are here and sends you back to Draz'Zilb with word that the ogres will stay. Overlord Mok'Morokk wants to be left alone after Draz'Zilb reports the brood of Onyxia. He says the ogres will stay where they are and denies that any black dragon is here. Carry his answer to Draz'Zilb in Brackenwall Village.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1171-8a5031058cd36be157c8/1-0000.mp3", duration = 29.9885714, start = 0},
  },
}
P.transport["quest:1172"] = {
  hash = "f6181a",
  fullHash = "f6181a",
  text = "The Brood of Onyxia. In the marsh's south, Draz'Zilb sends you against Onyxia's eggs. No more of her whelps should hatch. Onyxia's brood lies scattered through the Dragonmurk. Draz'Zilb urges you south to the Wyrmbog, where the ogre is sure Onyxia made her lair and scattered her eggs. Dragons nest in the land around Stonemaul Village, keeping the ogres from taking it back. So you are sent to find and destroy the eggs.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1172-4a7a18f60285573dee4e/1-0000.mp3", duration = 26.8277551, start = 0},
  },
}
P.transport["quest:1173"] = {
  hash = "2f7dee",
  fullHash = "2f7dee",
  text = "Challenge Overlord Mok'Morokk. In Brackenwall Village, Overlord Mok'Morokk laughs at your challenge and vows to crush you. Draz'Zilb expected you to drive him from the village. After The Brood of Onyxia, you face Overlord Mok'Morokk. He laughs at your nerve and promises to crush you. Then he tells you to speak when you are ready for a beating. Draz'Zilb in Brackenwall Village expected you to chase Mok'Morokk from the village. Why have you returned only to talk?",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1173-dcee612a627502d0e4ba/1-0000.mp3", duration = 32.2873469, start = 0},
  },
}
P.transport["quest:1175"] = {
  hash = "512182",
  fullHash = "512182",
  text = "A Bump in the Road. At the Mirage Raceway, Trackmaster Zherin needs the growing beasts kept from the track. You are asked to thin the Saltstone Basilisks, Crystalhides and Gazers before they wander onto it. A basilisk once struck the goblins' racer, the Red Thunder. After the crash, Kronkrider hired Zherin to watch over the Mirage Raceway track. Zherin does not know what the beasts on the Shimmering Flats are eating. He knows only that they have grown too big.\n\nTheir numbers must be kept down before one strays onto the course during a race. Clearing wreckage is bad enough. Zherin would rather not pick burnt animal parts out of it as well.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1175-1b7836c3ea8f5673d7b4/1-0000.mp3", duration = 39.2359184, start = 0},
  },
}
P.transport["quest:1177"] = {
  hash = "e578dd",
  fullHash = "e578dd",
  text = "Hungry!. Mudcrush Durtfeet is hungry in northern Dustwallow Marsh and wants food from you. Bash the fishy Mirefin and bring back their heads, or Mud will eat you. Mudcrush Durtfeet, an ogre called Mud, makes a plain bargain. Bash the fishy Mirefin and bring him their heads for food. Feed Mud, or he will eat you.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1177-8b68954ebc272aa78389/1-0000.mp3", duration = 21.76, start = 0},
  },
}
P.transport["quest:1178"] = {
  hash = "90fdac",
  fullHash = "90fdac",
  text = "Goblin Sponsorship. The goblin racers are waiting on a promised part as the gnomes gain ground. Pozzik sends you to Ratchet to ask Gazlowe what happened. Pozzik calls the racing team the pride of goblins. Many people help it in one way or another. Gazlowe searches the world for parts and once came to work on one of its rigs.\n\nWeeks ago, Gazlowe promised a new prototype fuel regulator, but it has not arrived. He is usually prompt, so Pozzik asks you to go to Ratchet and learn what happened. The gnomes are gaining.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1178-4db275a2139f181fb753/1-0000.mp3", duration = 32.6791837, start = 0},
  },
}
P.transport["quest:1180"] = {
  hash = "50aaff",
  fullHash = "50aaff",
  text = "Goblin Sponsorship. Gazlowe in Ratchet still waits for the fuel regulator he promised Pozzik. Revilgaz in Booty Bay said he would ship it, but it has not arrived. So Gazlowe sends you to Wharfmaster Lozgil at the far northwestern end of the Booty Bay docks to check the cargo records. Gazlowe promised Pozzik a new fuel regulator, but it has not reached Ratchet. Revilgaz in Booty Bay said he would ship it over. Perhaps the part slipped through the cracks. If it never left, there may be little to do. Still, you can find out whether it departed Booty Bay. Wharfmaster Lozgil, at the far northwestern end of the docks, can search the cargo records.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1180-3b1225dd2c8218232e95/1-0000.mp3", duration = 44.8261224, start = 0},
  },
}
P.transport["quest:1181"] = {
  hash = "20af35",
  fullHash = "20af35",
  text = "Goblin Sponsorship. At the Mirage Raceway, the goblin racers still need their missing fuel regulator. Wharfmaster Lozgil sends you to Baron Revilgaz in Booty Bay for help. Wharfmaster Lozgil can do little more to trace the missing shipment bound for Ratchet. He sends you to Baron Revilgaz, since the Baron knows his own business best. You will find him on the top floor of the tavern across the harbor in Booty Bay.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1181-b0f8bb42b93e5a571fbb/1-0000.mp3", duration = 25.7828571, start = 0},
  },
}
P.transport["quest:1182"] = {
  hash = "ff1ec4",
  fullHash = "ff1ec4",
  text = "Goblin Sponsorship. Baron Revilgaz is seeking the Venture Company’s new fuel regulator plans for Pozzik at Lake Nazferiti. Foreman Cozzle has outsmarted him, so the Baron sends you after the blueprints. Baron Revilgaz says the Venture Company’s shredders at Lake Nazferiti in northern Stranglethorn carry a new model of fuel regulator. Pozzik could use its details, but Foreman Cozzle has proved cleverer than the Baron expected. So Revilgaz believes you may have better luck finding the plans.\n\nThe blueprints are kept in Cozzle’s house, almost certainly under lock and key. The Venture Company’s base lies around Lake Nazferiti, in the vale’s north-eastern corner. Cozzle keeps the key in his cabin atop the oil tower. The box of blueprints is in the small house near the tower’s base. Revilgaz admits the gnome team there is good, and his team needs every advantage it can find.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1182-8f11d39277ae223597f8/1-0000.mp3", duration = 63.8171429, start = 0},
  },
}
P.transport["quest:1183"] = {
  hash = "22a312",
  fullHash = "22a312",
  text = "Goblin Sponsorship. At the Shimmering Flats, Baron Revilgaz's regards reach Pozzik with the Fuel Regulator Blueprints. The Baron invites Pozzik to ask for anything he needs. Baron Revilgaz sends you to the Shimmering Flats with the Fuel Regulator Blueprints and his regards for Pozzik. The Baron says Pozzik should ask if he ever needs anything. Revilgaz waits to hear that Pozzik breaks the track record.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1183-31cd70509129270babc9/1-0000.mp3", duration = 24.9730612, start = 0},
  },
}
P.transport["quest:1184"] = {
  hash = "bcbfdb",
  fullHash = "bcbfdb",
  text = "Parts of the Swarm. From Thousand Needles, Korran sends word to Orgrimmar about Moktar and his studies. Korran sends you to Belgrom Rockmaul in Orgrimmar with word from Thousand Needles. The cracked carapaces came from silithid at the Rustmaul Digsite. Tell Belgrom that Moktar is doing his bidding well and that Korran's studies are progressing. Korran hopes to learn more soon.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1184-315bcb76e73069daf640/1-0000.mp3", duration = 24.0587755, start = 0},
  },
}
P.transport["quest:1186"] = {
  hash = "c11a89",
  fullHash = "c11a89",
  text = "The Eighteenth Pilot. On the Shimmering Flats, Pozzik sends you to find Razzeric while he works on the racers. Razzeric is the team's eighteenth pilot, and he enjoys modifying the racers. Pozzik is fitting a new fuel regulator into the racer designs. He sends you to Razzeric on the Shimmering Flats, the team's eighteenth pilot. Razzeric likes to modify the racers. Pozzik says he is a little off his rocker, so try not to look too surprised.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1186-bbf3abf4693029d711a2/1-0000.mp3", duration = 30.8244898, start = 0},
  },
}
P.transport["quest:1187"] = {
  hash = "5404ff",
  fullHash = "5404ff",
  text = "Razzeric's Tweaking. On the Shimmering Flats, Razzeric's Tweaking gives racers more power once Pozzik is done with them. A seaforium booster ordered from Shreev in Gadgetzan traveled by zeppelin, which Razzeric says crashed in Dustwallow Marsh. He wants the booster brought back. Pozzik is a fine mechanic, Razzeric says, but too cautious with firepower and too ready to hold back. Once Pozzik finishes with a racer, Razzeric loosens its controls, removes parts of its frame, and adds power. He ordered a seaforium booster from Shreev at the Gizmorium in Gadgetzan. Razzeric says the zeppelin carrying it crashed in Dustwallow Marsh. The booster belongs back on the Shimmering Flats. Facing the track without that extra kick would be a travesty.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1187-16a8dfefb50fb76876c0/1-0000.mp3", duration = 50.7297959, start = 0},
  },
}
P.transport["quest:1188"] = {
  hash = "d33262",
  fullHash = "d33262",
  text = "Safety First. Razzeric sends you south with a seaforium booster, bound for Shreev in Gadgetzan. Its safety is still on, though Razzeric asked for it to be removed. Razzeric finds the safety still on his seaforium booster. It limits the power the booster can deliver, though he had asked Shreev to remove it. So he gives you the booster and sends you south of the Shimmering Flats, into the Tanaris desert. Shreev can remove the safety at the Gadgetzan Gizmorium.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1188-eaba745a88e480ec342d/1-0000.mp3", duration = 31.7126531, start = 0},
  },
}
P.transport["quest:1189"] = {
  hash = "72c17e",
  fullHash = "72c17e",
  text = "Safety First. On the Shimmering Flats, you carry Shreev’s modified seaforium booster back to Razzeric. Shreev warns that one slip while setting it off could leave Razzeric a scorch mark on the track. Shreev hands you the modified booster, prepared as Razzeric asked. He warns that Razzeric must take care when setting it off. One slip, and Razzeric will be a scorch mark on the track instead of racing ahead. Shreev says that would be a shame. Then he wonders whether the nineteenth driver would have been any good. Back on the Shimmering Flats, Razzeric grumbles that Pozzik loaded a bucket of sand onto his racer. How can he reach top speed with sand beneath the seat?",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1189-65d35ac434e886dabdbd/1-0000.mp3", duration = 40.2808163, start = 0},
  },
}
P.transport["quest:1190"] = {
  hash = "b0d8e3",
  fullHash = "b0d8e3",
  text = "Keeping Pace. Pozzik suspects the Brassbolts brothers have found a new material for their cars. Their designs and run data are unchanged, yet the cars go faster. Rizzle Brassbolts keeps close to his plans, and Zamek can distract him so you can take them. This follows News for Fizzle. The Brassbolts brothers' cars have grown faster, and Pozzik can find only one explanation: a new building material. Their designs and the data from their runs remain unchanged. Rizzle Brassbolts has been absorbed in plans for this discovery almost constantly. Zamek can distract Rizzle while you take his plans. Pozzik is waiting for them on the Shimmering Flats.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1190-060a9ea3fcc8bdc0f486/1-0000.mp3", duration = 40.3591837, start = 0},
  },
}
P.transport["quest:1191"] = {
  hash = "04afec",
  fullHash = "04afec",
  text = "Zamek's Distraction. In Thousand Needles, Zamek's Distraction can draw Rizzle away while you work through Keeping Pace. You cannot finish Keeping Pace without it. While you work through Keeping Pace, Zamek draws Rizzle from his hut. The Indurium plans remain behind.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1191-a2209c854bbc3af96208/1-0000.mp3", duration = 16.9534694, start = 0},
  },
}
P.transport["quest:1192"] = {
  hash = "5fa4a2",
  fullHash = "5fa4a2",
  text = "Indurium Ore. Pozzik needs Indurium Ore to build several parts for the racers. The ore lies at the Uldaman dig in the Badlands, across the sea in Khaz Modan. Gnomes are already gathering their own supply, and Pozzik wants to keep pace. Pozzik asks you to bring him four pieces of raw Indurium Ore. You can find it at the Uldaman dig in the Badlands, across the sea in Khaz Modan. Gnomes are already gathering their own supply, and Pozzik wants some too. This comes after Rizzle's Schematics.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1192-7c9829483d7a620cfed4/1-0000.mp3", duration = 33.8285714, start = 0},
  },
}
P.transport["quest:1194"] = {
  hash = "a74e49",
  fullHash = "a74e49",
  text = "Rizzle's Schematics. After Keeping Pace, you carry a raw indurium sample to Pozzik on the Shimmering Flats. Rizzle's plans lie beneath the ore, and his notes trace it to the dwarves' dig at Uldaman in the Badlands. They also describe how well indurium resists heat. Rizzle's plans explain how to refine indurium ore. Scrawled notes trace its source to the dwarves' dig at Uldaman in the Badlands. Other notes describe the ore's resistance to heat. A lump of raw indurium holds the plans down, and you take the sample to Pozzik.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1194-02076dfb963aca3f0de9/1-0000.mp3", duration = 33.9069388, start = 0},
  },
}
P.transport["quest:1201"] = {
  hash = "75073a",
  fullHash = "75073a",
  text = "Theramore Spies. In Dustwallow, Horde and Alliance keep an uneasy truce, though skirmishes and covert deeds continue. Nazeer Bloodpike wants Alliance infiltrators east of Brackenwall Village hunted down and slain. Alliance spies watch Brackenwall Village from the islands to its east. They send word of Horde movements back to Theramore.\n\nNazeer Bloodpike, the village spymaster, sends you to find and kill them. Their superiors must know such spies are unwelcome.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1201-9efcc093834022efc96d/1-0000.mp3", duration = 30.3281633, start = 0},
  },
}
P.transport["quest:1202"] = {
  hash = "b8eb18",
  fullHash = "b8eb18",
  text = "The Theramore Docks. At Theramore Docks, papers taken from a ship lie beneath the water. Nazeer Bloodpike sends you to recover them after two spies were discovered and cast them into the sea. After dealing with the Theramore spies, you hear from Nazeer Bloodpike again. Two spies went to a ship by the Theramore docks and took its papers. They were discovered and threw the papers into the sea. One spy escaped and reported the failure, unable to retrieve what they had cast away. The Captain's Documents lie in a footlocker beneath the water by the Theramore docks. You are sent to recover them and bring them to Nazeer Bloodpike in Brackenwall Village. He says the papers matter greatly to the Alliance's stability. That makes them important to the Horde's security, too.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1202-908ee502a98149889c44/1-0000.mp3", duration = 59.5069388, start = 0},
  },
}
P.transport["quest:1203"] = {
  hash = "8349fa",
  fullHash = "8349fa",
  text = "Jarl Needs a Blade. In Dustwallow Marsh, Jarl needs a blade for urgent cutting. “Swamp Eye” Jarl wants a moonsteel broadsword and warns you not to dawdle. “Swamp Eye” Jarl has cutting to do, but keeps its purpose to himself. He asks for a particular blade, called a moonsteel broadsword by some and a swing blade by Jarl. You might find one in town, or ask a blacksmith to make one special. Jarl warns you not to sleep on it; whatever needs cutting will not keep forever.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1203-45bb87834a780128094e/1-0000.mp3", duration = 28.9959184, start = 0},
  },
}
P.transport["quest:1204"] = {
  hash = "9045cf",
  fullHash = "9045cf",
  text = "Mudrock Soup and Bugs. In Theramore, Morgan Stern hopes to win Stormwind City over with a new dish. The trek through Dustwallow Marsh is too much for Morgan Stern, so you gather Mudrock tongues for Mudrock Soup and Bugs. Morgan Stern is gathering ingredients for a new dish in Theramore. A long trek through Dustwallow Marsh is more than Morgan Stern expects to survive, so you hunt Mudrock turtles. Their tongues are needed first. Mudrock turtles roam the coast of Dustwallow Marsh, mostly around the bay. Morgan Stern wants forked tongues in particular, having heard they bring a distinct flavor to the dish.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1204-570b2b3732fd36f42f00/1-0000.mp3", duration = 38.4522449, start = 0},
  },
}
P.transport["quest:1206"] = {
  hash = "be2f78",
  fullHash = "be2f78",
  text = "Jarl Needs Eyes. At Swamplight Manor, Jarl seeks forty unpopped Darkmist eyes for their smooth, salty juice. The spiders live in Darkmist Cavern, west of the manor. After Soothing Spices, Jarl turns to eye juice, a drink they enjoy. Most creatures have only two eyes, but spiders have many. Jarl likes the taste of Darkmist eye juice. The Darkmist spiders live in Darkmist Cavern, west of the manor. Jarl wonders whether the cave took its name from the spiders, or the spiders from the cave.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1206-fe399eecdd6abab93d92/1-0000.mp3", duration = 33.044898, start = 0},
  },
}
P.transport["quest:1218"] = {
  hash = "7f8be9",
  fullHash = "7f8be9",
  text = "Soothing Spices. In Dustwallow Marsh, \"Swamp Eye\" Jarl needs three Soothing Spices for a stew. \"Swamp Eye\" Jarl loves swamp cooking, including fried green frog legs. Now Jarl plans a stew and needs soothing spice for the pot. Bring three Soothing Spices, and Jarl will share the stew with you. Does stew suit your taste?",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1218-cea49ffcbce2c359c28f/1-0000.mp3", duration = 18.8604082, start = 0},
  },
}
P.transport["quest:1219"] = {
  hash = "e0c3e0",
  fullHash = "e0c3e0",
  text = "The Orc Report. In Dustwallow Marsh, you find a severed orc hand gripping a bone tube. Inside lies a dirt-stained parchment in Orcish, meant for a Theramore Lieutenant. In the loose dirt, you find a severed orc hand gripping a tube carved from bone. Inside is a dirt-stained parchment written in Orcish. It seems significant, and a Theramore Lieutenant is the one to show it to.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1219-682193f7eaea0a9e142e/1-0000.mp3", duration = 25.7044898, start = 0},
  },
}
P.transport["quest:1220"] = {
  hash = "3f5080",
  fullHash = "3f5080",
  text = "Captain Vimes. Near Theramore, Lieutenant Aden sends you to Captain Garran Vimes with an orc report and word of Horde spies. Lieutenant Aden sends you to Captain Garran Vimes with the orc report you found. Vimes reads orcish better than most, so Aden wants him to know that Horde spies are close to Theramore. You’ll find Vimes at the barracks on the northeastern side of Theramore Isle.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1220-2f7dcdb05d0b4b736212/1-0000.mp3", duration = 25.835102, start = 0},
  },
}
P.transport["quest:1222"] = {
  hash = "435bfc",
  fullHash = "435bfc",
  text = "Stinky's Escape. In the swamp, \"Stinky\" Ignatz is searching for bogbean leaves for a cook in Theramore. Critters have surrounded him, and he asks you to guard him while he looks for a plant. When he is done, Morgan Stern is waiting in Theramore. \"Stinky\" Ignatz is glad to find someone who does not see him as a meal. Morgan Stern, a cook in Theramore, sent him to gather bogbean leaves for a new recipe. Ignatz guesses Stern finds them tasty. Now critters have surrounded him, and he asks you to guard his back while he searches for a bogbean plant. Morgan Stern, a cook in Theramore, is anxious. Ignatz went into the swamp a while ago and has not returned.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1222-d0e6bad3c5d3858d19b1/1-0000.mp3", duration = 42.6318367, start = 0},
  },
}
P.transport["quest:1238"] = {
  hash = "94027f",
  fullHash = "94027f",
  text = "The Lost Report. In Dustwallow Marsh, you uncover a spy's report bound for Brackenwall Village. An orc's severed hand grips a bone tube holding a dirt-stained account of weeks spent watching Theramore. You find an orc's severed hand in loose dirt, its fingers closed around a tube carved from bone. Inside lies a dirt-stained parchment. It reports on Theramore after weeks of spying and is meant for Nazeer Bloodpike, the orcs' spymaster at Brackenwall Village.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1238-487ef73b3f7c5ffcca80/1-0000.mp3", duration = 32.6791837, start = 0},
  },
}
P.transport["quest:1239"] = {
  hash = "e32724",
  fullHash = "e32724",
  text = "The Severed Head. In Dustwallow Marsh, you uncover a male orc's severed head. Bring it to Nazeer Bloodpike in Brackenwall Village. Your digging turns up a male orc's head, ragged where it was cut from the neck. Its lips curl in a snarl, and dark eyes glare defiantly. Bring the head to Nazeer Bloodpike in Brackenwall Village.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1239-368257e165f74d8a4dd7/1-0000.mp3", duration = 22.8310204, start = 0},
  },
}
P.transport["quest:1240"] = {
  hash = "274ec1",
  fullHash = "274ec1",
  text = "The Troll Witchdoctor. Nazeer Bloodpike seeks the truth about Marg Nighteye's death through troll witch-magic. You carry Marg's head to Kin'weelay at Grom'gol Base Camp in Stranglethorn Vale. Nazeer Bloodpike insists the truth about Marg's death must come to light. He says only troll witch-magic can reveal what happened. So you carry Marg's head to Kin'weelay at Grom'gol Base Camp in Stranglethorn Vale. No Darkspear witchdoctor is mightier than Kin'weelay, and Nazeer believes Kin'weelay can reach Marg's spirit.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1240-18e4ee2fb3b3fd886ed4/1-0000.mp3", duration = 31.7126531, start = 0},
  },
}
P.transport["quest:1248"] = {
  hash = "ceb668",
  fullHash = "ceb668",
  text = "The Missing Diplomat. You follow the trail of a kidnapped Stormwind diplomat to Menethil Harbor. An intercepted docket confirms the abduction but leaves the diplomat's identity and the conspirators' destination unknown. You have a docket that confirms a diplomat was taken from Stormwind. It names neither the diplomat nor the conspirators' destination. So the trail leads beyond Stormwind's gates to Menethil Harbor in the Wetlands, where you can search among the harbor crowds and their secret dealings.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1248-c9ebf8217505b7c75483/1-0000.mp3", duration = 34.7689796, start = 0},
  },
}
P.transport["quest:1249"] = {
  hash = "66b1f6",
  fullHash = "66b1f6",
  text = "The Missing Diplomat. Stormwind's envoy is missing, and you follow the trail from the capital to Menethil Harbor. There, the inquiry crosses paths with underworld figures and operatives tied to Stormwind's intelligence network. You follow the missing Stormwind envoy's trail north to Menethil Harbor in the Wetlands. Its docks and taverns hide shady dealers and covert runners, all working under the local guard's nose. To follow the leads through this port, you must deal with people who know the darker side of Alliance territory.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1249-74bedc354cac70c104e4/1-0000.mp3", duration = 37.3812245, start = 0},
  },
}
P.transport["quest:1250"] = {
  hash = "b9c153",
  fullHash = "b9c153",
  text = "The Missing Diplomat. Jahn says the Defias took the king from his ship while it lay moored. You are sent to Mikhail in the Wetlands as the search for Hendel continues. Jahn says the Defias put a man named Hendel aboard the king's ship while it was moored. The king was bound for Theramore to meet Jaina Proudmoore. Jahn believes the Defias worked with someone else, so you are asked to speak with Mikhail in the Wetlands as the search for Hendel begins.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1250-22277454a6149405da9f/1-0000.mp3", duration = 31.3469388, start = 0},
  },
}
P.transport["quest:1251"] = {
  hash = "bcf0de",
  fullHash = "bcf0de",
  text = "The Black Shield. At the burned Shady Rest Inn, a black shield clings to the crumbling chimney. Krog at Brackenwall Village waits to see it. Fire swept through the Shady Rest Inn and left little behind. An iron shield, charred black, is fixed to the crumbling chimney. You can work it free of the brick and bring it to Krog at Brackenwall Village. He will ask whether it counts as evidence from the inn’s remains.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1251-75f0c600b41dd6496702/1-0000.mp3", duration = 25.2865306, start = 0},
  },
}
P.transport["quest:1252"] = {
  hash = "4b25b5",
  fullHash = "4b25b5",
  text = "Lieutenant Paval Reethe. At the Shady Rest Inn, Lieutenant Paval Reethe's badge lies beneath the rubble, marked with Theramore's sign. Bring it to Captain Garran Vimes in Theramore. Ash and debris bury a badge in the Shady Rest Inn ruins. Beneath it, Lieutenant Paval Reethe's name lies below Theramore's sign. Captain Garran Vimes in Theramore asks what you found, and the badge belongs in his hands.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1252-817695c6375123f9aca4/1-0000.mp3", duration = 28.16, start = 0},
  },
}
P.transport["quest:1253"] = {
  hash = "3ea98b",
  fullHash = "3ea98b",
  text = "The Black Shield. At the burned Shady Rest Inn, a fire-blackened shield hangs from the crumbling chimney. Captain Garran Vimes in Theramore awaits evidence from the ruins. Few parts of the burned Shady Rest Inn remain beyond a crumbling chimney. A fire-blackened iron shield is still fixed to its brick, and can be removed. Captain Garran Vimes in Theramore awaits evidence from the inn site.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1253-c2de1d44b8944bda9890/1-0000.mp3", duration = 26.7493878, start = 0},
  },
}
P.transport["quest:1258"] = {
  hash = "37ad87",
  fullHash = "37ad87",
  text = "... and Bugs. Morgan Stern in Theramore is shaping a recipe that may become Stormwind's next food craze. He has the Mudrock tongues, but still needs pristine, unscarred legs from a giant crab. Morgan Stern needs each crab leg's shell to shape his dish's appearance. Every leg must be pristine and unscarred, yet an adult crab may have only one or two legs fit for his research. He needs many, and the Muckshells of Dustwallow Marsh will not do. Only crabs from the faraway Swamp of Sorrows suit the recipe, so you face a long journey.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1258-a3eba2e891fead6192d2/1-0000.mp3", duration = 32.6530612, start = 0},
  },
}
P.transport["quest:1259"] = {
  hash = "afc216",
  fullHash = "afc216",
  text = "Lieutenant Paval Reethe. In Theramore, Captain Garran Vimes asks you to learn who Lieutenant Paval Reethe is. Captain Garran Vimes does not recognize Lieutenant Paval Reethe's name. So he sends you to Adjutant Tesoran in Theramore, who keeps the guard's records of its people and equipment. Vimes expects those records to reveal who Reethe is.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1259-f5d065c9254bb55474f1/1-0000.mp3", duration = 22.5697959, start = 0},
  },
}
P.transport["quest:1260"] = {
  hash = "c22913",
  fullHash = "c22913",
  text = "Morgan Stern. In Theramore, Angus Stern waits for word from Morgan Stern, who is gathering recipes for a new menu. Angus Stern wants customers at the Blue Recluse to taste rural dishes in the bayou style. He sent his nephew Morgan to Theramore, the city beside Dustwallow Marsh, to gather recipes from the locals. The journey is too long for Angus, so he asks you, a young traveler, to speak with Morgan.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1260-eb47755bff6f6e0e022f/1-0000.mp3", duration = 26.6187755, start = 0},
  },
}
P.transport["quest:1261"] = {
  hash = "951202",
  fullHash = "951202",
  text = "Marg Speaks. Near Theramore, Marg's stolen pendant and unfinished duty still weigh on them. Marg asks you to find the muckshell that killed them, recover the jeweled pendant taken from Alliance soldiers, and carry it to Nazeer Bloodpike in Brackenwall Village. Alliance soldiers had made camp on the beach near Theramore. One wore a pendant set with more gems than a soldier could pay for. Marg slipped into the camp that night and stole it. On the way back to base, a muckshell crab-man killed Marg. Now Marg asks you to find the muckshell, recover the pendant, and bring it to Nazeer in Brackenwall Village.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1261-cdc7173b99cb131535fe/1-0000.mp3", duration = 43.4938776, start = 0},
  },
}
P.transport["quest:1262"] = {
  hash = "0915b8",
  fullHash = "0915b8",
  text = "Report to Zor. Nazeer Bloodpike sends you to Orgrimmar with Marg's jeweled pendant. Strange that common soldiers carried such a fine piece, he asks Zor Lonetree, who knows Alliance politics, to judge its history. Nazeer Bloodpike finds it strange that common soldiers carried a pendant so fine. Perhaps its owner was in disguise, or perhaps the soldiers stole it themselves. Either way, Nazeer judges it a noble's pendant. Its true owner must be found to unravel the mystery. Zor Lonetree in Orgrimmar knows much of Alliance politics and can tell whether Stormwind's nobility once claimed it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1262-dc6a7037917df24ea443/1-0000.mp3", duration = 43.3893878, start = 0},
  },
}
P.transport["quest:1264"] = {
  hash = "e0959a",
  fullHash = "e0959a",
  text = "The Missing Diplomat. A tavern keeper sends you to Commander Samaul in Theramore, where Hendel may still be stationed. The tavern keeper believes Hendel is among the Kul Tiras Marines who visit regularly. They are paid at the beginning of each month and usually leave Theramore afterward. Commander Samaul may know if Hendel is still stationed there. Mention Elling's name, and Samaul may help discreetly. Commander Samaul is the officer in charge of Miss Proudmoore's forces in Theramore. He is busy, but offers to answer your questions. The marsh beyond the city holds ogres, orcs and murlocs. Black dragons dwell in its southern reaches.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1264-50781303bd6d6301b6cf/1-0000.mp3", duration = 44.4081633, start = 0},
  },
}
P.transport["quest:1268"] = {
  hash = "6444da",
  fullHash = "6444da",
  text = "Suspicious Hoofprints. At the Shady Rest Inn, hoofprints lead into the marsh. Its bare frame still smokes, and the tracks fade across the soft ground. Krog at Brackenwall Village should hear of them. The Shady Rest Inn is a smoking frame, with hoofprints stretching away into the marsh. Some impressions show clearly, while others are nearly lost in the soft ground. You carry word of the tracks to Krog at Brackenwall Village.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1268-b900907253ab57da399d/1-0000.mp3", duration = 26.6187755, start = 0},
  },
}
P.transport["quest:1269"] = {
  hash = "2b8da1",
  fullHash = "2b8da1",
  text = "Lieutenant Paval Reethe. At Brackenwall Village, Krog awaits Lieutenant Paval Reethe's badge and news of the Shady Rest Inn. Beneath rubble and brush, you find a badge marked with Theramore's sign. Ash and debris cover it, but Lieutenant Paval Reethe's name is embossed below the golden anchor. Krog waits at Brackenwall Village. He asks whether you have learned what befell the Shady Rest Inn.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1269-8d6d8ecd1f8a5a002090/1-0000.mp3", duration = 26.0179592, start = 0},
  },
}
P.transport["quest:1270"] = {
  hash = "f87d93",
  fullHash = "f87d93",
  text = "Stinky's Escape. In the swamp, “Stinky” Ignatz is trapped by critters before he finds bogbean. Mebok Mizzyrix of Ratchet needs the leaves for a potion, so Ignatz asks you to free and guard him as he searches. Then find Mebok in Ratchet. “Stinky” Ignatz is glad to meet someone who will not eat him. Mebok Mizzyrix, a goblin from Ratchet, needs bogbean leaves for a potion. Ignatz says the reason does not matter; the pay was good, and he knows the swamp. But before he found the plant, critters surrounded him. He asks you to help him escape and guard him while he searches.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1270-7c777a9ab42974ff6e2d/1-0000.mp3", duration = 37.1722449, start = 0},
  },
}
P.transport["quest:1271"] = {
  hash = "8bc2eb",
  fullHash = "8bc2eb",
  text = "Feast at the Blue Recluse. In Dustwallow Marsh, you finish your work for Morgan Stern with ... and Bugs, then return to Angus Stern at the Blue Recluse. Angus Stern is Morgan Stern's uncle. You return to Angus at the Blue Recluse after helping Morgan research recipes in Dustwallow Marsh.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1271-11dd25fe33d838ca2605/1-0000.mp3", duration = 20.3755102, start = 0},
  },
}
P.transport["quest:1273"] = {
  hash = "1a3a21",
  fullHash = "1a3a21",
  text = "Questioning Reethe. Ogron has found Reethe at last and asks you to help question him. He says Reethe hid well for a human, though the days in the swamp may have driven him mad. Afterward, you return to Krog at Brackenwall Village. Ogron has found Reethe after a long search. By Ogron's reckoning, Reethe hid well for a human. Yet Ogron fears the days in the swamp may have left Reethe mad, and wants you beside him for answers. Once you have spoken with Reethe, you return to Krog at Brackenwall Village.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1273-d5929f14331652020fe1/1-0000.mp3", duration = 32.6269388, start = 0},
  },
}
P.transport["quest:1276"] = {
  hash = "254617",
  fullHash = "254617",
  text = "The Black Shield. In Thunder Bluff, Krog brings a blackened iron shield to a smith for answers. Reethe gave him nothing useful, leaving Mosarn as his only lead. Krog remembers Mosarn as a highly regarded blacksmith in Thunder Bluff. The Earthen Ring once thanked Krog with armor Mosarn had crafted, and Krog speaks well of that work. He believes Mosarn made the shield too and may know more. It is a slim lead. Reethe yielded nothing useful, so Krog brings the blackened iron shield to Mosarn in Thunder Bluff.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1276-c94423f4ee826f771f1e/1-0000.mp3", duration = 35.8922449, start = 0},
  },
}
P.transport["quest:1282"] = {
  hash = "0e9086",
  fullHash = "0e9086",
  text = "They Call Him Smiling Jim. Guard Byron sends you to Theramore for the story of They Call Him Smiling Jim. He hints that Jim's life was not always this way. Guard Byron remembers the fine inn Smiling Jim once kept in the marsh. He pities Jim, but would rather not speak of what changed. For the full story, ask Captain Garran Vimes in Theramore.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1282-abd2726a0ecfde1f7faf/1-0000.mp3", duration = 22.2563265, start = 0},
  },
}
P.transport["quest:1284"] = {
  hash = "867d03",
  fullHash = "867d03",
  text = "Suspicious Hoofprints. Smoke rises from the Shady Rest Inn, and Suspicious Hoofprints cross the marsh. Some prints are clear; others fade in the soft mud. Captain Garran Vimes in Theramore needs the report. Hoofprints lead from the smoking ruin of the Shady Rest Inn into the marsh. Some are easy to see, while others nearly vanish in the soft mud. Captain Garran Vimes in Theramore needs to hear about them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1284-250e025a672a17181b0e/1-0000.mp3", duration = 26.6187755, start = 0},
  },
}
P.transport["quest:1285"] = {
  hash = "6b2265",
  fullHash = "6b2265",
  text = "Daelin's Men. Adjutant Tesoran has found Lieutenant Paval Reethe in the guard's records. They trace Reethe's service from enlistment in the Kul Tiras marines at sixteen, through promotions for distinguished service, to the Theramore guard with Lady Proudmoore's recruits. The final entry marks Reethe missing, and Captain Garran Vimes is to hear the news. Captain Garran Vimes sent you to Adjutant Tesoran, who searched the books and found Lieutenant Paval Reethe. Reethe enlisted in the Kul Tiras marines at sixteen, and distinguished service brought him promotions. Later, he joined the Theramore guard with most of the recruits who sailed over with Lady Proudmoore. The record ends by listing him as missing. Vimes, in Theramore, is to hear the news.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1285-8c6ea6c0e4f4ae9cf229/1-0000.mp3", duration = 53.6816327, start = 0},
  },
}
P.transport["quest:1286"] = {
  hash = "fc5667",
  fullHash = "fc5667",
  text = "The Deserters. At Lost Point, Captain Garran Vimes questions deserters who took Theramore’s abandoned tower. Captain Garran Vimes struggles to hold the marsh, yet his people keep several watchtowers standing. Scouts have found deserters in an abandoned tower at Lost Point, southeast of the inn. A man named Jacken leads them. Vimes asks you to learn what Jacken knows about Reethe, though the man may not give up the information easily.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1286-c2e99825aee256aae547/1-0000.mp3", duration = 31.5820408, start = 0},
  },
}
P.transport["quest:1287"] = {
  hash = "d9d8b3",
  fullHash = "d9d8b3",
  text = "The Deserters. Reethe has been driven from the deserter band, and Balos Jacken calls him a coward. Jacken asks you to forget the meeting. Captain Garran Vimes in Theramore is waiting to hear about Reethe. Balos Jacken says the deserters drove Reethe out for repeatedly plundering the ogres’ stores at Brackenwall Village. The band is too small to face those ogres, he says, and Reethe crossed the line once too often. They left Reethe to manage alone. In return for the answer, Jacken asks you to forget the meeting.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1287-a51ae1a02e9982feb2c0/1-0000.mp3", duration = 38.1910204, start = 0},
  },
}
P.transport["quest:1288"] = {
  hash = "6201aa",
  fullHash = "6201aa",
  text = "Vimes's Report. Captain Garran Vimes praises your work as the finest he has seen from an amateur. Now you carry his report to Theramore for Lady Jaina Proudmoore. Lady Jaina Proudmoore asked Captain Vimes to keep her informed about a delicate situation. He has not spoken with her for some time. He planned to deliver the report later, but now sends you in his place. You may have better answers to her questions than he does.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1288-20c46d42e3778c4db22a/1-0000.mp3", duration = 32.3395918, start = 0},
  },
}
P.transport["quest:1289"] = {
  hash = "991440",
  fullHash = "991440",
  text = "Vimes's Report. Lady Jaina Proudmoore has read Vimes's Report and thanks you for aiding Captain Garran Vimes's investigation. She sends you back to Vimes in Theramore to help uncover the mystery. Lady Jaina Proudmoore thanks you for helping Captain Vimes's investigation. His report eases her mind because the matter is in capable hands. She sends you back to him in Theramore to help uncover the mystery.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1289-58ca081f92e47cac508e/1-0000.mp3", duration = 27.7681633, start = 0},
  },
}
P.transport["quest:1302"] = {
  hash = "308907",
  fullHash = "308907",
  text = "James Hyal. Across the Great Sea, James Hyal's family waits for word from Kalimdor. He sailed there with Lady Jaina Proudmoore's expedition and set out to open an inn on the frontier. Now his family looks to Theramore's records for news. During the Third War, many left their homes in the Eastern Kingdoms to follow Lady Jaina Proudmoore across the Great Sea. James Hyal went with them, known at home for his gift in the kitchen. After the fighting ended and Theramore Isle was founded, he sought a living on Kalimdor. He planned to open an inn for travelers and fellow settlers. Back in the Eastern Kingdoms, James's brother grows worried. No letters have come from across the sea, though he hopes James is busy running a roadside taproom. He asks travelers to seek his brother out. The search begins in Theramore, where Clerk Lendry keeps records of expedition members who have ventured into the wilderness.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1302-14a978856763e2d8df24/1-0000.mp3", duration = 63.3469388, start = 0},
  },
}
P.transport["quest:1319"] = {
  hash = "c6d476",
  fullHash = "c6d476",
  text = "The Black Shield. At Theramore's smithy, Captain Garran Vimes sends a shield to a smith who may know its maker. Captain Garran Vimes knows little about the shield. So he sends you to Caz Twosprocket, one of the best blacksmiths around. Caz tends the forge in Theramore's smithy and may be able to tell you more.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1319-8f7683425b4e6ba1651e/1-0000.mp3", duration = 21.1069388, start = 0},
  },
}
P.transport["quest:1320"] = {
  hash = "85a282",
  fullHash = "85a282",
  text = "The Black Shield. Caz Twosprocket studies the black shield tied to the Shady Rest Inn mystery. One detail nearly escapes notice, and Caz sends you to Captain Garran Vimes in Theramore with what was found. A last detail nearly escapes Caz Twosprocket while looking over the black shield. The leather strap on its back has burned away, yet it seems to have been made for a large person. Caz guesses a tauren. That is all Caz can tell, so you are sent to Captain Garran Vimes in Theramore with the word and Caz's apology for not being more help.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1320-b066a14e618970a0c356/1-0000.mp3", duration = 37.1722449, start = 0},
  },
}
P.transport["quest:1321"] = {
  hash = "9b3c36",
  fullHash = "9b3c36",
  text = "The Black Shield. Krog sends you to Brackenwall Village to ask Do'gol about the Blackened Iron Shield. Krog finds nothing unusual about the Blackened Iron Shield. Still, he thinks Do'gol, the blacksmith in Brackenwall Village, may see something more. He urges you not to expect much.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1321-6a6b64f0a4cc9fa3706f/1-0000.mp3", duration = 17.5281633, start = 0},
  },
}
P.transport["quest:1322"] = {
  hash = "3ae070",
  fullHash = "3ae070",
  text = "The Black Shield. In Brackenwall Village, Do'gol seeks venom for a shield whose writing is hidden by burned residue. Six sacs from the marsh's Darkfang spiders hold acid that can clear its rim. At Brackenwall Village, Do'gol studies the lettering around a shield's rim. Burned grime makes it hard to read, but acid can clear the residue. Darkfang spiders in the marsh carry venom fit for the work, so Do'gol asks you for six of their venom sacs.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1322-a03a9b4edf5fbd9d5684/1-0000.mp3", duration = 26.2269388, start = 0},
  },
}
P.transport["quest:1323"] = {
  hash = "77f324",
  fullHash = "77f324",
  text = "The Black Shield. In Brackenwall Village, Do'gol sends you to Krog to learn a name on the shield. The writing seems to say Mosarn, but Do'gol does not know the name. Do'gol has rubbed the shield with too much acid, yet its writing remains hard to read. The name seems to be Mosarn, but Do'gol does not know it. Krog knows many people in Brackenwall Village, so Do'gol sends you to speak with Krog.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1323-1331c02f880f90096a17/1-0000.mp3", duration = 24.6857143, start = 0},
  },
}
P.transport["quest:1361"] = {
  hash = "0c44e3",
  fullHash = "0c44e3",
  text = "Regthar Deathgate. In the Barrens, Regthar Deathgate calls seasoned Horde fighters west. He is gathering volunteers for a campaign across the mountains into Desolace, where centaur clans terrorize the frontier. Horde leaders watch their borders for threats. In the Barrens, Regthar Deathgate has raised a defensive post to guard the western passes. So Horde officers send proven fighters west of the Crossroads to answer his call. Regthar Deathgate waits in a fortified redoubt along the ridges west of the Crossroads. From there, he watches the mountain trails into Desolace. He is gathering a vanguard to cross hostile ground and strike the Kolkar and other warring centaur clans before their expansion threatens Horde territory.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1361-b7c15d1fd18767887cff/1-0000.mp3", duration = 47.9346939, start = 0},
  },
}
P.transport["quest:1362"] = {
  hash = "dc3e96",
  fullHash = "dc3e96",
  text = "The Kolkar of Desolace. Regthar Deathgate sends Horde champions west into Desolace to reinforce scout Felgur Twocuts at Ghost Walker Post. The Kolkar threaten Horde lands from their stronghold there. Centaur raiders keep pressing into the Barrens. Regthar Deathgate knows the fighting will not end there while the Kolkar draw strength from their ancestral lands on Kalimdor's western coast. Their stronghold remains beyond Horde control, and raiders keep pouring through the mountain passes. The Horde must strike at their home. Ghost Walker Post gives the Horde a foothold deep in Desolace. Scout Felgur Twocuts watches the rival centaur clans from the outpost. Regthar sends seasoned fighters from the Barrens to serve under Felgur. From this camp, the Horde carries its campaign west, from defense to direct action.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1362-2b764ad4c53001a7fd84/1-0000.mp3", duration = 50.7559184, start = 0},
  },
}
P.transport["quest:1365"] = {
  hash = "a4527c",
  fullHash = "a4527c",
  text = "Khan Dez'hepah. After The Kolkar of Desolace, Felgur Twocuts turns against Khan Dez'hepah. Many centaur clans fight across Desolace, and Felgur wants the Kolkar weakened before they unite. Across Desolace, centaur clans fight one another. The Kolkar are one of many, roaming the dry plains and killing their own. Felgur Twocuts does not mourn their losses. Centaur are strong and brutal, and united they would be a fierce foe for the Horde. Felgur wants the Kolkar weakened before that can happen. Felgur Twocuts begins by disrupting the Kolkar. Their village lies northeast of where Felgur stands. Felgur wants Khan Dez'hepah's head brought back.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1365-196d3ffba81ac6c7e0d8/1-0000.mp3", duration = 45.2179592, start = 0},
  },
}
P.transport["quest:1367"] = {
  hash = "12c752",
  fullHash = "12c752",
  text = "Magram Alliance. In Desolace, Gurda Wildmane urges you to turn the centaur clans' hatred against them. Befriend one clan to learn how all can be beaten. If you side with the Magram, slay the Gelkis, then speak with Warug at the edge of Magram Village in southeast Desolace. Gurda Wildmane urges you to turn the centaur clans' hatred against them. Choose one clan as an ally and learn from it how all can be beaten. If you side with the Magram, slaying their foes, the Gelkis, earns their respect. Warug, the Magram spokesman, waits on the outskirts of Magram Village in southeast Desolace once you have earned enough respect. Before then, he has nothing to say to you. The Magram have no words for the weak. They kill them instead. To prove your strength, Warug sends you to face many Gelkis.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1367-be915fc6f41fa793231a/1-0000.mp3", duration = 55.6930612, start = 0},
  },
}
P.transport["quest:1368"] = {
  hash = "947886",
  fullHash = "947886",
  text = "Gelkis Alliance. In southwest Desolace, Gurda Wildmane turns the centaur clans' hatred toward their defeat. Befriend one clan to learn how the others may be beaten. The Gelkis demand that you kill their hated enemies, the Magram, before you meet Uthek the Wise at Gelkis Village. Gurda Wildmane means to turn the centaur clans' hatred against them. Befriend one clan, and what you learn may show how to defeat them all. Choose the Gelkis. To earn their respect, kill the Magram, the clan they hate most. Once the Gelkis respect you, meet Uthek the Wise, their shaman, on the outskirts of Gelkis Village in southwest Desolace. Until then, you are not welcome there. Uthek says you tread on Gelkis earth. Prove your friendship by killing Magram centaur, then return when their blood has soaked the ground.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1368-74ccd4e4f7512e220b34/1-0000.mp3", duration = 55.4840816, start = 0},
  },
}
P.transport["quest:1369"] = {
  hash = "19ba89",
  fullHash = "19ba89",
  text = "Broken Tears. In the Gelkis village cave, Warug wants you to break the crystals they call the tears of Theradras. He asks for three broken pieces, claiming the centaur mother cannot protect them. Warug mocks the Gelkis for trusting Theradras, mother of the centaur, to protect them. He says no one protects the centaur, while the Magram are strongest and need no protection. In a cave in the Gelkis village, the Gelkis hoard crystals called the tears of Theradras. Warug sends you to smash them and bring him three broken pieces. He trusts you with this only if you are no enemy of the Magram.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1369-bc1902fd971fe0e39927/1-0000.mp3", duration = 42.997551, start = 0},
  },
}
P.transport["quest:1370"] = {
  hash = "5a22d0",
  fullHash = "5a22d0",
  text = "Stealing Supplies. In Desolace, Uthek the Wise sends you east after the Magram’s stores. The Gelkis believe meat gives them strength, while the Magram keep supplies for the days between hunts. Uthek the Wise says the Gelkis draw strength from meat. A full belly fights harder than an empty one. The Magram keep extra stores for the days between hunts. So you are sent to their village to the east for six bags of crudely dried meat, to bring back to Uthek at the Gelkis Village.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1370-2fbced51d56718bae776/1-0000.mp3", duration = 29.5444898, start = 0},
  },
}
P.transport["quest:1371"] = {
  hash = "e63be7",
  fullHash = "e63be7",
  text = "Gizmo for Warug. In Magram Village, Warug now wants a new target dummy to replace the wooden human he broke. Warug remembers a gnome who came to Desolace long ago with horses and a cart. Inside were curious things: some burned in different colors, while others moved though they were not alive. Warug killed the gnome, but not before the gnome made him laugh.\n\nWarug kept his favorite thing from the cart, a wooden human that waved at him. He hit it and broke it. Now he wants an advanced target dummy to take its place, and expects one from anyone who is no enemy of the Magram.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1371-068d4e8745c8888f2f81/1-0000.mp3", duration = 36.3363265, start = 0},
  },
}
P.transport["quest:1373"] = {
  hash = "b3b3b4",
  fullHash = "b3b3b4",
  text = "Ongeku. Uthek sends you from Desolace to find a shard of draenethyst. The earth has whispered of the red crystal to him, and Ongeku holds a shard in the Swamp of Sorrows. After Stealing Supplies, Uthek the Wise sends you far from Desolace for a red crystal called draenethyst. He says the earth shares its secrets with those who listen. The crystal has only recently come to this land, carried from a place of flying mountains ruled by demons.\n\nUthek says a shard will make the magic strong. Ongeku, the lost one, holds one in the Swamp of Sorrows in the Eastern Kingdoms. When you return, Uthek will seek proof that the Gelkis can still call you friend.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1373-21497b174394c4daff41/1-0000.mp3", duration = 47.8302041, start = 0},
  },
}
P.transport["quest:1374"] = {
  hash = "dba7f3",
  fullHash = "dba7f3",
  text = "Khan Jehn. At Gelkis Village, Uthek the Wise says Khan Jehn must fall as the Magram grow weak. He asks you to bring the Khan's head back. At Gelkis Village, Uthek the Wise listens to what the earth tells him. The Magram are growing weak, and their Khan, Jehn, is the one to strike down. Uthek asks you to bring back the Magram Khan's head. He expects you to return as a friend of the Gelkis.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1374-266f122aaf5b8cfbbb76/1-0000.mp3", duration = 27.8726531, start = 0},
  },
}
P.transport["quest:1375"] = {
  hash = "bd81a4",
  fullHash = "bd81a4",
  text = "Khan Shaka. Warug of the Magram now sends you after Khan Shaka, the Gelkis Khan. Bring him Shaka’s head so he can stare at it and laugh at his enemy. In Magram Village, Warug says your help has pleased him and served the Magram well. Now he wants Khan Shaka, the Gelkis Khan, killed, and his head brought back. Warug means to stare at it and laugh at his enemy. He expects you to stay on good terms with the Magram.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1375-e142561609c23f8e30e0/1-0000.mp3", duration = 29.0481633, start = 0},
  },
}
P.transport["quest:1380"] = {
  hash = "5e18ea",
  fullHash = "5e18ea",
  text = "Khan Hratha. At Gelkis Village, Uthek the Wise sends you against the Maraudine after your help against the Magram. Their leader, Khan Hratha, carries a piece of a key Uthek wants returned to him. The Gelkis need your help against the Maraudine, Uthek the Wise tells you. Their War Horn stands on a tall bluff in the Valley of Spears. Sound it, and Khan Hratha will answer. But first, you need a warhorn mouthpiece. Only trusted Maraudine centaur carry one, and they are rare. More centaur arrive when the horn sounds. Hratha comes last. Khan Hratha holds a piece of a key. Uthek wants you to bring it to Gelkis Village.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1380-7a2fd44993477f6c0f67/1-0000.mp3", duration = 44.3820408, start = 0},
  },
}
P.transport["quest:1381"] = {
  hash = "c7a227",
  fullHash = "c7a227",
  text = "Khan Hratha. In Desolace, Warug sets his sights on Khan Hratha after the Gelkis Khan's death. He sends you to face the Maraudine Khan and return with the piece of a key he carries. Warug wants Khan Hratha, the Maraudine Khan, dead. A horn on a bluff in the Valley of Spears will draw him out, but first you need its mouthpiece from a Maraudine centaur. Sound the horn and Maraudine centaur gather at the tower. Hratha appears after them. Khan Hratha carries part of a key, and Warug wants you to bring it to him in Magram Village. He expects you to prove yourself an ally of the Magram.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1381-1c430d7bd6ca6c74fcb2/1-0000.mp3", duration = 41.6653061, start = 0},
  },
}
P.transport["quest:1382"] = {
  hash = "0b74cc",
  fullHash = "0b74cc",
  text = "Strange Alliance. Captain Pentigast seeks an alliance with the Gelkis in Desolace. They are at war with the Magram, and he sends you southwest to Uthek the Wise. Captain Pentigast sees a chance in the centaur clans’ quarrels. Joined together, they could not be stopped. He hopes their division will serve the Alliance. The Gelkis and Magram are locked in a brutal war, so striking at the Magram might persuade the Gelkis to join the Alliance. Uthek the Wise is where the Gelkis camps begin in southwestern Desolace. Pentigast hopes she can help secure an alliance. At first, she sends you away. She tells you to return after killing many Magram.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1382-6eb364e610c5801d0a75/1-0000.mp3", duration = 44.042449, start = 0},
  },
}
P.transport["quest:1384"] = {
  hash = "27b251",
  fullHash = "27b251",
  text = "Raid on the Kolkar. In Desolace, Uthek the Wise sends you northeast against the Kolkar centaurs. After Strange Alliance, he wants ten of their charms brought back. Uthek scorns the Kolkar centaurs for trusting in their magic. To him, they know nothing of such things. So you head northeast, kill Kolkar, and take their charms. Uthek wants ten Crude Charms to cast into the fire and laugh as they burn.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1384-e94fa57b1dbeef09efd7/1-0000.mp3", duration = 25.3910204, start = 0},
  },
}
P.transport["quest:1385"] = {
  hash = "5795d1",
  fullHash = "5795d1",
  text = "Brutal Politics. Captain Pentigast fears Desolace’s victorious centaur clan will threaten Alliance strongholds. He seeks a clan’s friendship so the Alliance can learn how to defeat the centaurs. Centaur clans wage war across Desolace. Captain Pentigast fears the victor will turn against Alliance strongholds, so he seeks a way to prevent that danger. The Alliance needs a centaur clan as a friend to learn how to defeat the others. The Magram fight the Gelkis, so attacking the Gelkis may win the Magram’s favor. Earn that favor, then find Warug in the Magram village in southeastern Desolace. Warug says killing Gelkis is how you become a friend to the Magram.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1385-632c5abdc1413fd4ec0d/1-0000.mp3", duration = 46.5502041, start = 0},
  },
}
P.transport["quest:1386"] = {
  hash = "16d7b5",
  fullHash = "16d7b5",
  text = "Assault on the Kolkar. In Magram Village, Warug wants you to prove you can kill Kolkar as the Magram do. After Brutal Politics, you head north to face Kolkar centaurs, scouts and maulers. Warug mocks the Kolkar and their belief that they are strong. The Magram laugh as they kill them, and Warug wants you to prove you can do the same. Head north and slay twelve Kolkar centaurs, twelve scouts and six maulers.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1386-788be787a582f724ce1f/1-0000.mp3", duration = 26.2791837, start = 0},
  },
}
P.transport["quest:1389"] = {
  hash = "09214b",
  fullHash = "09214b",
  text = "Draenethyst Crystals. At the Harborage, Magtoor asks you to recover six draenethyst crystals stolen from the Fallow Sanctuary. Sacred to his people, the crystals are bound to their fear of losing their way. The lost ones of the Fallow Sanctuary resemble Magtoor's people. The journey to Azeroth drove them mad. Once brethren, they now dwell in the Sanctuary to the east, where they seize or kill anyone who strays close. They have also stolen draenethyst crystals, sacred to Magtoor's people. Magtoor's people lack the strength to enter the Fallow Sanctuary and reclaim the draenethyst among its huts and campfires. Without the crystals, they fear they too may lose their way. So Magtoor asks you to bring back six.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1389-c9e3c3a2d16b3a2eb34b/1-0000.mp3", duration = 59.1934694, start = 0},
  },
}
P.transport["quest:1392"] = {
  hash = "f23718",
  fullHash = "f23718",
  text = "Noboru the Cudgel. At the Harborage, the Draenei have endured Noboru the Cudgel’s torment for months. You carry his cudgel to their leader, a token of the cruelty the lost ones have dealt them. For months, Noboru has tormented the Draenei who live at the Harborage. His cudgel recalls the cruelty the lost ones have dealt them. You carry it to their leader.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1392-8d3c1ced2cbba914171b/1-0000.mp3", duration = 26.3314286, start = 0},
  },
}
P.transport["quest:1393"] = {
  hash = "37f20e",
  fullHash = "37f20e",
  text = "Galen's Escape. In the Fallow Sanctuary, Galen Goodward calls for help as creatures close around him. He offers a great treasure from his camp north of Stonard. Galen Goodward calls out from the Fallow Sanctuary, afraid the creatures around him will eat him. He promises a great treasure to anyone who gets him out. It lies in a strongbox at his camp in the swamp north of Stonard. Only Galen knows the trick to open it, and he will teach it to whoever rescues him.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1393-67ca8cba5be1e271e6c1/1-0000.mp3", duration = 27.6897959, start = 0},
  },
}
P.transport["quest:1394"] = {
  hash = "4265d3",
  fullHash = "4265d3",
  text = "Final Passage. You have passed Parqual Fintallas's test and all that came before it. Now he sends you to Dorn Plainstalker in Thousand Needles, who will judge whether your mind, body and spirit have grown strong enough to earn honour. Dorn Plainstalker began the Test of Faith, and its trials now reach their final step. He waits in the Weathered Nook, in a cave reached by a ramp north of Freewind Post. Parqual Fintallas urges you to keep the balance you have shown through the trials.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1394-34b82f57ae8f84caa8de/1-0000.mp3", duration = 32.4440816, start = 0},
  },
}
P.transport["quest:1396"] = {
  hash = "df6476",
  fullHash = "df6476",
  text = "Encroaching Wildlife. After Lost Ones wreck Watcher Biggs's caravan, wild creatures prowl near his camp. Biggs alone survives and asks you to help defend the supplies that remain. This follows Help Watcher Biggs. Watcher Biggs's caravan set out for the eastern coast, but never arrived. Lost Ones attacked, killing the guards and smashing the supplies. Biggs alone survived, and he has sworn to protect what remains. Now wild creatures skulk near the camp, and Biggs asks you to help defend it. Young sawtooth crocolisks, sorrow spinners and swamp jaguars press close to the camp. Biggs names eight crocolisks, ten spinners and ten jaguars to be slain.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1396-1c765bb6a91173bbdd9e/1-0000.mp3", duration = 41.0906122, start = 0},
  },
}
P.transport["quest:1398"] = {
  hash = "599a60",
  fullHash = "599a60",
  text = "Driftwood. Watcher Biggs sends you east to the coast for dry driftwood. He needs it to mend his wagon before he can reach Nethergarde. Watcher Biggs thanks you and asks for help again. His wagon needs repairs before he can reach Nethergarde. The swamp's wood is too spongy and tangled to use, so he needs strong, dry wood. Watcher Biggs sends you east to the coast for driftwood dried by the sun. Bring eight pieces back to him in the Swamp of Sorrows.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1398-210812cc936dad783f3f/1-0000.mp3", duration = 28.9959184, start = 0},
  },
}
P.transport["quest:1418"] = {
  hash = "b5dfe0",
  fullHash = "b5dfe0",
  text = "Neeka Bloodscar. In Stonard, Helgrum the Swift sends you to Kargath, where his messages often fail to arrive. In the Badlands, harsh country near Alliance-held Loch Modan, messages between Stonard and Kargath often fail. Helgrum asks you to prove yourself by traveling to Kargath and speaking with Neeka Bloodscar, its head scout. Then you carry Neeka's report back to Helgrum.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1418-8a612cc318c5dd2f6534/1-0000.mp3", duration = 26.3053061, start = 0},
  },
}
P.transport["quest:1419"] = {
  hash = "62c9d9",
  fullHash = "62c9d9",
  text = "Coyote Thieves. In Kargath, crag coyotes have stolen food, and Neeka Bloodscar wants them hunted. She asks you to bring back thirty jawbones. Neeka Bloodscar asks whether you have spent many days in the Badlands, felt its heat, and met the beasts of its dusty plains. Crag coyotes are tough, and they have crept into Kargath to steal food from the outpost. She wants you to hunt them and bring back their jawbones. Bring enough, and Neeka may believe you know the Badlands.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1419-3d4224bb2fd894a65c92/1-0000.mp3", duration = 29.7795918, start = 0},
  },
}
P.transport["quest:1420"] = {
  hash = "dc0230",
  fullHash = "dc0230",
  text = "Report to Helgrum. At Kargath, Neeka Bloodscar gives you a fresh report for Helgrum the Swift in Stonard. You have just spoken with her there. Neeka Bloodscar gives you a fresh report for Helgrum in Stonard. She warns that anyone who calls themselves an outrunner must keep the way and avoid falling to an enemy.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1420-57b99c17997170e9e39d/1-0000.mp3", duration = 19.6963265, start = 0},
  },
}
P.transport["quest:1421"] = {
  hash = "8147ac",
  fullHash = "8147ac",
  text = "The Lost Caravan. Watcher Biggs needs the caravan's reagents recovered after the Lost Ones carry a wagon north to the Fallow Sanctuary. The chest holds supplies for the wizards of Nethergarde Keep. Watcher Biggs was knocked senseless when the Lost Ones attacked the caravan. Before he fell, he saw them drag one of its wagons north to the Fallow Sanctuary, their village. A chest of reagents was aboard, prized by the wizards of Nethergarde Keep for their studies. Biggs asks you to find the chest and carry its contents back.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1421-12306d53c71226f3ad10/1-0000.mp3", duration = 34.5077551, start = 0},
  },
}
P.transport["quest:1422"] = {
  hash = "c8bf8d",
  fullHash = "c8bf8d",
  text = "Threat From the Sea. Tok'Kar works on your weapon while Katar reports the beach patrols could use help. Tok'Kar works on your weapon and sends you to Katar. Katar says the beach patrols could use help. Some louses at camp drink, but Tok'Kar would rather you keep your wits sharp and your weapons ready than join them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1422-e57fd263427b41f8dc44/1-0000.mp3", duration = 19.6963265, start = 0},
  },
}
P.transport["quest:1423"] = {
  hash = "3b606c",
  fullHash = "3b606c",
  text = "The Lost Supplies. A barrel bound for Nethergarde Keep bears Quartermaster Lungertz’s name. Pungent yellow wax seals the seams of a small, sturdy barrel. Its base carries a stamp naming Quartermaster Lungertz and Nethergarde Keep, marking where it belongs.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1423-7d9d41f458771dad6d18/1-0000.mp3", duration = 15.6734694, start = 0},
  },
}
P.transport["quest:1424"] = {
  hash = "36db9e",
  fullHash = "36db9e",
  text = "Pool of Tears. In Stonard, Fel'zerul sends you to search the Pool of Tears for Atal'ai artifacts. The Warchief's people came to investigate strange events at the Temple of Atal'Hakkar and found it sunk. The Atal'ai trolls are a tribe of dark casters known for forbidden magic. Fel'zerul's party reached the Temple of Atal'Hakkar and found it sunk. Green dragons now watch over the temple and call themselves protectors of Azeroth. Fel'zerul wants to learn what happened, so he asks you to gather Atal'ai artifacts around the Pool of Tears. The pieces may help the puzzle come together. No one knows what dark rites the trolls practiced in the temple, only that they used great magical forces. Fel'zerul hopes their spells may aid the Horde. He wants to learn what the Atal'ai sought and what went so horribly wrong.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1424-d592a05f200cb2830e81/1-0000.mp3", duration = 66.795102, start = 0},
  },
}
P.transport["quest:1425"] = {
  hash = "d8fa81",
  fullHash = "d8fa81",
  text = "Deliver the Shipment. After Driftwood, Watcher Biggs asks you to carry supplies to Quartermaster Lungertz at Nethergarde Keep while his wagon is repaired. Watcher Biggs packs the key supplies rescued from the ogre attacks for you to carry. He stays behind to repair the wagon. Nethergarde Keep lies in the Blasted Lands' northern hills and watches over the Dark Portal. Biggs sends you east along the road, then south into the Blasted Lands where it branches. At the next fork, take the left turn and stay wary.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1425-69ae4a9993526bf3f500/1-0000.mp3", duration = 34.3771429, start = 0},
  },
}
P.transport["quest:1426"] = {
  hash = "5844ba",
  fullHash = "5844ba",
  text = "Threat From the Sea. Tok'Kar sends you to Katar in the Swamp of Sorrows. Katar hates the sea and takes pleasure in seeing fish men fall to those who serve the Horde. Now Katar asks how many you can slay and whether you can face their strongest kind. In the Swamp of Sorrows, Katar asks you to kill marsh murlocs, marsh inkspewers and marsh flesheaters. Katar despises the sea and every creature from it. To Katar, the sea is a strong but blind, callous and brutal mistress. Slaying fish men by the hundreds would delight Katar, if that were possible. For now, watching them fall to those who serve the Horde brings some satisfaction.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1426-8b75500840587ce98d35/1-0000.mp3", duration = 40.6204082, start = 0},
  },
}
P.transport["quest:1427"] = {
  hash = "077bda",
  fullHash = "077bda",
  text = "Threat From the Sea. Katar sends you back to Tok'Kar before you rest. He believes Tok'Kar finished a few weapons while you were away, and one will be offered to you for your help. Before you rest, Katar sends you back to Tok'Kar. He believes Tok'Kar finished a few weapons while you were away. Tok'Kar will offer you one for your help. Katar says you could test its strength against the murlocs when ready, which would please him further.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1427-4b9be81824bd525a2f3e/1-0000.mp3", duration = 28.8653061, start = 0},
  },
}
P.transport["quest:1428"] = {
  hash = "4386e6",
  fullHash = "4386e6",
  text = "Continued Threat. Along the Swamp of Sorrows beach, Katar sees your hatred of the fish men growing like her own. Katar sends you farther along the beach to hunt marsh inkspewers, marsh flesheaters and marsh oracles. Return when you have had enough of the fight. She will take no pleasure until the sea and all her children are silenced, with the repulsive fish men foremost in her thoughts.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1428-8903def9df333e033342/1-0000.mp3", duration = 22.8310204, start = 0},
  },
}
P.transport["quest:1429"] = {
  hash = "d814d8",
  fullHash = "d814d8",
  text = "The Atal'ai Exile. At Stonard, Fel'zerul sends you north with the artifacts from the Pool of Tears. Find an exiled Atal'ai priest in the Hinterlands and learn what the artifacts are for. A blood-marked scroll sentences an Atal'ai priest to a fate worse than death among his own people. He is sent to live with the Witherbark trolls, far north in the Hinterlands. Fel'zerul bundles the artifacts and sends you to find the exile, learn their true use, and return.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1429-02928b626ef008131ae1/1-0000.mp3", duration = 30.7722449, start = 0},
  },
}
P.transport["quest:1430"] = {
  hash = "a8309c",
  fullHash = "a8309c",
  text = "Fresh Meat. Dar needs crawler legs from the coast for hungry customers in Orgrimmar. Dar's customers in Orgrimmar crave crawler meat, especially from the monstrous crawlers. East of here, the creatures scurry over the beaches and into the surf. Bring back some of their legs, and Dar promises a cask of wine. He means to taste the meat before it goes on to Orgrimmar.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1430-10f00e49ae1edd5bd146/1-0000.mp3", duration = 22.4391837, start = 0},
  },
}
P.transport["quest:1437"] = {
  hash = "e5b20a",
  fullHash = "e5b20a",
  text = "Vahlarriel's Search. In Desolace, Vahlarriel Demonslayer searches for two missing nobles of House Malem. Their father fears the worst, and the siblings were last reported crossing the Stonetalon Mountains some weeks ago. Vahlarriel asks you to find their wagon. Vahlarriel Demonslayer seeks Tyranis and Dalinda Malem. Their father has charged Vahlarriel with doing everything possible to find them. The search has only begun, and Vahlarriel hopes it will not keep them in Desolace long. The siblings were last reported crossing the Stonetalon Mountains some weeks ago. You are asked to find their wagon in Desolace and return at once. Its charred remains lie there, with a chest among them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1437-1005e62d5a53f7140025/1-0000.mp3", duration = 43.2326531, start = 0},
  },
}
P.transport["quest:1438"] = {
  hash = "30211d",
  fullHash = "30211d",
  text = "Vahlarriel's Search. At the fortress, Vahlarriel Demonslayer sends you to find Dalinda and Tyranis Malem. Their search begins there as Vahlarriel alerts superiors in Darnassus. They put Dalinda’s safe return first and question Tyranis’s motives. Vahlarriel Demonslayer asks you to seek Dalinda and Tyranis at the fortress and bring back what you learn. Vahlarriel will contact superiors in Darnassus at once. In private, they share their concern about why Tyranis came to Desolace. Above all, they want Dalinda brought home safe. Tyranis’s return can wait until they know more about him.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1438-0c800f2839d2fc7d8e99/1-0000.mp3", duration = 40.2285714, start = 0},
  },
}
P.transport["quest:1439"] = {
  hash = "82feb5",
  fullHash = "82feb5",
  text = "Search for Tyranis. At Thunder Axe Fortress, Dalinda Malem waits to learn what became of Tyranis. Orcs killed their guards and servants before bringing the siblings there. Tyranis tried to speak with his captors, and Dalinda asks you to find him and return once you know his fate. Orcs killed every guard and servant before dragging Dalinda and Tyranis to Thunder Axe Fortress. She expected them to die at once, but their captors had other designs. Tyranis tried speaking with the orcs, perhaps hoping his arcane learning would impress them. Dalinda cannot say why. She will not escape until she knows his fate, so she asks you to find him and return. He is in the building left of the fortress entrance. Dalinda fears Tyranis will seek the Burning Blade's secrets and join them if he can. Power has always drawn him, as magic draws those it seduces. To Dalinda's people, even studying such things is a grave crime. She doubts she could face her family knowing her brother had toyed with that danger.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1439-619da2865a424734235c/1-0000.mp3", duration = 65.2016327, start = 0},
  },
}
P.transport["quest:1440"] = {
  hash = "a5d38a",
  fullHash = "a5d38a",
  text = "Return to Vahlarriel. At Thunder Axe Fortress, Dalinda Malem is ready to leave when you choose. She thanks you for helping her and her family. Escort her out, then find Vahlarriel Demonslayer. Dalinda Malem is ready to leave Thunder Axe Fortress when you judge the moment right. She thanks you for all you have done for her and her family, in case things do not go as hoped. Nothing else keeps her there. She will leave when you choose the time. Escort her out of the fortress, then find Vahlarriel Demonslayer in Desolace.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1440-6ff2690291b5c902b9d1/1-0000.mp3", duration = 31.4253061, start = 0},
  },
}
P.transport["quest:1444"] = {
  hash = "f6b5be",
  fullHash = "f6b5be",
  text = "Return to Fel'Zerul. In the Hinterlands, the Atal'ai Exile sends word to Fel'zerul in Stonard. The artifacts you brought are harmless, but the exile fears what Jammal'an the Prophet may do. The Atal'ai Exile once held Jammal'an the Prophet worthy of the high priesthood. Now the exile fears his unyielding faith in the prophecy may doom the Atal'ai, if it has not already. Speaking out earned the exile the name infidel and banishment from the Temple of Atal'Hakkar.\n\nThe artifacts you brought are harmless. Yet danger may lie in the summoning ritual, for Jammal'an may have found the right fetish enchantment. The world could be in great peril. Fel'zerul in Stonard waits to hear what the exile learned.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1444-f3bfaa6e9eb1b575a803/1-0000.mp3", duration = 44.6171429, start = 0},
  },
}
P.transport["quest:1450"] = {
  hash = "871450",
  fullHash = "871450",
  text = "Gryphon Master Talonaxe. Inside the Aerie Peak Aviary, flight assignments fall to Gryphon Master Talonaxe. Falstad Wildhammer sends you there after turning away someone who came for an old Explorers' League friend. Falstad Wildhammer has little patience for a visitor sent by an old Explorers' League member. He does not know who that friend once flew with, and flight assignments belong to the gryphon master. You can find Gryphon Master Talonaxe inside the Aerie Peak Aviary. Falstad has real work for anyone who stays nearby.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1450-abfbdbf14e9151260889/1-0000.mp3", duration = 39.4187755, start = 0},
  },
}
P.transport["quest:1451"] = {
  hash = "492450",
  fullHash = "492450",
  text = "Rhapsody Shindigger. At the Aerie Peak Aviary, Talonaxe has news of a fallen flyer. Rhapsody Shindigger was once its finest flyer, but liquor cost Rhapsody the post. Now Rhapsody keeps a brewing camp east of the aviary, in the Hinterlands, Talonaxe has heard. Gryphon Master Talonaxe says the aviary dwarves all enjoy a good ale. Rhapsody took to liquor as readily as a gryphon takes to the skies. No one could fly like Rhapsody, and Talonaxe still regrets the loss.\n\nThe trouble began when Rhapsody returned stumbling from a trip with Brohann. Things worsened quickly, and the aviary let Rhapsody go. Talonaxe’s last word is that Rhapsody now keeps a brew camp east of Aerie Peak.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1451-1c044dda18cc333e6a50/1-0000.mp3", duration = 47.882449, start = 0},
  },
}
P.transport["quest:1452"] = {
  hash = "833394",
  fullHash = "833394",
  text = "Rhapsody's Kalimdor Kocktail. In the Hinterlands, Rhapsody Shindigger is ready to tell you what happened in the swamp, once he has a stiff drink. His Kalimdor Kocktail needs Roc gizzards from Tanaris and Groddoc and Ironfur livers from Feralas. Rhapsody greets Brohann's messenger with a hiccup. The two shared quite an adventure, but Rhapsody will tell you what happened in the swamp only after a stiff drink. The tale is not pretty. He has a recipe in mind: the Kalimdor Kocktail. Once it is brewed, he promises to tell you everything. Rhapsody needs three Roc gizzards from Tanaris, three Groddoc livers from Feralas, and three Ironfur livers from Feralas. Even his finest malt cannot help him face the memory of that fateful flight over the swamp.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1452-2c291b5b7c76ac28a836/1-0000.mp3", duration = 53.3942857, start = 0},
  },
}
P.transport["quest:1454"] = {
  hash = "1f5a6d",
  fullHash = "1f5a6d",
  text = "The Karnitol Shipwreck. After sea giants strike his ship in Desolace, Karnitol flees with his servants by teleporting away. Kreldig Ungor sends you to find the noble's chest. After Reclaimers' Business in Desolace, Kreldig Ungor sends you to find Karnitol's lost chest. Karnitol is a mage and some kind of noble in Stormwind. Sea giants struck his ship in the northwest waters of Desolace.\n\nHe and his servants tried to bring one of his costlier chests ashore, but the giants swarmed them. Karnitol left the chest behind and teleported away with his servants. Find the chest and its contents, then return them to Karnitol in Stormwind. It lies along the northern coastline, in the Ethel Rethor stretch.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1454-a452cb718027a1c32991/1-0000.mp3", duration = 47.6734694, start = 0},
  },
}
P.transport["quest:1455"] = {
  hash = "40fc37",
  fullHash = "40fc37",
  text = "The Karnitol Shipwreck. At Karnitol's wreck, you find the chest open and empty. Deep scratches score its sides and top, so you return to Kreldig Ungor at Nijel's Point. The chest lies empty, its sides and top scored with long, deep scratches. The marks suggest neither man nor giant forced it open. They look unlike cuts from a dagger or sword. With nothing more to learn, you close the chest and prepare to leave. Kreldig Ungor will be disappointed.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1455-67654f1088f7595bdcaf/1-0000.mp3", duration = 29.5967347, start = 0},
  },
}
P.transport["quest:1456"] = {
  hash = "3be068",
  fullHash = "3be068",
  text = "The Karnitol Shipwreck. Near Ranazjar Isle, Kreldig Ungor still hopes Karnitol's belongings can be found. The Slitherblade naga live among night elf ruins beneath the sea, where Kreldig thinks the satchel is most likely to be. Kreldig Ungor says there is still hope of finding Karnitol's belongings. Farther north along the coast, sunken night elf ruins lie on the ocean floor near Ranazjar Isle. The Slitherblade naga live there, and Kreldig believes it is the likeliest place to find Karnitol's satchel. He gives you a Recovery Diver's Potion. Kreldig believes the scouting party that traveled so far south must have been strong. He would search the mightier naga first: the tidehunters and sea witches.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1456-4de7828d3be637bc2cb7/1-0000.mp3", duration = 47.124898, start = 0},
  },
}
P.transport["quest:1457"] = {
  hash = "f41c46",
  fullHash = "f41c46",
  text = "The Karnitol Shipwreck. Karnitol's satchel waits in Ironforge for Roetten Stonehammer, who will pay you to carry it there. Kreldig Ungor sends you to take Karnitol's things to Roetten Stonehammer in Ironforge. Roetten will pay you for the work. With a laugh, Kreldig says Roetten may be so pleased that he asks you to join the Reclaimers full time. Travel carefully and without delay. Karnitol has little patience, though he is generous.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1457-7930fc2b3f631e046288/1-0000.mp3", duration = 29.4922449, start = 0},
  },
}
P.transport["quest:1458"] = {
  hash = "d1f7b6",
  fullHash = "d1f7b6",
  text = "Reagents for Reclaimers Inc.. In Desolace, Kreldig Ungor gathers reagents for Leftwitch, a gnome mage in Kharanos. The Reclaimers are short-handed, so he begins with claws and horns from the Hatefury satyrs to the east. After Reclaimers' Business in Desolace, Kreldig Ungor takes on another job. He gathers reagents for Leftwitch, a gnome mage who lives in Kharanos. Roetten calls it easy coin because the Reclaimers are already in Desolace. The crew is short-handed, but Kreldig says he does not care. Kreldig begins with ten claws and ten horns from the Hatefury satyrs to the east. They dwell in the Sargeron ruins, due east of Nijel's Point. Once you have the claws and horns, the rest of Leftwitch's list can begin.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1458-d3f70c44733ab1637382/1-0000.mp3", duration = 45.2179592, start = 0},
  },
}
P.transport["quest:1459"] = {
  hash = "095ff3",
  fullHash = "095ff3",
  text = "Reagents for Reclaimers Inc.. In Desolace, Leftwitch's list sends Kreldig Ungor after scorpashi venom and aged kodo hides. He barely knows the land and cannot point you toward either creature. Kreldig Ungor reaches the next items on Leftwitch's list. She asks for seven vials of venom from any scorpashi and three hides from aged kodo. Dying and ancient kodo will not do. The instructions are plain, though Kreldig muses that mages ask for odd things. Kreldig cannot tell you where the kodo or scorpashi roam. He barely knows Desolace and has had no time to explore it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1459-3e7bf42fe2e4c5b851c9/1-0000.mp3", duration = 37.4334694, start = 0},
  },
}
P.transport["quest:1465"] = {
  hash = "e3544e",
  fullHash = "e3544e",
  text = "Vahlarriel's Search. In Desolace, Vahlarriel's Search follows a trail south from the Malems' wagon. A pendant lies there, and smoke rises from a large fort in the distance. At Nijel's Point, Vahlarriel Demonslayer needs the pendant and word that the Malems may still be alive. You find a pendant in the Malems' wagon and footprints leading south. Smoke rises from a large fort in the distance. A tended fire feeds it, rather than burning buildings. If the Malems are alive, the tracks suggest they were taken toward the fort. At Nijel's Point, Vahlarriel Demonslayer needs to see the Malem Pendant. Tell her about the footprints leading south.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1465-1c12ef44aafc255be6ec/1-0000.mp3", duration = 44.7477551, start = 0},
  },
}
P.transport["quest:1466"] = {
  hash = "012b39",
  fullHash = "012b39",
  text = "Reagents for Reclaimers Inc.. In Desolace, Kreldig Ungor has the last items Leftwitch requested. They all come from demons: brains, wings, and blood. Kreldig Ungor warns you that the final set is grim and slower to gather than any before. Leftwitch wants ten of each of three kinds of parts. You can take felhound brains from mana eaters, mage hunters, or ley hunters. The wings come from nether maidens, sisters, or sorceresses, while doomwarder captains and lords carry the blood. Kreldig would understand if you passed on this one. Kreldig Ungor had not known these demons lived in Desolace. His reading said the centaur held most of the land after the night elves departed years ago. So he wonders how the demons came here and why they settled. They dwell near Mannoroc Coven in southern Desolace, beyond the Kodo Graveyard.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1466-18a0d7251aba8a58072e/1-0000.mp3", duration = 52.6628571, start = 0},
  },
}
P.transport["quest:1467"] = {
  hash = "0be1c2",
  fullHash = "0be1c2",
  text = "Reagents for Reclaimers Inc.. In Desolace, Kreldig Ungor sends you to Ironforge with Leftwitch's package. Roetten Stonehammer has your pay, and Kreldig plans to speak well of you when he returns home. Kreldig says Roetten Stonehammer has your pay in Ironforge. Roetten will be glad to receive Leftwitch's package, and handing it over should be enough to collect what you are owed. Kreldig expects to stay in Desolace only a little longer. Once he is home, he still means to speak well of you.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1467-aeb91ae70f1409a3aeba/1-0000.mp3", duration = 29.3877551, start = 0},
  },
}
P.transport["quest:1469"] = {
  hash = "b16f4c",
  fullHash = "b16f4c",
  text = "Rhapsody's Tale. After Rhapsody Shindigger gets his Kalimdor Kocktail, he tells of the flight with Brohann Caskbelly. He gives you an Atal'ai Tablet Fragment to take to Brohann in Stormwind. Rhapsody Shindigger tells you what happened after the kocktail. Before the flight, he drank a whole keg of stout while Brohann followed him through the sky. Rhapsody kept a troll souvenir, an Atal'ai Tablet Fragment. Now he asks you to take it to Brohann Caskbelly in Stormwind.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1469-1524997717e19fbabf92/1-0000.mp3", duration = 34.4293878, start = 0},
  },
}
P.transport["quest:1480"] = {
  hash = "c75c49",
  fullHash = "c75c49",
  text = "The Corrupter. At Thunder Axe Fortress, a flayed strip from the Burning Blade bears red markings and a signature-like symbol. It smells rotten, yet bends easily. Maurin Bonesplitter at Ghost Walker Post may know more. The flayed skin smells of rot, yet bends easily despite its dry, fragile feel. Unrolled, it shows red markings on one side, written in some kind of language. A plain symbol at the bottom looks like a signature. Maurin Bonesplitter at Ghost Walker Post may know more about the skin. Maurin believes the Burning Blade are coming to see how weak they are. Their magic is poor and their strength slight. Whatever power they hold comes from those they serve, not from any grasp of true power or knowledge.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1480-fe1be2eb361d88cedadc/1-0000.mp3", duration = 49.397551, start = 0},
  },
}
P.transport["quest:1481"] = {
  hash = "9a56fa",
  fullHash = "9a56fa",
  text = "The Corrupter. Maurin Bonesplitter searches for a way to find The Corrupter, though its wards may foil scrying. He needs a Hatefury shadowstalker scalp from the old ruins in northeast Desolace, near Sargeron. Maurin Bonesplitter believes the right reagents can reveal the demon lord. If Maurin is right about its power, those reagents must come from deadly creatures. He trusts you to face that danger in the Warchief's name.\n\nFirst, the demon lord's wards against scrying must be broken. Maurin asks you for a satyr's scalp, and only a Hatefury shadowstalker's will serve. Search the old ruins in northeast Desolace, near Sargeron. Maurin warns you to bring back the right scalp. Wrong reagents could get people killed, for the demon lord may have contingency spells meant to slay anyone who tries to scry on him. Fate has already dealt out enough pain, he says.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1481-aaec7577068595de6571/1-0000.mp3", duration = 60.4995918, start = 0},
  },
}
P.transport["quest:1482"] = {
  hash = "ae4fd7",
  fullHash = "ae4fd7",
  text = "The Corrupter. Maurin Bonesplitter seeks an oracle crystal to find the demon lord Azrethoc. Northwest along the coast, the Slitherblade naga dwell in a vast coral reef, and they will take your intrusion badly. Maurin Bonesplitter needs an oracle crystal to find the demon lord Azrethoc. The skin you brought him bore Azrethoc's signature. Naga craft these crystals for their oracles, who dwell in a vast coral reef northwest along the coast. The Slitherblade naga live there near the shore. They are deadly and will take your intrusion badly, so Maurin urges you to move carefully and quickly. Maurin says finding and destroying Lord Azrethoc would earn you both much favor with the Warchief. Working together and moving swiftly serves each of your aims.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1482-20e334faef9fa92667e2/1-0000.mp3", duration = 50.3902041, start = 0},
  },
}
P.transport["quest:1484"] = {
  hash = "ac3d0e",
  fullHash = "ac3d0e",
  text = "The Corrupter. Near Maurin Bonesplitter, the demon lord has proved more dangerous than he expected. Maurin believes Takata Steelblade doubts his skill, and that withholding what happened would dishonor Takata. So he sends you to speak with the swordsman nearby. The demon lord has proved more dangerous than Maurin Bonesplitter expected. Maurin believes Takata Steelblade doubts he can handle the creature, and keeping Takata uninformed would insult the swordsman's honor.\n\nMaurin asks you to speak with Takata and offer to slay the demon, if Takata allows it. He cautions you not to press too hard, for he thinks Takata should believe the idea is his own. Takata Steelblade is nearby, across the path from Maurin. He stands on a cliff overlooking the Kodo Graveyard.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1484-4cfd45b7e6f6aacb1ba6/1-0000.mp3", duration = 57.1820408, start = 0},
  },
}
P.transport["quest:1488"] = {
  hash = "7fe279",
  fullHash = "7fe279",
  text = "The Corrupter. Takata Steelblade sides with Maurin: Lord Azrethoc must be stopped, especially if he seeks influence over the Burning Blade. Takata trusts you to gather a party against the demon lord and his warlock servant, Jugkar Grim'rod. Takata has never heard of Lord Azrethoc, but agrees with Maurin that the demon lord must be stopped. The danger grows if Azrethoc is trying to sway the Burning Blade. You have already shown that you want to aid the Warchief, so Takata trusts you to gather a party and slay Azrethoc and his warlock servant, Jugkar Grim'rod. Head directly south to Mannoroc Coven, where both are found. Takata calls the demons in Desolace a greater threat than ever. Each newly arrived foul creature dims the prospect of returning to the Warchief. At times, Takata wishes the centaur were the only enemy.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1488-36b42095d6319821a721/1-0000.mp3", duration = 59.1934694, start = 0},
  },
}
P.transport["quest:1560"] = {
  hash = "59dd36",
  fullHash = "59dd36",
  text = "Tooga's Quest. In Tanaris, you and Tooga are trying to reach Torta. She waits just south of Steamwheedle Port. Tooga wanders near a crashed goblin zeppelin by Thistleshrub Valley, unsure of the way home. His wife, Torta, sent him to fetch dinner. A wrong turn left him lost, so he asks you to lead him back to her. Torta waits just south of Steamwheedle Port, across Tanaris from Tooga. Reaching her means walking nearly the whole width of the zone.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1560-cefaf0d9407ea99b71d8/1-0000.mp3", duration = 29.5183673, start = 0},
  },
}
P.transport["quest:162"] = {
  hash = "b03b2e",
  fullHash = "b03b2e",
  text = "Rise of the Silithid. Senior Surveyor Fizzledowser sends you to Darnassus with a report for Gracina Spiritmight, a night elf scholar and historian. Senior Surveyor Fizzledowser wants the report in the hands of someone who knows such matters. Gracina Spiritmight is a night elf scholar and historian. She has spent much time studying life forms unique to Azeroth's ecology. Fizzledowser hopes she can judge the danger and find a way to halt it. At Fizzledowser's last word, Gracina lives in the Temple of the Moon in Darnassus.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_162-3de7f03ee2441a1a1e5b/1-0000.mp3", duration = 37.12, start = 0},
  },
}
P.transport["quest:1690"] = {
  hash = "b9f378",
  fullHash = "b9f378",
  text = "Wastewander Justice. In Tanaris, the Wastewander hold nearly every well, and Gadgetzan's water supply is at risk. Chief Engineer Bilgewhizzle sends you east of town to bring justice to the Wastewander Bandits and Thieves. Without access to the wells held by Wastewander nomads, Gadgetzan's water supply will soon run dry. Chief Engineer Bilgewhizzle wants you to bring down ten Wastewander Bandits and Thieves east of town. Then you are to report back at once. He has a taste for goblin-style justice.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1690-85eb2cd4cf836dcdf539/1-0000.mp3", duration = 32.1306122, start = 0},
  },
}
P.transport["quest:1691"] = {
  hash = "9c9147",
  fullHash = "9c9147",
  text = "More Wastewander Justice. East and southeast of Gadgetzan, Bilgewhizzle now targets Wastewander rogues, assassins, and shadow mages. With fewer nomads left, the company can more easily reclaim the water wells. Chief Engineer Bilgewhizzle says you have done well, but the company needs fewer nomads before it can reclaim the wells. Now you face their rogues, assassins, and shadow mages east and southeast of Gadgetzan. Bilgewhizzle calls them a nasty lot. He insists the wells rightfully belong to the company.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1691-b38967bb9a476f385eae/1-0000.mp3", duration = 32.1044898, start = 0},
  },
}
P.transport["quest:1707"] = {
  hash = "671821",
  fullHash = "671821",
  text = "Water Pouch Bounty. In Gadgetzan, Spigot Operator Luglunket asks you to recover the Wastewander water pouches stolen by the nomads. Bring them back from anywhere in the desert, and the Gadgetzan Water Company offers an official care package for every five. Spigot Operator Luglunket wants you to bring back the Wastewander water pouches you find in the desert. The nomads stole Gadgetzan's water, so every pouch helps the town reclaim what is its own. For every five pouches returned, the Gadgetzan Water Company offers an official care package.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1707-73f8327575ffbfc2a08b/1-0000.mp3", duration = 38.2171429, start = 0},
  },
}
P.transport["quest:1712"] = {
  hash = "1b8af2",
  fullHash = "1b8af2",
  text = "Cyclonian. At the summoning site, Cyclonian waits for a champion bold enough to face him. A special parchment names the rare materials needed to call forth the wind lord, whose whirlwind heart can strengthen a formidable weapon. A watcher has kept vigil at the summoning site for ages. The raging elemental wind lord awaits a combatant with the raw martial prowess to challenge and destroy him. A special parchment names the rare materials needed to summon Cyclonian. Once the wind lord is called forth, you face him in direct combat. You may defeat him, or fall to his howling gale.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1712-8cce1829994acbe114d6/1-0000.mp3", duration = 44.6171429, start = 0},
  },
}
P.transport["quest:1713"] = {
  hash = "cf8d2e",
  fullHash = "cf8d2e",
  text = "The Summoning. At Bath'rah Windwatcher's camp, a warrior faces a trial against Cyclonian, the wind lord. Slay the elemental and claim the Whirlwind Heart, whose storm force can be bound into a weapon. Bath'rah Windwatcher has prepared an ancient ritual to summon Cyclonian into the mortal realm. The fearsome elemental is known as the wind lord. There will be no bargain with the tempest. An able champion must strike it down as soon as it takes form. Cyclonian's Whirlwind Heart sustains his physical form. When the wind lord falls, Bath'rah wrenches the heart free and harnesses the gale within. Its volatile power can imbue a weapon with the force of the storm.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1713-84479f8867bfff95a2ed/1-0000.mp3", duration = 45.7926531, start = 0},
  },
}
P.transport["quest:1714"] = {
  hash = "1136c4",
  fullHash = "1136c4",
  text = "Essence of the Exile. At the cauldron, Essence of the Exile draws travelers with its beckoning vapors. Charms set off a violent reaction that reveals molten rock. A bubbling cauldron sends out vapors that draw travelers to its churning depths. Specific enchanted charms stir an intense reaction within the vessel. The charms sink slowly through the liquid. Then a large bubble rises and bursts, revealing a churning lump of molten rock forged from the combined materials.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1714-40ab6c92b41b690dcdef/1-0000.mp3", duration = 30.5632653, start = 0},
  },
}
P.transport["quest:1792"] = {
  hash = "bc6767",
  fullHash = "bc6767",
  text = "Whirlwind Weapon. A warrior's chosen weapon awaits the storm Cyclonian left behind. The whirlwind heart can bind the elemental's fury into a forged vessel. After Cyclonian falls and the warrior claims its heart, a craftsperson prepares a weapon to hold the storm's power. The heart is fused into the chosen arm, turning forged metal into a channel for elemental fury. Cyclonian's heart holds the violence of howling winds and tempestuous gales. Bound into a forged weapon, it lends the wielder the living might of the storm alongside their own martial skill. Each strike carries the force of the defeated elemental, whose storm now rages in the hands of its vanquisher.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1792-a8262347e07ce89296b0/1-0000.mp3", duration = 51.7485714, start = 0},
  },
}
P.transport["quest:186"] = {
  hash = "f57b13",
  fullHash = "f57b13",
  text = "Tiger Mastery. At Nesingwary's Expedition in northern Stranglethorn Vale, Ajeck Rouack sends you to hunt mature tigers. After you defeat young stalkers, she sets you against ten mature Stranglethorn Tigers. Ajeck Rouack sends you to hunt ten mature Stranglethorn Tigers. Your success against younger predators has brought you to a harder test in the wilds of Stranglethorn Vale. Greater challenges lie beyond this hunt.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_186-7b7b47d55825a224b6a9/1-0000.mp3", duration = 25.2081633, start = 0},
  },
}
P.transport["quest:187"] = {
  hash = "4abb4e",
  fullHash = "4abb4e",
  text = "Tiger Mastery. At Nesingwary's Expedition, Ajeck Rouack sends you after ten elder Stranglethorn tigers. Their deaths will prove your skill before the final test. Ajeck Rouack sends you into the wilds to hunt ten elder Stranglethorn tigers. He says they are the hardest cats to track and the fiercest to overcome. Their deaths prepare you for a final trial. After it, he promises to proclaim you a master tiger hunter before Master Nesingwary.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_187-34d3e0b2491eee5c0a7a/1-0000.mp3", duration = 28.1077551, start = 0},
  },
}
P.transport["quest:1878"] = {
  hash = "3afc11",
  fullHash = "3afc11",
  text = "Water Pouch Bounty. In Gadgetzan, Spigot Operator Luglunket welcomes you back for five more Wastewander water pouches. A care package waits with your name on it. Luglunket welcomes you back and asks for five more Wastewander water pouches. A care package is already set aside with your name on it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1878-fb656a0e345678504f69/1-0000.mp3", duration = 20.1926531, start = 0},
  },
}
P.transport["quest:188"] = {
  hash = "f38c27",
  fullHash = "f38c27",
  text = "Tiger Mastery. At Nesingwary's Expedition, Ajeck Rouack sends you after a tiger his hunters have tracked for weeks. Sin'Dall waits in northern Stranglethorn Vale, and her paw will prove the hunt is done. At Nesingwary's Expedition, Ajeck Rouack sends you on one last hunt after your earlier trials against Stranglethorn's tigers. His hunters have tracked Sin'Dall through the jungle for weeks. Find the elusive tiger, kill her, and bring back her paw as proof.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_188-06c36f5aed25b382d9a7/1-0000.mp3", duration = 27.7420408, start = 0},
  },
}
P.transport["quest:189"] = {
  hash = "1fa456",
  fullHash = "1fa456",
  text = "Bloodscalp Ears. In Booty Bay, Bloodscalp Ears bring Kebok a way to answer for mounting losses. He pays for proof of a kill after clashes with the Bloodscalp tribe have cost him guards and agents. In Stranglethorn Vale, Bloodscalp trolls are killing Kebok's agents and guards. Many of his best guards have fallen in jungle skirmishes. The mounting costs leave him anxious about explaining them to Baron Revilgaz. Kebok offers coin to travelers who hunt Bloodscalp trolls in the jungle. He asks you to bring back fifteen severed ears as proof of the kills.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_189-6fb844cf0485f41d20b7/1-0000.mp3", duration = 37.5640816, start = 0},
  },
}
P.transport["quest:191"] = {
  hash = "1f59c4",
  fullHash = "1f59c4",
  text = "Panther Mastery. At Nesingwary's Expedition, Sir S. J. Erlgadin asks you to prove your worth among the seasoned hunters. After your hunt for young panthers, he sends you into Stranglethorn Vale for ten fully grown beasts. Your hunt for young panthers is done, and Sir S. J. Erlgadin sets a higher standard. He asks you to prove you can keep company with the expedition's seasoned big game hunters. So you set out to track and slay ten mature panthers, stronger and more dangerous than their young kin.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_191-6da4df37165e3cf81a02/1-0000.mp3", duration = 32.3918367, start = 0},
  },
}
P.transport["quest:192"] = {
  hash = "3da7a8",
  fullHash = "3da7a8",
  text = "Panther Mastery. In Stranglethorn Vale, Panther Mastery sends you after the deadliest panthers. After your earlier trials, ten Shadowmaw Panthers are your quarry. Sir S. J. Erlgadin calls Shadowmaw Panthers the most dangerous cats in Stranglethorn's jungles. To prove yourself as a stalker, you crawl through dense underbrush and track ten elusive beasts. Their ferocity makes them harder to kill than to find.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_192-22e23a2c5be7419d3667/1-0000.mp3", duration = 23.8759184, start = 0},
  },
}
P.transport["quest:193"] = {
  hash = "1d5a09",
  fullHash = "1d5a09",
  text = "Panther Mastery. At Nesingwary's Expedition, Sir S. J. Erlgadin sets one final trial for you. You have hunted panthers before, but the expedition's party has failed to find Bhag'thera. Bring back the predator's fang to prove your skill as a master of the hunt. At Nesingwary's Expedition, Sir S. J. Erlgadin sets one last test for you. Bhag'thera still prowls Stranglethorn Vale, beyond the expedition's party's reach. Track down the great panther and bring back its fang as proof of your skill.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_193-b294cf02d2c5bd8ee652/1-0000.mp3", duration = 32.5746939, start = 0},
  },
}
P.transport["quest:194"] = {
  hash = "021d3d",
  fullHash = "021d3d",
  text = "Raptor Mastery. At his northern Stranglethorn camp, Hemet Nesingwary tests your hunting skill. He asks you to find and slay ten Stranglethorn Raptors. After Welcome to the Jungle, Hemet Nesingwary tests your skill at tracking and hunting in the jungle. He gives you no map or directions. Finding the Stranglethorn Raptors is part of the trial, and you need to bring down ten of the fierce beasts.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_194-22f0447d5e216f55bdb9/1-0000.mp3", duration = 25.1036735, start = 0},
  },
}
P.transport["quest:195"] = {
  hash = "bee2c0",
  fullHash = "bee2c0",
  text = "Raptor Mastery. In Stranglethorn Vale, Hemet Nesingwary sends hunters after deadlier quarry. After their first raptor hunt, he asks them to track and kill ten Lashtail Raptors. North of Grom'gol Base Camp, Hemet Nesingwary sends hunters into dense jungle brush. After their first raptor hunt, he expects them to prove their focus and skill with deadlier quarry. Ten fierce Lashtail Raptors must be tracked and killed.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_195-de07ffda6a6979dec716/1-0000.mp3", duration = 27.3240816, start = 0},
  },
}
P.transport["quest:196"] = {
  hash = "bc9b57",
  fullHash = "bc9b57",
  text = "Raptor Mastery. In Stranglethorn Vale, Hemet Nesingwary sends you after Jungle Stalkers. Ten wary raptors stand between you and his finest hunt. Hemet Nesingwary sends you after Jungle Stalkers, a harder quarry than the raptors you hunted before. They are wary and hard to track or kill. Find and fell ten in the jungle, then return to camp. Hemet will give you a lead on his finest hunt yet.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_196-a6f3749dcd74aa4505de/1-0000.mp3", duration = 25.7306122, start = 0},
  },
}
P.transport["quest:197"] = {
  hash = "0f0599",
  fullHash = "0f0599",
  text = "Raptor Mastery. In Stranglethorn Vale, Hemet Nesingwary sends you after the raptor that has eluded even him. After your trials against lesser beasts, you are to track Tethis and bring its talon back to Hemet. Hemet Nesingwary tells you of Tethis, a vicious raptor that has escaped every hunter, even the expedition leader. Ajeck Rouack gave the beast its name. Among Stranglethorn's raptors, Tethis is the greatest challenge for a hunter. Tethis roams north of the Gurubashi Arena. Bring Hemet a talon from the slain raptor, and he will recognize you as a master raptor slayer. No other big game hunter has achieved that feat.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_197-97e94c6541c65f88ffad/1-0000.mp3", duration = 44.2253061, start = 0},
  },
}
P.transport["quest:198"] = {
  hash = "496c55",
  fullHash = "496c55",
  text = "Supplies to Private Thorsen. Krazek needs a courier in Booty Bay to carry supplies north to Private Thorsen. Troll attacks have stopped the regular shipments to Lieutenant Doren's camp near the northern border. Lieutenant Doren's men guard the border between Stranglethorn Vale and Duskwood. Krazek arranges regular shipments for them, but local trolls keep attacking. The usual deliveries have become dangerous, so the goblin merchant hires you to carry a package north along the jungle road. Private Thorsen can receive it at the camp northwest of the road or along his patrol route to the south.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_198-31b6fa154e2b5965677c/1-0000.mp3", duration = 35.0302041, start = 0},
  },
}
P.transport["quest:200"] = {
  hash = "4d59b2",
  fullHash = "4d59b2",
  text = "Bookie Herod. A leak has Lieutenant Doren searching his ranks for a traitor. Kurzen has learned Thorsen's secret, and Doren wants the records of Bookie Herod, Kurzen's logistics officer, from Kurzen's Compound. Lieutenant Doren suspects a traitor among his men. Kurzen learned Thorsen's secret, and the leak threatens their operations. So Doren needs to find its source. Thorsen kept a line into Kurzen's Compound through Bookie Herod, the colonel's logistics officer. Herod's written records may show how the operation was exposed. Bookie Herod's papers are inside Kurzen's Compound. When Doren served under Kurzen, Herod's office was on the top floor of the compound's only two-story house. Supply requisitions and messages from Colonel Kurzen may reveal how Thorsen's secret was betrayed.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_200-01decb724c945d25c2eb/1-0000.mp3", duration = 58.8277551, start = 0},
  },
}
P.transport["quest:201"] = {
  hash = "c978ac",
  fullHash = "c978ac",
  text = "Investigate the Camp. Krazek has heard Hemet Nesingwary may be in Stranglethorn Vale. He asks you to find the hunters' camp near Lake Nazferiti and confirm the report. Booty Bay reports place a hunters' camp in northern Stranglethorn Vale. Krazek has heard it lies along the river, just beyond the Venture Company's mining claim near Lake Nazferiti. The jungle is lawless, with dangers and competing interests. An armed camp draws notice. Hemet Nesingwary may be among the hunters at the camp. The renowned dwarven marksman is known across the lands as an elite explorer with influential ties. Krazek sends you upriver to learn whether the legendary hunter has arrived.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_201-d48237e50739a433156b/1-0000.mp3", duration = 40.8816327, start = 0},
  },
}
P.transport["quest:202"] = {
  hash = "d6b06f",
  fullHash = "d6b06f",
  text = "Colonel Kurzen. At the Rebel Camp, Lieutenant Doren sends you against Colonel Kurzen and his inner guard. Their defeat could secure the rebels' survival. Lieutenant Doren's defectors have reached the final struggle against their former commander. You have helped suppress Kurzen's elite specialists, but the rebels remain in danger while he holds his jungle redoubt. Doren sends you into the Stockpile cave, where Kurzen directs his forces beside his subchiefs and elites. Lieutenant Doren needs proof that Kurzen has fallen. He asks you to bring back the rogue colonel's head and defeat his elites and subchiefs. The cave confrontation gives the rebels their only chance to breathe easier amid the dangers of northern Stranglethorn.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_202-b76c84b76ece84707ed1/1-0000.mp3", duration = 52.0359184, start = 0},
  },
}
P.transport["quest:203"] = {
  hash = "51a756",
  fullHash = "51a756",
  text = "The Second Rebellion. At the Rebel Camp in northern Stranglethorn Vale, Sergeant Yohwa calls for aid against Colonel Kurzen's overwhelming force. Outnumbered ten to one, the rebels cannot fight a long, open war. They strike swiftly and in secret, hoping to thin Kurzen's ranks and ease the pressure on their refuge. At the Rebel Camp, the rebels face Colonel Kurzen's force with at least ten foes for every one of their own. Sergeant Yohwa knows the Colonel is a brilliant military tactician. An open war of attrition would leave the rebels with no chance.\n\nSo they turn Kurzen's covert methods against him. They strike quickly at his encampment, then flee before heavy reinforcements can answer. Sergeant Yohwa asks you to head east into Kurzen's stronghold and eliminate a sizable contingent of his jungle fighters. Their numbers press hard on the Rebel Camp. Thin their ranks, and the refuge can breathe easier.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_203-88d78d7e55c56e2e2d97/1-0000.mp3", duration = 65.0187755, start = 0},
  },
}
P.transport["quest:204"] = {
  hash = "2dc6d3",
  fullHash = "2dc6d3",
  text = "Bad Medicine. At the Rebel Camp in northern Stranglethorn Vale, Sergeant Yohwa seeks a way to weaken Colonel Kurzen's force. His medicine men heal his soldiers and poison Yohwa's fighters, and the resistance needs their remedies and toxins. Colonel Kurzen's medicine men heal his soldiers and poison Yohwa's fighters with venom fern extract. Sergeant Yohwa asks you to gather their supplies from the Kurzen Compound. The remedies can treat wounded fighters at the Rebel Camp. A sample of venom fern extract will let the resistance study the toxin and make cures of its own.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_204-06c460ed876c61ce8a5f/1-0000.mp3", duration = 35.4742857, start = 0},
  },
}
P.transport["quest:205"] = {
  hash = "00e586",
  fullHash = "00e586",
  text = "Troll Witchery. Brother Nimetz sends you into Skullsplitter territory to learn what has corrupted Colonel Kurzen. After Kurzen's Mystery, he asks you to gather fetishes from the tribe's spellcasters. Brother Nimetz suspects dark troll magic lies behind Colonel Kurzen's fall into evil. Legends recovered from the jungle have led him to the second troll tribe farther south. So he asks you to enter Skullsplitter lands and take fetishes from their Witch Doctors and Mystics. He will study the magic they carry at the Rebel Camp.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_205-09f8d55310ed7c388882/1-0000.mp3", duration = 31.1118367, start = 0},
  },
}
P.transport["quest:206"] = {
  hash = "6c9a51",
  fullHash = "6c9a51",
  text = "Mai'Zoth. In the eastern mountains of Stranglethorn Vale, Mai'Zoth keeps a relic said to twist minds. Brother Nimetz believes the ogre mage corrupted Colonel Kurzen and wants the relic recovered before another commander suffers the same fate. Brother Nimetz believes the power behind Kurzen's rebellion remains. His research points to Mai'Zoth, an ogre mage who lives in an ogre mound in the eastern heights of Stranglethorn Vale. Nimetz says Mai'Zoth used sorcery to warp Kurzen's thoughts. While Mai'Zoth lives, another commander could suffer the same corruption. Brother Nimetz asks you to slay Mai'Zoth and take the Mind's Eye from him. Bring the artifact to the Rebel Camp.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_206-c7413f0b101cb72f6b01/1-0000.mp3", duration = 42.2661224, start = 0},
  },
}
P.transport["quest:207"] = {
  hash = "934e44",
  fullHash = "934e44",
  text = "Kurzen's Mystery. At the Rebel Camp, Brother Nimetz seeks the reason for Colonel Kurzen’s fall. He suspects troll magic and sends you to copy legends from four tablets in Stranglethorn’s troll ruins. Brother Nimetz at the Rebel Camp seeks the cause of Colonel Kurzen’s fall from greatness into depravity. He suspects troll magic has taken hold of the colonel. Legends carved on four old tablets may test that suspicion. You are asked to copy each tablet’s markings and carry them back to camp. One tablet stands in the Bal'lal Ruins. Another lies deep underwater in the Vile Reef, off the coast near a sunken city held by Saltscale murlocs. The last two tablets are in the Ruins of Zul'Kunda.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_207-b353ecf1cf9b28f93000/1-0000.mp3", duration = 43.5983673, start = 0},
  },
}
P.transport["quest:208"] = {
  hash = "8e2745",
  fullHash = "8e2745",
  text = "Big Game Hunter. In Stranglethorn Vale, Hemet Nesingwary’s hunt for King Bangalash reaches its last trial. The famed marksman came to the jungle for the great white tiger. You have slain Sin'Dall, Bhag'thera, and Tethis in the trials set by the expedition's huntsmen. Hemet Nesingwary now knows your skill with weapons. Few have shown him finer skill on Lordaeron's battlefields or deep in the jungle.\n\nOne hunt remains. Bring down King Bangalash, the great white tiger Hemet came to hunt, and prove your abilities unmatched. King Bangalash drew Hemet Nesingwary to Stranglethorn Vale. The great beast has driven the expedition leader back to camp in defeat time and again. Its head would prove your hunting skill second to none.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_208-76f639f8805abdf34f31/1-0000.mp3", duration = 51.8269388, start = 0},
  },
}
P.transport["quest:209"] = {
  hash = "726d9f",
  fullHash = "726d9f",
  text = "Skullsplitter Tusks. In Booty Bay, Kebok struggles to fill orders for tiger fangs bound for the South Seas. Real fangs cost too much to supply, so he has found another way to meet demand. Kebok’s trade in tiger fangs for buyers across the South Seas has grown costly and hard to supply through ordinary hunting. So he has found a way to shape horn-like objects into convincing fangs without leaving a sign of the trick. Skullsplitter troll tusks make the closest match. Kebok hires adventurers to take eighteen from the jungle tribe for his next shipment.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_209-5f15bd079618913d4bd2/1-0000.mp3", duration = 34.8473469, start = 0},
  },
}
P.transport["quest:210"] = {
  hash = "110030",
  fullHash = "110030",
  text = "Krazek's Cookery. In Booty Bay, Corporal Kaleb has a broken pot to get mended. He asks you to carry the mechanical cooker he bought from a goblin trader to Krazek. Corporal Kaleb handles most of the camp's cooking. Before he bought a mechanical pot from a goblin trader in Booty Bay, cooking took hours. The pot spared him that work until it broke. Now he asks you to carry Krazek's Crock Pot to Krazek, the goblin who can repair it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_210-0c53e9803eb6005efba9/1-0000.mp3", duration = 31.9216327, start = 0},
  },
}
P.transport["quest:213"] = {
  hash = "67acb1",
  fullHash = "67acb1",
  text = "Hostile Takeover. In Booty Bay, Gelriz's latest move draws Baron Revilgaz's wrath in Hostile Takeover. Gelriz has pushed aside moguls appointed by the trade princes and now moves against the most notorious pirate of all. Kebok sends you to steal strange blue crystals Venture Company geologists have found near Lake Nazferiti. Baron Revilgaz gives Kebok leave to answer the insult as he sees fit. Kebok chooses theft, targeting the strange blue stones Venture Company mining crews have been unearthing. Venture Company geologists working around Lake Nazferiti have taken a keen interest in the unusual crystals. Kebok wants you to bring eight samples back to Booty Bay. How you get them matters little to him, so long as they end up in his hands.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_213-1298fe2297da1cd6ba12/1-0000.mp3", duration = 51.9314286, start = 0},
  },
}
P.transport["quest:215"] = {
  hash = "f30257",
  fullHash = "f30257",
  text = "Jungle Secrets. In northern Stranglethorn Vale, Private Thorsen explains why he rejoined Kurzen's men after you rescued him from an ambush. He sends you to the Rebel Camp to have his commander confirm the reason. Private Thorsen says the scene looks grim and asks you to hear him out. Lieutenant Doren ordered him to re-enlist with Colonel Kurzen's men and gather desperately needed intelligence for the rebellion. Thorsen hoped this would let him enter Kurzen's Compound, but the effort soon went badly. He sends you to Doren at the Rebel Camp for confirmation and begs you to keep the matter secret.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_215-2ac938bead3d1352793b/1-0000.mp3", duration = 44.2514286, start = 0},
  },
}
P.transport["quest:2258"] = {
  hash = "df3561",
  fullHash = "df3561",
  text = "Badlands Reagent Run. In Kargath, Jarkal Mossmeld needs Badlands reagents to refill his stocks. He offers coin when you bring them to him. Jarkal Mossmeld needs gizzards from five buzzards, fangs from ten crag coyotes, and shards from five rock elementals. Take each from the creatures themselves. If you do not fight, find friends who do. Jarkal pays in coin when you bring him the reagents.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2258-7654ee435cf8bacac098/1-0000.mp3", duration = 21.237551, start = 0},
  },
}
P.transport["quest:243"] = {
  hash = "a4d953",
  fullHash = "a4d953",
  text = "Into the Field. In Tanaris, you test desert creatures with Apothecary Zinge’s field testing kit. Its power source must come from Gadgetzan’s goblins, so Zinge sends you to Chief Engineer Bilgewhizzle. Apothecary Zinge needs to know whether tissue from Tanaris basilisks, scorpids and hyenas is consistent. You gather samples and test them with the field testing kit. Many will fail, so Zinge needs eight acceptable samples of each kind. Return only when you have them. The modified kit needs a power source like those held by Gadgetzan’s goblins. Zinge sends you to Chief Engineer Bilgewhizzle in Gadgetzan to get one.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_243-4aef5e78ee2572827331/1-0000.mp3", duration = 40.7510204, start = 0},
  },
}
P.transport["quest:2605"] = {
  hash = "c3672c",
  fullHash = "c3672c",
  text = "The Thirsty Goblin. In Gadgetzan, Marin Noggenfogger longs for a drink that can end his unending thirst. He has heard the dew collectors in the cactus garden southwest of town keep water in special glands, and hopes one will make such a drink possible. Marin Noggenfogger has heard of dew collectors in the cactus garden southwest of Gadgetzan. They keep water in special glands, and he believes a full gland could start a drink that ends his thirst for good. He asks you to find their garden and bring one back.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2605-e64f9667bf8e2d850dde/1-0000.mp3", duration = 31.5559184, start = 0},
  },
}
P.transport["quest:2606"] = {
  hash = "1c282c",
  fullHash = "1c282c",
  text = "In Good Taste. Marin Noggenfogger finds thistleshrub dew awful to drink, yet he keeps working on the brew. He sends you to Sprinkle in Gadgetzan with the dew. Marin Noggenfogger tastes the dew and finds it awful. Still, he keeps working on the drink. He sends you to Sprinkle, his friend in Gadgetzan and an excellent chef. You carry the dew and explain that the drink needs to go down more easily. Marin also wants it to have some kick.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2606-c3b8865db492019adcf4/1-0000.mp3", duration = 29.0742857, start = 0},
  },
}
P.transport["quest:261"] = {
  hash = "2a4ec7",
  fullHash = "2a4ec7",
  text = "Down the Scarlet Path. At Nijel's Point, Brother Anton calls on you to prove your allegiance to the Scarlet Crusade. Brother Anton says the Scourge must be stopped before it swallows the land and casts the world into darkness. The Scarlet Crusade has pledged itself to that fight. To prove your courage and allegiance, destroy thirty undead ravagers in the Valley of Bones, south of Anton. Succeed, and the Crusade will welcome you.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_261-6745a79e3b8bea601f61/1-0000.mp3", duration = 27.8987755, start = 0},
  },
}
P.transport["quest:2622"] = {
  hash = "36fd7b",
  fullHash = "36fd7b",
  text = "The Missing Orders. Dispatch Commander Ruag sends you to find Bengor after the orders go missing. Dispatch Commander Ruag bristles when you ask about the missing orders. He says they went with the soldiers sent to carry them. Murlocs ambushed and brutally beat the soldiers, and only one survived. Bengor can barely speak, cannot walk, and is fed through a tube. Ruag sends you to find him nearby, then warns you to mind what you poke your nose into.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2622-65375fe45336be069628/1-0000.mp3", duration = 27.5853061, start = 0},
  },
}
P.transport["quest:2623"] = {
  hash = "8b7604",
  fullHash = "8b7604",
  text = "The Swamp Talker. Orders bound for the Blasted Lands vanish in a murloc ambush. Bengor tells you what happened before he loses consciousness. Bengor says the dispatch commander gave out the orders. His group was bound for the Blasted Lands when many murlocs fell upon them. One of them, Swamp Talker, seized the orders from Bengor as a spear struck his skull. Before he passes out, Bengor speaks of a cave to the east. Recover the orders and take them to the Fallen Hero of the Horde.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2623-6ab725417ba22ba69991/1-0000.mp3", duration = 29.962449, start = 0},
  },
}
P.transport["quest:2641"] = {
  hash = "36ab43",
  fullHash = "36ab43",
  text = "Sprinkle's Secret Ingredient. In Gadgetzan, Sprinkle offers a way to make Marin Noggenfogger's foul brew drinkable with a Violet Tragan. The mushroom grows underwater in a small lake in the Hinterlands. As a child, Sprinkle's sister did all the cooking, and the food was hard to stomach. Sprinkle found a mushroom called the Violet Tragan and made it her secret ingredient. She says it made every dish taste wonderful. Now she will use it to make Marin's horrid brew drinkable. The Violet Tragan grows underwater in a small lake in the Hinterlands. Valorwind Lake lies just south of the road that crosses the zone. Dive beneath the surface to gather the mushroom, then return to Sprinkle in Gadgetzan.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2641-0d728704fa152c75e682/1-0000.mp3", duration = 43.0236735, start = 0},
  },
}
P.transport["quest:2661"] = {
  hash = "4eeb23",
  fullHash = "4eeb23",
  text = "Delivery for Marin. In Gadgetzan, Sprinkle sends Violet Powder to Marin Noggenfogger and reminds her of the favor Marin owes. In Gadgetzan, Sprinkle gives you Violet Powder after you bring her the Violet Tragan. Marin Noggenfogger is in the same town, and Sprinkle asks you to remind Marin that she owes a favor.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2661-16c96e0e22364e2690c1/1-0000.mp3", duration = 19.6963265, start = 0},
  },
}
P.transport["quest:2662"] = {
  hash = "87a68d",
  fullHash = "87a68d",
  text = "Noggenfogger Elixir. In Gadgetzan, Marin Noggenfogger works Violet Powder into the dew. He asks you to return in a moment, when his fabulous elixir should be ready. Marin has the dew and the powder. He begins mixing them, and the Noggenfogger Elixir should be ready after a short wait. Then speak to him again.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2662-7b87ab2dc366071d732f/1-0000.mp3", duration = 22.8832653, start = 0},
  },
}
P.transport["quest:2741"] = {
  hash = "953ead",
  fullHash = "953ead",
  text = "The Super Egg-O-Matic. At the control panel, Curgle Cranklehop's newest invention sputters wildly as hippogryph eggs go into the machine. At its control panel, Curgle Cranklehop's newest invention sputters wildly. It takes a hippogryph egg found in the mountains of southern Feralas, around the Ruins of Isildien.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2741-2153e91af0cb7e565606/1-0000.mp3", duration = 20.0097959, start = 0},
  },
}
P.transport["quest:2742"] = {
  hash = "852176",
  fullHash = "852176",
  text = "Rin'ji is Trapped!. At Quel'Danil Lodge, Rin'ji has lost an axe and is held captive. Rin'ji asks a passer-by for help escaping, offers something in return, and speaks of a secret at the Overlook Cliffs. At Quel'Danil Lodge, Rin'ji is frightened and held captive. The axe is gone, so Rin'ji begs a passer-by to help escape. Many dislike Rin'ji's kind. Still, Rin'ji offers something to a kind soul who helps and says a secret lies hidden at the Overlook Cliffs.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2742-b93fae55281762b6e6a4/1-0000.mp3", duration = 32.2873469, start = 0},
  },
}
P.transport["quest:2747"] = {
  hash = "ad04ba",
  fullHash = "ad04ba",
  text = "An Extraordinary Egg. In Tanaris, Curgle Cranklehop seeks an extraordinary egg from Feralas. Curgle Cranklehop says few eggs from Feralas arrive in extraordinary shape. Such eggs are the rarest of all. One is what Curgle seeks.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2747-1dfad77ea0a0c0497b34/1-0000.mp3", duration = 14.7591837, start = 0},
  },
}
P.transport["quest:2748"] = {
  hash = "c5e931",
  fullHash = "c5e931",
  text = "A Fine Egg. Curgle Cranklehop speaks of an egg that may hatch free of the Gordunni ogres’ evil incantations. Curgle Cranklehop says an egg has a good chance of hatching untouched by the Gordunni ogres’ wicked chanting, if conditions are ideal.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2748-8702aaac372aee696582/1-0000.mp3", duration = 15.3077551, start = 0},
  },
}
P.transport["quest:2749"] = {
  hash = "99c2af",
  fullHash = "99c2af",
  text = "An Ordinary Egg. Curgle Cranklehop tends ordinary hippogryph eggs, though only about half hatch. Only about half of ordinary hippogryph eggs hatch. Curgle Cranklehop does their best to nurture each one, hoping luck will see it hatch.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2749-0a0a60586c4375dd29f7/1-0000.mp3", duration = 14.6546939, start = 0},
  },
}
P.transport["quest:2750"] = {
  hash = "f4e812",
  fullHash = "f4e812",
  text = "A Bad Egg. Curgle Cranklehop takes charge when a hippogryph egg cannot be saved. Some hippogryph eggs cannot be saved. Curgle Cranklehop handles those that will never hatch.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2750-c43d3acc1006042bbd16/1-0000.mp3", duration = 11.8073469, start = 0},
  },
}
P.transport["quest:2766"] = {
  hash = "d5b32e",
  fullHash = "d5b32e",
  text = "Find OOX-22/FE!. A homing robot has crashed in Feralas, and Oglethorpe Obnoticus calls for help through a strange metal egg. Carry its beacon to a cave near Feral Scar Vale. Turn the knob on the metal egg, and it opens into a gnomish contraption. Oglethorpe Obnoticus speaks from within. His homing robot has crashed, and he promises payment if you recover it. He has worked out that the machine lies in a cave near Feral Scar Vale. Carry the beacon there.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2766-d2c3761bd5440d69d1f4/1-0000.mp3", duration = 33.0710204, start = 0},
  },
}
P.transport["quest:2767"] = {
  hash = "09ef7a",
  fullHash = "09ef7a",
  text = "Rescue OOX-22/FE!. In Feral Scar Vale, OOX-22/FE! waits for your help on the way to the Forgotten Coast dock. Once it arrives, Oglethorpe Obnoticus wants to speak with you in Booty Bay. OOX-22/FE needs an open, safe place for its lengthy take-off. The gnome's voice crackles through the robot as he explains that its built-in cloaking needs time before it works again. Oglethorpe Obnoticus also needs time to make it work. He suggests the Forgotten Coast dock, where everything can be brought online. You escort the robot there from where it stands. Once OOX-22/FE reaches the dock safely, Oglethorpe Obnoticus wants you to speak with him in Booty Bay.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2767-13246450e7707f3212f2/1-0000.mp3", duration = 40.0979592, start = 0},
  },
}
P.transport["quest:2781"] = {
  hash = "c7bc4d",
  fullHash = "c7bc4d",
  text = "WANTED: Caliph Scorpidsting. Across Gadgetzan and Steamwheedle Port, notices call for Caliph Scorpidsting, leader of the Wastewander outlaws. The Gadgetzan Water Company seeks proof of his death in Gadgetzan. In Gadgetzan and Steamwheedle Port, the Gadgetzan Water Company posts a high bounty for Caliph Scorpidsting. The notices accuse him of murdering company employees, stealing its resources and seizing its property. Bring proof of his death to Chief Engineer Bilgewhizzle in Gadgetzan.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2781-03bc0e72d225d5aa5f91/1-0000.mp3", duration = 37.4334694, start = 0},
  },
}
P.transport["quest:2782"] = {
  hash = "ac8ad3",
  fullHash = "ac8ad3",
  text = "Rin'ji's Secret. After helping Rin'ji, you carry Rin'ji's Secret, a tablet marked in Witherbark script that no one has read. Oran Snakewrithe studies the Witherbark and may decipher it. He is known to live in the Magic Quarter of the Undercity. Witherbark troll markings cover the tablet, but what Rin'ji's secret is remains a mystery. It may be worth a great deal or nothing at all. A Witherbark troll in trouble might try anything to escape it. Oran Snakewrithe is a well-known scholar of the Witherbark trolls. He is known to live in the Magic Quarter of the Undercity and may be able to read the tablet.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2782-996d22cbf759297fe2d8/1-0000.mp3", duration = 47.1771429, start = 0},
  },
}
P.transport["quest:2821"] = {
  hash = "129fcc",
  fullHash = "129fcc",
  text = "The Mark of Quality. At Feathermoon Stronghold, Pratt McGrubben seeks ten thick yeti hides and offers a choice of leather goods. Pratt McGrubben, a leatherworker at Feathermoon Stronghold, insists on the finest work. In search of fine materials, he found thick yeti hides. Yetis are native to Feralas, and many live around Feral Scar Vale, just inland of the Forgotten Coast. Bring Pratt a stack of ten hides at Feathermoon Stronghold. In return, you may choose one of the leather goods he has crafted.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2821-dfc779a0707c3daa2463/1-0000.mp3", duration = 32.7053061, start = 0},
  },
}
P.transport["quest:2822"] = {
  hash = "d1e55c",
  fullHash = "d1e55c",
  text = "The Mark of Quality. At Camp Mojache, Jangdor Swiftstrider seeks ten thick yeti hides and will not compromise on quality. Jangdor Swiftstrider takes pride in fine leatherwork. He has found thick yeti hides in Feralas, where the yetis make their home. Many roam west of Camp Mojache in Feral Scar Vale, just inland of the Forgotten Coast. Bring Jangdor a stack of ten hides at Camp Mojache. In return, he will let you choose one of the leather goods he has made.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2822-fcda5cfbf870b01a679d/1-0000.mp3", duration = 31.2685714, start = 0},
  },
}
P.transport["quest:2844"] = {
  hash = "da05d2",
  fullHash = "da05d2",
  text = "The Giant Guardian. Rockbiter searches for Shay, the night elf girl he was meant to watch over. Worried, he asks you to look for her. Rockbiter last saw Shay while they walked through the ruins just north of where he stands. Then he turned around, and she was gone. Unsure what to do, he asks you to search for his little friend. Your legs can carry you much faster than his.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2844-578560f6a2c91a7e5edb/1-0000.mp3", duration = 23.1444898, start = 0},
  },
}
P.transport["quest:2845"] = {
  hash = "b0180a",
  fullHash = "b0180a",
  text = "Wandering Shay. Shay Leafrunner is distracted by the sights along the way as she tries to return to Rockbiter, her friend. Shay was meant to be watched by Rockbiter. She wants to return to him, but the many things around her catch her eye and lead her astray. A bell in the chest beside Shay always catches her attention, and she treasures its sound. If she wanders off, ring it and she promises to come running back. You can carry the bell to Rockbiter's camp, where Shay hopes to be taken.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2845-b8c68560f0aa2c30bdc1/1-0000.mp3", duration = 30.7722449, start = 0},
  },
}
P.transport["quest:2862"] = {
  hash = "000b12",
  fullHash = "000b12",
  text = "War on the Woodpaw. At Camp Mojache, Hadoken Swiftstrider asks you to thin the Woodpaw gnolls’ growing numbers. Their attacks have grown more fevered, and ten Woodpaw Gnoll Manes will answer his call. Hadoken Swiftstrider says the camp’s survival matters more than the gnolls’ claim to Feralas. Unless Camp Mojache stands firm, he warns, the gnolls may drive it from the whole region. Their attacks have grown more fevered, so he wants their numbers thinned. For ten Woodpaw gnoll manes, he offers generous pay.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2862-e1f897ad5d2f62653749/1-0000.mp3", duration = 34.4816327, start = 0},
  },
}
P.transport["quest:2863"] = {
  hash = "2091bd",
  fullHash = "2091bd",
  text = "Alpha Strike. The Horde's stalemate with the Woodpaw gnolls may be broken by striking their leaders in quick succession. Hadoken Swiftstrider asks you to bring down five Alphas within one hour. Hadoken Swiftstrider believes the Woodpaw ranks will fall into chaos if their Alphas die one after another. The blows may also show the gnolls that the Horde can destroy them. He asks you to carry out the plan. Five Alphas must fall within one hour, or the stalemate continues.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2863-ca0af22743793914e8e2/1-0000.mp3", duration = 32.4179592, start = 0},
  },
}
P.transport["quest:2866"] = {
  hash = "49e992",
  fullHash = "49e992",
  text = "The Ruins of Solarsal. South of Shandris Feathermoon, Hatecrest naga crowd the Ruins of Solarsal. She sends you among the old stones to look for anything out of the ordinary. Shandris Feathermoon says explorers searched the ruins long ago and found nothing of note. So the stones were left alone. Now Hatecrest naga have taken them in alarming numbers. Their presence first seemed to herald an attack, and that danger remains. Yet Shandris suspects something else may be happening. She asks you to walk through the ruins and notice anything out of the ordinary.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2866-a3879e57a4093f6b8499/1-0000.mp3", duration = 40.7510204, start = 0},
  },
}
P.transport["quest:2867"] = {
  hash = "09efeb",
  fullHash = "09efeb",
  text = "Return to Feathermoon Stronghold. You return to Feathermoon Stronghold with news of a strange gazebo at the heart of the Ruins of Solarsal. General Shandris Feathermoon awaits your report. At Feathermoon Stronghold, General Shandris Feathermoon awaits your news of the strange gazebo. You carry your findings back from the heart of the ruins so she can hear what you saw.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2867-e747362e5c4ad3fb65cd/1-0000.mp3", duration = 23.562449, start = 0},
  },
}
P.transport["quest:2869"] = {
  hash = "4a1aee",
  fullHash = "4a1aee",
  text = "Against the Hatecrest. At Feathermoon Stronghold, Latronicus Moonspear means to face the Hatecrest naga before they make their move. He asks you to bring him ten Hatecrest Scales in good condition. Latronicus Moonspear expects the naga to try to claim the island someday. He wants to act before they can, so he asks you to bring ten Hatecrest Scales in good condition. You will have to see for yourself how to get them. He hopes gathering the scales will weaken the naga presence on Sardor Isle and give you your first taste of fighting naga. Latronicus says night elves cherish peace and harmony, not war. Still, he will not leave their interests unguarded. Protecting them is his duty to General Feathermoon and the stronghold.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2869-53104a0b4031ba9dd4ba/1-0000.mp3", duration = 53.995102, start = 0},
  },
}
P.transport["quest:2870"] = {
  hash = "bb3ad7",
  fullHash = "bb3ad7",
  text = "Against Lord Shalzaru. At Feathermoon Stronghold, Latronicus Moonspear asks you to stop Lord Shalzaru and recover the relic he found. Latronicus Moonspear has fresh reports on the naga chain of command. Royals give orders among their ranks. Lord Shalzaru is one of the crueler royals. Scouts say Lord Shalzaru uncovered an odd relic while the naga dug in a cave on the Isle of Dread. The cave lies over the water, south of the main ruins. Latronicus wants you to stop Shalzaru and end the dig. Then bring the Mysterious Relic to Feathermoon Stronghold for study.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2870-d4845e501da010c537c1/1-0000.mp3", duration = 39.0791837, start = 0},
  },
}
P.transport["quest:2871"] = {
  hash = "224fb3",
  fullHash = "224fb3",
  text = "Delivering the Relic. At Feathermoon Stronghold, Latronicus Moonspear sends you with the Mysterious Relic to his wife Vestia. He cannot make sense of it, and hopes she can tell what it is. Latronicus Moonspear cannot make sense of the device, wager or no wager. He says his wife Vestia is a fine priestess to their community and one of the most learned scholars anywhere. If anyone can work out what the relic is, she can. They need to know. Vestia is only a short walk away, though she is surely busy studying.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2871-1e4f0b1029a76b3e2800/1-0000.mp3", duration = 37.9297959, start = 0},
  },
}
P.transport["quest:2872"] = {
  hash = "7babf1",
  fullHash = "7babf1",
  text = "Stoley's Debt. At Steamwheedle Port, “Sea Wolf” MacKinley wants the rum Stoley wagered with him. He asks you to speak with the barkeep about it. “Sea Wolf” MacKinley says Stoley owes him a special bottle of rum. Stoley boasted that Steamwheedle Port’s rum was stronger than anything in Booty Bay. He promised to double the money he owes MacKinley if MacKinley tried it and disagreed.\n\nNow MacKinley thinks Stoley has lost his nerve about handing over the bottle. But MacKinley never backs away from a wager, so he asks you to speak with Stoley at the Steamwheedle Port bar.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2872-f5cbea847bd2835e192a/1-0000.mp3", duration = 38.6089796, start = 0},
  },
}
P.transport["quest:2873"] = {
  hash = "7009a5",
  fullHash = "7009a5",
  text = "Stoley's Shipment. Stoley is out of rum and asks you to recover his stolen shipment. Captain Cuergo keeps it in Lost Rigger Cove, the walled pirate town to the south. Stoley owes “Sea Wolf” MacKinley of Booty Bay rum for their wager, but his supply is gone. Captain Cuergo took the last shipment and keeps it in Lost Rigger Cove, the walled pirate town to the south. Stoley wants you to bring the rum back so he can prove Kalimdor’s drink is better than anything Booty Bay pours. The pirates keep the rum in crates on the upper floor of the house in the northwest.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2873-7b394d7a2296e19a2ee2/1-0000.mp3", duration = 35.6310204, start = 0},
  },
}
P.transport["quest:2874"] = {
  hash = "42f585",
  fullHash = "42f585",
  text = "Deliver to MacKinley. At Steamwheedle Port, Stoley gives you bilge rum for MacKinley in Booty Bay. The Sea Wolf can judge whether the drink settles his beliefs about Booty Bay booze. After you help with the shipment, Stoley gives you a bottle of Steamwheedle bilge rum. You carry it to MacKinley in Booty Bay, where he can finally set aside his beliefs about the booze there.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2874-bfb51cd0cf6f787f0232/1-0000.mp3", duration = 22.3869388, start = 0},
  },
}
P.transport["quest:2875"] = {
  hash = "d0820d",
  fullHash = "d0820d",
  text = "WANTED: Andre Firebeard. In Gadgetzan and Steamwheedle Port, a wanted notice names Andre Firebeard and accuses him of crimes against both places. Deliver his head to Security Chief Bilgewhizzle at Steamwheedle Port, and it counts as a binding contract. A notice condemns Andre Firebeard as a vile pirate accused of crimes against Steamwheedle and Gadgetzan. The governing counsel allows anyone who reads it to use lethal force to capture Andre and those who aid him. He can be found at the pirate enclave south along the coast from Steamwheedle Port, standing by a campfire inside its walls. A further decree says Andre's head may speak for him if he is dead or otherwise unable to attend his hearing. Delivered to Security Chief Bilgewhizzle at Steamwheedle Port, it counts as a binding contract.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2875-ede7df77896f33a1abca/1-0000.mp3", duration = 55.1967347, start = 0},
  },
}
P.transport["quest:2876"] = {
  hash = "236bae",
  fullHash = "236bae",
  text = "Ship Schedules. At Steamwheedle Port, some voyages bear marks on the ship schedule. It belongs with someone in authority there. Ships sail between Steamwheedle Port and Booty Bay, and the scroll names them all. It records voyages already made and those still to come. Large X marks cross some journeys. Notes beside others warn of plunder or a hard fight. Someone in authority at Steamwheedle Port needs the schedule.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2876-25d08b9ce5cbbb131521/1-0000.mp3", duration = 26.3836735, start = 0},
  },
}
P.transport["quest:2877"] = {
  hash = "6cc52d",
  fullHash = "6cc52d",
  text = "Skulk Rock Clean-up. Sludges and oozes overrun the Horde's old positions around Skulk Rock. Fraggar Thundermantle at Aerie Peak wants them cleared, for the Wildhammers have plans for the ground. The Wildhammers remember the past more than their brothers in Ironforge do. Fraggar Thundermantle says friends are made here by getting your hands dirty. The Horde left its positions around Skulk Rock in the Hinterlands, and sludges and oozes have overrun them. The Wildhammers have plans for that ground, but first the infestation must be thinned. Slay ten green sludges and ten jade oozes. Then return to Fraggar at Aerie Peak with your report.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2877-6b2a9a080ce4d719b55e/1-0000.mp3", duration = 44.5126531, start = 0},
  },
}
P.transport["quest:2879"] = {
  hash = "0fa67c",
  fullHash = "0fa67c",
  text = "The Stave of Equinex. At the Ruins of Ravenwind, Troyas Moonbreeze tests whether his stave can open the Equinex Monolith. You gather the essences of four flames still burning among the ruins. Troyas Moonbreeze thinks his stave may be the Stave of Equinex, a key to the Equinex Monolith in the Ruins of Ravenwind. Four flames still burn there: Samha, Imbel, Byltan and Lahassa. Each yields an essence. You use all four at the monolith to energize the stave. If it is truly the key, the monolith will open and reveal a sacred artifact.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2879-f7aea9d0193cb3f3d78f/1-0000.mp3", duration = 41.0906122, start = 0},
  },
}
P.transport["quest:2880"] = {
  hash = "f06d37",
  fullHash = "f06d37",
  text = "Troll Necklace Bounty. At Aerie Peak, Fraggar Thundermantle asks you to bring him five necklaces from trolls in the Hinterlands. Fraggar Thundermantle trusts deeds over words. The Wildhammers answer to no Alliance, and anyone seeking their friendship must prove their worth first. Trolls roaming the Hinterlands hillsides sometimes wear tribal necklaces. Bring five to Fraggar at Aerie Peak, and you will have made a start.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2880-2d6ba78ace6f9e93d462/1-0000.mp3", duration = 25.9657143, start = 0},
  },
}
P.transport["quest:2881"] = {
  hash = "f3d71a",
  fullHash = "f3d71a",
  text = "Troll Necklace Bounty. For Fraggar Thundermantle, troll tribal necklaces still come in batches of five. The Wildhammer has already accepted one batch from you, and the offer remains open. Fraggar Thundermantle welcomes more troll tribal necklaces whenever you find them and choose to hand them over. He says the Wildhammers will fight for those who fight for them. Each batch must hold five necklaces.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2881-a33081eff61c31ff4570/1-0000.mp3", duration = 23.5363265, start = 0},
  },
}
P.transport["quest:2902"] = {
  hash = "9393d4",
  fullHash = "9393d4",
  text = "Woodpaw Investigation. At Camp Mojache, Hadoken Swiftstrider suspects the Woodpaw gnolls are following written plans. He sends you south to search their camps for battle plans. After Alpha Strike, Hadoken Swiftstrider sends you back to the Woodpaw. He doubts the gnolls are clever, yet their recent assaults have been too well coordinated to be chance. He suspects they keep a written record of their strategy. If you find it, he may learn what stirred them up, so he asks you to search the camps and bring back anything that looks like battle plans.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2902-153d09d1bc5606197531/1-0000.mp3", duration = 32.2873469, start = 0},
  },
}
P.transport["quest:2903"] = {
  hash = "73ac5e",
  fullHash = "73ac5e",
  text = "The Battle Plans. You carry the Woodpaw battle plans toward Camp Mojache, where Hadoken Swiftstrider hopes to learn what the gnolls intend. After Woodpaw Investigation, you bring the Woodpaw battle plans back to Hadoken Swiftstrider at Camp Mojache. He needs firm evidence of what the gnolls intend.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2903-e3d91c32f123060ebf5d/1-0000.mp3", duration = 19.6179592, start = 0},
  },
}
P.transport["quest:2932"] = {
  hash = "954a54",
  fullHash = "954a54",
  text = "Grim Message. In Stranglethorn, Nimboya sends you north to punish the Witherbark trolls for betraying Thrall. He gives you a pike to bear their skulls and plant in one of their Hinterlands villages. Nimboya sends you from Stranglethorn to the Hinterlands, far to the north and northeast of Tarren Mill, a village held by the Forsaken. The Witherbark trolls once stood with the Horde, but betrayed Thrall. Hunt them for their skulls, then plant Nimboya's pike in Hiri'watha or Zun'watha, two of their smaller villages. The warning will show them what their deeds cost. Nimboya waits in Stranglethorn.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2932-8eb77c7704238b3d7e62/1-0000.mp3", duration = 38.3738776, start = 0},
  },
}
P.transport["quest:2933"] = {
  hash = "093198",
  fullHash = "093198",
  text = "Venom Bottles. In the Hinterlands, Venom Bottles fill a Witherbark village. Their great number suggests the Witherbarks value the vile green venom, and an apothecary in nearby Tarren Mill may want a sample. Vile green venom fills bottles throughout the Witherbark village. There are many of them, suggesting the Witherbarks consider the venom important. An apothecary in Tarren Mill may want a sample to examine.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2933-a2e9a9a7bd3d9f3cd432/1-0000.mp3", duration = 28.395102, start = 0},
  },
}
P.transport["quest:2934"] = {
  hash = "354817",
  fullHash = "354817",
  text = "Undamaged Venom Sac. In Tarren Mill, Apothecary Lydon needs a fresh sample of venom. You search the Hinterlands for the spiders that yield it, and the sac must reach him fresh. After Venom Bottles, Apothecary Lydon asks you for a fresher sample. The spiders that yield the venom live in the Hinterlands, many near the troll city of Shadra'Alor. Lydon wants an undamaged venom sac, delivered while it is fresh. He is eager to experiment with it and has ordered several small, terribly cute animals for testing.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2934-6769feb4485f8fab3f6a/1-0000.mp3", duration = 35.9183673, start = 0},
  },
}
P.transport["quest:2935"] = {
  hash = "b3bea6",
  fullHash = "b3bea6",
  text = "Consult Master Gadrin. In Sen'jin Village, Apothecary Lydon seeks a stronger venom sample. The broodguard venom you brought was weaker than your first sample, so another kind of spider may be the source. Apothecary Lydon needs a fresh sample of the stronger venom. The broodguard venom you brought was weaker than your first sample, so it must come from another kind of spider.\n\nLydon sends you to Master Gadrin in Sen'jin Village, in Durotar. Gadrin is a troll well acquainted with the Witherbark, and may know where the venom comes from.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2935-1cef35f114561d89494a/1-0000.mp3", duration = 35.3959184, start = 0},
  },
}
P.transport["quest:2937"] = {
  hash = "c8115f",
  fullHash = "c8115f",
  text = "Summoning Shadra. At Shadra'Alor, you read Master Gadrin's parchment and call Shadra from the Witherbark realm. Master Gadrin sends you deep into the Witherbark realm of the Hinterlands. At Shadra'Alor, you read his parchment at the altar, and Shadra the spider god answers. Defeat her there, then carry her venom to Apothecary Lydon in Tarren Mill.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2937-c871af62e7c818baec9b/1-0000.mp3", duration = 26.8277551, start = 0},
  },
}
P.transport["quest:2938"] = {
  hash = "ab350e",
  fullHash = "ab350e",
  text = "Venom to the Undercity. Apothecary Lydon sends spider god venom to the Undercity. Its strength delights Lydon, who entrusts you with a parcel for Faranell, a superior at the Apothecarium. Apothecary Lydon has killed nearly two dozen rabbits with one dose of the venom. Some were tiny, so their resistance was surely low. Even so, the poison is powerful. Lydon is certain Faranell will want to test it personally, and gives you a parcel for the Apothecarium in the Undercity.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2938-73a6a72a6c29798e0054/1-0000.mp3", duration = 38.635102, start = 0},
  },
}
P.transport["quest:2939"] = {
  hash = "7e34a8",
  fullHash = "7e34a8",
  text = "In Search of Knowledge. Troyas Moonbreeze sends you to seek Daryn Lightwind in Rut'theran Village. He found a stave in the rubble of Feralas and wants to learn what it is. Troyas Moonbreeze says the ruins of Feralas are dangerous, yet they have much to tell of what happened there. A few days ago, he searched the rubble to the south and found a stave that seemed ordinary. Still, he feels there is more to it. He and Angelas searched their books, but found no word of the stave. Troyas has a colleague in Darnassus who may know what the stave is. He asks you to speak with Daryn Lightwind in Rut'theran Village.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2939-861423f80b123ce431a8/1-0000.mp3", duration = 37.0677551, start = 0},
  },
}
P.transport["quest:2940"] = {
  hash = "241a05",
  fullHash = "241a05",
  text = "Feralas: A History. In Feralas, you find Feralas: A History, a book Troyas may need. It looks as if nobody has opened it in ages. The book belongs to Daryn Lightwind, so you need to ask whether you may borrow it. The book's covers are badly worn, and its pages have yellowed. After looking it over, you suspect it may be what Troyas is searching for. You pick it up, then think better of borrowing it without asking. It belongs to Daryn Lightwind, so ask her first.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2940-f212d1aa0c36162799df/1-0000.mp3", duration = 33.8546939, start = 0},
  },
}
P.transport["quest:2941"] = {
  hash = "e1b031",
  fullHash = "e1b031",
  text = "The Borrower. On the Hinterlands beach, Daryn Lightwind longs to see Gammerita, a giant snapjaw. Her research keeps her away, so she sends you to Tanaris with a letter for Curgle Cranklehop. Daryn Lightwind has studied many subjects. Now the snapjaws along the Hinterlands beach hold her attention, especially Gammerita, a giant snapjaw. Her research keeps her where she is, so she asks you to bring back a picture of Gammerita. Daryn gives you a letter for Curgle Cranklehop in Tanaris. Curgle made an invention that can capture a picture. Daryn believes Curgle calls it a snapshot.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2941-1c3cb9c22d8dcd136c26/1-0000.mp3", duration = 37.9820408, start = 0},
  },
}
P.transport["quest:2942"] = {
  hash = "13aaaa",
  fullHash = "13aaaa",
  text = "The Morrow Stone. At the Equinex Monolith, taking the artifact begins to drain the Stave of Equinex. You carry the Sparkling Stone and the stave back to Troyas Moonbreeze at Feathermoon Stronghold. The Stave of Equinex begins to lose energy when you take the artifact from the monolith. Troyas Moonbreeze at Feathermoon Stronghold awaits word of what you found. Bring him the Sparkling Stone and the stave.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2942-1e670de88d4edfad0cdd/1-0000.mp3", duration = 29.204898, start = 0},
  },
}
P.transport["quest:2943"] = {
  hash = "1106ca",
  fullHash = "1106ca",
  text = "Return to Troyas. Daryn Lightwind sends you to Feathermoon Stronghold with her book, Feralas: A History. Troyas Moonbreeze is eager for your return. After the Super Snapper FX, Daryn Lightwind entrusts you with her book, Feralas: A History. She urges you to hurry because Troyas Moonbreeze is eager for your return. The book is bound for Troyas at Feathermoon Stronghold.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2943-432ff81418c72480a4dc/1-0000.mp3", duration = 26.2008163, start = 0},
  },
}
P.transport["quest:2944"] = {
  hash = "ae8a0a",
  fullHash = "ae8a0a",
  text = "The Super Snapper FX. Curgle Cranklehop has a new device for you to try: the Super Snapper FX. Aim it at Gammerita, a creature from the Hinterlands, then bring the picture and device to Daryn Lightwind in Rut'theran Village. This follows The Borrower. After The Borrower, Curgle Cranklehop puts a new invention in your hands: the Super Snapper FX. Aim it at what you want pictured, then press the button. Curgle gives it to you to try. Gammerita, a creature from the Hinterlands, is the subject you mentioned to Curgle. He wishes you luck in finding her and expects Daryn Lightwind to be pleased with the snapshot. Once you have the picture, bring it and the device to Daryn in Rut'theran Village.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2944-3f72e5e9b6aecd013596/1-0000.mp3", duration = 50.3118367, start = 0},
  },
}
P.transport["quest:2945"] = {
  hash = "97883d",
  fullHash = "97883d",
  text = "Grime-Encrusted Ring. A Dark Iron dwarf in Gnomeregan carries a ring caked in toxic filth and hardened muck. The Sparklematic 5200 in the Clean Zone dormitory can scour it clean and reveal its markings. Fighting leaves Gnomeregan's corridors coated in toxic sludge, oil, and radioactive fallout. Dark Iron dwarves who infiltrate the city carry trinkets fouled by that filth. One ring bears a crust that ordinary washing cannot remove. Beneath it, the metal may be copper, gold, or junk.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2945-5b791f93c758420be02e/1-0000.mp3", duration = 33.2277551, start = 0},
  },
}
P.transport["quest:2947"] = {
  hash = "0a8c92",
  fullHash = "0a8c92",
  text = "Return of the Ring. In Gnomeregan, a golden ring bears a maker’s mark that leads you to Ironforge. You place a grime-caked bauble in Gnomeregan’s Sparklematic 5200. The machine strips away years of irradiated grime, revealing a polished Brilliant Gold Ring that still hums with arcane power. Inside the band, three initials, “TdK,” sit beside Ironforge’s hallmark seal.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2947-999297bc6f2c7026ed70/1-0000.mp3", duration = 25.1820408, start = 0},
  },
}
P.transport["quest:2949"] = {
  hash = "821052",
  fullHash = "821052",
  text = "Return of the Ring. A ring from Gnomeregan bears Orgrimmar's seal and the letters NOG. Its trail leads to Nogg, a goblin engineer with a theory about the ruins. You clean a ring from Gnomeregan in the Sparklematic 5200. The machine strips away the filth and reveals Orgrimmar's official seal, a surge of magical power, and the partly legible letters NOG. Gnomeregan lies deep in Khaz Modan, an Alliance city far from the Horde capital. The ring may have been made in Kalimdor or carried there on a doomed expedition, but its seal points back to Orgrimmar.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2949-e0a1fd2693a020666f72/1-0000.mp3", duration = 39.2097959, start = 0},
  },
}
P.transport["quest:2954"] = {
  hash = "2bc0de",
  fullHash = "2bc0de",
  text = "The Stone Watcher. At the Uldum Pedestal, The Stone Watcher guards the way into the compound. You have carried the platinum discs across Tanaris, and now it asks you to learn its story before you go on. At the Uldum Pedestal, the Stone Watcher blocks the way into the Uldum compound. You brought the platinum discs across Tanaris. The guardian says entry is allowed only when the Plates of Uldum are part of your set. Learn the Watcher's story, then use the pedestal.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2954-247eda21274a7262cc1c/1-0000.mp3", duration = 38.3477551, start = 0},
  },
}
P.transport["quest:2969"] = {
  hash = "65112d",
  fullHash = "65112d",
  text = "Freedom for All Creatures. At the Grimtotem camp, Kindal Moonweaver asks you to free the captured faerie dragons. Neither Kindal nor Jer'kai knows what the Grimtotem clan intends. Kindal will go with you, while Jer'kai stays behind. Kindal Moonweaver calls the Grimtotem clan filthy for taking faerie dragons. Neither Kindal nor Jer'kai knows what the clan intends, only that it means no good. They are not strong enough to fight into the camp, so Kindal asks you to help free the sprite darters. The Bamboo Cage Key opens their pen, and Kindal wants them to escape alive. Bring strong friends to stand with you. Kindal waits on a ledge behind the Grimtotem Compound, above the water. A path climbs the cliff face to reach him. Kindal fights beside you through the camp. Jer'kai stays behind.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2969-1c273a4512b029bb4131/1-0000.mp3", duration = 54.3085714, start = 0},
  },
}
P.transport["quest:2970"] = {
  hash = "23275d",
  fullHash = "23275d",
  text = "Doling Justice. In Feralas, Jer'kai Moonweaver and Kindal are ready to strike back after the sprite darters' rescue. Jer'kai asks you to thin the Grimtotem ranks, then return to him. After the sprite darter rescue, Jer'kai Moonweaver and Kindal are ready to strike at the Grimtotem. They can thin the tauren ranks together without much risk, and welcome your help.\n\nYou have seen the camp below, and more lie to the east. Choose your own tactics against Grimtotem Naturalists, Raiders and Shamans, then return to Jer'kai.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2970-c4d7aafc4a190b1325e5/1-0000.mp3", duration = 36.2579592, start = 0},
  },
}
P.transport["quest:2972"] = {
  hash = "d37409",
  fullHash = "d37409",
  text = "Doling Justice. In Feralas, Jer'kai Moonweaver sends you to Darnassus with a ring for High Priestess Tyrande Whisperwind. It will show that Jer'kai and Kindal are well and support your account. Jer'kai Moonweaver and Kindal have little to offer in Feralas, yet they want you to know they are grateful. Jer'kai gives you a signet ring for High Priestess Tyrande Whisperwind at the Temple of the Moon in Darnassus. The ring shows Tyrande that the pair are well and lends weight to your account.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2972-df332d3a7a242ab33b92/1-0000.mp3", duration = 31.764898, start = 0},
  },
}
P.transport["quest:2973"] = {
  hash = "4dab52",
  fullHash = "4dab52",
  text = "A New Cloak's Sheen. At Camp Mojache, Krueg Skullsplitter asks you to gather wings for Korrin’s cloak. He came to Feralas with companions sent by their masters in Orgrimmar. Krueg Skullsplitter came to Feralas with companions sent by their masters in Orgrimmar. His life-mate Korrin loves new clothes, so he plans a cloak adorned with delicate faerie dragon wings. The sprite darters he seeks live west of Camp Mojache. Bring Krueg ten Iridescent Sprite Darter Wings. Krueg warns that provoked sprite darters are dangerous. Nearby night elves tend to hole up in the forests, so take even greater care around them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2973-f5b0ec7bca5a012145e4/1-0000.mp3", duration = 39.7583673, start = 0},
  },
}
P.transport["quest:2974"] = {
  hash = "98fdd7",
  fullHash = "98fdd7",
  text = "A Grim Discovery. In Camp Mojache, Krueg Skullsplitter hears that you met tauren in Feralas and names them the Grimtotem. Belgrom has put a bounty on them, and Krueg asks for twenty horns. You tell Krueg Skullsplitter about the tauren you met in Feralas. He names them as the Grimtotem clan. Belgrom, one of Krueg's masters, has put a bounty on them and takes a keen interest in their kind. Krueg warns you that the Grimtotem are evil and must not be underestimated. He wants twenty horns brought back before they can raze villages or pilfer land.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2974-ec15fb6ae7c95e082ad0/1-0000.mp3", duration = 38.4783673, start = 0},
  },
}
P.transport["quest:2975"] = {
  hash = "c8faf4",
  fullHash = "c8faf4",
  text = "The Ogres of Feralas. At Camp Mojache, Rok Orhan calls for the Gordunni to be driven back. Their outpost lies up the river to the north. Rok Orhan says the Gordunni ogres scar the land around Camp Mojache. Drive the tribe back before it reaches deeper into Feralas. Follow the river north to find their outpost. There, slay ten Gordunni Ogres, ten Gordunni Ogre-Magi and five Gordunni Brutes to show the tribe they are unwelcome.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2975-8c7e2283f4001378f9d4/1-0000.mp3", duration = 30.5371429, start = 0},
  },
}
P.transport["quest:2976"] = {
  hash = "b47161",
  fullHash = "b47161",
  text = "A Grim Discovery. In Orgrimmar, Belgrom Rockmaul awaits the Grimtotem horns and your account of Feralas. Krueg Skullsplitter says you did the work and deserve the best of the bounty. This follows the first A Grim Discovery. Krueg Skullsplitter admits he spoke of a bounty after the first A Grim Discovery. You did the work, so he believes you deserve the best of the payoff. He packs the horns into a crate for you to carry to Belgrom Rockmaul in the Valley of Honor. Belgrom wants to hear what you saw, and Krueg says he will make your hard work worth it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2976-6e0474ae0ab59a62baf8/1-0000.mp3", duration = 41.7697959, start = 0},
  },
}
P.transport["quest:2978"] = {
  hash = "4e6ffd",
  fullHash = "4e6ffd",
  text = "The Gordunni Scroll. At the Gordunni Outpost, the Gordunni Scroll may reveal a gathering or ceremony. Rok Orhan at Camp Mojache wants to see it and learn what it means for the Gordunni. You find a soiled scroll at the Gordunni Outpost. Its image seems to show a gathering or ceremony. Rok Orhan at Camp Mojache wants to see it and learn what it might mean for the Gordunni.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2978-e33f2407e724a332d6aa/1-0000.mp3", duration = 27.8726531, start = 0},
  },
}
P.transport["quest:2979"] = {
  hash = "c1bc9e",
  fullHash = "c1bc9e",
  text = "Dark Ceremony. At Camp Mojache, Rok Orhan studies the Gordunni Scroll and seeks an orb from a Gordunni mage-lord. He hopes it will reveal more about the ceremony and the Gordunni's magic. Rok Orhan reads the Gordunni Scroll as plans for a dark ceremony. He believes the Gordunni mage-lords conduct it. Find one of them and take his orb. A mage's orb holds great power, and Rok hopes it will teach him more about the ceremony and the magic the Gordunni wield.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2979-706ff4c2de1f0ff3f5c6/1-0000.mp3", duration = 34.3771429, start = 0},
  },
}
P.transport["quest:2980"] = {
  hash = "040972",
  fullHash = "040972",
  text = "The Ogres of Feralas. In Feralas, Rok Orhan sends you southwest of Camp Mojache to drive back the Gordunni ogres. You have proved yourself a true fighter, and he trusts you with this work in the High Wilderness. Rok Orhan trusts you with this work because you have proved yourself a true fighter. Southwest of Camp Mojache, the High Wilderness holds abandoned, wrecked structures on ground the night elves once owned.\n\nWithered trees and desecrated ground mark the Gordunni's territory. Rok warns that these ogres are far tougher than the earlier ones. Ten Gordunni Shamans, ten Gordunni Warlocks and five Gordunni Maulers are to fall.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2980-8742430df3c1d36d442b/1-0000.mp3", duration = 43.0759184, start = 0},
  },
}
P.transport["quest:2982"] = {
  hash = "703c2c",
  fullHash = "703c2c",
  text = "The High Wilderness. In Feralas, Angelas Moonbreeze worries as Troyas enters the High Wilderness alone. Gordunni ogres hold that ground, and she hopes you can make the ruins southeast of here safer by culling them. Angelas Moonbreeze and Troyas explore the scattered ruins of Feralas, though the work is dangerous. Lately, Troyas goes to the High Wilderness alone, and Angelas fears for him. Gordunni ogres hold that ground and welcome no one into their territory. So Angelas asks you to make the ruins southeast of here safer for Troyas by culling eight Gordunni Warlocks, eight Gordunni Shamans and eight Gordunni Brutes.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2982-5a38fb533ac7d7caef78/1-0000.mp3", duration = 44.1991837, start = 0},
  },
}
P.transport["quest:2987"] = {
  hash = "18cef0",
  fullHash = "18cef0",
  text = "Gordunni Cobalt. Orwin Gizzmick has come to Feralas seeking cobalt buried by the Gordunni ogres. He asks you to search the Gordunni Outpost, north of Camp Mojache, for twelve samples. New to Feralas, Orwin Gizzmick has heard that the Gordunni ogres bury interesting minerals. They guard the minerals fiercely, keeping them from folk like Orwin. He does not know what they want them for.\n\nOrwin gives you a shovel and points you north of Camp Mojache to the Gordunni Outpost. Follow the blue glow and dig up twelve samples of Gordunni cobalt.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2987-cd63dfe705017b6b287c/1-0000.mp3", duration = 35.3959184, start = 0},
  },
}
P.transport["quest:2988"] = {
  hash = "e32297",
  fullHash = "e32297",
  text = "Witherbark Cages. At Witherbark Cages, you search for Sharpbeak, heir of Swiftwing, whom Talonaxe calls the mightiest gryphon. Gryphon Master Talonaxe believes the trolls took the young gryphon. Gryphon Master Talonaxe asks you to find Sharpbeak, who went missing a few days ago while hunting with his parents. Talonaxe and the others believe the trolls took him. Three cages in the two Witherbark troll villages remain to be checked. Talonaxe awaits your findings.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2988-0971180bb4af25642a9e/1-0000.mp3", duration = 34.5077551, start = 0},
  },
}
P.transport["quest:2989"] = {
  hash = "201e3d",
  fullHash = "201e3d",
  text = "The Altar of Zul. At the Altar of Zul, Talonaxe's search for Sharpbeak reaches the Vilebranch lands. Witherbark has no sign of the young gryphon, and Talonaxe fears the Vilebranch may hold him. With no sign of Sharpbeak in the Witherbark cages, Gryphon Master Talonaxe suspects the Vilebranch trolls took him. So he sends you to search the top of the Altar of Zul, at the western edge of their lands. If they hold the gryphon child, Talonaxe fears what they may be doing to him.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2989-d5e2226f40bce17677d8/1-0000.mp3", duration = 33.5673469, start = 0},
  },
}
P.transport["quest:2990"] = {
  hash = "c3ba27",
  fullHash = "c3ba27",
  text = "Thadius Grimshade. At Nethergarde Keep, Talonaxe sends you to Thadius Grimshade with a feather from Sharpbeak's nest. Years ago, Thadius Grimshade left Aerie Peak to seek darker knowledge. Yet Talonaxe says he remains a Wildhammer at heart. He hopes Thadius can use divining magic and Sharpbeak's feather to find the gryphon child. Thadius lives in the mage tower at Nethergarde Keep, in the Blasted Lands.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2990-2a1522c751c8a24db894/1-0000.mp3", duration = 30.6677551, start = 0},
  },
}
P.transport["quest:2992"] = {
  hash = "5c07b0",
  fullHash = "5c07b0",
  text = "The Divination. Thadius Grimshade turns to Sharpbeak’s feather, seeking the gryphon through its trace. He asks you to give him room as he follows the bond to its owner. Thadius Grimshade follows the bond between Sharpbeak’s feather and the gryphon who owns it. He hopes to reach Sharpbeak himself, and asks you for silence and room to work. The ritual may not go as planned. If it does not, he warns, you had better close your eyes.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2992-8d8552b1d404a60ff863/1-0000.mp3", duration = 32.1828571, start = 0},
  },
}
P.transport["quest:2993"] = {
  hash = "8546b6",
  fullHash = "8546b6",
  text = "Return to the Hinterlands. You carry Thadius Grimshade's news of Sharpbeak to Gryphon Master Talonaxe. Thadius Grimshade has learned where Sharpbeak is held. The gryphon is caged on a high cliff atop Jintha'Alor in the Hinterlands. Vile Priestess Hexx, high priestess of the Vilebranch trolls, holds the key. You bring the news to Gryphon Master Talonaxe.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2993-6cf2f827469e9001ef6b/1-0000.mp3", duration = 26.2008163, start = 0},
  },
}
P.transport["quest:2994"] = {
  hash = "83ca55",
  fullHash = "83ca55",
  text = "Saving Sharpbeak. At Jintha'Alor, Sharpbeak waits in a cage deep in Vilebranch territory. Gryphon Master Talonaxe sends you to free him, and Vile Priestess Hexx holds the key. After Thadius Grimshade's divination, you report to Talonaxe. Now the path to Sharpbeak is clear. Jintha'Alor lies at the heart of Vilebranch territory, and you fight your way to its summit. Vile Priestess Hexx holds the key to Sharpbeak's cage. Take it from her, then find the cage and free the gryphon.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2994-e0dbf9b3111d7d24e208/1-0000.mp3", duration = 35.9183673, start = 0},
  },
}
P.transport["quest:3002"] = {
  hash = "6164be",
  fullHash = "6164be",
  text = "The Gordunni Orb. After Dark Ceremony, Rok Orhan sends you to Orgrimmar with the Gordunni Orb. Uthel'nay at Darkbriar Lodge can judge its power. After Dark Ceremony, Rok Orhan holds the Gordunni Orb. He knows the Gordunni well, but a warrior cannot judge the orb's power. So he sends you to Orgrimmar with it. There, Uthel'nay at Darkbriar Lodge can tell you more.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3002-080b42cb3203437d347d/1-0000.mp3", duration = 26.3314286, start = 0},
  },
}
P.transport["quest:3022"] = {
  hash = "92e887",
  fullHash = "92e887",
  text = "Handle With Care. Curgle Cranklehop sends a crate of eggs to a druid in Rut'theran. The village lies in Teldrassil. Curgle Cranklehop entrusts you with a carefully packed crate for Erelas Ambersky. Hippogryph eggs lie inside, bound for the druid. Erelas Ambersky cares for hippogryph eggs in Rut'theran Village. He helps them hatch and trains the young hippogryphs. Rut'theran is a small village in southern Teldrassil.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3022-c19d30939012798208d4/1-0000.mp3", duration = 33.0187755, start = 0},
  },
}
P.transport["quest:3062"] = {
  hash = "f48764",
  fullHash = "f48764",
  text = "Dark Heart. At Camp Mojache, Talo Thornhoof seeks Edana Hatetalon’s heart to end the hatred she spreads. Edana Hatetalon rules the Northspring brood in ruins to the west. Talo calls her pure evil and says she feels nothing but hatred for everyone. He has heard her heart is made of crystal. He asks you to face her and bring back her dark heart, so her hatred can be stopped. Talo has heard that harpies carry a horn. Sound it near the Hatetalon stones in the northern part of the ruins, and it is said to draw Edana out. Talo relishes the thought that death, rather than her kin, will answer her call.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3062-2d122c299c41bffaaed0/1-0000.mp3", duration = 42.4228571, start = 0},
  },
}
P.transport["quest:3063"] = {
  hash = "b161ed",
  fullHash = "b161ed",
  text = "Vengeance on the Northspring. Talo Thornhoof seeks vengeance on the Northspring harpies to the west. Once a hunter who feared no creature, Talo has hated them since they ambushed Talo in the forest. Talo Thornhoof once hunted the wild without fear. After a hard fight, Talo stayed in the forest to hone a weapon. Then harpies closed in, and Talo barely escaped to safety. Their cries still echo in Talo's memory. Talo's life was never the same, and the hatred has endured. Now Talo wants revenge. The Northspring harpies live to the west. Talo asks you to kill four Northspring Harpies, four Northspring Roguefeathers, four Northspring Windcallers and four Northspring Slayers. Their wings are black as night, Talo warns. They can vanish into the darkness.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3063-38bdfda75c2008dc9e55/1-0000.mp3", duration = 55.8236735, start = 0},
  },
}
P.transport["quest:3121"] = {
  hash = "1cd431",
  fullHash = "1cd431",
  text = "A Strange Request. In Feralas, Witch Doctor Uzer'i sends you to Orgrimmar for a concoction. Witch Doctor Uzer'i says Neeru Fireblade in Orgrimmar has a concoction needed to begin work in Feralas. Uzer'i will not yet explain what it is for. You carry a shrunken head, promised to Neeru in exchange for the herbs. It belonged to some poor dwarf Uzer'i came across in the forest. Neeru waits in the Cleft of Shadow.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3121-2a70dd52b76b8a116934/1-0000.mp3", duration = 29.1004082, start = 0},
  },
}
P.transport["quest:3122"] = {
  hash = "cbb07f",
  fullHash = "cbb07f",
  text = "Return to Witch Doctor Uzer'i. Neeru Fireblade sends you to Witch Doctor Uzer'i in Feralas with herbs and word that he is satisfied with the shrunken head. After A Strange Request, Neeru Fireblade gives you herbs for Witch Doctor Uzer'i in Feralas. Take them to Uzer'i and tell him Neeru is satisfied with the shrunken head.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3122-2d7c601af1387aa8e9b6/1-0000.mp3", duration = 19.8530612, start = 0},
  },
}
P.transport["quest:3123"] = {
  hash = "48b4dc",
  fullHash = "48b4dc",
  text = "Testing the Vessel. You return to Witch Doctor Uzer'i, who tests the ritual and your skill. Now you must capture ten wildkin in the Hinterlands and bring them with the vessel back to Feralas. Witch Doctor Uzer'i tests the ritual you just performed and your own skill. The vessel Uzer'i gives you can shrink a creature and trap it inside. You travel to the Hinterlands to find wildkin. Their kind once belonged to Elune, the night elf goddess, as pets. Uzer'i names the vicious, primitive, savage owlbeasts as your quarry. Capture ten before their spirits slip away, then return with them and the vessel to Uzer'i in Feralas.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3123-ed183e530788f016d0ae/1-0000.mp3", duration = 45.9493878, start = 0},
  },
}
P.transport["quest:3124"] = {
  hash = "5a39b4",
  fullHash = "5a39b4",
  text = "Hippogryph Muisek. In the High Wilderness, Frayfeather hippogryphs carry spirits Uzer'i wants you to capture. Their muisek can escape unless you act quickly. Witch Doctor Uzer'i trusts you with the vessel and asks you to capture another creature's spirit. Hippogryphs have long been companions to the night elves, and their spirits are loyal and steadfast. You need ten Frayfeather hippogryphs of any kind. Kill each one, then quickly shrink and capture it with the vessel to preserve its muisek. Uzer'i places them in the High Wilderness, south of the camp.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3124-c1de53b659be5506750c/1-0000.mp3", duration = 38.1126531, start = 0},
  },
}
P.transport["quest:3125"] = {
  hash = "178bef",
  fullHash = "178bef",
  text = "Faerie Dragon Muisek. West of Witch Doctor Uzer'i, the Horde seeks the spirits of faerie dragons. Sprite darters and sprite dragons bear the strength Uzer'i hopes to capture. Witch Doctor Uzer'i sees strength in faerie dragons, though they look delicate. They have long been allies to the night elves, and Uzer'i wants the Horde to share their power. Uzer'i gives you a Muisek Vessel and sends you west. Slay eight sprite darters or sprite dragons, then use the vessel on each fallen faerie dragon to shrink and capture its spirit.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3125-0d98c31b5036a3d482c4/1-0000.mp3", duration = 31.8171429, start = 0},
  },
}
P.transport["quest:3126"] = {
  hash = "65dda2",
  fullHash = "65dda2",
  text = "Treant Muisek. In Feralas, Witch Doctor Uzer'i turns your search to the wandering treants. After the faerie dragons, he sends you to find three forest walkers. The night elves have made treants their allies against the Horde. Uzer'i says they move slowly, yet none can deny their strength as protectors. He means to put that strength to work for the Horde. Uzer'i asks you to find and kill three wandering forest walkers. When each treant falls, use the Muisek Vessel to shrink and capture it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3126-2b7322fbabfea16d628a/1-0000.mp3", duration = 28.7608163, start = 0},
  },
}
P.transport["quest:3127"] = {
  hash = "d9a577",
  fullHash = "d9a577",
  text = "Mountain Giant Muisek. Northwest across Feralas, you face the last creatures Witch Doctor Uzer'i hopes to harness: mountain giants. Witch Doctor Uzer'i says mountain giants came down from the mountains to aid the night elves when the Burning Legion first arrived in the world. Their immense size marks them, and rocky ground trembles beneath their steps. Uzer'i hopes to harness power on that scale.\n\nSeven Land Walkers or Cliff Giants must fall. Then the Muisek Vessel can shrink and capture them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3127-0f08500cfeed0d2c7ead/1-0000.mp3", duration = 31.4253061, start = 0},
  },
}
P.transport["quest:3128"] = {
  hash = "252c11",
  fullHash = "252c11",
  text = "Natural Materials. In Camp Mojache, Natural Materials are needed by Witch Doctor Uzer'i for an endeavor. The materials come from treants, mountain giants, faerie dragons, owlbeasts and hippogryphs, alongside the other trials. After you return to Witch Doctor Uzer'i, another list of materials awaits alongside the other trials. Bring two splintered logs from a Feralas treant. Mountain giants and faerie dragons westward carry six pieces of encrusted minerals. Owlbeasts in the Hinterlands or hippogryphs in Feralas provide twenty pieces of resilient sinew. Any of these creatures can yield the forty metallic fragments needed.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3128-0b2bc447356c4c97c402/1-0000.mp3", duration = 39.9412245, start = 0},
  },
}
P.transport["quest:3129"] = {
  hash = "016cce",
  fullHash = "016cce",
  text = "Weapons of Spirit. Witch Doctor Uzer'i is preparing weapons for you in Feralas. The work takes time, so you wait while the spirits are bound. Witch Doctor Uzer'i has the materials and the spirits you captured. Imbuing weapons with muisek takes hard work, so Uzer'i asks you to wait while the weapons are prepared.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3129-167fc5856bd0c849e551/1-0000.mp3", duration = 21.8122449, start = 0},
  },
}
P.transport["quest:3130"] = {
  hash = "d834c7",
  fullHash = "d834c7",
  text = "Against the Hatecrest. In Feathermoon Stronghold, Shandris sends you to Latronicus as she weighs the naga threat. General Shandris Feathermoon sends you to Latronicus Moonspear, her second. He has watched the naga forces closely, and Shandris must judge the wider danger they pose.\n\nShe would like to commit a full force against them. But then Feathermoon Stronghold would be open to a direct attack from the Horde, or something worse. Latronicus awaits you in the stronghold.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3130-6e4de0a374da2a008f9b/1-0000.mp3", duration = 31.3469388, start = 0},
  },
}
P.transport["quest:3161"] = {
  hash = "aeba8e",
  fullHash = "aeba8e",
  text = "Gahz'ridian. In Tanaris, Marvon Rivetseeker searches for thirty ornaments left by its old trolls. He gives you a detector of his own making to help find them. Long ago, trolls lived in Tanaris and carved ornaments in the likeness of Gahz'rilla, the hydra they revered as a god. Marvon Rivetseeker named the element in the carvings Gahz'ridian, after the hydra. He has found a few ornaments and wants more to study. Marvon Rivetseeker gives you a detector he invented to make finding Gahz'ridian easier. Wear it, and the search begins. The ornaments may lie almost anywhere in Tanaris. They are thickest near Broken Pillar, the Eastmoon Ruins and the Southmoon Ruins.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3161-4434db78208d0428a084/1-0000.mp3", duration = 49.162449, start = 0},
  },
}
P.transport["quest:3181"] = {
  hash = "5145f4",
  fullHash = "5145f4",
  text = "The Horn of the Beast. In Searing Gorge, Margol the Rager's horn bears a broken axe head. Margol the Rager's horn is scratched and cracked. A broken axe head is lodged in its rough surface, and Mountaineer Pebblebitty's name marks the metal. When you try to free it, the axe head shatters into a million pieces. Stonewrought Pass runs between Loch Modan and Searing Gorge. The horn begins the chain that opens the gate, and you are to take it to Mountaineer Pebblebitty. Pebblebitty is not willing to open the gate.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3181-7fb02e1e86669efbf768/1-0000.mp3", duration = 32.6269388, start = 0},
  },
}
P.transport["quest:32"] = {
  hash = "764e5c",
  fullHash = "764e5c",
  text = "Rise of the Silithid. In Orgrimmar, you carry Senior Surveyor Fizzledowser's report on the insect threat to Zilzibin Drumlore. Senior Surveyor Fizzledowser wants the report in the hands of someone who understands such matters. Zilzibin Drumlore is a troll scholar and historian who has spent much time studying Azeroth's unique life forms. Fizzledowser hopes Zilzibin can learn what the danger is and how it might be stopped. All the help they can get will be needed. Zilzibin lives in a house on the Drag's second tier, in Orgrimmar.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_32-3690010eaf7a4e2c31d9/1-0000.mp3", duration = 34.0636735, start = 0},
  },
}
P.transport["quest:328"] = {
  hash = "41d1d8",
  fullHash = "41d1d8",
  text = "The Hidden Key. Bookie Herod's papers lead you to a strongbox in the Stockpile. Its contents may reveal how Private Thorsen's cover was blown. Bookie Herod's ledgers never name Private Thorsen. But one book hides a small brass key in its binding. Scraps among the papers point to a strongbox in the Stockpile, the cavern complex behind Kurzen's Compound. Inside may lie the reason Thorsen's cover was blown. Deep in the cave system behind Kurzen's Compound, the strongbox waits among stacked crates. The sturdy chest is heavy and bound in bronze.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_328-37219bfc093f281fed77/1-0000.mp3", duration = 38.6089796, start = 0},
  },
}
P.transport["quest:329"] = {
  hash = "5a2bc9",
  fullHash = "5a2bc9",
  text = "The Spy Revealed!. You have found a muddy note in Bookie Herod's strongbox. Its account of Private Thorsen's daily routines points to an informant among the rebels in northern Stranglethorn Vale, and it is meant for Lieutenant Doren. At the Rebel Camp, the note traces Private Thorsen's patrols, companions, and daily activities. Someone has watched him closely. The signature is only -M, and the detail points to a traitor living beside him in the camp.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_329-2b87ad7574e9b8d9e06c/1-0000.mp3", duration = 35.7093878, start = 0},
  },
}
P.transport["quest:330"] = {
  hash = "0f9bbd",
  fullHash = "0f9bbd",
  text = "Patrol Schedules. At the Rebel Camp, Lieutenant Doren searches for the writer behind a note signed only with an initial. The writer says they shared patrol routes with Private Thorsen the previous week, and the duty records may reveal their name. A note found at the Rebel Camp bears the initial M. Its writer says they walked regular routes with Private Thorsen during the previous week. That may point to the one aiding the Kurzen forces. Lieutenant Doren sends you to Corporal Sethman, who keeps the duty logs. His records may show who patrolled beside Thorsen.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_330-d6eb0a6a3fa158dfe33d/1-0000.mp3", duration = 39.6016327, start = 0},
  },
}
P.transport["quest:331"] = {
  hash = "4ddc0c",
  fullHash = "4ddc0c",
  text = "Report to Doren. Corporal Sethman sends you to report the patrol findings to Lieutenant Doren. The rebels' commander receives them at Rebel Camp in northern Stranglethorn Vale. Corporal Sethman wants you to give Lieutenant Doren a direct account of the patrol information. Bring back what you learned.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_331-8f8ed3ee631d60e6a230/1-0000.mp3", duration = 20.6106122, start = 0},
  },
}
P.transport["quest:3362"] = {
  hash = "e29228",
  fullHash = "e29228",
  text = "Thistleshrub Valley. In Tanaris, strange beasts keep Tran'rek from entering Thistleshrub Valley. They hope to return once the creatures are cleared away. South-west of Gadgetzan, Tran'rek warns that Thistleshrub Valley is a dangerous place. Strange beasts roam there, including gnarled thistleshrubs and thistleshrub rootshapers. With so many about, Tran'rek will not return. Tran'rek asks you to clear out eight gnarled thistleshrubs and eight thistleshrub rootshapers. They also want a closer look at the cactus in the valley, so leave some of it in one piece.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3362-ae3b0de896697814d448/1-0000.mp3", duration = 34.1159184, start = 0},
  },
}
P.transport["quest:3367"] = {
  hash = "eb1b79",
  fullHash = "eb1b79",
  text = "Suntara Stones. In Searing Gorge, Dorius Stonetender lies badly hurt and asks you to help him reach Ironforge. Dorius Stonetender groans with pain. He feels light-headed as the world spins around him, and he is bleeding inside. He longs to return to Ironforge. So he asks you to help him make the journey.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3367-21c11d65e907ffb58306/1-0000.mp3", duration = 21.8383673, start = 0},
  },
}
P.transport["quest:3368"] = {
  hash = "65e56b",
  fullHash = "65e56b",
  text = "Suntara Stones. At the Suntara Stones, Dorius's letter tells of a team enslaved by the Dark Irons. The stones are real and held by the Dark Irons. Their leader, Lathoric the Black, uses the stones' power to enslave Dorius's excavation team. You carry the letter to his brother Thorius at Ironforge's Hall of Explorers. Dorius's letter tells his brother he is gone if the message is being read. The Suntara Stones are real, and the Dark Irons hold them. Their leader, Lathoric the Black, uses their power to enslave Dorius's excavation team. The team was taken to the cauldron, where their minds are twisted as they toil day and night to finish something called Obsidion. Dorius begs his brother to help them. He calls it his final wish and asks that those who bring the letter be thanked.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3368-e32d75c50a332c000959/1-0000.mp3", duration = 58.5665306, start = 0},
  },
}
P.transport["quest:3372"] = {
  hash = "9dece5",
  fullHash = "9dece5",
  text = "Release Them. In Searing Gorge, a dying archaeologist begs you to free those still laboring under Suntara's power. Their bodies have failed, and the relic guarded by Twilight's Hammer must be placed on Suntara's altar. A dying archaeologist asks you to release those still at their labor, then collapses. Their bodies have given out, yet Suntara's power drives them on. The archaeologist says Suntara's altar is the key. Northwest of the cave, in the hills above it, Twilight's Hammer Idolaters guard the Mysterious Artifact. Take the relic from them and carry it to the Slag Pit. There, set it upon Suntara's altar.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3372-29cbc8a473ebece5af1a/1-0000.mp3", duration = 48.7183673, start = 0},
  },
}
P.transport["quest:3374"] = {
  hash = "c41695",
  fullHash = "c41695",
  text = "The Essence of Eranikus. At the Oathstone, Itharius reaches you through the stone and asks you to help redeem Eranikus's corrupted soul. The first sacrifice is the gem that chains the free part of Eranikus's mind. Itharius waits in the Swamp of Sorrows. Through the Oathstone, Itharius asks you to aid Ysera's Dragonflight in redeeming Eranikus's corrupted soul. He warns that many sacrifices will be asked of you both. First, give him the gem that chains the part of Eranikus's mind still free. Take the Oathstone and the Chained Essence of Eranikus to Itharius in the Swamp of Sorrows. There, you choose whether to aid the dragonflight.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3374-7ff4c335e1886910b4be/1-0000.mp3", duration = 48.6922449, start = 0},
  },
}
P.transport["quest:3377"] = {
  hash = "fc6f07",
  fullHash = "fc6f07",
  text = "Prayer to Elune. In Searing Gorge, Zamael Lunthistle waits in a cage and asks for your help. Many years have passed since anyone visited him, and first he asks you to hear his tale. Zamael Lunthistle greets you with praise to Elune. Many years have passed since anyone came to visit him. Now he asks for your help. First, hear his tale.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3377-aa30ec5cdea30549f749/1-0000.mp3", duration = 24.1371429, start = 0},
  },
}
P.transport["quest:3378"] = {
  hash = "eb80dd",
  fullHash = "eb80dd",
  text = "Prayer to Elune. At Zamael Lunthistle's request, you seek a prayer to Elune lost among the idol worshippers. Engraved on a golden tablet, it is meant for Astarii Starseeker in Darnassus. Zamael Lunthistle's faith has awakened again. Yet he says that means little after the harm he has done to the world and its people. He expects no absolution. He asks only for his prayer to be heard, so you seek the golden tablet from the idol worshippers and carry it to Astarii Starseeker in Darnassus.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3378-bd423fd3bb71b3b17513/1-0000.mp3", duration = 39.8628571, start = 0},
  },
}
P.transport["quest:338"] = {
  hash = "f719a9",
  fullHash = "f719a9",
  text = "The Green Hills of Stranglethorn. Across Stranglethorn Vale, loose pages from Hemet Nesingwary's novel lie scattered through the jungle. Barnil Stonepot asks you to gather them into four chapters and return them. At the expedition camp, Barnil Stonepot is troubled after Welcome to the Jungle. While he proofread Hemet Nesingwary's draft, a gale snatched its loose pages and flung them into the wild. Barnil recovered many, but others remain lost in the brush. He needs you to find them and assemble Chapter I, Chapter II, Chapter III, and Chapter IV before Nesingwary learns what happened. Once you return all four chapters, Barnil can avoid an unpleasant confrontation with Nesingwary. He hopes the restored manuscript will soon reach libraries across the world.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_338-5b7b3b945aa4a147b394/1-0000.mp3", duration = 48.0130612, start = 0},
  },
}
P.transport["quest:339"] = {
  hash = "8f5eb4",
  fullHash = "8f5eb4",
  text = "Chapter I. In Stranglethorn, Barnil Stonepot searches the jungle for four lost pages of Hemet Nesingwary's hunting manuscript. Barnil Stonepot wants the opening passage of The Green Hills of Stranglethorn restored. He says it sets the stage for the wider story and describes Hemet Nesingwary's hunting party, including Barnil himself. Pages one, four, six, and eight are missing in the jungle. When you return the four missing leaves, Barnil pieces the first section of Hemet Nesingwary's text back together.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_339-925544e8a747b6e9c209/1-0000.mp3", duration = 34.5077551, start = 0},
  },
}
P.transport["quest:340"] = {
  hash = "739478",
  fullHash = "739478",
  text = "Chapter II. In Stranglethorn Vale, Barnil Stonepot searches for leaves missing from Hemet Nesingwary's manuscript. He gathered most of them himself, but travelers must help find the rest. Barnil Stonepot has recovered many leaves from Hemet Nesingwary's scattered manuscript across Stranglethorn Vale. The second chapter follows panthers and tigers through the wilderness. Pages ten, eleven, fourteen, and sixteen remain missing, so those hunting accounts are incomplete.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_340-5becca7e13f9ff8c9f2c/1-0000.mp3", duration = 29.4661224, start = 0},
  },
}
P.transport["quest:341"] = {
  hash = "950b61",
  fullHash = "950b61",
  text = "Chapter III. Barnil Stonepot searches Stranglethorn Vale for the missing leaves of Hemet Nesingwary's hunting manuscript. Its third chapter tells of Sir Erlgadin and Lady Rouack's first kill with a dwarven rifle. Barnil Stonepot favors this part of The Green Hills of Stranglethorn. It follows Sir Erlgadin and Lady Rouack in their early exploits, including their first kill with a dwarven rifle. Then the tale breaks off at a sharp cliffhanger. Barnil needs four leaves to restore the story: pages eighteen, twenty, twenty-one, and twenty-four. They were carried off with the rest of the manuscript and scattered across Stranglethorn Vale.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_341-2cd59bd5fbf23874d67e/1-0000.mp3", duration = 41.2995918, start = 0},
  },
}
P.transport["quest:342"] = {
  hash = "23b738",
  fullHash = "23b738",
  text = "Chapter IV. Barnil Stonepot is searching for the ending of Hemet Nesingwary's hunting tale in Chapter IV. Three pages are missing from the jungle. Barnil Stonepot calls the fourth chapter Hemet Nesingwary's grand finale. He needs you to find pages twenty-five, twenty-six, and twenty-seven. The three sheets lie scattered across the jungle. Without them, he cannot restore the tale's conclusion.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_342-9e494f0e2d80131f7176/1-0000.mp3", duration = 26.1746939, start = 0},
  },
}
P.transport["quest:3441"] = {
  hash = "ed068c",
  fullHash = "ed068c",
  text = "Divine Retribution. In Searing Gorge, Kalaran Windblade tells you how his father died and why he seeks vengeance. Stormwind would not hear his plea, so he turns to a brave adventurer. Kalaran says the filth in the cauldron killed his father. He pleaded with the Stormwind magistrate, but no one answered. He says Stormwind would rather deny this part of the world exists than send soldiers to see justice done. Kalaran wants vengeance. Only a lumbering oaf of a squire stands with him, while the Dark Iron dwarves and Ragnaros's beasts could crush him alone. So he trusts a brave adventurer to face the cauldron's denizens. For anyone who helps, he promises riches beyond all dreams.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3441-25e3db78ff464cb4b06c/1-0000.mp3", duration = 45.9232653, start = 0},
  },
}
P.transport["quest:3442"] = {
  hash = "76f523",
  fullHash = "76f523",
  text = "The Flawless Flame. In Searing Gorge, Kalaran Windblade prepares to strike where it will hurt most. He means to burn the four sentry towers, opening the way for an offensive before anyone can react. First, he needs a torch of flawless flame. After Divine Retribution, Kalaran Windblade lays out his plan. He means to burn the four sentry towers so an offensive can begin before anyone has time to react.\n\nFor that, he needs the right tool and the materials to make it. Bring Kalaran four hearts of flame and four globes of golem oil, and he will craft the torch of flawless flame. He points you toward the golems and elementals of these lands.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3442-86a8741ebaa03a5a581f/1-0000.mp3", duration = 43.4155102, start = 0},
  },
}
P.transport["quest:3443"] = {
  hash = "f0a582",
  fullHash = "f0a582",
  text = "Forging the Shaft. After The Flawless Flame, Kalaran Windblade needs a shaft to hold its fire. Eight thorium plated daggers from the cauldron can be reforged into one. Kalaran Windblade needs a shaft and a casing to hold the flawless flame. In the cauldron, Dark Iron slavers and taskmasters wield enchanted thorium, a sturdy metal. Kalaran can break down eight of their daggers and reforge the alloy into a shaft.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3443-180e24e9261487e25e8c/1-0000.mp3", duration = 28.4995918, start = 0},
  },
}
P.transport["quest:3444"] = {
  hash = "9c3ba9",
  fullHash = "9c3ba9",
  text = "The Stone Circle. Marvon Rivetseeker waits in Ratchet for a serpent-marked stone. He barely escaped the Sunken Temple, and hopes it will bring back his memories. Marvon Rivetseeker remembers the evil that touched everyone who entered the Sunken Temple. Escaping meant struggling through ooze spread across the floors. One place stayed with him: a large round room crowded with serpent statues. Marvon Rivetseeker found a round stone marked with what seems to be the same serpent symbol. He had it crated and sent to his workshop in Ratchet. Bring it to him, and he may remember more.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3444-110e9d9442a8dc303909/1-0000.mp3", duration = 39.5493878, start = 0},
  },
}
P.transport["quest:3445"] = {
  hash = "b5e4b1",
  fullHash = "b5e4b1",
  text = "The Sunken Temple. Angelas Moonbreeze points you toward a buried place and a missing scholar. Far below the earth, the Sunken Temple lies beyond any power Angelas has seen. To learn more, seek Marvon Rivetseeker, last known to be in Tanaris. Angelas Moonbreeze tells you that the Sunken Temple was driven deep beneath the earth by forces beyond anything she has seen. She sends you to Marvon Rivetseeker, a goblin who studies ancient sites with her and Troyas.\n\nMarvon left his home in Ratchet to investigate the troll ruins of Tanaris. No word of him has come for some time.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3445-44faae46a9bad200e18b/1-0000.mp3", duration = 45.4269388, start = 0},
  },
}
P.transport["quest:3452"] = {
  hash = "f46828",
  fullHash = "f46828",
  text = "The Flame's Casing. Kalaran Windblade seeks the last piece for the torch. A large Twilight's Hammer encampment is rumored to lie in the mountains to the northwest, where its people honor their god with symbols and idols. He wants one Symbol of Ragnaros. Kalaran Windblade says the torch needs one last piece. A large Twilight's Hammer encampment is rumored to lie in the mountains to the northwest, with symbols and idols honoring its god. Their enchantment may give the torch a magical casing. Kalaran asks you for one Symbol of Ragnaros, hoping to draw out its magic. Without a suitable source of arcane energy, the torch of retribution cannot be finished.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3452-9b33e14c58df23f0033e/1-0000.mp3", duration = 51.8530612, start = 0},
  },
}
P.transport["quest:3453"] = {
  hash = "22f6ee",
  fullHash = "22f6ee",
  text = "The Torch of Retribution. At Kalaran Windblade's side, you wait while he joins the pieces and enchants The Torch of Retribution. Kalaran Windblade needs time to join the pieces and enchant the torch. He channels magic as he works, so you wait and leave him undisturbed.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3453-2bb2980263c0998f2925/1-0000.mp3", duration = 18.5469388, start = 0},
  },
}
P.transport["quest:3454"] = {
  hash = "7ab3d5",
  fullHash = "7ab3d5",
  text = "The Torch of Retribution. Kalaran Windblade has finished the torch and asks you to claim it. Kalaran Windblade says the torch must be bound to its owner. He asks you to take it up yourself.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3454-e43ffb414dd71c55878b/1-0000.mp3", duration = 13.2440816, start = 0},
  },
}
P.transport["quest:3462"] = {
  hash = "838c0b",
  fullHash = "838c0b",
  text = "Squire Maltrake. With the Torch of Retribution in hand, Kalaran Windblade sends you to Squire Maltrake for instructions. Kalaran Windblade sends you to Squire Maltrake. The squire will explain how to use the Torch of Retribution.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3462-fe363e65b800996cc293/1-0000.mp3", duration = 15.0465306, start = 0},
  },
}
P.transport["quest:3463"] = {
  hash = "6abf81",
  fullHash = "6abf81",
  text = "Set Them Ablaze!. In Searing Gorge, you carry Maltrake’s torch to the four sentry towers. Its flames cannot be subdued, and the towers cannot be destroyed. While they burn, guards and sentries abandon their posts, leaving the Dark Irons without their first line of defense. The Torch of Retribution burns beyond the power of any element or force to subdue. Maltrake sends you into each of the four sentry towers, North, South, East and West, to use it within the walls. Dark Iron lookouts keep watch there, so Maltrake warns you to beware.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3463-d07baa07c1d565ec24ab/1-0000.mp3", duration = 37.0155102, start = 0},
  },
}
P.transport["quest:348"] = {
  hash = "8b33de",
  fullHash = "8b33de",
  text = "Stranglethorn Fever. In Booty Bay, Fin Fizracket grows weaker with Stranglethorn Fever. He believes he is dying and says only Mokk the Savage's heart can cure him. Fin Fizracket stammers as his strength fails. Certain he has caught Stranglethorn Fever, he says he must eat the heart of Mokk the Savage to be cured. Mokk is an elusive white beast, and only Witch Doctor Unbagwa can summon him. Fin sends you to find Unbagwa in the Spirit Den, a hidden cave on the southern cape.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_348-57976bc7b9dc481b28de/1-0000.mp3", duration = 32.6269388, start = 0},
  },
}
P.transport["quest:3481"] = {
  hash = "de4ada",
  fullHash = "de4ada",
  text = "Trinkets.... After Set Them Ablaze!, you find the Hoard of the Black Dragonflight in Searing Gorge. The Hoard of the Black Dragonflight waits in Searing Gorge after the towers burn. The chest looks locked, and it is yours to open.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3481-b207130f43620ac6d134/1-0000.mp3", duration = 16.3265306, start = 0},
  },
}
P.transport["quest:349"] = {
  hash = "de2d1e",
  fullHash = "de2d1e",
  text = "Stranglethorn Fever. In Stranglethorn Vale, Witch Doctor Unbagwa prepares a chant to draw Mokk the Savage from the jungle. He needs ten Gorilla Fangs to begin. As he communes with the spirits, nearby gorillas come to threaten him. Witch Doctor Unbagwa knows a ritual that can draw Mokk the Savage from the jungle. He asks for ten Gorilla Fangs before beginning the chant. As he communes with the spirits, the chant draws nearby gorillas. They threaten the witch doctor while he tries to finish the ritual.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_349-5edb191c7cde8dabee5f/1-0000.mp3", duration = 35.7877551, start = 0},
  },
}
P.transport["quest:351"] = {
  hash = "dd5000",
  fullHash = "dd5000",
  text = "Find OOX-17/TN!. In Tanaris, you turn the knob and Find OOX-17/TN! springs to life. Oglethorpe's voice says his homing robot is missing and asks you to carry the beacon to it. A knob opens the strange egg, revealing a gnomish contraption. A voice crackles from within and names its speaker as Oglethorpe. His homing robot has gone missing. Oglethorpe has computed where it went down, near the Gaping Chasm in Tanaris, and asks you to take the beacon there.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_351-38a9bac6b42b02ed8366/1-0000.mp3", duration = 28.5518367, start = 0},
  },
}
P.transport["quest:3512"] = {
  hash = "1dfe12",
  fullHash = "1dfe12",
  text = "In Eranikus' Own Words. Itharius seeks Eranikus' voice through the gem. Eranikus lies between sleep and death, caught in nightmares. The essence you gave is badly tainted, yet hope remains. Itharius sends you to eastern Winterspring. Itharius says Eranikus lies between sleep and death, caught in a weave of nightmares. The essence you gave is badly tainted, yet there may be a way to reach him. To speak through the gem, Itharius sends you to eastern Winterspring to seek one of his mortal allies. Umbranse the Spiritspeaker is the ally Itharius has in mind. Umbranse is a human who acts as a medium for the dead. Eranikus is not truly dead, but Itharius believes Umbranse may still help.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3512-3895829124f76a3f9dd1/1-0000.mp3", duration = 53.1330612, start = 0},
  },
}
P.transport["quest:3520"] = {
  hash = "5383c4",
  fullHash = "5383c4",
  text = "Screecher Spirits. In Steamwheedle Port, Yeh'kinya asks you to gather the spirits of Feralas vale screechers. They are kin to an ancient god, and he promises to tell you more when you bring back three essences. Yeh'kinya says the vale screechers of Feralas are kin to an ancient god. Their spirits are linked to him. He gives you a bramble wand and sends you to southern and central Feralas. Wave it over a fallen vale screecher to draw out its spirit, then touch the spirit to gather its essence. He wants three essences returned with the bramble.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3520-deb9d912a03ecec93ba2/1-0000.mp3", duration = 43.1804082, start = 0},
  },
}
P.transport["quest:3566"] = {
  hash = "c46afa",
  fullHash = "c46afa",
  text = "Rise, Obsidion!. At the archaeologist’s gasp, you learn the truth: the rescue was a trap. They beg you to avenge them and Thorius by killing Lathoric the Black and Obsidion. Curator Thorius in Ironforge needs proof. The archaeologist can barely speak. They gasp that it was all a trap, ask forgiveness, then plead for you to kill the traitor for them and for Thorius. Lathoric the Black and Obsidion must both fall. Curator Thorius in Ironforge needs proof: one head and one heart.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3566-2b61585ac12ecc16c119/1-0000.mp3", duration = 39.915102, start = 0},
  },
}
P.transport["quest:3625"] = {
  hash = "c2e3a3",
  fullHash = "c2e3a3",
  text = "Enchanted Azsharite Fel Weaponry. In Stranglethorn Vale, Galvan the Ancient prepares enchanted arms against a powerful demon. Their Felcurse is meant to weaken Razelikh the Defiler and his servitors. Just south of the path into Zul'Gurub, Galvan the Ancient works with care. Forging a blade, staff, or dagger takes patience, and haste risks a flaw. Each weapon bears the Felcurse, which can be unleashed from time to time against Razelikh the Defiler and his demonic underlings. Its weakening effect lasts for different lengths of time.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3625-2334d74495bc7f14c460/1-0000.mp3", duration = 40.0195918, start = 0},
  },
}
P.transport["quest:3626"] = {
  hash = "473156",
  fullHash = "473156",
  text = "Return to the Blasted Lands. Galvan the Ancient sends you back to the Blasted Lands with your newly forged weapons. The Fallen Hero of the Horde waits there, ready to ask if you will face Razelikh. Galvan the Ancient says your hour of redemption has come. Your enchanted weapons are complete, so you carry them back to the Blasted Lands to find the Fallen Hero of the Horde. The ghostly warrior asks if you are ready to face Razelikh and his minions.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3626-c3cf60d542e8412d1375/1-0000.mp3", duration = 32.1306122, start = 0},
  },
}
P.transport["quest:3633"] = {
  hash = "fe39c1",
  fullHash = "fe39c1",
  text = "Goblin Engineering. Among master inventors, Goblin Engineering offers a path to command explosive power and volatile concussive ordnance. Its craft relies on high-yield blasting powders and relentless firepower, making it a destructive choice beside intricate tinkering. Azeroth's engineers follow two distinct philosophies. Goblin tinkerers favor violent combustion, while other inventors make delicate clockwork and subtle devices. Goblins harness blasting powder to build tools of great devastation, turning fire, shrapnel, and concussive force toward practical problems. Goblin engineers make no secret of the hazards. Recruits work with volatile compounds, heavy incendiaries, and prototypes that may singe their creator's eyebrows or level an opposing barricade. They prize maximum yield and destructive power, and welcome engineers who choose decisive firepower over fragile safety rules.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3633-25fc1b66dd68a6089067/1-0000.mp3", duration = 68.9893878, start = 0},
  },
}
P.transport["quest:379"] = {
  hash = "e5416a",
  fullHash = "e5416a",
  text = "Slake That Thirst. In Gadgetzan, Chief Engineer Bilgewhizzle needs five Wastewander Water Pouches before he can supply the 4711-FTZ power source for your kit. The Wastewander nomads east of town carry them. Chief Engineer Bilgewhizzle in Gadgetzan can help with the power source your kit needs after Into the Field. First, he asks you for five Wastewander Water Pouches. The Wastewander nomads live east of Gadgetzan, and Bilgewhizzle suggests you walk up and ask one for water. He wants to hear how it goes.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_379-95f9d19dfc32296df18c/1-0000.mp3", duration = 30.7983673, start = 0},
  },
}
P.transport["quest:3821"] = {
  hash = "29050d",
  fullHash = "29050d",
  text = "Dreadmaul Rock. In the Burning Steppes, Sha'ni's platoon has been gone for more than three weeks. Thal'trak Proudtusk cannot leave his post, and asks you to learn what became of his wife. Sha'ni went to the Burning Steppes to investigate strange rituals among the Firegut ogres. More than three weeks have passed, and Goretooth has heard nothing from her platoon. He tells Thal'trak to put the matter behind him and keep to his duty. But Sha'ni is his wife, and Thal'trak will not accept that. Bound to his post, he asks you to search for her.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3821-5b0b2d2e936ed407cefa/1-0000.mp3", duration = 37.5118367, start = 0},
  },
}
P.transport["quest:3841"] = {
  hash = "705024",
  fullHash = "705024",
  text = "An Orphan Looking For a Home. Kindal Moonweaver has news for you after Darnassus: the nest was saved, but its mother died. The eggs will soon hatch, and Kindal offers you one to care for. Quentin waits by the race tracks in the Shimmering Flats of Thousand Needles. Kindal Moonweaver greets you after your return from Darnassus. The nest was saved, but its mother died before help could reach her. The eggs are close to hatching, and they need a good keeper. Kindal offers you one as a pet. Carry the egg to Quentin at the race tracks in the Shimmering Flats if you want to care for it. Quentin can tell you more. Quentin waits in Thousand Needles, though the races are not why he is there. He studies whether new, fertile soil can restore the land. He hopes to find a water source nearby. The change from Feralas to Thousand Needles seems strange to him. Quentin says strange magic was at work when it happened.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3841-7e13f488a0b17b5bedc3/1-0000.mp3", duration = 64.3395918, start = 0},
  },
}
P.transport["quest:3842"] = {
  hash = "bd3420",
  fullHash = "bd3420",
  text = "A Short Incubation. In Thousand Needles, Quentin waits as the sprite darter egg nears hatching. The Moonweavers gave you the egg, and Quentin asks for two elixirs of fortitude so he can check its health and protect it. Quentin finds it intriguing that the Moonweavers cared for the egg, and he considers them both capable. Since they gave the egg to you, you may take responsibility for it as long as you wish. It looks almost ready to hatch, but Quentin wants to check its health and make sure it is undamaged first.\n\nA small spell will protect the egg. Quentin has every component except two elixirs of fortitude. While he waits, he admits he is growing tempted by the races. Once he knows the egg is healthy, he will return it for you to keep.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3842-4917b8adb06acae5796f/1-0000.mp3", duration = 49.684898, start = 0},
  },
}
P.transport["quest:3843"] = {
  hash = "2d4b3a",
  fullHash = "2d4b3a",
  text = "The Newest Member of the Family. Only an hour remains to bring the fragile egg to Agnar Beastamer at Aerie Peak, before the hatchling inside dies. Quentin calls the sprite darter egg a magnificent specimen. If it survives, it will make a healthy pet. He sends you to Aerie Peak in the Hinterlands, where Agnar Beastamer can guide the final steps of incubation. The dwarf is a master animal handler, and the egg cannot go long without care. Find Agnar within an hour, or the hatchling inside will die. He lives in Wildhammer Keep.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3843-b8ef7dbe3c3cc5ab1caf/1-0000.mp3", duration = 32.6791837, start = 0},
  },
}
P.transport["quest:4041"] = {
  hash = "e4808e",
  fullHash = "e4808e",
  text = "The Videre Elixir. Bring Gregan Brewspewer an Evoroot, and he can brew the Videre Elixir. He boasts of his knowledge of herbs and alchemy. Gregan Brewspewer needs an Evoroot before he can brew your Videre Elixir. He boasts that he knows a great many things about herbs and alchemy, then begins a tale about turning the cheese meant for lunch into gold. When you walk away, he asks where you are going. Ask Gregan where to find an Evoroot.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4041-7b48589ae7fa969494ef/1-0000.mp3", duration = 26.7493878, start = 0},
  },
}
P.transport["quest:4062"] = {
  hash = "4b2f30",
  fullHash = "4b2f30",
  text = "The Rise of the Machines. In the Burning Steppes, the machines bore marks that now send you to Lotwil Veriatus. The shards bear G.L.A., with a rank marking beneath. The machines you brought down in the Burning Steppes bore Rank IV, which Theodora takes to be a low rank. So Hierophant Theodora Mulvadania sends you with a sample shard to Lotwil Veriatus, renowned among scholars of elemental sciences. Lotwil is stationed at a camp to the east, where Theodora hopes he can help with the search.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4062-112b0b84c4041355629d/1-0000.mp3", duration = 33.1232653, start = 0},
  },
}
P.transport["quest:4120"] = {
  hash = "75ddef",
  fullHash = "75ddef",
  text = "The Strength of Corruption. At Camp Mojache, Talo Thornhoof sends you north to Felwood to judge the strength of its tainted beasts. Talo Thornhoof hunts by studying the strengths of his foes. He believes knowing an enemy can turn a battle in your favor. Felwood lies north of Ashenvale, where fel has tainted the creatures. Talo fears its maddened bears and wolves have grown stronger. Face twelve Angerclaw grizzlies and twelve Felpaw ravagers there. Fel-touched creatures glow a strange green. Talo senses that fel is evil, yet very powerful.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4120-2da9c1a77b2035d47617/1-0000.mp3", duration = 33.3061224, start = 0},
  },
}
P.transport["quest:4124"] = {
  hash = "11e86a",
  fullHash = "11e86a",
  text = "The Missing Courier. In Feathermoon Stronghold, Latronicus Moonspear seeks help after a courier vanishes. The courier and his parcels have been gone about a week, and the stronghold's searches found nothing. Latronicus has declared him missing in action and sends you to Ginro Hearthkindle. Latronicus Moonspear has exhausted the stronghold's search for a courier and his parcels. Both have been missing for about a week, and Latronicus has declared the courier missing in action.\n\nGinro Hearthkindle, Latronicus's associate, is looking for help in Feathermoon Stronghold, perhaps in his quarters. Latronicus asks you to speak with Ginro if you have time and means to spare.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4124-70bcc7fae08928868329/1-0000.mp3", duration = 48.9273469, start = 0},
  },
}
P.transport["quest:4125"] = {
  hash = "909372",
  fullHash = "909372",
  text = "The Missing Courier. Ginro Hearthkindle searches Feralas's coast for Raschal, missing for about a week. Raschal set out for Thalanaar, planning to row down the coast. Ginro could not find the boat and asks you to search the shore for a clue. Ginro Hearthkindle believes Raschal planned to row down the coast toward Thalanaar. Raschal set out about a week ago and knows Feralas well. Raschal has served with the expeditionary forces since General Feathermoon led them here.\n\nThe route crosses southern Feralas, away from the Horde camp. Ginro could not find the boat, so it may be hidden or sunk. It could hold a clue to Raschal's whereabouts. On the mainland, the Forgotten Coast runs south from the jetty.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4125-aacc707e0e79fd926d74/1-0000.mp3", duration = 43.8595918, start = 0},
  },
}
P.transport["quest:4127"] = {
  hash = "74576a",
  fullHash = "74576a",
  text = "Boat Wreckage. Off the coast, Boat Wreckage holds a clue for Ginro Hearthkindle in Feathermoon Stronghold. A well-cared-for knife lies in the mud, and you sense something else in the water. Near the wrecked boat, you feel through the mud and find a well-cared-for knife. Whoever was aboard may have lost it when the large chunk went missing from the boat. You take the knife to Ginro Hearthkindle in Feathermoon Stronghold. Ginro asked you to bring back any clue you found, yet something else still shares the water.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4127-55df0cd75e0e09086c54/1-0000.mp3", duration = 29.5967347, start = 0},
  },
}
P.transport["quest:4129"] = {
  hash = "f4a3f9",
  fullHash = "f4a3f9",
  text = "The Knife Revealed. Ginro Hearthkindle sends you to Quintis Jonespyre with the knife, seeking a reading of its past. Ginro says the reading will settle Quintis's Kalimdor Hold 'Em debt. After Boat Wreckage, Ginro Hearthkindle sends you to Quintis Jonespyre with the knife. Quintis is Feathermoon Stronghold's resident druid, and he lives in a little tree-house there.\n\nBy touching an object, Quintis can learn its past. Ginro calls this psychometry magic he does not understand and chooses not to understand, though he has seen it work. Quintis owes Ginro a Kalimdor Hold 'Em debt, and Ginro says the knife's reading will clear it. Quintis says psychometric readings drain the psyche, much like losses at Kalimdor Hold 'Em. The Stronghold calls him the King of the Bad Beats. He is unlucky at cards, yet lucky with nature's secrets.\n\nQuintis agrees to read the knife. He hopes it will bring the breakthrough needed to uncover Raschal's fate.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4129-7bb4d244aed3c3b302c9/1-0000.mp3", duration = 66.1420408, start = 0},
  },
}
P.transport["quest:4130"] = {
  hash = "a4341f",
  fullHash = "a4341f",
  text = "Psychometric Reading. After Psychometric Reading, Quintis Jonespyre is still unsteady. His vision shows Raschal and the Woodpaw gnolls, and Quintis asks you to carry word to Ginro Hearthkindle in Feathermoon Stronghold. Quintis Jonespyre is unsteady, but his vision may help. Raschal pulls two large leather backpacks from the boat, heads inland, then returns to the boat. Gnoll scalps appear, and Quintis believes Raschal met Woodpaw gnolls. Raschal is very worried, almost terrified, and does not notice water elementals forming behind him. Then the images end. Quintis needs rest, so he asks you to tell Ginro, who needs to know.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4130-4392a47b798454fa8f87/1-0000.mp3", duration = 43.7812245, start = 0},
  },
}
P.transport["quest:4131"] = {
  hash = "4205c4",
  fullHash = "4205c4",
  text = "The Woodpaw Gnolls. In southern Feralas, you search Woodpaw camps for Raschal, the courier. After Quintis's vision, Ginro Hearthkindle sends you to find him or his belongings, though Ginro doubts the gnolls were his undoing. Ginro Hearthkindle admits the Woodpaw, whom Ginro calls “friends,” may have done for Raschal after all. Still, Ginro feels the gnolls were not responsible, and their camps are the best place to start. Ginro has no clearer plan than to search them.\n\nGnolls keep what they scavenge and fight over it, so they may have found the backpacks Quintis mentioned. Ginro once avoided open fighting during earlier searches. Now the vision guides you, and Ginro says to rip into them. The camps lie in southern Feralas.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4131-6a4c2e89c60f063324e9/1-0000.mp3", duration = 45.2179592, start = 0},
  },
}
P.transport["quest:4135"] = {
  hash = "b5e3d8",
  fullHash = "b5e3d8",
  text = "The Writhing Deep. In the Writhing Deep, Raschal has gone to investigate a grave danger to Feralas. Your search for him leads there. The backpacks hold a parcel for Thalanaar and a hurried note with no recipient named. Raschal of Feathermoon wrote it after finding bug-like creatures in the Writhing Deep, south of the gnoll camps. He feared they threatened all of Feralas, so he went to investigate them himself. His note shows where he went.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4135-8bd63057d39c956fbf3e/1-0000.mp3", duration = 31.764898, start = 0},
  },
}
P.transport["quest:4265"] = {
  hash = "f97f1f",
  fullHash = "f97f1f",
  text = "Freed from the Hive. At the Writhing Deep, Raschal lives, but the Zukk'ash hive has left him deeply stunned. He needs word sent to Ginro Hearthkindle in Feathermoon Stronghold. You help a night elf down from the pod, and he begins to stir. He names himself Raschal and says the bugs overwhelmed him, leaving him paralyzed inside. Though he looks healthy, he remains deeply stunned. He asks if the Stronghold sent you. Ginro Hearthkindle waits in Feathermoon Stronghold. Tell him Raschal lives and is well.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4265-a1e55a258fc4f4356fa0/1-0000.mp3", duration = 32.6791837, start = 0},
  },
}
P.transport["quest:4266"] = {
  hash = "3e5bb8",
  fullHash = "3e5bb8",
  text = "A Hero's Welcome. General Shandris Feathermoon has asked to see you in person. Ginro Hearthkindle thinks she may thank you for aiding Feathermoon Stronghold and speak about the Zukk'ash insects you and Raschal met in southern Feralas. Ginro Hearthkindle says General Shandris Feathermoon is waiting in Feathermoon Stronghold's main compound. The reports about the Zukk'ash insects frighten him.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4266-fc9449dbcf1703644681/1-0000.mp3", duration = 24.7640816, start = 0},
  },
}
P.transport["quest:4267"] = {
  hash = "d0b199",
  fullHash = "d0b199",
  text = "Rise of the Silithid. In Darnassus, a copy of Raschal's account is bound for Gracina Spiritmight. General Shandris Feathermoon gives it to you, trusting the priestess's knowledge of such creatures. General Shandris Feathermoon entrusts you with a copy of Raschal's account for Gracina Spiritmight, an associate of the Protectorate. The main report has been filed in Darnassus, where Gracina lives as a priestess in the Temple of the Moon. Shandris believes her broad knowledge of such creatures will benefit everyone who receives the account. She sends you on with good wishes and a prayer that Elune watch over all.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4267-9e9716883270601a7090/1-0000.mp3", duration = 42.2138776, start = 0},
  },
}
P.transport["quest:4281"] = {
  hash = "16c0d8",
  fullHash = "16c0d8",
  text = "Thalanaar Delivery. At the Woodpaw camps, a parcel for Thalanaar still waits for its recipient. The hand-written name may guide you there. You find goods for Thalanaar in the Woodpaw gnoll camps. The small way-station lies in southeastern Feralas. A hand-written name on the parcel points you toward the person expecting the goods: Falfindel Waywarder.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4281-d66c29c1806ab259284b/1-0000.mp3", duration = 22.4130612, start = 0},
  },
}
P.transport["quest:4297"] = {
  hash = "29b9de",
  fullHash = "29b9de",
  text = "Food for Baby. Agnar Beastamer will care for your egg until it hatches. Sprite darters eat meat and vegetation, and their young favor raw, juicy flanks. Agnar wants Silvermane stalker flanks for the hatchling. Agnar Beastamer says sprite darters eat meat and vegetation. Their young favor raw, juicy flanks. Agnar will care for the egg until it hatches and wants Silvermane stalker flanks for the hatchling. Without a good first meal, the newborn might not live through its first week. Agnar never learned why sprite darters eat meat. Agnar knows only that it is tied to Elune’s plan for the elves. Perhaps they were meant to be protectors, Agnar wonders, but cannot say for sure. Agnar also admits to being jealous that you got the egg.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4297-5a286490ab1dfeb891c5/1-0000.mp3", duration = 46.5502041, start = 0},
  },
}
P.transport["quest:4298"] = {
  hash = "6747ee",
  fullHash = "6747ee",
  text = "Becoming a Parent. In the Hinterlands, Agnar Beastamer has news: the egg is further along than he expected. He wants to speak with you. The egg has advanced further than Agnar Beastamer expected. You have brought food for the hatchling. Now speak with Agnar in the Hinterlands.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4298-d7422febb561819ce451/1-0000.mp3", duration = 19.1216327, start = 0},
  },
}
P.transport["quest:4449"] = {
  hash = "898f08",
  fullHash = "898f08",
  text = "Caught!. In Searing Gorge, someone is calling for help from a locked outhouse. The voice inside asks you to teach eight Dark Iron geologists a lesson and bring fifteen pieces of silk cloth, though they offer no reason. The occupant fled the Dark Iron dwarves and hid in the outhouse. They believe the geologists saw them slip inside and used their magic to lock the door before they could get away. The trapped person asks you to teach eight Dark Iron geologists a lesson and bring fifteen pieces of silk cloth. When you ask why, they stumble over their words, then say it is for nothing in particular.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4449-8d0383ce4e2011b3e815/1-0000.mp3", duration = 38.3477551, start = 0},
  },
}
P.transport["quest:4450"] = {
  hash = "8128b8",
  fullHash = "8128b8",
  text = "Ledger from Tanaris. In Searing Gorge, a small job from Tanaris now waits for you. Krinkle Goodsteel of Gadgetzan wants several things gathered here and elsewhere, then brought to him. The person inside the wooden outhouse has been helped and remembers a small job from Tanaris. Krinkle Goodsteel of Gadgetzan wants several things gathered, some in Searing Gorge and others farther away. The ledger will be slid beneath the door. Carry it and everything listed to Goodsteel in Tanaris. Goodsteel's ledger calls for twenty solid crystal leg shafts from the glassweb spiders of Searing Gorge. It also lists an overdue package at the crashed zeppelin in Beezil's Wreck, in Dustwallow Marsh. The third item is Goodsteel's balanced flameberge. Jarquia, a murloc along the eastern shore of the Swamp of Sorrows, has it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4450-869c1b60ab4b30387026/1-0000.mp3", duration = 51.8008163, start = 0},
  },
}
P.transport["quest:4451"] = {
  hash = "6a94ea",
  fullHash = "6a94ea",
  text = "The Key to Freedom. In Searing Gorge, you have a small brass key with no known destination. Its head reads Dark Iron Outhouse and warns against copying it. The small brass key is marked Dark Iron Outhouse, with a warning not to duplicate it. Where it leads remains unknown. Search Searing Gorge for a place that accepts it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4451-9f01ad39d55f87dfe8b9/1-0000.mp3", duration = 19.722449, start = 0},
  },
}
P.transport["quest:4496"] = {
  hash = "5b4239",
  fullHash = "5b4239",
  text = "Bungle in the Jungle. In Gadgetzan, Alchemist Pestlezugg studies the silithid and likens them to bees. He believes their queen is the weak point, and needs scent and soil from Un'Goro Crater to the west. Alchemist Pestlezugg likens the silithid to bees. He believes that if their queen is destroyed, the rest will fall into disarray. A lure can draw her out. You are to bring her down when she appears. To make the lure, Pestlezugg needs reagents from Un'Goro Crater. The silithid hive lies west of Gadgetzan. He asks you to bring an undamaged scent gland from one of the bugs and five samples of the native soil.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4496-1fd72c36209447545c28/1-0000.mp3", duration = 39.5755102, start = 0},
  },
}
P.transport["quest:4504"] = {
  hash = "9730aa",
  fullHash = "9730aa",
  text = "Super Sticky. In Gadgetzan, Tran'rek sees quick gold in super sticky glue. He needs tar from beasts near the pits in northern Un'Goro Crater and offers a little of the profit. Tran'rek hopes his newest idea will bring quick gold, and offers you a little of the profit. Ordinary tar is not sticky enough. He wants twelve samples from creatures near the tar pits in northern Un'Goro Crater. The plant-like creatures around the pits have chlorophyll in their skin. Mixed with tar, it makes a super sticky glue.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4504-adbd0c537940ac49454d/1-0000.mp3", duration = 32, start = 0},
  },
}
P.transport["quest:4507"] = {
  hash = "2356b2",
  fullHash = "2356b2",
  text = "Pawn Captures Queen. Alchemist Pestlezugg sends you into Un'Goro Crater with a lure for the Gorishi Hive Queen. After Bungle in the Jungle, he wants her brain brought to Gadgetzan for study. Pestlezugg gives you a lure for the silithid hive. He believes a crystal in the hive network attunes the whole swarm, and the hatcheries are the best place to search. Apply the lure to the crystal, and the queen should emerge with several guards beside her. Pestlezugg wants you to carry the queen's brain to Gadgetzan. He knows it sounds icky, but says the brain is badly needed for study.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4507-4dd5f8cfa4ed5b40d9d8/1-0000.mp3", duration = 38.1387755, start = 0},
  },
}
P.transport["quest:4508"] = {
  hash = "c1f973",
  fullHash = "c1f973",
  text = "Calm Before the Storm. After the queen falls, you carry the latest findings from Un'Goro beyond Gadgetzan. Alchemist Pestlezugg sends the report to Gracina Spiritmight at the Temple of the Moon in Darnassus. Alchemist Pestlezugg says Gadgetzan cannot face the silithid alone. The latest findings from Un'Goro must reach someone who can act on them, so you carry the report to Gracina Spiritmight in Darnassus. Pestlezugg hopes she is at the Temple of the Moon. She has friends among the Alliance's leading figures, and drawing them in may offer a way through this alive.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4508-0d12e492a62a9cba94e7/1-0000.mp3", duration = 40.8032653, start = 0},
  },
}
P.transport["quest:4509"] = {
  hash = "64eb39",
  fullHash = "64eb39",
  text = "Calm Before the Storm. After the queen's fall, Alchemist Pestlezugg sends his latest findings to those who may act. You carry his report on Un'Goro to Zilzibin Drumlore in Orgrimmar. Gadgetzan cannot manage alone, so Alchemist Pestlezugg sends you with his latest findings on Un'Goro. He wants them in the hands of those who can act. Pestlezugg expects Zilzibin Drumlore to be in the upper part of the Drag in Orgrimmar. Zilzibin has friends high in the Horde, and drawing them in may offer a way through this alive.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4509-8ae57a2fdf278d032fe4/1-0000.mp3", duration = 34.3510204, start = 0},
  },
}
P.transport["quest:4787"] = {
  hash = "684a00",
  fullHash = "684a00",
  text = "The Ancient Egg. In Tanaris, Yeh'kinya seeks the ancient egg named in the Prophecy of Mosh'aru. It comes from the age of troll empires, and he wants you to bring it from Jintha'Alor in the Hinterlands. The Prophecy of Mosh'aru tells of an ancient egg from the age when trolls ruled vast empires. Its power can contain Hakkar's essence. Yeh'kinya believes it may be the only way to guard the world from his evil. Yeh'kinya asks you to bring the egg to Tanaris. Tales place it deep inside Jintha'Alor in the Hinterlands, in a cave behind the amphitheater atop the city. Great forces stir, and Yeh'kinya fears time is running short.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4787-5104b4945a3505b5acba/1-0000.mp3", duration = 49.5804082, start = 0},
  },
}
P.transport["quest:485"] = {
  hash = "e04627",
  fullHash = "e04627",
  text = "Find OOX-09/HL!. Near Skulk Rock, a homing robot lies crashed in the Hinterlands. Its gnomish maker, Oglethorpe Obnoticus, calls through a metal egg and asks you to carry a beacon to the wreck. Turn the knob on the strange metal egg, and a gnomish device opens. A crackling voice gives the name Oglethorpe Obnoticus. His homing robot has crashed, and he has worked out where it came down: where the river begins, near Skulk Rock. Carry the beacon there. At the river's head, you find wreckage shaped like a robotic chicken. Oglethorpe Obnoticus confirms that it is his homing robot. It needs a jump start before it can return to Booty Bay for repairs. Place the beacon inside.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_485-d26c19b12581c6ee659b/1-0000.mp3", duration = 44.564898, start = 0},
  },
}
P.transport["quest:500"] = {
  hash = "08476b",
  fullHash = "08476b",
  text = "Crushridge Bounty. From Southshore, Marshal Redpath warns that Crushridge ogres have settled near Alterac's ruins. He offers a bounty to anyone who hunts them in the Alterac Mountains. Marshal Redpath sends you north after reports that Crushridge ogres have dug a mound in the Alterac Mountains near Alterac's ruined city. They have taken the ruins too. Redpath fears they may grow comfortable there, then move down into the foothills and reach Southshore's door. He offers a bounty for hunting them and bringing back the Dirty Knucklebones they carry.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_500-b9bffe047e8f888a5971/1-0000.mp3", duration = 35.0302041, start = 0},
  },
}
P.transport["quest:503"] = {
  hash = "20b1dd",
  fullHash = "20b1dd",
  text = "Gol'dir. In Tarren Mill, Krusk has found where Gol'dir is held. The documents point north to a large Syndicate base, perhaps in the Alterac Mountains, and Gol'dir has been captive too long. In Tarren Mill, Krusk studies the documents you brought back after Infiltration. They point to a large Syndicate base up north, perhaps in the Alterac Mountains. Gol'dir has been held too long, and Krusk wants him freed. Syndicate fill the inn at Strahnbrad, where Gol'dir is held in the top room. A Rusted Iron Key opens the lock. Jailor Borhuin carries it and may be in any building in town.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_503-e83a9347a34459c44604/1-0000.mp3", duration = 41.3779592, start = 0},
  },
}
P.transport["quest:504"] = {
  hash = "783364",
  fullHash = "783364",
  text = "Crushridge Warmongers. In the Ruins of Alterac, Crushridge Warmongers face a fiercer hunt. Marshal Redpath of Southshore sends you after them to keep the ogres from Alliance lands. Marshal Redpath sends you into the Ruins of Alterac after Crushridge Bounty. He wants you to hunt down many Crushridge Warmongers and strike the Crushridge ogres hard. Redpath believes nothing else will teach the brutes to keep clear of Alliance territory.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_504-9f2000b7ea546f15ecd0/1-0000.mp3", duration = 28.1077551, start = 0},
  },
}
P.transport["quest:505"] = {
  hash = "e53a38",
  fullHash = "e53a38",
  text = "Syndicate Assassins. Southshore’s new magistrate suspects the Syndicate Assassins killed his predecessor. His clues point north of Tarren Mill, where he wants the gang slain. Magistrate Henry Maleb now holds office in Southshore. The previous magistrate was assassinated, and the killers were never found. Maleb is almost certain the Syndicate hired them.\n\nThieves make up the gang, led by villainous nobles from the fallen kingdom of Alterac. Maleb’s last clues point north of Tarren Mill, which the Horde occupies. He asks you to slay the Syndicate members at the camp there.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_505-71593d1767092fbd9b1b/1-0000.mp3", duration = 42.3706122, start = 0},
  },
}
P.transport["quest:506"] = {
  hash = "8902a3",
  fullHash = "8902a3",
  text = "Blackmoore's Legacy. Gol'dir is already free and carries word to Krusk in Tarren Mill. Aliden Perenolde, leader of the Syndicate, visited him and spoke of enslaving orcs who resist. Perenolde brought Elysa, who wears the pendant the Warchief desires. Gol'dir has word for Krusk after a visit from Aliden Perenolde, leader of the Syndicate. Perenolde called himself lord of the land and spoke of enslaving orcs who resist him. His father and mentor, the despised Blackmoore, had planned the same.\n\nGol'dir sends you to carry this news to Krusk in Tarren Mill. He will follow once he has settled his own business where he is. Perenolde also brought his mistress, a slight girl named Elysa. Around her neck hung the pendant the Warchief desires.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_506-f549f936e61f315899ad/1-0000.mp3", duration = 57.364898, start = 0},
  },
}
P.transport["quest:507"] = {
  hash = "2309d2",
  fullHash = "2309d2",
  text = "Lord Aliden Perenolde. Krusk sends you north to Lord Aliden Perenolde's manor by Lordamere Lake. Once Perenolde is dead, his mistress Elysa can tell you about the Warchief's pendant. After Blackmoore's Legacy, Krusk sends you to end Perenolde's foulness. His manor stands at Dandred's Fold, on the shores of Lordamere Lake to the north. Once Perenolde is dead, ask his mistress Elysa about Taretha's pendant. The Warchief desires it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_507-96771f69fffb1c64aa6d/1-0000.mp3", duration = 30.9028571, start = 0},
  },
}
P.transport["quest:508"] = {
  hash = "cd2e25",
  fullHash = "cd2e25",
  text = "Taretha's Gift. Elysa gives up Taretha's Gift and asks for peace. After the step with Lord Aliden Perenolde, you carry the pendant to Krusk in Tarren Mill. Elysa wants no memory of Lord Aliden Perenolde. She gives you the pendant and asks only to be left in peace. It once belonged to Taretha Foxton, Thrall's childhood friend. You carry it to Krusk in Tarren Mill, returning it to the orcs.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_508-64bb8a5497d0bdc01b73/1-0000.mp3", duration = 34.5861224, start = 0},
  },
}
P.transport["quest:510"] = {
  hash = "8b2c2e",
  fullHash = "8b2c2e",
  text = "Foreboding Plans. The Syndicate's papers call for supplies to reach Southshore soon, where Magistrate Henry Maleb awaits them. The Syndicate papers list food, weapons and clothing. They also call for masks, oil and poison. The supplies are needed soon for an important undertaking against Southshore. Magistrate Henry Maleb is to receive them there.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_510-33e8a45f11b960a8729a/1-0000.mp3", duration = 22.8310204, start = 0},
  },
}
P.transport["quest:511"] = {
  hash = "acf00e",
  fullHash = "acf00e",
  text = "Encrypted Letter. Among the Syndicate papers, one letter cannot be read. You take it to Loremaster Dibbs in Southshore. Among the Syndicate documents, one letter is written in a cipher no one can read. You bring it to Loremaster Dibbs in Southshore.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_511-df5ef1fcbf3f4f11a526/1-0000.mp3", duration = 17.397551, start = 0},
  },
}
P.transport["quest:512"] = {
  hash = "074abc",
  fullHash = "074abc",
  text = "Noble Deaths. In Southshore, Magistrate Henry Maleb fears the Syndicate means ruin for the town. He sends you north to Strahnbrad's ruins in the Alterac Mountains, where he believes its leaders have their headquarters. After Foreboding Plans, Magistrate Henry Maleb wants the Syndicate's leaders struck down before their plans come to pass. Its cutthroats answer to former Alterac nobles, who may hide among ordinary agents. Their signet rings mark them out. Maleb asks you to bring him seven Alterac signet rings in Southshore.\n\nHe believes the Syndicate has made its headquarters among Strahnbrad's ruins, north in the Alterac Mountains.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_512-0590612c1f99775b6cb4/1-0000.mp3", duration = 42.4228571, start = 0},
  },
}
P.transport["quest:514"] = {
  hash = "dc46cf",
  fullHash = "dc46cf",
  text = "Letter to Stormpike. In Southshore, Loremaster Dibbs entrusts you with an encrypted letter for Ironforge. He hopes Prospector Stormpike can read it. Dibbs sends you to Ironforge to find Prospector Stormpike. He is in the Library, inside the Hall of Explorers. Tell him Dibbs sent you and show him the letter. Dibbs believes no one north of Blackrock Spire can read it better than Stormpike.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_514-20257f854c0f94514173/1-0000.mp3", duration = 25.9134694, start = 0},
  },
}
P.transport["quest:518"] = {
  hash = "1ea23e",
  fullHash = "1ea23e",
  text = "The Crown of Will. In Tarren Mill, Melisara seeks to weaken Mug'Thol's ogres before striking their hold in the Ruins of Alterac. She sends you to hunt the Crushridge maulers. Mug'Thol and the Crushridge ogres hold the Ruins of Alterac. Melisara sees little chance of punishing Mug'Thol while so many ogres remain around him. Their numbers must fall before she can make her next move. You are sent after the Crushridge maulers.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_518-8c630776e5217e45b1c4/1-0000.mp3", duration = 29.7273469, start = 0},
  },
}
P.transport["quest:519"] = {
  hash = "deed99",
  fullHash = "deed99",
  text = "The Crown of Will. In Tarren Mill, Melisara seeks three ogre heads before Mug'Thol's. Melisara names Targ, Muckrake and Glommus as Mug'Thol's loyal lieutenants. She wonders what could make an ogre loyal. Kill all three and bring their heads to Tarren Mill. Then Mug'Thol's head, crown and all, is the only one left to take.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_519-c0e622904a4f607a54d0/1-0000.mp3", duration = 21.002449, start = 0},
  },
}
P.transport["quest:520"] = {
  hash = "848dc5",
  fullHash = "848dc5",
  text = "The Crown of Will. Melisara in Tarren Mill sends you after Mug'Thol, whose lieutenants are dead. Bring back his head and the Crown of Will, and the Crushridge resistance will be over. Only Mug'Thol remains. Melisara expects him to resist giving up the Crown of Will. With his lieutenants fallen, he likely expects you. Find him, kill him, and bring his head and the Crown back to Tarren Mill.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_520-a7ee09ea73b032167ed8/1-0000.mp3", duration = 27.4808163, start = 0},
  },
}
P.transport["quest:521"] = {
  hash = "c7dd46",
  fullHash = "c7dd46",
  text = "The Crown of Will. Melisara sends the Crown of Will to the Undercity, where Sharlindra will see it reaches Lady Sylvanas. Melisara sends you with the Crown to Sharlindra in the Undercity. Sharlindra will pass it on to Lady Sylvanas. Melisara warns you not to use the Crown for your own ends. Mug'Thol's fate is warning enough.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_521-c7c3d34b927032649abc/1-0000.mp3", duration = 24.7640816, start = 0},
  },
}
P.transport["quest:522"] = {
  hash = "ff1349",
  fullHash = "ff1349",
  text = "Assassin's Contract. In Hillsbrad Foothills, a Shadowy Assassin bears a contract naming Magistrate Henry Maleb for death. You are to carry it to Maleb in Southshore, where red wax bears a distinctive signet ring's mark. A Shadowy Assassin carries a contract in Hillsbrad Foothills. It names Magistrate Henry Maleb for death, and a distinctive signet ring has marked the red wax. Bring the paper to Maleb in Southshore.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_522-f9b13b84564c5ac6d64b/1-0000.mp3", duration = 30.0146939, start = 0},
  },
}
P.transport["quest:523"] = {
  hash = "863398",
  fullHash = "863398",
  text = "Baron's Demise. In Southshore, Magistrate Henry Maleb seeks justice for the contract you recovered. Baron Vardus, a cold-hearted nobleman of old Alterac, signed it, and Maleb asks you to bring him his head. After Assassin's Contract, Magistrate Henry Maleb tells you Baron Vardus signed the contract. Vardus is a nobleman of old Alterac, known for his cold heart and brutal ways. Maleb is not surprised to find him behind it. Southshore will not let the baron send thugs against the town without answering for it.\n\nMaleb thinks Vardus may be among the Syndicate's haunts, in Strahnbrad's ruins or the valley north of them. He asks you to bring him the baron's head.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_523-bcea6cfb1673d8c68ccd/1-0000.mp3", duration = 46.3412245, start = 0},
  },
}
P.transport["quest:525"] = {
  hash = "3567b9",
  fullHash = "3567b9",
  text = "Further Mysteries. In the Alterac foothills, a decrypted letter leaves Prospector Stormpike searching for meaning. He sends you to Southshore's magistrate with the message. Prospector Stormpike has decrypted the letter you found among thieves in the Alterac foothills. Yet its meaning escapes him, and he wonders why thieves had it at all. Southshore lies nearest to Alterac. If a threat is brewing, its magistrate should hear of it, so you carry the message to Magistrate Henry Maleb.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_525-52e03b9a4c141ea037e9/1-0000.mp3", duration = 34.037551, start = 0},
  },
}
P.transport["quest:533"] = {
  hash = "64999a",
  fullHash = "64999a",
  text = "Infiltration. In Tarren Mill, Krusk seeks word of Gol'dir, the orc prisoner the Syndicate keeps moving. He sends you to its large camp just north of town for any information you can bring back. Krusk has heard word and rumor of Gol'dir, an orc prisoner held by the Syndicate. Its human captors keep moving him, but the search has narrowed to their large camp just north of Tarren Mill. Krusk sends you there to find what you can and carry it back. Each day, he fears Gol'dir's prospects grow darker.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_533-4409faf831c9f569a482/1-0000.mp3", duration = 32.9404082, start = 0},
  },
}
P.transport["quest:535"] = {
  hash = "6cd111",
  fullHash = "6cd111",
  text = "Valik. In a Syndicate camp, Valik lies dying with an enemy before them. Valik expects you to kill them, but offers answers for a mug of Southshore Stout. Henchman Valik lies wounded in the Syndicate camp, with you standing before them as an enemy. They expect you to kill them all the same. Yet Valik offers answers to your questions if you bring a mug of Southshore Stout to the camp. They even wonder aloud whether your kind drinks at all.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_535-6d1bea330c57039fb296/1-0000.mp3", duration = 31.9477551, start = 0},
  },
}
P.transport["quest:5361"] = {
  hash = "80823d",
  fullHash = "80823d",
  text = "Family Tree. Cliffwatcher Longhorn sends you to Ghost Walker Post with news of unusual centaur activity. His brother is there in Desolace. A year has passed since Cliffwatcher Longhorn last wrote to his brother. Now the centaurs are acting strangely, and that is news Nataka should not go without. So Cliffwatcher sets it all down in a report and trusts you to carry it to Ghost Walker Post in Desolace. The road is long. It climbs north past the Crossroads into the Stonetalon Mountains, turns west through the Charred Vale, and drops south into the grey wastes of Desolace. At its end, at Ghost Walker Post, Nataka waits, and he does not know what his brother has seen.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5361-a5d33f932c560b76abfe/1-0000.mp3", duration = 43.3371429, start = 0},
  },
}
P.transport["quest:537"] = {
  hash = "8c2b83",
  fullHash = "8c2b83",
  text = "Dark Council. In Southshore, Magistrate Henry Maleb weighs a letter naming Nagaz and the Argus Wake. He fears they may threaten the land if allied with the Syndicate, and sends you to hunt Nagaz and the Argus Shadow Mages in the Uplands. After Further Mysteries, Maleb tells you the letter came from Nagaz, who belongs to the Argus Wake. He does not know what the Argus Wake is, but fears an alliance with the Syndicate would make them a threat. So he wants Nagaz and the Argus Shadow Mages named in the letter found and killed. Bring him Nagaz’s head.\n\nSearch the Uplands, north of Strahnbrad, where the Syndicate is strongest. Maleb hopes the Argus Wake’s envoys are there.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_537-55b8bcb033ae6ba89aa9/1-0000.mp3", duration = 52.1404082, start = 0},
  },
}
P.transport["quest:5381"] = {
  hash = "13fc9d",
  fullHash = "13fc9d",
  text = "Hand of Iruxos. At Shadowprey Village, Taiga Wisemane sends you to Thunder Axe Fortress for a Demon Box. The Burning Blade uses the Hand of Iruxos inside it to open portals for demons at Mannoroc Coven. Taiga Wisemane wants the demons' passage into our world stopped. She gives you a demon pick for the red crystal inside Thunder Axe Fortress. Use it to reach the Demon Box, then bring the box and pick back to Taiga in Shadowprey Village.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5381-934de630c41968f890b5/1-0000.mp3", duration = 33.5673469, start = 0},
  },
}
P.transport["quest:5386"] = {
  hash = "767746",
  fullHash = "767746",
  text = "Catch of the Day. At Ghost Walker Post, Nataka Longhorn is longing for cooked fish. She praises the trolls of Shadowprey Village as the finest fish-catchers, but centaur activity keeps her from making the journey. She asks you to bring her two Bloodbelly fish. At Ghost Walker Post, Nataka Longhorn has gone a long while without cooked fish. She trusts the trolls of Shadowprey Village to catch the finest fish, but centaur activity leaves her little time to travel. So she asks you to speak with Jinar'Zillen, the village's local fisherman, and bring back two Bloodbelly fish. They are Nataka's favorite. The road south of the post bends west toward the troll village.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5386-ffcc5568431dd5520639/1-0000.mp3", duration = 41.4302041, start = 0},
  },
}
P.transport["quest:544"] = {
  hash = "9b41a8",
  fullHash = "9b41a8",
  text = "Prison Break In. Magus Wordeen Voidglare faces a crisis in Tarren Mill while pursuing his research. Four Forsaken fled the Undercity months ago with artifacts stolen from a secure vault, and Sylvanas wants them returned. Magus Wordeen Voidglare came to Tarren Mill to research. Now a crisis calls for his attention. Four Forsaken turned from their brethren and stole from the Dark Lady. They broke into a secure vault and took four artifacts the apothecaries need for certain studies. Sylvanas wants them returned. The thieves fled the Undercity for Dalaran. Its wizards placed them in quarantine at the Lordamere Internment Camp. You are sent to find the traitors, recover the artifacts and report to Voidglare in Tarren Mill. There are four: a Bloodstone Wedge, Marble, Shard and Oval. Dermot holds the wedge, Ricter the marble, Alina the shard and Kegan Darkmar the oval.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_544-cbeee86a606cf9dae390/1-0000.mp3", duration = 67.6832653, start = 0},
  },
}
P.transport["quest:545"] = {
  hash = "3b6cf3",
  fullHash = "3b6cf3",
  text = "Dalaran Patrols. In Tarren Mill, Magus Wordeen Voidglare turns his gaze toward Dalaran’s outskirts. Beyond the great dome, ruined streets may hold treasures of magical worth, but wizards and their elemental slaves patrol them. Voidglare wants those patrols thinned. After Prison Break In, Voidglare turns his attention to Dalaran’s wizards. They raised a great dome of magic over the heart of their city. Some say it shields them from the violence of the age. Others say they sought solitude to study and plot. Voidglare cares nothing for their reason.\n\nBeyond the dome, the ruined outskirts may hold treasures of real magical worth. Yet wizards and their elemental slaves patrol those streets. You are sent to hunt six Dalaran Summoners and twelve Elemental Slaves, then return to Voidglare in Tarren Mill.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_545-ad998bf6df51df74a539/1-0000.mp3", duration = 55.7453061, start = 0},
  },
}
P.transport["quest:55"] = {
  hash = "203fa6",
  fullHash = "203fa6",
  text = "Morbent Fel. Above Raven Hill Cemetery, Morbent Fel's wards keep ordinary steel from reaching him. Sven Yorgen sends you with Morbent's Bane to break them and end the necromancer's terror in western Duskwood. Morbent Fel haunts an abandoned house atop a rocky ridge just east of Sven's camp. The house looks over the sprawl of Raven Hill Cemetery. From there, the necromancer sends undead through the surrounding forest and defiles Duskwood's graves. Dark magic and loyal undead thralls keep ordinary steel from reaching him. Morbent Fel's wards turn a direct assault into suicide and deflect conventional attacks. Sven entrusts you with Morbent's Bane, an enchanted artifact made to unravel that magical shielding. Invoke the relic and the barrier collapses. Then Fel is open to a mortal strike.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_55-fef78e296fe871d0d2ac/1-0000.mp3", duration = 55.5885714, start = 0},
  },
}
P.transport["quest:550"] = {
  hash = "54034b",
  fullHash = "54034b",
  text = "Battle of Hillsbrad. At Hillsbrad, the Forsaken have broken the township's defenses. High Executor Darthalia sends you to carry her commendation to Varimathras in the Undercity. Fierce fighting in Hillsbrad Foothills has decided the struggle for southern Lordaeron. From Tarren Mill, Horde champions struck the township's farmers, militia, blacksmiths, and civic leaders. Alliance forces are crippled, and the territory is secured for the Forsaken. Now High Executor Darthalia prepares an official commendation so the champion's deeds reach the highest ranks of command. Darthalia's sealed commendation takes you to Varimathras in the Undercity's Royal Quarter. The dreadlord oversees military operations across Lordaeron beside Lady Sylvanas Windrunner. The Scourge from the northern Plaguelands remains the Dark Lady's greatest threat. Yet surviving human enclaves still endanger the Forsaken's southern borders.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_550-19a8cc8a20e5d9e0b364/1-0000.mp3", duration = 61.962449, start = 0},
  },
}
P.transport["quest:5501"] = {
  hash = "623683",
  fullHash = "623683",
  text = "Bone Collector. At Kormek's Hut in Desolace, Bibbly F'utzbuckle is waiting on ten more kodo bones. A caravan is due any moment, and the goblin expects the bones to change the world. Bibbly F'utzbuckle sees a fortune in the kodo bones around the hut. Customers turn them into furniture, musical instruments, and even blasting powder. So Bibbly sends you south to the Kodo Graveyard for ten bones, promising something in return. A caravan comes by Kormek's Hut to collect Bibbly's kodo bones. It sells them at Shadowprey Village, and it is due any moment. Bibbly is ten bones short of a career high.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5501-0e6e0c03aa842ef7fa15/1-0000.mp3", duration = 39.6016327, start = 0},
  },
}
P.transport["quest:551"] = {
  hash = "14e8cf",
  fullHash = "14e8cf",
  text = "The Ensorcelled Parchment. At the top of The Ensorcelled Parchment, Nagaz is the only name clear. A spell hides the rest, so you take it to Loremaster Dibbs in Southshore. A spell keeps the parchment's writing from being read. Only Nagaz can be made out at the top. You take it to Loremaster Dibbs in Southshore.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_551-0fdd7b2c50fbcb737434/1-0000.mp3", duration = 21.0285714, start = 0},
  },
}
P.transport["quest:552"] = {
  hash = "c92de0",
  fullHash = "c92de0",
  text = "Helcular's Revenge. In Tarren Mill, Helcular's Revenge turns on Thaivand's vow of vengeance. Master Helcular, a great wizard near becoming a lich, was killed by a human lynching crowd after it found his ritual lair in the hills. Before vengeance falls on Southshore, Thaivand needs Helcular's Rod, which he believes one of the yeti holds. Master Helcular was near becoming a lich when a human lynching crowd found his ritual lair in the hills and killed him. They buried his body in the Southshore cemetery. Thaivand, his apprentice, finds this treatment of a great wizard unacceptable. He vows that Southshore will face vengeance. Thaivand says Helcular's Rod must be found first. Yeti have taken over the ritual lair, and Thaivand is sure one of them has the rod. So many yeti roam the region that the search will be difficult. You can find them at Growless Cave and Darrow Hill.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_552-d10e94ce8a0985a332d9/1-0000.mp3", duration = 59.2195918, start = 0},
  },
}
P.transport["quest:553"] = {
  hash = "56a1fe",
  fullHash = "56a1fe",
  text = "Helcular's Revenge. In Hillsbrad, Helcular's Revenge begins with a rod and three flames. Novice Thaivand gives you the Rod of Helcular. Helcular fashioned three ceremonial pyres for his most powerful spell, and each flame must charge the rod before it is driven into Helcular's grave in Southshore. Helcular fashioned three ceremonial pyres for his most powerful spell, and each flame must charge the rod. The Flames of Azel and Veraz burn in the yeti cave at Darrow Hill, within the Foothill Caverns. The Flame of Uzel lies in a small cave above the caverns, farther north in the mountains near Growless Cave. After all three flames charge the rod, it is to be driven into Helcular's grave at Southshore, a heavily guarded human town. The graveyard lies in the town's northeast corner by the river. Helcular's grave is at the graveyard's southeastern corner.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_553-0d00eed03e9355200d79/1-0000.mp3", duration = 59.0628571, start = 0},
  },
}
P.transport["quest:554"] = {
  hash = "092257",
  fullHash = "092257",
  text = "Stormpike's Deciphering. In Ironforge, Loremaster Dibbs sends you to Prospector Stormpike with an ensorcelled parchment. After The Ensorcelled Parchment, Dibbs sends you to Ironforge with the parchment. Prospector Stormpike is studying at the Prospector headquarters. Tell him Dibbs sent you; Dibbs has been bringing Stormpike plenty of business lately.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_554-b92529de7e87c4f5463d/1-0000.mp3", duration = 24.2938776, start = 0},
  },
}
P.transport["quest:556"] = {
  hash = "742b2c",
  fullHash = "742b2c",
  text = "Stone Tokens. At Tarren Mill, Keeper Bel'varil sends you to recover Stone Tokens from Dalaran agents in Alterac. The Forsaken seek to learn how Dalaran's mages bind and command elementals. Magus Voidglare studies those arcane methods for them. Dalaran's magi have long commanded elemental beings with specialized conduits and enchanted foci. They bind creatures from other dimensions and force them into servitude.\n\nThough the city is still rebuilding, its agents and remnant forces patrol the surrounding territory. They use elementals as laborers and defensive shock troops. Magus Voidglare, an arcane researcher in Tarren Mill, works for the Forsaken and seeks to uncover the sorcery that compels these beings to obey.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_556-b2c8a0b269ef58323af1/1-0000.mp3", duration = 53.6293878, start = 0},
  },
}
P.transport["quest:5561"] = {
  hash = "8258d2",
  fullHash = "8258d2",
  text = "Kodo Roundup. At Scrabblescrew's Camp, five tamed kodos are needed for a caravan due soon. You take Smeed Scrabblescrew's kodo kombobulator among Desolace's ancient, aged and dying kodos, then lead each tamed beast back to camp. A caravan is due at Scrabblescrew's Camp shortly, and Smeed Scrabblescrew says it depends on him. Bibbly thinks no other goblin in Desolace knows how to make a profit. Smeed disagrees. He has formed a partnership with Cork and Rigger, and the caravan is willing to brave this land. Smeed built the kodo kombobulator to revive aged and dying kodos and bring them under control. Aim it at an ancient, aged or dying kodo, and the device jolts the beast into a tamed kodo that follows you. Bring five kodos and the device back to Scrabblescrew's Camp.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5561-f3b32d327fe5d980c168/1-0000.mp3", duration = 51.4873469, start = 0},
  },
}
P.transport["quest:557"] = {
  hash = "65aebf",
  fullHash = "65aebf",
  text = "Bracers of Binding. In Tarren Mill, Keeper Bel'varil watches for what the Magus may need next. As the Magus studies the stone tokens you gathered, Bel'varil sends you to the ruins of Dalaran for four Bracers of Earth Binding. The Magus studies the stone tokens you gathered, and Keeper Bel'varil expects another need to follow. Bracers of binding are worn on an elemental's wrists, binding the creature to a mage's service. The elementals wear them among the ruins of Dalaran. Bel'varil asks you to bring four Bracers of Earth Binding back to Tarren Mill.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_557-8ebda4f2c0f0d68b16b2/1-0000.mp3", duration = 38.3738776, start = 0},
  },
}
P.transport["quest:5581"] = {
  hash = "1a6512",
  fullHash = "1a6512",
  text = "Portals of the Legion. At Mannoroc Coven, six demon portals threaten to widen the flow of demons into this world. Taiga Wisemane asks you to close them from Shadowprey Village. From Shadowprey Village, Taiga Wisemane gives you the Hand of Iruxos. She says you need to carry it to Mannoroc Coven and banish the portals there. The demon threat is growing, and each portal you close limits how many demons cross into this world. She wants all six banished. Beware their guardians.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5581-0a6b0f2d3feeccb623eb/1-0000.mp3", duration = 36.3102041, start = 0},
  },
}
P.transport["quest:559"] = {
  hash = "60deb5",
  fullHash = "60deb5",
  text = "Farren's Proof. Along Southshore’s coast, Farren Orinelle sends Alliance recruits to prove his patrol’s work. Marshal Redpath wants evidence that the murlocs are gone from the Western Strand. After the first coastal sweeps in Down the Coast, Lieutenant Farren Orinelle faces questions from Marshal Redpath and Southshore’s leaders. Farren says the local murlocs are gone, but his superiors want proof. So he sends wandering Alliance adventurers back to the shore to bring evidence of the kills, leaving the grim work to them. West of Southshore, coastal murlocs live along the shallows of the Western Strand. Farren asks you for ten severed murloc heads to satisfy the garrison’s officers. He detests the creatures, whose repulsive sight and smell have spoiled his appetite for Southshore’s chief export and staple food.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_559-9f3aa110c63a58c15d5a/1-0000.mp3", duration = 54.4130612, start = 0},
  },
}
P.transport["quest:560"] = {
  hash = "c5fab5",
  fullHash = "c5fab5",
  text = "Farren's Proof. At Southshore, Lieutenant Farren Orinelle sends you to carry his report to Marshal Redpath. The murloc heads are proof of your work, but Farren will not carry them himself. Lieutenant Farren Orinelle patrols and secures the southern coast of Hillsbrad Foothills. Yet the harsh work of frontier warfare turns his stomach. After you cull the murlocs along the beaches, he cannot bring himself to touch the severed heads you bring back as proof. So he sends you across Southshore to deliver them to the town's command. Marshal Redpath oversees Southshore's defenses and military readiness as threats rise from Tarren Mill and wild beasts. He receives the sack of murloc heads from you, rather than directly from Farren. Redpath knows you have become Farren's errand runner, but accepts your help. Southshore needs every willing hand to keep its borders safe.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_560-55b5a421fc07139d9d85/1-0000.mp3", duration = 61.0481633, start = 0},
  },
}
P.transport["quest:561"] = {
  hash = "3ce3e2",
  fullHash = "3ce3e2",
  text = "Farren's Proof. In Southshore, Marshal Redpath sends Lieutenant Farren Orinelle orders to turn toward the naga on the Eastern Strand. He wants Orinelle to drive them back and report in person. Marshal Redpath sends word across Southshore to Lieutenant Farren Orinelle. Reports tell of naga incursions on the Eastern Strand, and Redpath wants Orinelle focused on that threat. The lieutenant must set aside other concerns, drive back the naga, and report his progress to the Marshal in person.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_561-bf32920ea911751504d4/1-0000.mp3", duration = 35.84, start = 0},
  },
}
P.transport["quest:562"] = {
  hash = "cd7efc",
  fullHash = "cd7efc",
  text = "Stormwind Ho!. Alliance High Command fears the naga threat, and Stormwind Ho! gives Farren Orinelle a way south. He hopes to claim their defeat and win a return to Stormwind City. Lieutenant Farren Orinelle finds his post in Southshore miserable. The town lies on Lordaeron’s edge, hemmed in by Forsaken forces, syndicate brigands, and sea fiends. Farren once served as a city guardsman in Stormwind, where his days meant drunks and petty brawls. Now he longs to return south.\n\nHis former mentor tells him Alliance High Command grows anxious about naga encroaching on the coasts. Farren sees a chance to leave the north behind. Farren admits he lacks the courage and skill to face Daggerspine sirens and shorehunters in open combat. So he sends you to scour the beaches southeast of Southshore and thin the naga ranks.\n\nHe needs your deeds for an impressive dispatch to Major Samuelson in Stormwind. With that credit, Farren hopes to secure a reassignment.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_562-6f2d694e08e95e5e093e/1-0000.mp3", duration = 68.6497959, start = 0},
  },
}
P.transport["quest:563"] = {
  hash = "2f476e",
  fullHash = "2f476e",
  text = "Reassignment. In Southshore, Lieutenant Farren Orinelle seeks a way back to Stormwind. He sends an adventurer to Stormwind Keep with an exaggerated account of his deeds against the coastal naga, meant for his former mentor, Major Samuelson. Lieutenant Farren Orinelle resents his posting in the Hillsbrad Foothills. Southshore lies far from the capital, and Marshal Redpath keeps a stern watch over the town. So Farren spends his days plotting a transfer south. He claims credit for clearing out the nearby Daggerspine naga, hoping to look like an indispensable, battle-hardened officer ready for promotion. Farren wants a transfer without arousing Marshal Redpath's suspicion, so he goes around the local chain of command. He turns to Major Samuelson, a senior officer in Stormwind Keep who mentored him in the past. A report sent straight to Samuelson puts Farren's claimed deeds before an officer with authority over garrison assignments.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_563-c31273cf428ac326089e/1-0000.mp3", duration = 66.2726531, start = 0},
  },
}
P.transport["quest:564"] = {
  hash = "6f94ae",
  fullHash = "6f94ae",
  text = "Costly Menace. In Southshore, Darren Malvew fears the mountain lions descending from Alterac. Undead, the Syndicate gang, and other scoundrels have cost the town horses, but the lions trouble him most. Darren Malvew lives in Southshore and hates seeing the town lose its beautiful horses. Undead, the Syndicate gang, and other scoundrels in the region have already taken quite a few. Yet Darren fears the mountain lions of Alterac most. They keep coming down from the hills. Darren wants eight Mountain Lions and ten Hulking Mountain Lions dealt with. The Mountain Lions roam the lower hills of the Alterac Mountains.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_564-54ad3a5f8da7f6eea6b2/1-0000.mp3", duration = 38.5828571, start = 0},
  },
}
P.transport["quest:565"] = {
  hash = "79fe2b",
  fullHash = "79fe2b",
  text = "Bartolo's Yeti Fur Cloak. In Southshore, Bartolo Ginsetti gathers materials for Bartolo's Yeti Fur Cloak. The eccentric artisan claims his mantle is renowned throughout the Alliance and calls for tailoring supplies, a leatherworker's cloak, and raw yeti fur. Travelers in coastal Southshore can commission a Yeti Fur Cloak from Bartolo Ginsetti. The artisan boasts that no finer garment exists anywhere on the planet. His work draws on materials gathered from the local wilderness and the skill of allied trades. Bartolo needs more than a pelt and needle to make his cloak. Bring him a Bolt of Wool, Fine Thread, a Hillman's Cloak, and ten clumps of Yeti Fur from beasts roaming the foothills. With those goods in hand, he works the raw materials into his cold-weather mantle.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_565-910690766cf1b9f783a7/1-0000.mp3", duration = 49.6326531, start = 0},
  },
}
P.transport["quest:566"] = {
  hash = "05b5de",
  fullHash = "05b5de",
  text = "WANTED: Baron Vardus. In Tarren Mill, High Executor Darthalia calls for Baron Vardus's death. He is a human and a high-ranking member of the Syndicate, accused of crimes against the Forsaken. Bring Darthalia proof of his death. High Executor Darthalia has set a price on Baron Vardus. He is a human accused of crimes against the Forsaken and one of the Syndicate's high-ranking members. Word last placed him in the Uplands of the Alterac Mountains, north of Tarren Mill. Darthalia calls for his death, and payment awaits whoever brings her proof. Baron Vardus may be at any of the Syndicate camps across the Uplands. He may also be hiding in the cellar of the inn at Strahnbrad.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_566-9a0c8ca71470806d0c64/1-0000.mp3", duration = 48.9534694, start = 0},
  },
}
P.transport["quest:568"] = {
  hash = "c77146",
  fullHash = "c77146",
  text = "The Defense of Grom'gol. At Grom'gol, Commander Aggro'gosh guards the Horde's foothold in Stranglethorn Vale. He works to keep supplies moving safely to Stonard by thinning the Lashtail Raptors outside the base camp. Commander Aggro'gosh guards the Horde at Grom'gol Base Camp. The camp is vital to a safe supply line to Stonard, but local inhabitants stand in the way. Lashtail Raptors outside Grom'gol threaten the supply line. Aggro'gosh calls on loyal fighters to thin their numbers, then report back for new orders.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_568-e6a657954904b1d04fb1/1-0000.mp3", duration = 33.9330612, start = 0},
  },
}
P.transport["quest:569"] = {
  hash = "a24467",
  fullHash = "a24467",
  text = "The Defense of Grom'gol. At Grom'gol, Commander Aggro'gosh moves to guard the supply road to Stonard. After the raptor hunt outside camp, Mosh'Ogg ogres at Mizjah Ruins keep attacking the caravans. Commander Aggro'gosh must keep supplies moving from Grom'gol through Stranglethorn Vale to Stonard, an outpost vital to the Horde. He did not come to fight every people of the Vale. Yet the Mosh'Ogg ogres have taken Mizjah Ruins southeast of camp, and warnings have not stopped their repeated attacks on Horde caravans. So Aggro'gosh orders a strike against the ogres and witch doctors holding the ruins.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_569-bca27b4ed4c6b1c0b6b5/1-0000.mp3", duration = 36.7804082, start = 0},
  },
}
P.transport["quest:570"] = {
  hash = "363a27",
  fullHash = "363a27",
  text = "Mok'thardin's Enchantment. At Grom'gol Base Camp, Far Seer Mok'thardin gathers the jungle's power for the Horde. His earlier rites have succeeded, and he seeks sharp claws and a pristine feline fang for an enchantment. At Grom'gol Base Camp, Far Seer Mok'thardin studies the wild's feral power. He seeks to bend it for the Horde. His first rites have succeeded, and he offers to shape an enchanted relic. Those willing must enter the thick underbrush and hunt the deadly predators nearby. Mok'thardin's rite calls for eight claws from shadowmaw panthers and a pristine fang from a tigress. The fierce cats roam across Stranglethorn Vale. Many prowl southeast of the Mizjah Ruins, just beyond the river.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_570-43c51dbdf3237de6e740/1-0000.mp3", duration = 48.875102, start = 0},
  },
}
P.transport["quest:571"] = {
  hash = "c22845",
  fullHash = "c22845",
  text = "Mok'thardin's Enchantment. At Grom'gol Base Camp, Far Seer Mok'thardin needs a strong binding for the Stranglethorn trophies gathered so far. Aged sinew from elder primates in southern Stranglethorn Vale will hold the feathers, claws, and fang fast. The feathers, claws, and pristine fang bring Far Seer Mok'thardin to the next stage of his ritual. He needs a tough magical tether to bind them together. Only aged sinew from an Elder Mistvale Gorilla can endure the magic he plans to weave. Elder Mistvale Gorillas forage in the jungles east of Booty Bay. Mok'thardin needs flawless sinew, so you may have to hunt several before finding one fit for his enchantment.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_571-b3f4a862d08bc7445c4b/1-0000.mp3", duration = 45.6881633, start = 0},
  },
}
P.transport["quest:572"] = {
  hash = "e8bc4a",
  fullHash = "e8bc4a",
  text = "Mok'thardin's Enchantment. At Grom'gol Base Camp, Far Seer Mok'thardin gathers materials for a shamanistic ritual. With feline trophies collected, he now seeks feathers from Stranglethorn Vale's raptors. Far Seer Mok'thardin still needs more before his shamanistic ritual can begin. He is gathering materials for a tool to aid the Warchief. Now he asks you to bring feathers worn by Jungle Stalkers. The raptors live in the dense jungle south of Grom'gol Base Camp, near the great arena.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_572-e1e53ef3a52c2d401f38/1-0000.mp3", duration = 30.3804082, start = 0},
  },
}
P.transport["quest:573"] = {
  hash = "0c9575",
  fullHash = "0c9575",
  text = "Mok'thardin's Enchantment. At Grom'gol Base Camp, Far Seer Mok'thardin seeks the last sacred water for a ceremonial choker. He sends you to a Holy Spring on the southern bluffs near the western sea, where naga explorers have arrived. Far Seer Mok'thardin needs water from a Holy Spring high above Stranglethorn Vale's southern bluffs, near the western coast. You have helped with the earlier stages of the enchantment. Scholars of the mystic and divine dispute who the spring was sanctified for. Every race across Azeroth claims its holy waters were meant for its own people. Naga explorers have reached the spring, and Mok'thardin needs you to drive them away. Bring him a draught of the water and slay ten of the serpent intruders. He needs both to finish the ceremonial choker in the Warchief's name.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_573-f667f88dd6585bec88a1/1-0000.mp3", duration = 48.7444898, start = 0},
  },
}
P.transport["quest:574"] = {
  hash = "25b9ca",
  fullHash = "25b9ca",
  text = "Special Forces. At the Kurzen Compound, Sergeant Yohwa sets her sights on the colonel's elite troops. You enter the Stockpile cave to face the commandos and headshrinkers, then report to Lieutenant Doren. Sergeant Yohwa now targets the elite specialists at the Kurzen Compound. The Second Rebellion has weakened Kurzen's regular soldiers, and Yohwa knows many of his troops personally. She calls them skilled, loyal and cruel.\n\nWhen they are not in the wilderness slaughtering rebel soldiers, the commandos and headshrinkers gather in the Stockpile cave at the back of the compound. To weaken Kurzen further, you enter and kill ten Kurzen Commandos and six Kurzen Headshrinkers. After the fight, Sergeant Yohwa sends you to her commanding officer, Lieutenant Doren, at the Rebel Camp. He will want to hear your account firsthand.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_574-3e041889b2744f23fca8/1-0000.mp3", duration = 59.115102, start = 0},
  },
}
P.transport["quest:5741"] = {
  hash = "9f1a50",
  fullHash = "9f1a50",
  text = "Sceptre of Light. At Thunder Axe Fortress, the Burning Blade has the Sceptre of Light, said to have come from the naga. Azore Aldamort fears it can sink whole cities beneath the great seas, so he asks you to bring it to Ethel Rethor. Word has spread that the Burning Blade at Thunder Axe Fortress holds the naga's Sceptre of Light. Legend says the sceptre can sink whole cities beneath the great seas. Azore Aldamort will not let the Burning Blade keep such power. A Burning Blade seer keeps the sceptre in a watchtower atop the fortress and studies it there. Azore asks you to take the sceptre from the seer and carry it back to the tower at Ethel Rethor.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5741-d3c5a936a0ad6379c459/1-0000.mp3", duration = 50.5991837, start = 0},
  },
}
P.transport["quest:576"] = {
  hash = "4d9377",
  fullHash = "4d9377",
  text = "Keep An Eye Out. In Booty Bay, Dizzy One-Eye needs the enchanted eye that gives him sight. Bloodsail Buccaneers ambushed him last night and took it. Dizzy One-Eye lost both eyes in battle. Later, his ship docked at Menethil, where a traveling wizard made him an enchanted glass eye. It restored his sight, and Dizzy once kept watch from the crow’s nest. Without it, he feels useless. Bloodsail Buccaneers ambushed Dizzy as he was leaving last night and took his eye. Their presence in Booty Bay troubles him. He fears the captain will keelhaul him when the eye’s fate comes out. A lookout who cannot see may be fit only to scrub the bilge, he reckons. So he asks you to get the eye back from the Bloodsail Buccaneers.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_576-1b8e9c817d7337b4ae1d/1-0000.mp3", duration = 45.1918367, start = 0},
  },
}
P.transport["quest:577"] = {
  hash = "d7fb77",
  fullHash = "d7fb77",
  text = "Some Assembly Required. In Booty Bay, Drizzlik says the Excelsior boots are coming along, but the skins you brought will not cover their insides. He plans to use cheaper, thicker hides from crocolisks near Lake Nazferiti for those hidden layers. Drizzlik says the Excelsior boots are coming along nicely. The skins from Supply and Demand will not cover their insides. Since no one will see those layers, he plans to use thicker, cheaper hides from the crocolisks near Lake Nazferiti.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_577-c458d1d0b5fd01f8d040/1-0000.mp3", duration = 28.7346939, start = 0},
  },
}
P.transport["quest:578"] = {
  hash = "6fd784",
  fullHash = "6fd784",
  text = "The Stone of the Tides. Off Stranglethorn Vale, strange reports from an island reach Baron Revilgaz. He suspects an ancient troll relic has resurfaced and sends you to scout the shore, with a pass to study it in Stormwind's archives. Strange apparitions and water elementals haunt an island off Stranglethorn Vale. Baron Revilgaz rules Booty Bay and suspects Gazban, a goblin mage, has found the fabled Stone of the Tides. He sends you to find the island and learn whether the rumors are true. To aid your search, he gives you a library scrip for Stormwind's scholars.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_578-e92458dbccf83534365b/1-0000.mp3", duration = 42.1616327, start = 0},
  },
}
P.transport["quest:580"] = {
  hash = "7024bf",
  fullHash = "7024bf",
  text = "Whiskey Slim's Lost Grog. In Booty Bay, Whiskey Slim needs twelve bottles of Pupellyverbos Port back before his ship sails. His crew seized the crate from a privateer, and he fears a flogging if his commanding officer finds it missing. Off the Overlook Cliffs, Whiskey Slim's ship was caught in severe weather with the Hinterlands shore nearby. The crew had seized a crate of Pupellyverbos Port from a privateer bound for Stormwind. As waves threatened to swallow the ship, Slim broke into the captain's crate for courage. Then a sudden surge swept the bottles overboard. Back in Booty Bay, Whiskey Slim's ship is preparing to weigh anchor. He fears the cat-o'-nine-tails when his commanding officer discovers the confiscated port is missing. Slim needs someone to bring back twelve bottles before his theft comes to light.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_580-7a801b18c2e879225937/1-0000.mp3", duration = 50.3902041, start = 0},
  },
}
P.transport["quest:5801"] = {
  hash = "f53d6c",
  fullHash = "f53d6c",
  text = "Fire Plume Forged. At Fire Plume Ridge, you face the heat needed to forge a skeletal key stem. The simmering volcano lies west in Un'Goro Crater, where its lava lake can fuse the stem. Then you carry it to Alchemist Arbington at Chillwind Point in the Western Plaguelands. Krinkle Goodsteel says the key stem needs two bars of thorium and fierce heat. You find the thorium, and your gold buys a mold. Dip it in the lava lake atop Fire Plume Ridge. There, the heat fuses thorium and bone together. Krinkle Goodsteel has done their part. To finish the key, you return to Alchemist Arbington at Chillwind Point in the Western Plaguelands. The lava-forged stem remains unfinished. This work prepares you for an assault.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5801-f8fc9c1dc4fa5fb2335f/1-0000.mp3", duration = 56.7640816, start = 0},
  },
}
P.transport["quest:5802"] = {
  hash = "7b10ef",
  fullHash = "7b10ef",
  text = "Fire Plume Forged. At Fire Plume Ridge, fierce heat can forge the stem of a skeletal key. Krinkle Goodsteel sends you to the volcano west in Un'Goro Crater, where a lava lake crowns its summit. You then carry the stem to Apothecary Dithers at the Bulwark in the Western Plaguelands. Two bars of thorium and fierce heat are needed to forge the key stem. You find the thorium, and Krinkle Goodsteel helps provide the heat. Your gold has bought a mold, ready for the lava lake atop Fire Plume Ridge. There, lava fuses thorium and bone together. Krinkle Goodsteel has done their part. Now you return to Apothecary Dithers at the Bulwark in the Western Plaguelands to finish the key. The stem forged in lava remains unfinished, and this work prepares for an assault.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5802-6e150ecb609a8a281065/1-0000.mp3", duration = 58.2530612, start = 0},
  },
}
P.transport["quest:581"] = {
  hash = "1a6941",
  fullHash = "1a6941",
  text = "Hunt for Yenniku. At Grom'gol Base Camp, Nimboya searches for Yenniku, the youngest son of his chieftain. He suspects the Bloodscalp tribe holds the boy and asks you to prove your strength by hunting their warriors and bringing back their tusks. At Grom'gol Base Camp, Nimboya fears a grim fate for Yenniku, the youngest son of the Darkspear chieftain. An old tribal custom placed the boy among the Gurubashi trolls of Zul'Gurub. When the Darkspear tribe left their homeland with the orc warchief Thrall, Yenniku was left behind and lost. Nimboya has returned from Orgrimmar to Stranglethorn Vale to find the chieftain's son and bring him to safety. Nimboya suspects the Bloodscalp tribe holds Yenniku. To prove you are strong enough to hunt them, he sends you north to gather nine tusks from Bloodscalp trolls. Bring the trophies back to Grom'gol Base Camp as proof of your strength in battle. Then the search for the chieftain's boy can continue with Headhunting.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_581-277ad5c0b4236bf4a35e/1-0000.mp3", duration = 62.6416327, start = 0},
  },
}
P.transport["quest:582"] = {
  hash = "abc611",
  fullHash = "abc611",
  text = "Headhunting. At Grom'gol Base Camp, Nimboya seeks news of Yenniku, the Darkspear chieftain's son. He sends you to hunt Bloodscalp headhunters and bring back their shrunken heads, hoping to learn whether Yenniku is dead. Nimboya fears the Bloodscalp tribe may have killed Yenniku, the Darkspear chieftain's son. The search began with Hunt for Yenniku, and now he sends you after Bloodscalp Headhunters at the ruins of Zuuldaia and Zul'Kunda along Stranglethorn Vale's northern coast.\n\nBring back twenty shrunken heads. Nimboya will inspect them for signs that Yenniku met a violent end. If the youth is dead, Nimboya curses Gan'zulah, chief of the Bloodscalp.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_582-746b9e66e8306047a140/1-0000.mp3", duration = 42.8669388, start = 0},
  },
}
P.transport["quest:5821"] = {
  hash = "c3ac9e",
  fullHash = "c3ac9e",
  text = "Bodyguard for Hire. In Desolace, Cork Gizelton and Rigger stop their kodo caravan at the sound of centaur war drums. Cork asks you to guard it past the Kolkar village, with payment waiting down the road. Cork Gizelton and Rigger lead their kodo caravan past the Kolkar centaur. Then the war drums sound, and the caravan stops. Dead traders bring no profit, so Cork asks you to guard it a short distance past the Kolkar village and keep it safe. The caravan waits north of the Kolkar Village and southeast of Thunder Axe Fortress. Smeed Scrabblescrew waits with payment at Scrabblescrew's Camp, a little way down the road. Smeed does a little business with the Gizelton caravan.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5821-ee1e53915bb262dba45c/1-0000.mp3", duration = 43.4938776, start = 0},
  },
}
P.transport["quest:584"] = {
  hash = "1c2cad",
  fullHash = "1c2cad",
  text = "Bloodscalp Clan Heads. Nimboya still seeks word of Yenniku after the trophies are sorted. The young troll is missing, so the Darkspear turn to the Bloodscalp Clan Heads for answers. Nimboya seeks answers from the Bloodscalp leaders. The earlier hunt found no sign of Yenniku among the fallen. Gan'zulah, the Bloodscalp chief, and Nezzliok the Dire, his witch doctor, are enemies of the Darkspear. Neither would speak willingly. So Nimboya plans to bring their heads to the cauldron at Grom'gol Base Camp and force the truth from their dead lips. Gan'zulah and Nezzliok dwell deep in the ruins of Zul'Kunda in northwestern Stranglethorn Vale. Nimboya means to cast their heads into the boiling brew and make them speak about Yenniku.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_584-69f06969b2d18b3d21bb/1-0000.mp3", duration = 49.4759184, start = 0},
  },
}
P.transport["quest:585"] = {
  hash = "df4764",
  fullHash = "df4764",
  text = "Speaking with Nezzliok. At Grom'gol Base Camp, Nezzliok's severed head speaks from a bubbling cauldron. The Bloodscalp witch doctor knows where Yenniku was taken, but demands a grim tribute before he tells you. Nezzliok remains bound in the bubbling cauldron after the hunt for Bloodscalp Clan Heads. He knows where Yenniku was taken, but gives up nothing freely. Bring three trophy skulls from the rival Skullsplitter tribe to his resting place. Then his departed spirit can command thralls in the Nether. Nezzliok demands one skull from the Skullsplitter trophy pile at Balia'mah, one from Ziata'jai, and one from Zul'Mamwe. All three offerings must lie beside his own head before the dead witch doctor will consider his spirit satisfied.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_585-41927ce418e2d8c58c94/1-0000.mp3", duration = 48.8489796, start = 0},
  },
}
P.transport["quest:586"] = {
  hash = "cff3aa",
  fullHash = "cff3aa",
  text = "Speaking with Gan'zulah. At Grom'gol Base Camp, Gan'zulah curses those who stand over the bubbling pot. The Bloodscalp chieftain demands the deaths of his Skullsplitter rivals and the ruin of their ruler, Ana'thek the Cruel. Gan'zulah's severed head curses anyone who stands over the bubbling pot. Though dead, the Bloodscalp chieftain still hates his captors and ancestral enemies. He points you east toward the Skullsplitter stronghold and demands the deaths of its hunters, headhunters, and berserkers. Their ferocious warband may kill those who dare face it. Gan'zulah expects the assault to end in disaster. He believes Chief Ana'thek the Cruel will tear apart any intruder who challenges him. Still, he demands Ana'thek's shattered armor as proof of triumph. Bring that trophy back to the cauldron at Grom'gol Base Camp to satisfy Gan'zulah's spite.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_586-94ba272c495c63a12fea/1-0000.mp3", duration = 57.8089796, start = 0},
  },
}
P.transport["quest:5863"] = {
  hash = "b6cbc5",
  fullHash = "b6cbc5",
  text = "The Dunemaul Compound. In the desert south of Gadgetzan, a growing ogre force has Andi Lynn afraid. She wants the compound destroyed before the ogres gather more strength. A large band of nomadic ogres has reached Tanaris. South of Gadgetzan, they have claimed a broad stretch of desert and made their compound. Smaller bands roam the desert, and some have entered the old troll ruins. Andi Lynn fears what may happen if the ogres grow stronger. Andi Lynn wants ten Dunemaul Brutes and ten Dunemaul Enforcers cut down. Gor'marok the Ravager leads the band. Andi Lynn believes the ogres will begin to crumble once he no longer commands them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5863-4c113afeb74d46d9b012/1-0000.mp3", duration = 40.724898, start = 0},
  },
}
P.transport["quest:587"] = {
  hash = "044ed4",
  fullHash = "044ed4",
  text = "Up to Snuff. In Booty Bay, Deeg is waiting for the snuff he likes, but the herbalist has none to sell. Bloodsail Raiders are said to have taken the shipment, and Deeg asks you to bring him fifteen shares. Deeg knows life at sea may be poor, yet it is the only life he has. Whenever he reaches port, he looks for grog and fine snuff.\n\nThe Booty Bay herbalist has run out. The herbalist says Bloodsail Raiders hijacked the shipment, so Deeg hopes a fearless traveler can persuade them to share it. He wants fifteen shares of snuff.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_587-898453b3d83acf71d833/1-0000.mp3", duration = 33.5934694, start = 0},
  },
}
P.transport["quest:588"] = {
  hash = "1175a2",
  fullHash = "1175a2",
  text = "The Fate of Yenniku. At Grom'gol Base Camp, Nezzliok's head speaks of Yenniku from the cauldron. Kin'weelay waits beside it for the spirit's words. You've appeased the spirits of Gan'zulah and Nezzliok. Now Nezzliok's head speaks from the bubbling cauldron. Kin'weelay waits beside it to hear the secret.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_588-4a66fa77c039f2ee9d7b/1-0000.mp3", duration = 20.6889796, start = 0},
  },
}
P.transport["quest:589"] = {
  hash = "124e30",
  fullHash = "124e30",
  text = "The Singing Crystals. Kin'weelay seeks a way to free Yenniku from the darkness holding him. He turns to the Mind's Eye and asks you to gather shards that may help him command its power. Kin'weelay searches old jungle lore for a way to free Yenniku's spirit. The tales speak of the Mind's Eye, a gem hidden deep in Stranglethorn and mighty in magic. Kin'weelay believes it may hold the answer. As he seeks the jungle spirits' guidance to find it, he needs rare catalysts to control its sorcery safely. Kin'weelay sends you southeast to Crystalvein Mine, where ironjaw basilisks dwell beneath the earth. He asks you to recover three pulsing blue shards from them. He plans to channel the magic in these singing stones during a final ritual. Once he has recovered the Mind's Eye, he means to bend its power to his will.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_589-824054cd221895e63c2c/1-0000.mp3", duration = 60.8130612, start = 0},
  },
}
P.transport["quest:591"] = {
  hash = "98b231",
  fullHash = "98b231",
  text = "The Mind's Eye. At Grom'gol Base Camp, Kin'weelay seeks The Mind's Eye to save Yenniku. Mai'Zoth holds the gem deep in the Mosh'Ogg Ogre Mound. After the singing crystals are recovered, Kin'weelay turns to The Mind's Eye. He believes only the gem can help save Yenniku, son of the Darkspear chieftain. Mai'Zoth holds it. Kin'weelay remembers the ogre mage from the Darkspear tribe's earlier days in the jungle. Mai'Zoth dwells deep in the Mosh'Ogg Ogre Mound, east of Grom'gol. His magic was formidable before he took The Mind's Eye, and the stone has made him stronger still. The ogre stronghold is perilous. Yet the gem is the young troll's only hope of freedom.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_591-fbc10a521ca3853be8c2/1-0000.mp3", duration = 37.6685714, start = 0},
  },
}
P.transport["quest:592"] = {
  hash = "66c432",
  fullHash = "66c432",
  text = "Saving Yenniku. Kin'weelay has found a way to bring Yenniku home from Zanzil the Outcast. He reshapes the recovered Mind's Eye into a soul gem that can stun Yenniku and hold his spirit until you take it to Nimboya. Kin'weelay turns the recovered Mind's Eye into a magical soul gem. Its enchantment lets you stun Yenniku and set the stone on his head to capture his spirit. With Yenniku's spirit inside, you can carry the gem safely to his kin at Grom'gol Base Camp. Zanzil the Outcast holds Yenniku in the Ruins of Aboraz, along the Crystal Shore on the southern Cape of Stranglethorn. You enter Zanzil's territory and use the gem to break the witch doctor's hold over the young troll. Then you carry the filled gem back to Nimboya.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_592-016394df2e3d9ebca43d/1-0000.mp3", duration = 46.5763265, start = 0},
  },
}
P.transport["quest:593"] = {
  hash = "cfe6b9",
  fullHash = "cfe6b9",
  text = "Filling the Soul Gem. In Stranglethorn Vale, you reach Yenniku while he remains caught in a trance. A prepared soul gem may preserve him by taking his spirit. Yenniku, the young troll you have tried to save, stands motionless before you in Stranglethorn Vale. His mind is far away. The enchanted gem prepared to hold his essence is the only path forward.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_593-0e387775ec550e88aa1b/1-0000.mp3", duration = 22.1518367, start = 0},
  },
}
P.transport["quest:594"] = {
  hash = "b09765",
  fullHash = "b09765",
  text = "Message in a Bottle. Along Stranglethorn Vale's shore, Message in a Bottle bears a plea from someone held captive. The writer says a great beast keeps them on an isolated island in the South Seas. A plea for rescue rests in a glass container, half-buried in the sand. The captive is trapped beneath thick jungle canopies on a foreign island, held by a great Skymane. Wild Shore lies to the northwest through the trees. Large sailing vessels drift to the southwest.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_594-0587bb550e04e0231a55/1-0000.mp3", duration = 27.0628571, start = 0},
  },
}
P.transport["quest:5943"] = {
  hash = "2d06fc",
  fullHash = "2d06fc",
  text = "Gizelton Caravan. At Mannoroc Coven, Rigger Gizelton asks you to guard his caravan. He and Cork set out to make a fortune, but trade has proved more dangerous than they expected. Rigger Gizelton and Cork began their caravan hoping to make a fortune. They did not know how risky turning a profit could be. Mannoroc Coven lies ahead, where demons usually leave the caravan alone. This time, the kodos are spooked. Rigger offers payment if you guard the caravan past the coven. Once it is safely through, Smeed will pay you at Scrabblescrew's Camp.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5943-0ce25d864e486939eff3/1-0000.mp3", duration = 38.0081633, start = 0},
  },
}
P.transport["quest:595"] = {
  hash = "4a20e6",
  fullHash = "4a20e6",
  text = "The Bloodsail Buccaneers. Along the Savage Coast, rumors of rival pirates trouble the newly arrived Blackwater Raiders. First Mate Crazz sends you to scout a cove while his crew drinks and seeks company in Booty Bay. The Blackwater Raiders have just docked in Booty Bay when word reaches them of rivals across southern Stranglethorn Vale. The crew is busy with grog and company ashore, so First Mate Crazz asks you to go in their place. Head north along the Savage Coast and scout a cove for signs of what the Bloodsail Buccaneers are doing.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_595-c9ffaec0f1e9e5e476ed/1-0000.mp3", duration = 34.5077551, start = 0},
  },
}
P.transport["quest:596"] = {
  hash = "af48ce",
  fullHash = "af48ce",
  text = "Bloody Bone Necklaces. At Grom'gol Base Camp, Kin'weelay turns the Bloodscalp conflict into a private struggle. Kin'weelay came to Grom'gol Base Camp to help Nimboya, yet he has purposes of his own. The Bloodscalp trolls to the north are enemies of the Darkspears. Kin'weelay believes trophies taken from fallen foes grant spiritual power over them. So he asks travelers to hunt Bloodscalp warriors and take the bloody bone necklaces they wear.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_596-5e87c4d92cccf8898b67/1-0000.mp3", duration = 28.6563265, start = 0},
  },
}
P.transport["quest:597"] = {
  hash = "efdf0f",
  fullHash = "efdf0f",
  text = "The Bloodsail Buccaneers. At Booty Bay, the Bloodsail Buccaneers’ plans now point to a camp and an attack signal. A map marks the Bloodsail Buccaneers’ intended camp in Booty Bay with a red X. Their orders call for silence. The crew must kill anyone who approaches and wait for a signal from the southern command post before attacking. You carry the findings back to First Mate Crazz in Booty Bay. He sent you to scout, and the pirates are still waiting for the signal before they attack.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_597-5c213dc70b42e0346533/1-0000.mp3", duration = 32.5746939, start = 0},
  },
}
P.transport["quest:598"] = {
  hash = "152a64",
  fullHash = "152a64",
  text = "Split Bone Necklace. Kin'weelay at Grom'gol Base Camp sends you southeast to hunt the Skullsplitters. The Darkspears left Stranglethorn Vale, yet their old feud with these jungle rivals continues. Bring back twenty-five split bone trophies to aid the Darkspears and earn their friendship. After the Bloodscalp hunt, Kin'weelay turns to another old enemy. Southeast of Grom'gol Base Camp, the Skullsplitter tribe has fought the Darkspears for many years. The Darkspears no longer live in Stranglethorn Vale, yet they remain bound to this war. You travel into Skullsplitter territory to claim twenty-five split bone necklaces and earn the Darkspears' friendship and respect. Kin'weelay takes pride in seeing these hostile trolls cut down like young saplings by a basilisk. Each trophy you bring back counts as a victory for his people.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_598-6145752368e56e9ed097/1-0000.mp3", duration = 55.1444898, start = 0},
  },
}
P.transport["quest:599"] = {
  hash = "b8edf2",
  fullHash = "b8edf2",
  text = "The Bloodsail Buccaneers. First Mate Crazz has learned that the Bloodsail Buccaneers mean to strike Booty Bay. He sends you to warn Fleet Master Seahorn, commander of the Blackwater Raiders, before they move. First Mate Crazz sends you to warn Fleet Master Seahorn of an attack on Booty Bay. Crazz has learned the Bloodsail Buccaneers mean to strike the port directly, and the threat is greater than he first thought. Seahorn is somewhere in town. He must hear the warning before the rival pirates move.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_599-d7abc56fd0dcb5b9da4d/1-0000.mp3", duration = 32.3657143, start = 0},
  },
}
P.transport["quest:600"] = {
  hash = "b8a0ea",
  fullHash = "b8a0ea",
  text = "Venture Company Mining. In northern Stranglethorn, the Venture Company keeps finding Singing Blue Crystals. Crank Fizzlebub in Booty Bay wants ten brought back from the hills near Crystalvein Mine. You’ve gathered Singing Blue Shards, and now Crank Fizzlebub points you toward a larger rival. The Venture Company’s work across the jungle cuts into the profits of independent goblins. Basilisks keep its miners out of Crystalvein Mine, so they dig in the hills around it for Singing Blue Crystals. Crank asks you to take ten from the miners and bring them to Booty Bay as proof of their setback.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_600-c34c5846f25f6ac6b65d/1-0000.mp3", duration = 35.7616327, start = 0},
  },
}
P.transport["quest:601"] = {
  hash = "73a00a",
  fullHash = "73a00a",
  text = "Water Elementals. On the island off the coast, Water Elementals may offer a clue to the Stone of the Tides' curse. Baron Revilgaz wants their bracers examined for a way to counter it. Baron Revilgaz suspects the Water Elementals' magical residue may help fight the Stone of the Tides' curse. The stone is said to make anyone who wields it drift in and out of reality. So he sends you back to the island off the coast to gather bracers for the scholarly mages of Dalaran to examine. Baron Revilgaz admits he lacks the skill to judge whether the bracers can help. He refuses to leave Booty Bay just to speak with tiresome old mages. So he sends you north to have a mage examine them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_601-4e4f8ba5889604243f7b/1-0000.mp3", duration = 42.0310204, start = 0},
  },
}
P.transport["quest:602"] = {
  hash = "9bc467",
  fullHash = "9bc467",
  text = "Magical Analysis. From Booty Bay, Baron Revilgaz sends you north to Dalaran with water elemental bracers. He hopes Archmage Ansirem Runeweaver can study the curse tied to the Stone of the Tides. Baron Revilgaz has the bracers in Booty Bay, but their secret lies beyond his reach. The town has no mage skilled enough to unravel the curse behind the Stone of the Tides, so he points you toward Dalaran. Its wizards are working to rebuild their broken kingdom. Revilgaz has dealt with Archmage Ansirem Runeweaver before and trusts his knowledge. He believes no mage can resist an intriguing puzzle.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_602-2059abb77e85aa682492/1-0000.mp3", duration = 39.68, start = 0},
  },
}
P.transport["quest:6027"] = {
  hash = "cfcef4",
  fullHash = "cfcef4",
  text = "Book of the Ancients. At the Ethel Rethor tower, Azore Aldamort entrusts you with the Gem of the Serpent. Set it on the Serpent Statue on Ranazjar Isle, northwest of the tower, and the guardian of the Book of the Ancients will appear. After Sceptre of Light, Azore Aldamort gives you the Gem of the Serpent. Ranazjar Isle lies northwest of the Ethel Rethor tower, and there the Serpent Statue waits. Set the gem on its hand to call forth the Book of the Ancients’ guardian. The naga have kept the book’s secrets for centuries, and Azore hopes it will teach much about their scaled foes.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6027-4d978a9f8d991765f6cb/1-0000.mp3", duration = 45.2440816, start = 0},
  },
}
P.transport["quest:603"] = {
  hash = "bfc558",
  fullHash = "bfc558",
  text = "Ansirem's Key. An ancient troll dagger may weaken the magic empowering the Stone of the Tides. Archmage Ansirem Runeweaver found the blade in Stranglethorn, then gave it to his daughter Catelyn, who left home for the pirates of Booty Bay. Archmage Ansirem Runeweaver has found that an altar, or focal point, amplifies the Stone of the Tides. To overpower that magic, he needs an ancient troll dagger he uncovered while researching in Stranglethorn. He gave the blade to his daughter Catelyn long ago. Headstrong, she left home for the pirates of Booty Bay.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_603-a60eca98c64f29c6a279/1-0000.mp3", duration = 41.2212245, start = 0},
  },
}
P.transport["quest:604"] = {
  hash = "89ab20",
  fullHash = "89ab20",
  text = "The Bloodsail Buccaneers. On the Wild Shore, the Bloodsail Buccaneers have raised a southern command post. Fleet Master Seahorn sends a trusted Blackwater Raider to seize their charts and orders, so the fleet can learn their plans. Crazz’s praise has brought you to Fleet Master Seahorn’s notice. The Bloodsail Buccaneers have raised a southern command post on the Wild Shore. Seahorn sends you to strike their camp, cut down their swashbucklers, and seize their naval charts and written orders. The fleet needs those papers to learn what its rivals intend.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_604-76847278ac07e7e11380/1-0000.mp3", duration = 35.0563265, start = 0},
  },
}
P.transport["quest:605"] = {
  hash = "0aadaa",
  fullHash = "0aadaa",
  text = "Singing Blue Shards. In Stranglethorn Vale, buyers seek Singing Blue Shards. The Venture Company makes it hard for Crank Fizzlebub to gather raw Singing Crystals, so he offers you a cut of the profits for ten shards taken from basilisk hides. Crank Fizzlebub has buyers for Singing Crystals, found only in Stranglethorn Vale. The Venture Company makes gathering raw crystals hard for him. So he seeks another way to get them. Basilisks eat the crystals, and the mineral becomes part of their hardened hides. You can recover usable shards there. Basilisks across the jungle may yield crystal fragments. Fizzlebub points you to the gentler ones along the northern shores south of Zul'Kunda. Bring him ten shards so he can move ahead with his buyers. Then his attention turns to the Venture Company's operations.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_605-fbe5d6013d7c19f130a1/1-0000.mp3", duration = 49.5804082, start = 0},
  },
}
P.transport["quest:606"] = {
  hash = "2928d3",
  fullHash = "2928d3",
  text = "Scaring Shaky. At Booty Bay's docks, “Shaky” Phillipe still owes “Sea Wolf” MacKinley from last week's game. MacKinley sends you outside town for Elder Mistvale Gorilla giblets to frighten Phillipe into paying. “Sea Wolf” MacKinley wants his gambling debts paid, and many people owe him. “Shaky” Phillipe is first. He waits by the docks in Booty Bay and owes a large sum from last week's game. MacKinley sends you outside town to hunt Elder Mistvale Gorillas and bring back plenty of giblets. Keep their animal origin quiet, so Phillipe imagines the worst.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_606-6ac0c9320608c9a4a4ce/1-0000.mp3", duration = 35.317551, start = 0},
  },
}
P.transport["quest:607"] = {
  hash = "f771a5",
  fullHash = "f771a5",
  text = "Return to MacKinley. You carry Phillipe’s pouch to Sea Wolf MacKinley, who is owed payment. Phillipe says he meant to pay all along and asks that you go easy. \"Shaky\" Phillipe hands you a pouch of payment for Sea Wolf MacKinley. He swears he always meant to repay the debt. Phillipe says he got a little drunk and lost the way. He thinks MacKinley will understand, and insists there is no need to get rough.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_607-f4951dd3a0910d101631/1-0000.mp3", duration = 24.0587755, start = 0},
  },
}
P.transport["quest:608"] = {
  hash = "27f247",
  fullHash = "27f247",
  text = "The Bloodsail Buccaneers. In Stranglethorn, the Bloodsail Buccaneers gather strength for an attack. Fleet Master Seahorn will not risk his whole fleet in a counterstrike, so he sends a small crew against their leaders before they can begin. Fleet Master Seahorn means to halt the Bloodsail attack before it gains strength. He mocks Fleet Master Firallon's skill at sea, then chooses to strike at the commanders. Seahorn will not risk a full naval battle. Instead, he sends a small crew to Firallon's landing camp to kill Firallon, Captain Stillwater, and Captain Keelhaul. Without their leaders, the buccaneers will be left without command.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_608-a669ea6f024f8cdc41dd/1-0000.mp3", duration = 40.4636735, start = 0},
  },
}
P.transport["quest:609"] = {
  hash = "b12ca8",
  fullHash = "b12ca8",
  text = "Voodoo Dues. In Booty Bay, “Sea Wolf” MacKinley is still waiting for three old debts to be paid. Maury “Club Foot” Wilkins, Jon-Jon the Crow, and Chucky “Ten Thumbs” owe him, but rumors say curses and enchantment sent them wandering ancient jungle ruins. MacKinley wants their prized possessions, whatever their fate. You have already collected debts for “Sea Wolf” MacKinley, but three accounts remain unpaid. Maury “Club Foot” Wilkins, Jon-Jon the Crow, and Chucky “Ten Thumbs” have owed him for months. MacKinley first thought they had left Booty Bay to escape their debts. Then he heard they had met a stranger, darker fate deep in the jungle. Whispers say curses and enchantment have left the three men wandering ancient stonework northeast of Booty Bay. They are said to roam the Ruins of Aboraz and the Ruins of Jubuwal. MacKinley wants you to find each man and take his notable valuables: Jon-Jon's Golden Spyglass, Chucky's Huge Ring, and Maury's Clubbed Foot.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_609-df616af3da035dbd0308/1-0000.mp3", duration = 66.2726531, start = 0},
  },
}
P.transport["quest:610"] = {
  hash = "1e9fca",
  fullHash = "1e9fca",
  text = "\"Pretty Boy\" Duncan. Catelyn the Blade has lost the dagger her father asked her to return. She wants it back from Pretty Boy Duncan before she helps you further. Catelyn the Blade has left the mages and their dusty tomes behind. Ansirem's Key led you to her, but she cannot give you the dagger her father asked her to return. A Bloodsail Buccaneer took it. Until her blade is recovered, Catelyn will hand over nothing else. Pretty Boy Duncan struck Catelyn unconscious and took the knife she carried in a fight. She relies on that weapon. Now she insists on getting that very blade back from the buccaneer before she helps you further.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_610-768a92ca1a9b294b2c78/1-0000.mp3", duration = 45.3746939, start = 0},
  },
}
P.transport["quest:611"] = {
  hash = "4fc380",
  fullHash = "4fc380",
  text = "The Curse of the Tides. Off Stranglethorn's coast, Catelyn the Blade lends you her recovered knife to strike a sunken altar. Baron Revilgaz in Booty Bay seeks the Stone of the Tides for his collection of ancient troll artifacts. Catelyn the Blade lends you her recovered troll dagger to break an altar beneath the waves. She knows less of troll ruins than her father, but has heard of a sunken troll city. So she points you northwest of Grom'gol Base Camp. There, in the Vile Reef's underwater ruins, the Altar of the Tides glows blue among sea life and murlocs.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_611-6c65414bf22bdef0a57d/1-0000.mp3", duration = 37.3028571, start = 0},
  },
}
P.transport["quest:613"] = {
  hash = "7148b7",
  fullHash = "7148b7",
  text = "Cracking Maury's Foot. At Booty Bay, MacKinley still cannot claim what Maury owed him. Maury locked the debt inside his own foot, so MacKinley sends travelers to the Mosh'Ogg ogre mound in Stranglethorn Vale to find the key. After the foot was recovered in Voodoo Dues, \"Sea Wolf\" MacKinley faces another obstacle in Booty Bay. His late debtor locked the foot, sealing the valuables he owes inside. Maury gambled with the ogres at the Mosh'Ogg mound northeast of Booty Bay. MacKinley recalls Maury saying they drove him away after he won too much. So MacKinley suspects they have the key and sends you to search for it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_613-9d44f2fa7e232b31a556/1-0000.mp3", duration = 38.922449, start = 0},
  },
}
P.transport["quest:6132"] = {
  hash = "a60aca",
  fullHash = "a60aca",
  text = "Get Me Out of Here!. In the Valley of Spears, Melizza Brimbuzzle fears the Maraudines mean to eat her. She asks you to get her out, and her brother Hornizz promises good pay. Melizza Brimbuzzle came to the Valley of Spears hoping to strike a deal with the Maraudines. They would not talk, and now she fears they mean to eat her. Minutes ago, she overheard centaurs discussing wood for their cookpot. She wants to leave quickly. Hornizz Brimbuzzle waits at the family camp east of Melizza's present position. It lies beside the kodo graveyard. Melizza promises her brother will pay you well if you bring her out of the valley.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6132-329c339f2d9799c6c90d/1-0000.mp3", duration = 40.5159184, start = 0},
  },
}
P.transport["quest:6134"] = {
  hash = "f85682",
  fullHash = "f85682",
  text = "Ghost-o-plasm Round Up. Hornizz Brimbuzzle sends you into the Valley of Bones for ghost energy, hoping the Magram will pay well for it. Hornizz Brimbuzzle sends you southeast to the Valley of Bones, where Magram ghosts walk. The valley sounds frightening to him. Yet he thinks the spirits must frighten the Magram even more, and he is sure the centaurs would pay well for ghost energy captured there. Hornizz Brimbuzzle gives you a crate of ghost magnets. Set one between the two huge skeletons called the Dead Goliaths, and it draws the ghosts toward it. The spirits yield ghost-o-plasm, which Hornizz plans to sell to the Magram. He asks you to bring him eight ghost-o-plasms and the crate.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6134-93acc281e4535c4d83ca/1-0000.mp3", duration = 41.9787755, start = 0},
  },
}
P.transport["quest:6141"] = {
  hash = "d6900e",
  fullHash = "d6900e",
  text = "Brother Anton. In Nijel's Point, Brother Anton seeks help against the undead in Desolace. He came from distant lands after hearing of the threat. Rumors of undead in Desolace reached Brother Anton in far-off Kalimdor. He booked passage at once to seek them out and destroy them. Now he looks for people with courage and resolve. If your heart is true, Brother Crowley sends you to find him in Nijel's Point, the Alliance town in Desolace.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6141-9a6db1eb820830b34882/1-0000.mp3", duration = 28.5257143, start = 0},
  },
}
P.transport["quest:6142"] = {
  hash = "cd5f78",
  fullHash = "cd5f78",
  text = "Clam Bait. At Shadowprey Village, Mai'Lahii trusts one bait above all others. He asks for ten pieces of soft-shelled clam meat from the wrecked ship north along the coast. Mai'Lahii asks you for bait fish cannot resist. He has fished all his life and trusts soft-shelled clam meat above all else. North of Shadowprey Village, a wrecked ship lies off the coast, and soft-shelled clams are scattered throughout the area. He wants ten pieces of the meat.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6142-96f35440f4b3bf058d0b/1-0000.mp3", duration = 27.5591837, start = 0},
  },
}
P.transport["quest:6143"] = {
  hash = "4be773",
  fullHash = "4be773",
  text = "Other Fish to Fry. At Shadowprey Village, Drulzegar Skraghook asks you to strike back at the Slitherblade. Naga took the fishing crew near Ranazjar Isle, and Drulzegar alone returned. Drulzegar Skraghook and the crew often fished near Ranazjar Isle. The isle lies north of a wreck on the coast. One morning, the naga attacked and killed everyone but Drulzegar. Now revenge fills Drulzegar's thoughts, and guilt is too much to bear. Drulzegar asks you to slay seven Slitherblade Myrmidons, seven Slitherblade Naga and five Slitherblade Sorceresses. A bad knee keeps Drulzegar from joining you. The naga usually lurk far down among coral reefs beneath the waves, Drulzegar says. Your effort will be rewarded.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6143-a78e2bf683373ca8ae71/1-0000.mp3", duration = 47.2816327, start = 0},
  },
}
P.transport["quest:616"] = {
  hash = "06159c",
  fullHash = "06159c",
  text = "The Haunted Isle. In Booty Bay, Krazek hears a tale of an isle haunted by a goblin ghost. He gathers unusual rumors for Baron Revilgaz, and this one recalls an old troll legend. Krazek gathers reports of strange happenings throughout Stranglethorn Vale for Baron Revilgaz. In a Booty Bay tavern, sailors tell him of an isle off the coast where water elementals dwell. They say the ghost of a raving goblin haunts it. Krazek gives little heed to spectral gossip, but this tale catches his attention. He asks you to carry it to the baron. Baron Revilgaz remembers an old troll legend from a book when he hears Krazek's report. The water elementals and goblin apparition make him suspect that the Stone of the Tides may be within his grasp. He hopes to add the ancient relic to his personal collection of artifacts.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_616-1a6d69bbb9530be32a73/1-0000.mp3", duration = 59.3502041, start = 0},
  },
}
P.transport["quest:6161"] = {
  hash = "722194",
  fullHash = "722194",
  text = "Claim Rackmore's Treasure!. During Claim Rackmore's Treasure!, Rackmore's log tells of a ship attacked on its way to Feathermoon Stronghold. He hid his treasure chest on Ranazjar Isle to keep it from his enemies, but both keys to open it were lost. Rackmore's log tells of seafaring creatures attacking his ship on its way to Feathermoon Stronghold. He hid his treasure chest on Ranazjar Isle to keep it from his enemies. Both keys needed to open it were lost, one silver and one gold. Whoever finds the keys and the chest will find a treasure.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6161-3c7a080af50fe6a70291/1-0000.mp3", duration = 35.3959184, start = 0},
  },
}
P.transport["quest:617"] = {
  hash = "3431e5",
  fullHash = "3431e5",
  text = "Akiris by the Bundle. In Booty Bay, Privateer Bloads seeks akiris reeds for an associate who pays well. The naga were last seen on the northern beach, where you must take the reeds from them. Privateer Bloads offers seaside work in Booty Bay. His associate Groy pays well for bundles of akiris reed, a plant that grows by the sea and bears the name the naga give it. Bloads does not know why Groy wants the reeds. He needs ten stalks, and the naga were last seen on the northern beach.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_617-8fa730c99cc5910f78e5/1-0000.mp3", duration = 32.3657143, start = 0},
  },
}
P.transport["quest:618"] = {
  hash = "10a535",
  fullHash = "10a535",
  text = "Facing Negolash. Along Stranglethorn Vale's coast, a stolen cutlass sets events in motion. Sprogger knows how to draw Negolash out with the giant's favorite food and drink. When giants wrecked Captain Smotts' vessel, Negolash headed for the galley. He left the crew alone and went after wine and Barbecued Buzzard Wings, Sprogger's specialty. Sprogger had traveled to the Badlands to learn the recipe. Sprogger plans to lure Negolash with a feast. You carry ten servings of wings and five bottles of wine to Captain Smotts' ruined lifeboat on the southeastern shore. The banquet draws the giant near. Then you can confront him and reclaim the captain's cutlass.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_618-8149889e083740373e7f/1-0000.mp3", duration = 44.9567347, start = 0},
  },
}
P.transport["quest:619"] = {
  hash = "70c873",
  fullHash = "70c873",
  text = "Enticing Negolash. Along Stranglethorn Vale's shore, a marked lifeboat offers a way to lure Negolash. Ten barbecued buzzard wings and five bottles of junglevine wine lie on the wreck. The abandoned lifeboat bears the faded words Smotts' Revenge. While hunting Negolash, arrange ten barbecued buzzard wings and five bottles of junglevine wine on the wreck to draw him out.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_619-6c5528aa1fe007b48a27/1-0000.mp3", duration = 24.2416327, start = 0},
  },
}
P.transport["quest:621"] = {
  hash = "85dabb",
  fullHash = "85dabb",
  text = "Zanzil's Secret. Crank Fizzlebub seeks Zanzil's Secret in the ruins northeast of Booty Bay. The exiled troll's brew bends minds and strengthens bodies, and Crank wants samples for himself. Northeast of Booty Bay, Zanzil has made his home in the ruins of Jubuwal and Aboraz. His former tribal leaders cast him out, fearing his mastery over other minds. Now he rules followers with concoctions made from jungle plants. The mixtures dull their will and heighten their strength, leaving them docile but sturdy. Crank Fizzlebub sees profit in Zanzil's craft. Those who want power over others might pay handsomely for such a brew, so the goblin wants a supply from the ruins. Deliver enough samples and Crank offers the usual coin, with a quiet bonus if you keep the bargain private.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_621-e02193c1f87760777358/1-0000.mp3", duration = 54.0212245, start = 0},
  },
}
P.transport["quest:622"] = {
  hash = "59cbe4",
  fullHash = "59cbe4",
  text = "Return to Corporal Kaleb. At the Rebel Camp, Corporal Kaleb waits for the pot Krazek repaired in Booty Bay. It has a second steam whistle and a chopper built into its base. Krazek has finished repairing the pot you brought him. He added another steam whistle and fitted a chopper to its base, sharp enough to cut through leg bones. He calls it a sure way to please the cook and expects its owner to be glad of the changes. Now it is ready to return to Corporal Kaleb at the Rebel Camp.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_622-54c778e0e28ea2a12d9b/1-0000.mp3", duration = 35.4481633, start = 0},
  },
}
P.transport["quest:623"] = {
  hash = "c55ecd",
  fullHash = "c55ecd",
  text = "Akiris by the Bundle. In Stranglethorn Vale, Bloads has a fresh bundle of akiris reeds bound for Theramore Isle. His contact, Privateer Groy, has a client eager for more, but Bloads cannot sail to Dustwallow Marsh for another week. While you are away, word reaches you from across the sea. Privateer Groy in Theramore Isle is pleased with the last shipment of akiris reeds, and a client wants another bundle at once. Privateer Bloads cannot sail to Dustwallow Marsh for another week. So he gives you the parcel to carry across the sea by hand.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_623-7134d918e6518a6ee056/1-0000.mp3", duration = 33.6195918, start = 0},
  },
}
P.transport["quest:624"] = {
  hash = "174960",
  fullHash = "174960",
  text = "Cortello's Riddle. A parchment bearing Cortello's Riddle turns up aboard Bloodsail Buccaneer vessels along the Wild Shore. Its verse sends you toward a clue beneath an ornate bridge. Bloodsail Buccaneers anchored off Stranglethorn Vale's southern coast carry scattered notes with a rhyme. Cortello's verse describes a finely worked bridge, worn by many travelers. It lies east of Deadwind and south of Redridge. Follow the directions out of the jungle and into the marshes, where something waits below.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_624-77f85ddd88e6439f9643/1-0000.mp3", duration = 31.5036735, start = 0},
  },
}
P.transport["quest:625"] = {
  hash = "f11874",
  fullHash = "f11874",
  text = "Cortello's Riddle. Travelers follow Cortello's second verse across the sea to Kalimdor. Its lines point treasure hunters toward a cave in southwestern Dustwallow Marsh. Cortello's second verse sends searchers toward Kalimdor. It describes Dustwallow Marsh, a gloomy wetland east of the Barrens. The riddle points to a clue in a cave in the southwest of the marsh.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_625-41eb07d3487548488658/1-0000.mp3", duration = 23.5363265, start = 0},
  },
}
P.transport["quest:626"] = {
  hash = "b361cd",
  fullHash = "b361cd",
  text = "Cortello's Riddle. In the Hinterlands, the final verses of Cortello's Riddle draw treasure hunters to the coast. A musty scroll points north from the southern tropics, and the trail ends beneath the waterfalls. The weathered verse turns the search north, away from the southern tropics and toward Lordaeron. There, amid the great turmoil of the embattled lands, the long chase reaches its end along the coast. The final hoard lies along the Hinterlands shore. Search underwater at the foot of the great falls.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_626-450709c01285140df783/1-0000.mp3", duration = 30.9028571, start = 0},
  },
}
P.transport["quest:627"] = {
  hash = "6d1e3b",
  fullHash = "6d1e3b",
  text = "Favor for Krazek. In Booty Bay, Krazek pauses his work on a broken crock pot to ask you for four loads of lesser bloodstone ore from the northern hills. He will return the cookware when you bring them. Krazek pauses his repair of the broken cookware in Booty Bay to offer a trade. He sends you far north to the Arathi Highlands. There, a cave in Drywhisker Gorge holds lesser bloodstone ore. The mineral is low grade, yet those who know its uses prize it. Krazek keeps working on the pot while you travel north. He expects four loads of bloodstone and promises payment if you bring back enough. The ore must be mined. If you lack the skill, you need someone who can extract it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_627-338c31b3e80a95f7bd8a/1-0000.mp3", duration = 42.7363265, start = 0},
  },
}
P.transport["quest:628"] = {
  hash = "3594df",
  fullHash = "3594df",
  text = "Excelsior. In Booty Bay, Drizzlik is ready for the last piece of the Excelsior boots. He needs an elder saltwater crocolisk skin for their outer layer. Drizzlik has finished the boots’ inner layer. For the outside, he uses the finest elder crocolisk skins. They are tougher and give the Excelsior designs and accents a better surface. Only an elder saltwater crocolisk skin fits his plan.\n\nFinding one is difficult. Elders come out only to guard other saltwater crocolisks. Drizzlik has also read that saltwater crocolisk numbers are dwindling, which worries him for his business.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_628-766aa7ad7326a5bfe6da/1-0000.mp3", duration = 37.9820408, start = 0},
  },
}
P.transport["quest:629"] = {
  hash = "e738fe",
  fullHash = "e738fe",
  text = "The Vile Reef. Beneath the Savage Coast, Kin'weelay seeks a shard from the sunken troll city. He hopes to carry Gri'lek's story to Orgrimmar, where the Darkspear can preserve it. Northwest of Grom'gol Base Camp, the Savage Coast hides an ancient troll city beneath the water. A violent earthquake shattered the land long ago and sank the city. Now called the Vile Reef, its flooded ruins are home to hostile murlocs who attack anyone who ventures near.\n\nOn the sea floor rests a massive stone tablet carved with the story of Gri'lek. He was a legendary troll hero, and the Darkspear still hold his memory sacred. The monument is too massive to carry from the depths, so Kin'weelay asks you to break off a shard. He plans to take the fragment to Orgrimmar and enshrine it in a sacred place. There, the Darkspear can keep Gri'lek's strength and honor in their memory.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_629-baa2a90dfb29dee724f9/1-0000.mp3", duration = 66.5077551, start = 0},
  },
}
P.transport["quest:630"] = {
  hash = "e53948",
  fullHash = "e53948",
  text = "Message in a Bottle. The message in a bottle brings you to an island off the Stranglethorn coast, where Princess Poobah waits in chains. King Mukla commands the island’s beasts and keeps her captive. To free her, you need the key to her shackle. On an island off the Stranglethorn coast, Princess Poobah waits in chains. The message in the bottle has brought you to her. King Mukla is a great Skymane gorilla who commands the creatures roaming the island. He keeps Poobah imprisoned, and she trusts you to face the ape and bring back her shackle key. Princess Poobah says her captor often prowls the island’s southeastern side. King Mukla is a formidable foe. Defeating him is the only way to claim the shackle key and free Poobah.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_630-43af9f4164134b87a04d/1-0000.mp3", duration = 45.2702041, start = 0},
  },
}
P.transport["quest:635"] = {
  hash = "7f4ef0",
  fullHash = "7f4ef0",
  text = "Crystal in the Mountains. In Arathi's northern mountains, a vision draws you toward a gleaming crystal. The Pendant of Myzrael pulses in your hand as a plea for help reaches you. The Pendant of Myzrael pulses in your hand, carrying a plea from someone in need of help. Then a vision shows a gleaming crystal thrusting from the ground in the mountains north of Arathi. You feel drawn there.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_635-100a24594d3f5280bf15/1-0000.mp3", duration = 25.4432653, start = 0},
  },
}
P.transport["quest:638"] = {
  hash = "ae3626",
  fullHash = "ae3626",
  text = "Trollbane. At Hammerfall, the Darkspear prepare for battles against Zul'Gurub's jungle trolls. Vol'jin has sent them to recover Trol'kalar from ruined Stromgarde, where the blade rested in human hands. After King Thoras Trollbane fell, Stromgarde became a ruin. Chieftain Vol'jin then ordered the Darkspear to spirit Trol'kalar away. The storied sword had long rested in human hands. Now the tribe seeks it for the battles ahead against Zul'Gurub's jungle trolls. Vol'jin sent Zengu, a seasoned hunter, to Hammerfall in the northeastern Arathi Highlands. From Stranglethorn Vale, Nimboya directs travelers to find Zengu and help secure the legendary sword.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_638-0492658a70db9ac47a46/1-0000.mp3", duration = 45.7404082, start = 0},
  },
}
P.transport["quest:639"] = {
  hash = "9fc26a",
  fullHash = "9fc26a",
  text = "Sigil of Strom. At Hammerfall, Zengu seeks the sigils that guard Trol'kalar, Lord Ignaeus Trollbane's sword. The Syndicate took the Sigil of Strom, and one of its agents in Stromgarde likely carries it. Long ago, Lord Ignaeus of Strom, called Trollbane, was the Arathorian Empire's ablest foe in its war against the trolls. He wielded Trol'kalar in battle. In the trolls' old tongue, its name means troll slayer. Now Trollbane's sons are weakened, and their stronghold lies in ruins. Several sigils guard Trol'kalar, and Stromgarde's survivors each took some. Zengu says they must all be recovered. The Syndicate seized the first, the Sigil of Strom. Zengu believes one of its agents in Stromgarde holds it. Bring the sigil back to Zengu at Hammerfall.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_639-b3dd9bcab2f12384262e/1-0000.mp3", duration = 52.9763265, start = 0},
  },
}
P.transport["quest:640"] = {
  hash = "497fba",
  fullHash = "497fba",
  text = "The Broken Sigil. Zengu sends you to recover sigils from the Stromgarde militia. Galen, son of Thoras Trollbane, broke the Sigil of Thoradin into eleven pieces, and you carry them to Tor'gan in Hammerfall. Three sigils guard Thoras Trollbane's tomb. You have taken the first from the Syndicate. The firmly entrenched Stromgarde militia holds the other two. Galen, Thoras' son, broke the Sigil of Thoradin into eleven pieces and scattered them among the defenders. Zengu asks you to gather the pieces from Stromgarde's defenders. Then carry them to Tor'gan, the troll shaman at Hammerfall. He can bind them into a whole sigil.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_640-a09553a9fd3f381837ff/1-0000.mp3", duration = 48.6661224, start = 0},
  },
}
P.transport["quest:641"] = {
  hash = "802730",
  fullHash = "802730",
  text = "Sigil of Thoradin. Tor'gan has restored the Sigil of Thoradin, and Zengu waits in Hammerfall for its return. The sigil can open the seal on Trollbane's tomb. Tor'gan's reconstruction has worked. The Sigil of Thoradin can open the seal on Trollbane's tomb, so he sends you back to Zengu in Hammerfall. Zengu has more for you to do.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_641-7dd267c578d561c819a8/1-0000.mp3", duration = 22.2563265, start = 0},
  },
}
P.transport["quest:642"] = {
  hash = "1a125a",
  fullHash = "1a125a",
  text = "The Princess Trapped. Across the Arathi Highlands, an iridescent shard carries Myzrael’s plea from deep underground. She calls herself a princess of the earth, imprisoned by giants, and asks travelers to strengthen a crystal cluster in Drywhisker Gorge. Strange shards lie scattered across the Arathi Highlands, humming with distant power. Near them, Myzrael’s voice rises from deep beneath the ground. She calls herself a princess of the earth, cast down and bound underground by ancient giants. Cut off from the lands above, she uses the crystals to carry her plea to anyone willing to listen. Myzrael directs you east to Drywhisker Gorge, where she asks you to strengthen your contact with her. Drywhisker kobolds infest the gorge, and she calls them allies of the giants who hold her captive. They carry Motes of Myzrael and guard a cluster of iridescent shards. Take the motes from the kobolds and use their energy on the formation. That will strengthen the crystal cluster and deepen your communication with the trapped princess.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_642-03e4611122e5ab60e667/1-0000.mp3", duration = 75.5461224, start = 0},
  },
}
P.transport["quest:643"] = {
  hash = "6dc383",
  fullHash = "6dc383",
  text = "Sigil of Arathor. Zengu sends you from Hammerfall to seek a sigil carried by human cavalry in the Arathi Highlands. Find their leader, Lieutenant Valorcall, and bring the sigil back. Zengu doubts the humans can claim Stromgarde, much less the whole Arathi Highlands. Yet their prince still sends the last of his horsemen through the countryside. Zengu cannot see why. He knows Lieutenant Valorcall leads those riders and carries one of the sigils. Find Valorcall and bring it back to Hammerfall.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_643-42dd084cfe5bd4fd5954/1-0000.mp3", duration = 32.4702041, start = 0},
  },
}
P.transport["quest:644"] = {
  hash = "8fc2c0",
  fullHash = "8fc2c0",
  text = "Sigil of Trollbane. In Hammerfall, Zengu sends you deep into Stromgarde for the Sigil of Trollbane. Prince Galen keeps the last sigil, which is needed to claim Trol'kalar. Prince Galen, son of Thoras Trollbane, keeps the last sigil in Stromgarde. He waits in a chapel deep in the districts held by the militia. Zengu warns that Galen is well guarded and a fine fighter. You are to kill the prince and carry the sigil back to Zengu in Hammerfall.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_644-ec17e913853a41b364a0/1-0000.mp3", duration = 29.2571429, start = 0},
  },
}
P.transport["quest:645"] = {
  hash = "ae4c0c",
  fullHash = "ae4c0c",
  text = "Trol'kalar. At Stromgarde, Zengu sends you after Trol'kalar, now that four sigils have joined as one. Zengu has seen the four sigils unite as the Sigil of Ignaeus. He believes their union can break the wardings on Trollbane's tomb. The tomb lies in the Sanctum behind Stromgarde's chapel, and Zengu sends you there to retrieve Trol'kalar. A fenced path to the right of the chapel entrance descends to the crypt.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_645-79f0c11653394a4c4d29/1-0000.mp3", duration = 26.644898, start = 0},
  },
}
P.transport["quest:646"] = {
  hash = "129544",
  fullHash = "129544",
  text = "Trol'kalar. At Trollbane's Tomb, Trol'kalar slips free of its stone sheath as the light fades. You carry the sword to Zengu in Hammerfall. At Trollbane's Tomb, you find Trol'kalar free of its stone sheath. You carry the sheathed sword to Zengu in Hammerfall, in the Arathi Highlands.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_646-62df86703765564a7a0b/1-0000.mp3", duration = 18.8342857, start = 0},
  },
}
P.transport["quest:648"] = {
  hash = "0e85d8",
  fullHash = "0e85d8",
  text = "Rescue OOX-17/TN!. At Steamwheedle Port, OOX-17/TN needs time and open ground for take-off. Oglethorpe's voice comes through the damaged robot, asking you to escort it there safely, then find him in Booty Bay. Oglethorpe's voice crackles through OOX-17/TN again. The robot has built-in cloaking, but Oglethorpe needs time to make it work again. It needs an open, safe place to begin its lengthy take-off. Oglethorpe has chosen Steamwheedle Port, and the journey there will give him time to restore the cloaking. You are asked to escort the robot safely. Once OOX-17/TN reaches Steamwheedle Port, find Oglethorpe Obnoticus in Booty Bay. He is a master inventor.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_648-a37e347b66cb1a0d419e/1-0000.mp3", duration = 41.4563265, start = 0},
  },
}
P.transport["quest:651"] = {
  hash = "cb7066",
  fullHash = "cb7066",
  text = "Stones of Binding. In Arathi, four Stones of Binding hold Myzrael beneath the ground. A voice from the iridescent shards says the strongest stone needs keys from the other three. Across Arathi, four stones keep Myzrael beneath the ground, a voice says. The Stone of Inner Binding is strongest, and keys from the Stones of West, East and Outer Binding can unlock it. Gather the Burning Key, the Cresting Key and the Thundering Key. Guardians watch the stones, though someone clever or lucky may find a way to banish them. Carry the keys to the Stone of Inner Binding.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_651-c914c8b3683627a402b4/1-0000.mp3", duration = 40.3591837, start = 0},
  },
}
P.transport["quest:652"] = {
  hash = "35ec3a",
  fullHash = "35ec3a",
  text = "Breaking the Keystone. The voice has more freedom now, though the Keystone still binds it. The Keystone lies among a ring of stones, and Fozruk holds the key the watchers call the Rod of Order. Opening the Stones of Binding eased the voice's confinement, but one lock still holds the Keystone. It lies among the circle of stones around you. Fozruk, a stone watcher and one of its captors, holds the key the watchers call the Rod of Order. Carry the rod to the Keystone and open the lock. The voice promises gratitude that will shake the earth to its roots. Geomantic energy fills the Keystone.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_652-21b333efa1390ee575c7/1-0000.mp3", duration = 44.4865306, start = 0},
  },
}
P.transport["quest:653"] = {
  hash = "0d0520",
  fullHash = "0d0520",
  text = "Myzrael's Allies. Myzrael is free, yet she must gather strength before she can face her captors. She calls you a noble ally and sends you to Gerrig Bonegrip in a shop in Ironforge's Forlorn Cavern, where he knows how to summon her. Myzrael is free, but not strong enough to face her captors. They would overpower her now and lock her away again. So she will gather strength in hiding. When she is ready, she means to face the giants and make them rue the day they held her. She calls you a noble ally and says she will need your help to summon her to the surface. Myzrael sends you to Gerrig Bonegrip, whose shop is in Ironforge's Forlorn Cavern. He knows how to summon her.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_653-324939a29bb706fea25c/1-0000.mp3", duration = 44.8, start = 0},
  },
}
P.transport["quest:654"] = {
  hash = "7f8dc3",
  fullHash = "7f8dc3",
  text = "Tanaris Field Sampling. In Tanaris, a field test begins as soon as the kit's power source is switched on. Your two hours of sampling start then. Chief Engineer Bilgewhizzle expected the kit to glow and vibrate once its power source was running. Now you have two hours to gather acceptable samples from eight basilisks, eight hyenas and eight scorpions in the Tanaris desert.\n\nIf the time runs out, all the data is lost. You will need to buy another power source from Bilgewhizzle, then return the kit to him in Gadgetzan before its power gives out. Bilgewhizzle offers no sympathy when a kit goes dead. The Gadgetzan Water Company’s profit is all that matters to him.\n\nHe will keep selling power sources until the company can afford to import water from the icy springs of Dun Morogh.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_654-e5ffc72df8f80bdc7da9/1-0000.mp3", duration = 48.8489796, start = 0},
  },
}
P.transport["quest:655"] = {
  hash = "d4e350",
  fullHash = "d4e350",
  text = "Hammerfall. At Hammerfall, the Horde holds a camp won at the cost of Warchief Orgrim Doomhammer's life. Gor'mul remembers the captives' escape and why the stronghold bears its name. In the Arathi Highlands, the Alliance once held orcs captive behind wood and steel. Young Thrall and Warchief Orgrim Doomhammer led an assault on the camp's enclosures and freed their kin. Many captives escaped as the defenses fell. Then a mounted lance struck Doomhammer from behind. He died where Hammerfall now stands. Gor'mul was among those who did not find freedom that day. In the battle's chaos and the earth's tremors, he watched the Warchief fall and lost the will to fight. His brethren fled, leaving him behind. For years, Gor'mul wandered the highlands in grief. The Horde has reclaimed the site as a fortified base, yet survivors still carry the memory of Doomhammer's death.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_655-3f45bccec935e2152a81/1-0000.mp3", duration = 59.5591837, start = 0},
  },
}
P.transport["quest:656"] = {
  hash = "3bb4bb",
  fullHash = "3bb4bb",
  text = "Summoning the Princess. At the Shards of Myzrael, you summon Myzrael and face her before she grows strong enough to challenge her captors. Theldurin the Lost wants her defeated and her Eldritch Shackles bound to the Shards. Theldurin fears Myzrael will grow strong enough to turn against her captors. Some say she can be controlled. But Theldurin asks why the giants would have chained her if that were true. You take the Scroll of Myzrael to the Shards, where you first spoke with her, and call her forth. Once Myzrael is defeated, you bind her Eldritch Shackles to the Shards and trap her again.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_656-bc2ae9c0441f92aca219/1-0000.mp3", duration = 41.6653061, start = 0},
  },
}
P.transport["quest:6568"] = {
  hash = "4299f4",
  fullHash = "4299f4",
  text = "The Testament of Rexxar. Rexxar sends you to the Western Plaguelands with a message for Myranda the Hag. He needs her skill with illusions to pass the Black Flight's defenses. Rexxar needs an illusion to pass the Black Flight's defenses. So he sends you to Myranda the Hag, a master illusionist who lives in the Western Plaguelands. The Lordaeron alliance drove her out. She has helped Rexxar's kind before, when a cause seemed worthy. Now you carry his message to her. A member of the Horde is a rare sight in these parts of Lordaeron, Myranda says. Then she asks what you have brought her.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6568-01a4a0478b93b6e3ae55/1-0000.mp3", duration = 38.7657143, start = 0},
  },
}
P.transport["quest:657"] = {
  hash = "1acbad",
  fullHash = "1acbad",
  text = "Hints of a New Plague?. Kinelory is bound for Go'Shek Farm, where Apothecary Jorell's deadly experiments continue. Quae has learned of them from a folder, but she is too hurt from a clash with orcs to go along. The folder shows that Jorell is conducting deadly experiments at Go'Shek Farm. Quae does not know what they mean for Hillsbrad. But Phin would not want them to continue. Some of Jorell's research has already reached Tarren Mill. Quae fought some orcs while you were away, and now she cannot help Kinelory. Kinelory plans to go to the farm and take the research Jorell has not yet sent to Tarren Mill. She needs your protection on the way.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_657-44fde465c3494abbe97b/1-0000.mp3", duration = 39.6538776, start = 0},
  },
}
P.transport["quest:658"] = {
  hash = "f6b520",
  fullHash = "f6b520",
  text = "Hints of a New Plague?. At Go'Shek Farm, Quae and Kin have watched for days, and Kin saw a courier leave a small house to the south. They suspect she carries notes to Tarren Mill, so Quae asks you to track her and bring back the documents. Quae expected Phin Odelic to send you. He worries too much, in Quae's view. Quae and Kin have watched the farm for days, and Kin recently saw a courier leave a small house to the south. Kin talks often, but Quae trusts Kin's senses in dangerous places. Quae asks if you are a skilled tracker. The courier may carry notes bound for Tarren Mill, and the documents could shed light on what is happening in Hillsbrad. Find the Forsaken Courier and bring her Sealed Folder to Quae near Go'Shek Farm.\n\nWhile you search, Kin spots an apothecary leaving that same house. Quae suspects the apothecary is up to no good, but needs proof before anyone acts rashly.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_658-3e4951ab5bd27285bc64/1-0000.mp3", duration = 56.3722449, start = 0},
  },
}
P.transport["quest:659"] = {
  hash = "27b8b0",
  fullHash = "27b8b0",
  text = "Hints of a New Plague?. In Hillsbrad, Phin Odelic's band searches for signs of trouble. Quae and Kinelory have been missing for days after traveling to Go'Shek Farm in the Arathi Highlands. Phin Odelic's cousin in Hillsbrad had to put down his dog, Stanley. The beast had mystically grown huge and attacked anyone who came near. Phin suspects the undead are behind these strange happenings. So his band searches for signs to prove it. Quae and Kinelory traveled to Go'Shek Farm in the Arathi Highlands. They have not checked in for days, and Phin fears for them. He asks you to find them near the farm.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_659-b7ed8a42940de6d749b3/1-0000.mp3", duration = 37.2244898, start = 0},
  },
}
P.transport["quest:660"] = {
  hash = "a77c2b",
  fullHash = "a77c2b",
  text = "Hints of a New Plague?. Kinelory is ready to go down to the farm, and asks you to come with her. She fears the undead may harm Hillsbrad while they wait. You are needed to see her safely back. Kinelory is ready to act after the earlier steps of the investigation. She asks you to go with her down to the farm, then return safely to Quae. The people of Hillsbrad need her protected.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_660-5088bbbc111785e5ea6f/1-0000.mp3", duration = 25.1036735, start = 0},
  },
}
P.transport["quest:661"] = {
  hash = "26d732",
  fullHash = "26d732",
  text = "Hints of a New Plague?. In Arathi, Quae and Kinelory remain near the farm while you carry news to Southshore. Quae has the farm items, and Kinelory has returned safely. Quae is pleased with how you cared for Kinelory. She says Kinelory is in better shape than after a night at the tavern. The items from the farm should help Phin Odelic understand what is happening in Arathi.\n\nSince the farm was attacked, Quae and Kinelory plan to stay there a little longer in case anyone retaliates. They ask you to return to Southshore and speak with Phin.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_661-7513a0acc0fe2f5f5f22/1-0000.mp3", duration = 37.6946939, start = 0},
  },
}
P.transport["quest:662"] = {
  hash = "9954d2",
  fullHash = "9954d2",
  text = "Deep Sea Salvage. After Land Ho!, First Mate Nilzlix asks you to recover the charts and logs from two wrecks before anyone leaves the cove. O'Breen brought three ships into the cove, certain treasure lay there. The Harbinger docked safely. But the Maiden's Folly and the Spirit of Silverpine reached the reef as the tides began to fall. Both struck a temple-like structure and sank fast. First Mate Nilzlix wants you to recover the logs and charts from both wrecks. He fears the information could reach prying eyes. If enemies found it, Fleet Master Seahorn would force the crew down the plank.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_662-30edd87861006edfd76c/1-0000.mp3", duration = 40.3330612, start = 0},
  },
}
P.transport["quest:663"] = {
  hash = "5b8bd5",
  fullHash = "5b8bd5",
  text = "Land Ho!. At Faldir's Cove, Lolo warns you that Captain O'Breen's brief stop may last far longer than planned. The Spirit of Silverpine and the Maiden's Folly are lost, and Lolo directs you to the captain. Lolo greets you at Faldir's Cove and tells you what has gone wrong. Captain O'Breen promised the crew only a few hours ashore to gather treasure before sailing back to Booty Bay. Lolo doubts they will be away so briefly.\n\nThe Spirit of Silverpine and the Maiden's Folly, two ships in the formation, now lie on the sea floor. If you mean to stay, Lolo says to speak with the captain.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_663-e7ab067b174c7c3f3c51/1-0000.mp3", duration = 44.2514286, start = 0},
  },
}
P.transport["quest:664"] = {
  hash = "c1838a",
  fullHash = "c1838a",
  text = "Drowned Sorrows. At Faldir's Cove, Captain Steelgut mourns the Maiden's Folly and asks you to kill the Daggerspine naga who slew the wreck's survivors. At Faldir's Cove, Captain Steelgut sits by the fire and wishes the sea had taken him too. His crew fought hard to save the Maiden's Folly, but water rushed in all at once and the ship sank. O'Breen reached shore safely, while the naga killed the other survivors. Steelgut wants ten Daggerspine raiders and three Daggerspine sorceresses dead.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_664-2232f73fcafaa372bc37/1-0000.mp3", duration = 33.3061224, start = 0},
  },
}
P.transport["quest:665"] = {
  hash = "016fd7",
  fullHash = "016fd7",
  text = "Sunken Treasure. Professor Phizzlethorpe and Doctor Draxlegauge now aid the Blackwater Raiders in their search for lost elven treasure. Before the search can begin, the professor needs your protection while he charges goggles for the dark sea. Professor Phizzlethorpe asks you to guard him as he prepares for a search beneath the dark sea. Doctor Draxlegauge built goggles to find the lost gems, but they need power from an enchanted stone in a cave a short way uphill. The cave is cursed, and those who draw near are ambushed. Defend the professor while he draws the stone’s energy into the goggles.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_665-0cd27d1b4121139810b8/1-0000.mp3", duration = 42.3183673, start = 0},
  },
}
P.transport["quest:666"] = {
  hash = "15462b",
  fullHash = "15462b",
  text = "Sunken Treasure. In Faldir's Cove, Doctor Draxlegauge lends you his goggles to find ten elven gems for Captain O'Breen. He expects them back when you finish. The elven gems have lain on the sea floor so long that thick stone has hardened around them. The Goggles of Gem Hunting hold the power to find them through those stony shells. Proud of the gnomish ingenuity behind the goggles, Doctor Draxlegauge lends them to you. The gems are for Captain O'Breen. Doctor Draxlegauge says scientific work keeps him on safe, dry land, though he could swim down himself. He expects you to return the goggles afterward. Captain O'Breen, he says, will have plenty of use for them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_666-1081ef26296ff04128f6/1-0000.mp3", duration = 42.2138776, start = 0},
  },
}
P.transport["quest:667"] = {
  hash = "b907b3",
  fullHash = "b907b3",
  text = "Death From Below. Aboard Shakes O'Breen's ship in the Arathi Highlands, the Daggerspine naga gather to strike. You stand with O'Breen, man the cannon, and help the crew sail back to Booty Bay. After the Sunken Treasure, Shakes O'Breen sees the Daggerspine naga gathering to attack. They are ruthless and will keep coming until O'Breen is dead. O'Breen puts the crew's safety ahead of their own and asks you to defend them. Without O'Breen's knowledge of the seas, the crew cannot reach Booty Bay. So you wait aboard with O'Breen for the naga to rise from the water.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_667-881c4b49a8ee98e193b9/1-0000.mp3", duration = 41.5085714, start = 0},
  },
}
P.transport["quest:668"] = {
  hash = "3ca53f",
  fullHash = "3ca53f",
  text = "Sunken Treasure. Doctor Draxlegauge sends you to Captain O'Breen, who waits at the bridge for the elven gems. After weeks among pirates, the doctor and the professor have learned that keeping pirate treasure is bad for their health. Doctor Draxlegauge is eager to bring Captain O'Breen the elven gems. The captain waits at the bridge and wants to see them for himself. After weeks among these pirates, the doctor and the professor have learned that keeping pirate treasure is bad for their health. So Draxlegauge gives you the gems to carry to O'Breen.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_668-778140328f708070c09f/1-0000.mp3", duration = 34.0897959, start = 0},
  },
}
P.transport["quest:669"] = {
  hash = "5ee154",
  fullHash = "5ee154",
  text = "Sunken Treasure. In Sunken Treasure, Shakes O'Breen is held back by the low tide and watchful creatures, so word must reach Booty Bay. Shakes O'Breen needs Fleet Master Seahorn in Booty Bay to hear of the find at once. The tide is too low for him to leave, and the creatures his crew disturbed watch every move. He asks you to tell Seahorn the treasure has been found and more is being brought up. You carry a sample elven gem as proof.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_669-c4fb6494a3b7e624e0d8/1-0000.mp3", duration = 27.5853061, start = 0},
  },
}
P.transport["quest:670"] = {
  hash = "f59fe0",
  fullHash = "f59fe0",
  text = "Sunken Treasure. Fleet Master Seahorn waits in Booty Bay with a letter for Shakes O'Breen off the Arathi coast. His ships cannot sail until they restock. Fleet Master Seahorn sees an adventurer in you. His ships must restock before they can leave Booty Bay. Heavy things are brewing here and abroad, he says, and he has a secret letter for Shakes O'Breen off the Arathi coast. Can he trust you to deliver it safely and keep it confidential?",
  ["1"] = {
    {file = "Audio/Transport/full_quest_670-35f61086d214a563f1d9/1-0000.mp3", duration = 31.5297959, start = 0},
  },
}
P.transport["quest:671"] = {
  hash = "4633de",
  fullHash = "4633de",
  text = "Foul Magics. In the Arathi Highlands, Tor'gan follows a demonic presence to Northfold Manor. From Hammerfall, he seeks help recovering bloodstone amulets from the summoners. Demonic energy stirs in the Arathi Highlands, and Tor'gan feels it from his post at Hammerfall. The pull draws the orc west toward Northfold Manor. There, he finds signs of demonic summoning, but the lingering corruption makes his blood boil and stirs an involuntary rage tied to the blood curse's history. He retreats before the influence overwhelms his senses, then seeks help from others. At Northfold Manor, Tor'gan found a bloodstone amulet on the ground. It showed that dark rituals were being performed there. Such charms help channel and steady demonic summonings, but the amulet he recovered had lost its magic. It held too little power for a thorough study. Tor'gan asks Horde travelers to retrieve ten intact amulets from the manor's practitioners, so he can examine the rituals and learn what entities were summoned.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_671-b52b58e82f7ab9eb6c85/1-0000.mp3", duration = 74.0310204, start = 0},
  },
}
P.transport["quest:672"] = {
  hash = "0d8250",
  fullHash = "0d8250",
  text = "Raising Spirits. Tor'gan seeks a way to lift Gor'mul's spirits at Hammerfall in the Arathi Highlands. Tales of Orgrimmar and Warchief Thrall have brought no comfort, so Tor'gan turns to the Horde's newly rediscovered shamanic traditions. At Hammerfall in the Arathi Highlands, Gor'mul has fallen into deep melancholy. His companions have told him of Kalimdor, the mighty city of Orgrimmar, and Warchief Thrall's leadership. Yet none of these tales has eased his gloom or given him hope. Tor'gan turns to the Horde's revived spiritual traditions to help Gor'mul. He gathers the eyes of highland raptors roaming Arathi and makes an amulet blessed with their spirits. Through this rite, he hopes the predators' vital force will awaken Gor'mul's will to live.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_672-eef4960648f903ed0400/1-0000.mp3", duration = 55.7191837, start = 0},
  },
}
P.transport["quest:673"] = {
  hash = "13a8c2",
  fullHash = "13a8c2",
  text = "Foul Magics. In Hammerfall, Tor'gan fears a warlock in Stromgarde is calling demons with an arcane relic. Your first work for him has led to a hunt for the warlock and the relic. Tor'gan is certain a warlock within Stromgarde's walls uses an arcane relic to call up terrible demons in great numbers. The burning in his blood grows by the day. So he sends you to find and kill the warlock, then bring back the magical object on the warlock's body. He means to destroy it before its power can taint the land. The warlock is Marez Cowl, and the object is a Befouled Bloodstone Orb.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_673-4fdfefe58407650bd591/1-0000.mp3", duration = 42.0571429, start = 0},
  },
}
P.transport["quest:674"] = {
  hash = "6655c7",
  fullHash = "6655c7",
  text = "Raising Spirits. A Horde emissary hopes Raising Spirits will help Gor'mul find his fighting spirit again. The Raptor Talon Amulet is meant to rekindle it, but Gor'mul remains bitter and doubts any trinket can restore the Horde's former glory. An emissary brings Gor'mul a Raptor Talon Amulet, hoping its power will reach him. The talisman channels the wild strength and ferocity of raptors. It is meant to rekindle the flame that once burned fiercely within the orc warrior.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_674-2f6ec0a7d5c7e7fd51ee/1-0000.mp3", duration = 35.3697959, start = 0},
  },
}
P.transport["quest:675"] = {
  hash = "eb9d00",
  fullHash = "eb9d00",
  text = "Raising Spirits. Tor'gan hopes ancestral magic can restore Gor'mul's pride and will to live. The shaman seeks to lift an old orc veteran from despair. Gor'mul grieves that he survived when his fallen Warchief did not. Many orc veterans bear the weight of past wars, but Gor'mul believes fate denied him an honorable death beside his leader. Tor'gan, a shaman, hopes to ease that sorrow by recalling his people's spiritual strength. He prepares an enchanted amulet and trusts ancestral power to rekindle the old warrior's pride.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_675-acc174c29eb23c520b8a/1-0000.mp3", duration = 36.3363265, start = 0},
  },
}
P.transport["quest:676"] = {
  hash = "02e496",
  fullHash = "02e496",
  text = "The Hammer May Fall. Tallow sends fighters from Tarren Mill through the mountains to relieve Hammerfall in the Arathi Highlands. Before reporting to Drum Fel, you prove your strength against Boulderfist ogres near the ruins of Stromgarde. In Tarren Mill, Tallow has little patience for fighters who have not proved themselves. While recruits stand idle, allies face attack far away. He sends capable fighters east through Thoradin's Wall into the Arathi Highlands, where Hammerfall is besieged from several sides. First, they must prove their worth against a strong foe. Only then will Tallow send them to the outpost. Tallow demands a show of strength at the ogre mound northeast of the ruins of Stromgarde. Boulderfist ogres and their enforcers hold much of Arathi and threaten travelers on the highland trails. Fighting them thins the hostile forces flanking the road. It also proves you can face the danger before reaching Hammerfall.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_676-2f18b4d30204a9ee8ee4/1-0000.mp3", duration = 60.6302041, start = 0},
  },
}
P.transport["quest:677"] = {
  hash = "2fb61d",
  fullHash = "2fb61d",
  text = "Call to Arms. Drum Fel calls the Horde to strike from Hammerfall in the Arathi Highlands. The Witherbark have joined the Boulderfist ogres, and the Horde means to hold its foothold there. At Hammerfall, Drum Fel rallies the Horde from its fortified outpost in the Arathi Highlands. Old human ruins and hostile powers surround the settlement. The Witherbark forest trolls and Boulderfist ogres have made a pact, putting the Horde's foothold at risk. Drum Fel calls on champions to strike first and keep their enemies from deciding the struggle's course. South of Hammerfall, the Horde's first strikes reach Witherbark territory. The forest trolls have rejected diplomacy and joined the Boulderfist ogres in trying to drive the Horde from the highlands. Hammerfall targets their axe throwers, headhunters and witch doctors to weaken their leaders and show that the Horde intends to stay.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_677-53b1e50331b6f456f7a9/1-0000.mp3", duration = 56.32, start = 0},
  },
}
P.transport["quest:678"] = {
  hash = "283987",
  fullHash = "283987",
  text = "Call to Arms. At Hammerfall, Drum Fel sends proven warriors against the Boulderfist ogres. Their attacks threaten the Horde's foothold in Arathi. At Hammerfall, Drum Fel calls on travelers who have aided the outpost to face a real threat. Boulderfist ogres have harassed the Horde expedition and tested its defenders. Fel sends warriors against these foes, not minor skirmishers. He expects them to return alive or with honor, and promises praise for their tenacity in battle. Southwest of Hammerfall, the Boulderfist clan has dug in near the dwarven bridge between Arathi and the Wetlands. Brutes fight alongside cunning magi, bringing crushing strength and deadly magic. Their aggression threatens Horde supply lines and control of the region. Drum Fel orders warriors to defeat ten Boulderfist brutes and four magi. Their defeat will weaken the clan and show that Hammerfall will not yield ground or tolerate rivals in Arathi.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_678-5f4aea7758f549d397f3/1-0000.mp3", duration = 69.2506122, start = 0},
  },
}
P.transport["quest:679"] = {
  hash = "eaf3f4",
  fullHash = "eaf3f4",
  text = "Call to Arms. At Hammerfall, Drum Fel sends you after the Boulderfist leaders in Stromgarde. After your earlier work, he says it is time to strike the head from the beast. Drum Fel says you are ready to help deliver one last great blow. The Boulderfist leaders have made their lair in Stromgarde’s ruins, which he calls a symbol of human frailty. He sends you to hunt down the lords and the shaman who serve them. They lead attacks meant to drive the Horde from these lands.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_679-0dc724ade25b52fd7d6a/1-0000.mp3", duration = 30.4587755, start = 0},
  },
}
P.transport["quest:680"] = {
  hash = "7bdfc3",
  fullHash = "7bdfc3",
  text = "The Real Threat. Korin Fel asks you to end the attacks on Hammerfall by slaying Or'Kalar and bringing her his head. Korin Fel says you serve her husband well, though he does not know why Hammerfall is under attack. Or'Kalar serves Mug'thol in Stromgarde and seeks her husband's death. Years ago, her husband defeated the ogre. Now Korin's auguries warn that Or'Kalar has set a trap for him. Korin has hidden the signs of Or'Kalar's presence from her husband. She fears he would rush off foolishly if he knew where the ogre was, so she asks you to help instead. Or'Kalar is near the Tower of Arathor. Korin expects his death to end the attacks on Hammerfall.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_680-e219b70cfd1633f97157/1-0000.mp3", duration = 44.2514286, start = 0},
  },
}
P.transport["quest:682"] = {
  hash = "52d7d2",
  fullHash = "52d7d2",
  text = "Stromgarde Badges. In Stromgarde, the Syndicate pays for militia badges taken from the fallen. At Refuge Pointe, Captain Nials wants them brought back. The Syndicate fights a contingent of militia in Stromgarde. Its leaders offer gold for every badge taken from a slain militiaman, hoping to turn their followers against the better-trained soldiers. Captain Nials calls the Syndicate cutthroats and refuses to let them keep trophies from the brave fallen. You enter the part of Stromgarde they hold and bring the badges back to Refuge Pointe. Nials wants them to learn they cannot profit from the dead.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_682-21e2fb980ee869b87032/1-0000.mp3", duration = 40.3591837, start = 0},
  },
}
P.transport["quest:684"] = {
  hash = "55de56",
  fullHash = "55de56",
  text = "WANTED: Marez Cowl. At Stromgarde, Marez Cowl advises Syndicate leaders and traffics with demons. Her influence threatens Alliance forces in the Arathi Highlands. At Refuge Pointe, Alliance commanders offer a bounty on a high-ranking Syndicate leader. Marez Cowl advises the Syndicate and directs its work in Stromgarde’s ruins as a field operative. The bounty aims to break the group’s local command. Marez Cowl is a warlock among the Syndicate’s brigands and dispossessed nobles. She deals openly with demonic powers to enforce her will and defend Syndicate territory. To reach her lair in Stromgarde, you must face armed criminals and the demons she commands.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_684-e030afcedc6112aeefef/1-0000.mp3", duration = 48.6922449, start = 0},
  },
}
P.transport["quest:685"] = {
  hash = "05368a",
  fullHash = "05368a",
  text = "WANTED: Otto and Falconcrest. In the Arathi Highlands, the Stromgarde Militia has marked Lord Falconcrest and Otto for death. Falconcrest leads the local Syndicate forces, and Otto guards him with deadly skill. Their deaths would weaken the Syndicate's hold in the region. Proof must reach Captain Nials at Refuge Pointe. From Refuge Pointe, Stromgarde's defenders seek to break the Syndicate's hold over their ancestral lands. The militia has placed a bounty on Lord Falconcrest and Otto, his bodyguard. Bring both targets' heads to Captain Nials to claim the reward. Lord Falconcrest directs the Syndicate's push into the Arathi Highlands. His death would disrupt the criminal network's work in the region. Otto is a brutally effective bodyguard. His blades have killed dozens of Stromgarde's remaining militia soldiers.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_685-64b3bf4ab7f376f9c8a7/1-0000.mp3", duration = 52.3755102, start = 0},
  },
}
P.transport["quest:687"] = {
  hash = "134730",
  fullHash = "134730",
  text = "Theldurin the Lost. In the Badlands, the Twilight's Hammer hunts for Theldurin the Lost and the scroll of Myzrael he took when he fled. Theldurin once followed the Twilight's Hammer. Then his mind slipped, and he turned from its teachings. He fled with the scroll of Myzrael, and the order could not catch him. Word has reached the Twilight's Hammer that Theldurin hides in the Badlands, raving and mad. The order needs the scroll for the Lady's return. First, you must find the man who took it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_687-fe797161b16fc23ce4c6/1-0000.mp3", duration = 30.8767347, start = 0},
  },
}
P.transport["quest:688"] = {
  hash = "44f56a",
  fullHash = "44f56a",
  text = "Myzrael's Allies. Through the keystone, Myzrael declares herself free, though still hidden from her captors. She sends you to Zaruk in Hammerfall, who knows how to summon her. Myzrael declares that she is free through the keystone. She must gather her strength out of sight. Her captors would overpower and imprison her again if they faced her now. In time, she vows to confront the giants who held her and make them regret keeping her. Myzrael calls you a noble ally and says she will need your aid again in time. When ready, she will have you summon her to the surface. For now, she sends you to Zaruk in Hammerfall, who knows how it can be done.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_688-6d8461a6ed1bd2a601ef/1-0000.mp3", duration = 39.9673469, start = 0},
  },
}
P.transport["quest:690"] = {
  hash = "c0406e",
  fullHash = "c0406e",
  text = "Malin's Request. In Stormwind, Archmage Malin asks for help recovering relics from fallen Stromgarde. He sends seasoned Alliance adventurers north to Refuge Pointe in the Arathi Highlands, where an expedition seeks the magical relics left behind when Stromgarde fell. Archmage Malin serves in Stormwind's Wizard's Sanctum and acts for his former mentor, Archmage Trelane. When Stromgarde fell into chaos, Trelane made a desperate stand at the Tower of Arathor. As hostile forces took the city, he had to abandon his post and leave powerful enchanted possessions behind. Malin fears those relics may fall into hostile hands. He sends capable mercenaries north to strengthen his agents in the field and reclaim Trelane's lost belongings. Refuge Pointe lies on the road to Trelane's relics, in the central Arathi Highlands. The outpost is a hard-pressed refuge for Stromgarde loyalists, and Malin's chief contact there is the dwarf Skuerto. Syndicate outlaws, Witherbark trolls, and Boulderfist ogres press the outpost from every side. When you arrive, Skuerto and the garrison are stretched too thin to welcome you warmly without immediate help.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_690-0dc4382b5d9e93bf053d/1-0000.mp3", duration = 75.8073469, start = 0},
  },
}
P.transport["quest:691"] = {
  hash = "1917bf",
  fullHash = "1917bf",
  text = "Worth Its Weight in Gold. At Refuge Pointe, Apprentice Kryten needs reagents for Archmage Malin. He asks you to gather tusks, medicine pouches and a shadow hunter's knife from the Witherbark trolls of southeastern Arathi. Archmage Malin sent Kryten and Skuerto to Arathi for reagents. Kryten was unsure how to gather them until you arrived. He needs ten Witherbark tusks, four medicine pouches and one shadow hunter knife. The Witherbark trolls live in southeastern Arathi. Kryten's research says every Witherbark troll should have tusks. The witch doctors carry medicine pouches. The knife belongs to the mightiest shadow hunters, who receive it after completing their rites of passage. Only battle will show which one carries it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_691-4949c77000f1fdbe9a23/1-0000.mp3", duration = 46.4195918, start = 0},
  },
}
P.transport["quest:692"] = {
  hash = "7481c2",
  fullHash = "7481c2",
  text = "The Lost Fragments. Behind Theldurin, furious elementals fight over scraps of the Scroll of Myzrael. You gather the torn pieces while he fears what its magic might do. Theldurin the Lost fears the Scroll of Myzrael could draw Myzrael up to the surface. Then he considers another danger. She may already be free, or gathering strength to strike. If so, the scroll may be what you need to bind her again. Furious elementals took the scroll and tore it apart. Now they fight over its scraps in the hills behind Theldurin. Bring back three pieces: one torn, one crumpled and one singed. Theldurin hopes to mend them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_692-c261195e643faf0c9924/1-0000.mp3", duration = 48.3265306, start = 0},
  },
}
P.transport["quest:693"] = {
  hash = "de8aa4",
  fullHash = "de8aa4",
  text = "Wand over Fist. At Refuge Pointe, Skuerto has found where Trelane's first item went. Kor'gresh holds Trelane's Wand of Invocation in Boulderfist Hall, and Skuerto wants it back. After your work for Apprentice Kryten, Skuerto has traced Trelane's first item to Kor'gresh. The ogre holds the wand in Boulderfist Hall and uses blasts of ice to keep his kin in line. Skuerto fears Kor'gresh is close to discovering all its powers. Boulderfist Hall lies south of Refuge Pointe, then east of Thandol Span.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_693-d3875f3d5352a8b605c0/1-0000.mp3", duration = 28.3428571, start = 0},
  },
}
P.transport["quest:694"] = {
  hash = "828dab",
  fullHash = "828dab",
  text = "Trelane's Defenses. Ogres now ring the Tower of Arathor, and Skuerto needs its defenses working. An azure agate from the Boulderfist shaman can become a key after Apprentice Kryten at Refuge Pointe enchants it. In Stromgarde, ogres ring the Tower of Arathor. Skuerto says you need to activate its defenses to have a chance against them. Only then can you reach the items alive. The Boulderfist shaman took certain gems from the tower and have grown fond of them. Skuerto says they will not keep the gems for long. Bring an azure agate to Apprentice Kryten at Refuge Pointe. Kryten knows the spell that will enchant it to work as a key.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_694-4a250eec8be7a30c4275/1-0000.mp3", duration = 45.7142857, start = 0},
  },
}
P.transport["quest:695"] = {
  hash = "16fef7",
  fullHash = "16fef7",
  text = "An Apprentice's Enchantment. At the camp, Apprentice Kryten enchants the agate you brought from the Boulderfist shaman. It can wake the tower's defenses, and Kryten sends you to Skuerto before you leave. Apprentice Kryten gives you the enchanted gem and explains its power. Touch it to a pedestal at the tower's foot, and its defenses will wake. When you are ready to enter and search for the rest of Trelane's items, use the gem. Kryten will wait for you at the camp. Before you go, speak with Skuerto, who can answer any other questions.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_695-b1e0c36dde0aaebe6b6c/1-0000.mp3", duration = 39.6277551, start = 0},
  },
}
P.transport["quest:696"] = {
  hash = "844f2c",
  fullHash = "844f2c",
  text = "Attack on the Tower. At Refuge Pointe, Skuerto sends you to search the ogre-held tower for three items tied to Trelane. The phylactery, orb and ember agate should be in chests inside, and Skuerto says Malin will be pleased when you return with them. After Kryten enchants the gem, Skuerto sends you to find Trelane's phylactery, orb and ember agate. The three items should be in chests inside the tower, ready for you to open. But the ogres are dangerous. The tower's defenses will not deal with them, and the ogres will hurt you if they catch you stealing.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_696-d8e45f39f0e3375330df/1-0000.mp3", duration = 41.1428571, start = 0},
  },
}
P.transport["quest:697"] = {
  hash = "dc8f23",
  fullHash = "dc8f23",
  text = "Malin's Request. In Stormwind, Skuerto's letter carries news from Arathi to Archmage Malin. You are sent to the Mage Quarter with word that Kryten and Skuerto will soon be home. After your work in Arathi, Skuerto gives you a sealed letter for Archmage Malin in Stormwind's Mage Quarter. It says Kryten and Skuerto will be home soon. Skuerto trusts Malin will repay you well for helping them and wishes you a safe journey.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_697-f6a4fdeb64f593fd9469/1-0000.mp3", duration = 28.1338776, start = 0},
  },
}
P.transport["quest:698"] = {
  hash = "99141e",
  fullHash = "99141e",
  text = "Lack of Surplus. Dar needs more sawtooth meat for the eastern beach outpost. Tok'Kar has little time between guard shifts and cooking for the soldiers, so Dar asks you to bring some. Dar is gathering supplies for the outpost on the eastern beach. Tok'Kar guards the post and cooks for its soldiers, leaving little time for other work. The soldiers enjoy sawtooth meat when they can get it. Dar has not had time to send another shipment. Older sawtooths taste better, Dar says, so leave the young ones alone. They need a year or two to reach full size. Bring eight unprepared sawtooth flanks to Tok'Kar in the Swamp of Sorrows.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_698-8b1ea7091d88b9b6ee0c/1-0000.mp3", duration = 39.3926531, start = 0},
  },
}
P.transport["quest:699"] = {
  hash = "995602",
  fullHash = "995602",
  text = "Lack of Surplus. Along the coast, Tok'Kar and his soldiers watch for murlocs threatening Stonard. When the force grows too large, they send warning; for now, Tok'Kar asks you to bring six sawtooth snapper claws. Tok'Kar and the soldiers guard Stonard from murlocs along the coast. When the force is too large to face, they warn the town. Tok'Kar has little time to rest, so he asks you to help. Properly prepared, sawtooth snapper claws make fine weapons. Bring him six, and he offers one of the outpost's weapons in return, grateful for the meat and company.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_699-86772702eee08076389c/1-0000.mp3", duration = 35.6310204, start = 0},
  },
}
P.transport["quest:7003"] = {
  hash = "4d7723",
  fullHash = "4d7723",
  text = "Zapped Giants. On Feralas's Forgotten Coast, Zorbin Fandazzle tests a shrinking ray on the giants near the docks. He built it from a gnomish design and improved it with goblin know-how, then gives you the Ultra-Shrinker to try on Feralas's giants. Zorbin Fandazzle needs the giants of Feralas dealt with so he can stay and keep his business. His answer is a shrinking ray based on a gnomish design, improved with what he calls superior goblin advances. He would rather you test it than risk his own life.\n\nUse the Ultra-Shrinker on Cliff Giants, Deep Striders, Wave Striders, Shore Striders or Land Walkers. Gather the miniaturization residue left behind when they shrink, then bring it back to the docks. Zorbin calls miniaturization residue valuable in engineering. It helps keep a zapper from exploding on its user. Then he adds that this applies only to other zappers, not the one in your hands.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7003-413ff0f1fc2904ac9206/1-0000.mp3", duration = 57.8089796, start = 0},
  },
}
P.transport["quest:701"] = {
  hash = "20a765",
  fullHash = "20a765",
  text = "Guile of the Raptor. Tor'gan seeks to awaken Gor'mul's dormant warrior spirit through the guile of the raptor. He gathers Highland Fleshstalker hearts to make an enchanted charm and restore Gor'mul's fighting resolve. Tor'gan wants to draw Gor'mul out of his listlessness and restore the warrior spirit that lies dormant. He turns to primal magic instead of persuasion, hoping a charm filled with wild predators' essence will stir Gor'mul to action. Through the charm, he seeks to renew Gor'mul's martial resolve and show him the strength of this power. Tor'gan needs Highland Fleshstalker hearts to call on the instincts of a cunning hunter. In shamanic and primal traditions, a predator's heart carries its ferocity and guile. Tor'gan uses these trophies to make a physical token and weave a spell. He hopes they will give Gor'mul a predator's cunning and help him rediscover his calling.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_701-9ed8d4fe7ac3f84260ca/1-0000.mp3", duration = 52.8195918, start = 0},
  },
}
P.transport["quest:702"] = {
  hash = "15435c",
  fullHash = "15435c",
  text = "Guile of the Raptor. At Hammerfall, Tor'gan sends you to Gor'mul with an orb to rouse the warrior's spirit. Its energy bears the raptor's essence and may give Gor'mul fresh purpose. Tor'gan gives you an orb meant to fill Gor'mul with the raptor's essence. He hopes it will rouse the warrior's spirit and set him on a fresh course in life.\n\nOnce Gor'mul is himself again, Tor'gan plans to explain the Horde's present state. He hopes to win the help of a great warrior in its unceasing battles. Gor'mul greets your return with bitterness. He says all he wants is more of Tor'gan's pity, then mocks you with talk of brightly colored string.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_702-786af1dbd358c5f07c76/1-0000.mp3", duration = 42.3967347, start = 0},
  },
}
P.transport["quest:703"] = {
  hash = "109edf",
  fullHash = "109edf",
  text = "Barbecued Buzzard Wings. Rigglefuzz has every ingredient for his barbecued buzzard wings except the wings themselves. Rigglefuzz takes pride in his barbecued buzzard wings. He coats the tangy meat in rich sauce, and its aroma carries to hungry folk nearby. He has all the ingredients for a batch but the wings. Bring him four buzzard wings, and he may share the recipe.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_703-8ad34195e78c36221f4f/1-0000.mp3", duration = 22.9877551, start = 0},
  },
}
P.transport["quest:705"] = {
  hash = "78b42a",
  fullHash = "78b42a",
  text = "Pearl Diving. In the Badlands, Rigglefuzz is running low on powder for his flash bombs. He sends you to the Vile Reef in Stranglethorn to gather more. Rigglefuzz admits the Badlands frighten him. A short little goblin, he faces predators and scavengers all around. He knows how to make flash bombs, and uses them to drive the wildlife away. Now he is running low on crushed blue pearl powder. Clams at the Vile Reef in Stranglethorn hold blue pearls. Rigglefuzz jokes that you had better wear good boots, then waits in the Badlands for nine pearls. He promises to make your effort worthwhile.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_705-3bf891c9c983b25230df/1-0000.mp3", duration = 37.5640816, start = 0},
  },
}
P.transport["quest:706"] = {
  hash = "3d1825",
  fullHash = "3d1825",
  text = "Fiery Blaze Enchantments. A rare black drake whelp's still-beating heart is needed for Fiery Blaze Enchantments in the Badlands. Sigrun Ironhew waits for word from Ironforge, and the whelps of Lethlor Ravine may supply what she needs. Sigrun Ironhew learned to kindle fire on weapons while apprenticed to Feranor Steeltoe. Feranor was last heard of among the smiths of a hunting party in Lordaeron. Sigrun waits in the Badlands for word from Ironforge. She has little else to do. Sigrun shares little about the process. It calls for blood from the still-beating heart of a rare black drake whelp. Bring her a heart from a whelp in Lethlor Ravine, and she will show you the skill. The Scalding Whelps and Scorched Guardians there yield the hearts.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_706-4283f3a9fe35e0b66839/1-0000.mp3", duration = 49.3714286, start = 0},
  },
}
P.transport["quest:708"] = {
  hash = "85affa",
  fullHash = "85affa",
  text = "The Black Box. A giant condor in the Badlands swallowed a black box marked for Ironforge. After ages in the condor's stomach, acid had pitted the metal. A symbol marks the underside above the words Engine #19 - Ironforge Siege Brigade. You carry the box to Pilot Longbeard in Ironforge's Hall of Arms.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_708-25ff9c856037ff2d4b78/1-0000.mp3", duration = 19.2783673, start = 0},
  },
}
P.transport["quest:710"] = {
  hash = "0dbaa2",
  fullHash = "0dbaa2",
  text = "Study of the Elements: Rock. In the Badlands, Lotwil Veriatus needs stone shards to test his work on elemental shackles. Lesser rock elementals roam the hills just west of him. In the Badlands, Lotwil Veriatus is making shackles of elemental binding. When finished, they will let mages summon stronger elementals for greater uses. To test his offensive spells and a few pieced-together gizmos, he needs ten small stone shards. Lesser rock elementals roam the hills immediately west.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_710-2ed602cbae603b07fe6b/1-0000.mp3", duration = 30.3804082, start = 0},
  },
}
P.transport["quest:711"] = {
  hash = "dd7c08",
  fullHash = "dd7c08",
  text = "Study of the Elements: Rock. Lotwil Veriatus is ready to test larger pieces after the small shards behaved as he expected. He needs three large stone slabs from rock elementals. Lotwil Veriatus needs sturdier pieces for his next tests. Rock elementals have larger bodies, so their remains may yield slabs big enough.\n\nHe points you farther west or southeast along the mountain edges to gather three large stone slabs. For now, Lotwil needs time to test the smaller pieces you brought. Lotwil's spells acted on the smaller pieces as he predicted. If the next experiment goes as he expects, the elementals he controls will outshine anything he has summoned before.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_711-8351935cd4fd478097e2/1-0000.mp3", duration = 42.6057143, start = 0},
  },
}
P.transport["quest:712"] = {
  hash = "7a4bb7",
  fullHash = "7a4bb7",
  text = "Study of the Elements: Rock. In the Badlands, Lotwil Veriatus needs bracers from greater rock elementals to judge his shackles. Lotwil Veriatus needs one last part from the Badlands' elementals, after the stone slabs. Bracers of rock binding from greater rock elementals will help him judge the shackles under construction.\n\nHis scrying found a group southwest, near some ogres, if memory serves. He asks for five bracers so there will be spares, since Servo often misplaces reagents and research.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_712-902d5e6c2cd17064b236/1-0000.mp3", duration = 29.1526531, start = 0},
  },
}
P.transport["quest:713"] = {
  hash = "726df2",
  fullHash = "726df2",
  text = "Coolant Heads Prevail. Lotwil Veriatus needs Frost Oil for the shackles holding his summoned friend. Bro'kin, Lotwil's goblin friend in Alterac, can teach you to make it. Lotwil Veriatus says Frost Oil keeps engines and gears from overheating. He calls it an unmatched lubricant. It also helps magical items hold their enchantments. The oil could strengthen Lotwil's shackles enough to stop his summoned friend from killing everyone. Bro'kin, Lotwil's goblin friend, can teach you to make Frost Oil. He sells from a spot on the old city's wall in the Ruins of Alterac.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_713-a6804f23f2bf36a6941d/1-0000.mp3", duration = 34.9518367, start = 0},
  },
}
P.transport["quest:714"] = {
  hash = "61545a",
  fullHash = "61545a",
  text = "Gyro... What?. In the Badlands, Lotwil Veriatus is still at work on his contraption. You have brought him the Frost Oil from Coolant Heads Prevail, but one small part is missing: a gyrochronatom. Lotwil Veriatus is so caught up in his work that he praises you for doing the job beyond all standards. Then he says you may apply for work if you meet him in Kharanos.\n\nA hurried scramble follows as Lotwil tries to catch hold of something. Then he asks for a gyrochronatom. The part is small but crucial, and with it the project should be ready to complete.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_714-483734bf3508161ef001/1-0000.mp3", duration = 35.5004082, start = 0},
  },
}
P.transport["quest:716"] = {
  hash = "60e68d",
  fullHash = "60e68d",
  text = "Stone Is Better than Cloth. In the Badlands, Lucien Tosselwrench has a gift for you, though his work is not finished. The extra stones you gathered are ready, but he still needs patterned bronze bracers. After your work for Lotwil on his third Study of the Elements: Rock request, Lucien Tosselwrench admits Lotwil can be cheap. He means to make it up to you with fine enchanted bracers fashioned from the extra stones you gathered. They may help guard you against the coming atrocity of Lotwil's newest invention. To finish the bracers, Lucien needs patterned bronze bracers of the kind a blacksmith makes. He warns you not to wait long. No one knows what happens next.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_716-d4b422609f4245151eba/1-0000.mp3", duration = 40.96, start = 0},
  },
}
P.transport["quest:7162"] = {
  hash = "99f323",
  fullHash = "99f323",
  text = "Proving Grounds. In Alterac, recruits face a trial before they may join the Stormpike Guard. Lieutenant Haggerdin sends them into Icewing Caverns for a planted battle standard. Success earns an official Stormpike Insignia and opens the way through the expedition’s ranks. The Stormpike Guard fights the Frostwolf Clan in Alterac Valley. Lieutenant Haggerdin directs Alliance forces from their encampment in the Alterac Mountains. Before recruits reach the battlefield, he tests their skill and nerve in Icewing Caverns southwest of Dun Baldar. Deep in Icewing Caverns, a Stormpike banner waits among the frozen tunnels. Frost harpies nest in the icy recesses and attack unwary trespassers. A recruit who brings the banner back intact has crossed dangerous ground, faced its predators, and kept discipline under pressure. Return from the caverns with the standard, and you earn a Stormpike initiate’s insignia and a place in the expeditionary force. Haggerdin says the insignia can improve as you earn greater honor on the battlefield. The Eye of Command is one distant aim.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7162-4cc7bc8dd6e175355af7/1-0000.mp3", duration = 78.2628571, start = 0},
  },
}
P.transport["quest:717"] = {
  hash = "4f928c",
  fullHash = "4f928c",
  text = "Tremors of the Earth. At Lethlor, Garek fears the drakes may break free. Black dragons now dwell there, and ogres have taken the Sign of the Earth. So he sends you to free the drakes and kill them. At Lethlor, Garek fears Blacklash and Hematus may escape their prison. Black dragons now dwell there, and ogres have taken the Sign of the Earth. Garek sees no safer course. The drakes must die. Three runestones hold the drakes, and the Sign of the Earth is needed to release them. You use the Sign at the Pillars of Amethyst, Opal and Diamond, then place the runestones in the Seal of the Earth. Blacklash and Hematus are freed, and you slay them. Garek asks you to bring back Blacklash's Bindings, the Chains of Hematus and the Sign of the Earth.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_717-161d6c680084eeae5873/1-0000.mp3", duration = 57.835102, start = 0},
  },
}
P.transport["quest:718"] = {
  hash = "0e22a7",
  fullHash = "0e22a7",
  text = "Mirages. In the Badlands, Sigrun Ironhew's party has fled the Uldaman excavation and gone hungry. Sigrun's party fled the Uldaman dig in such haste that they took little with them. They left wagons and supply crates behind, and ogres from Camp Kosh have been picking through them. The ogres took the cart with all the party's weapons. Since then, the party has had no food. Sigrun admits the trouble is embarrassing and asks you to retrieve the supply crate.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_718-74cb3c10637b0491c71c/1-0000.mp3", duration = 32.1567347, start = 0},
  },
}
P.transport["quest:719"] = {
  hash = "e0608d",
  fullHash = "e0608d",
  text = "A Dwarf and His Tools. Prospector Ryedol escaped an attack on his dig site and now seeks his lucky pick. Dark Iron dwarves resembling the Shadowforge clan are all around. Dark Iron dwarves resembling the Shadowforge clan attacked the excavation site where Ryedol worked. Nearly everyone died, including his boss, Hammertoe. Ryedol barely escaped with his life. The site lies north of where he waits. Prospector Ryedol is trying to recover supplies lost in the attack, especially his lucky pick. One of the Dark Iron dwarves has it, though Ryedol does not know which one. He hopes you will help and waits south of Hammertoe's Dig Site.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_719-31e02812fadb63b4e2d0/1-0000.mp3", duration = 40.8032653, start = 0},
  },
}
P.transport["quest:720"] = {
  hash = "083332",
  fullHash = "083332",
  text = "A Sign of Hope. Hammertoe Grez lives, and a chalk plea on a crumpled map calls Prospector Ryedol to help. The note says they are taking Hammertoe to Uldaman. Hammertoe leaves a brief plea for Ryedol in chalk on a crumpled map. The note says they are taking Hammertoe to Uldaman and asks for help. Tell Prospector Ryedol that Hammertoe Grez lives.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_720-3241c6260262d20b26fa/1-0000.mp3", duration = 22.5959184, start = 0},
  },
}
P.transport["quest:723"] = {
  hash = "2e2cbb",
  fullHash = "2e2cbb",
  text = "Prospect of Faith. In the Badlands, Hammertoe Grez sends you to Prospector Ryedol with his amulet. Ryedol knows Hammertoe sought the origins of their people and wants to keep the scrolls from the Shadowforge clan. Wounded in the Badlands, Hammertoe Grez asks you to carry his amulet to Ryedol. He trusts Ryedol to know what to do. Hammertoe sought the origins of their people and meant to thwart the Shadowforge clan. The clan must not get the scrolls.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_723-87e4f49dabcd52dc137e/1-0000.mp3", duration = 29.6228571, start = 0},
  },
}
P.transport["quest:724"] = {
  hash = "3d2960",
  fullHash = "3d2960",
  text = "Prospect of Faith. In the Badlands, Prospector Ryedol sends you to Ironforge with Hammertoe's Amulet. Historian Karnik and Hammertoe sought Uldaman's lost artifacts together. Ryedol suspects the Shadowforge learned they knew more than they let on. Prospector Ryedol sends you to Historian Karnik in Ironforge. Tell Karnik what happened to Hammertoe and place the amulet in his hands. Karnik will decide what to do next.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_724-a01926aeeceb257f68e6/1-0000.mp3", duration = 27.5853061, start = 0},
  },
}
P.transport["quest:725"] = {
  hash = "041220",
  fullHash = "041220",
  text = "Passing Word of a Threat. Karnik sends you to Advisor Belgrum with a sealed note. Tell Belgrum what you witnessed and ask how to proceed while Karnik seeks answers from Hammertoe's spirit. Historian Karnik needs you to reach Advisor Belgrum quickly. Tell him what you witnessed and ask how he wants to proceed. The sealed note explains more.\n\nMeanwhile, Karnik speaks with Hammertoe's spirit, hoping to learn how to end the Shadowforge's doings in the Badlands. He can only pray that Hammertoe knows something that will help.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_725-2434d75b07fcf7895be2/1-0000.mp3", duration = 34.1942857, start = 0},
  },
}
P.transport["quest:726"] = {
  hash = "1a9a5c",
  fullHash = "1a9a5c",
  text = "Passing Word of a Threat. In the Badlands, Belgrum sends you back to Karnik with the king's command to act swiftly against the Shadowforge. Belgrum reads Karnik's note to the end. His eyes widen at the evil tidings. He sends you back to Karnik with the king's command: act swiftly and decisively on what is known. The Shadowforge's activities in the Badlands must stop.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_726-0d04cd06d35fbe5bc55b/1-0000.mp3", duration = 24.084898, start = 0},
  },
}
P.transport["quest:727"] = {
  hash = "674e6d",
  fullHash = "674e6d",
  text = "To Ironforge for Yagyin's Digest. Theldurin the Lost sends you to Ironforge with a sigil. In a shop in the Forlorn Cavern, Gerrig Bonegrip is meant to take you for one of the people Theldurin fled, so you can ask him for Yagyin's Digest. The Tablet has taught Theldurin much, yet questions remain. Yagyin wrote a digest ages ago, and the people Theldurin fled keep copies in many places. Their most learned study it. Theldurin believes its vast knowledge can offer protection, so he wants you to bring it back. Gerrig Bonegrip keeps a shop in Ironforge's Forlorn Cavern. Theldurin gives you the Sigil of the Hammer to show Gerrig. Then Gerrig should take you for one of the people Theldurin fled. Ask him for Yagyin's Digest.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_727-cddbc3945c0a17f65a03/1-0000.mp3", duration = 53.6293878, start = 0},
  },
}
P.transport["quest:728"] = {
  hash = "372f92",
  fullHash = "372f92",
  text = "To the Undercity for Yagyin's Digest. Theldurin the Lost sends you to the Undercity of Lordaeron with a sigil for Keeper Bel'dugur. He wants the keeper to mistake you for one of the people he fled, and asks you to find Yagyin's Digest. The tablet has answered much for Theldurin, yet questions remain. Yagyin wrote a digest ages ago, and the people Theldurin fled keep copies in many places. Their most learned study its pages. Theldurin believes its vast knowledge can protect them, so he wants you to bring it back. Keeper Bel'dugur waits in the Undercity of Lordaeron. Theldurin gives you the Sigil of the Hammer to show the keeper, who is to take you for one of the people he fled. Ask Bel'dugur for the digest.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_728-7a9492e94284123b10a6/1-0000.mp3", duration = 52.4016327, start = 0},
  },
}
P.transport["quest:732"] = {
  hash = "9487f0",
  fullHash = "9487f0",
  text = "Tremors of the Earth. Garek asks for your help after hearing all you have done for Sigrun. His master, Krasus of the Kirin Tor, sent him to the Badlands to stop trouble brewing in Lethlor Ravine. First, he needs the stolen Sign of the Earth. Krasus of the Kirin Tor sent Garek to the Badlands to stop trouble brewing in Lethlor Ravine. He cannot tell you the exact assignment, only that it matters greatly. Roving ogres took the Sign of the Earth, and Garek needs it back before he can tell you more. They are sometimes seen around Camp Boff. Ogres wander from camp to camp across the Badlands. Rising heat and swirling winds make their trail hard to follow. Garek has heard they sometimes pass through Camp Boff, so look there if you lose track of them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_732-32b71bc02e904ba8cc01/1-0000.mp3", duration = 49.7110204, start = 0},
  },
}
P.transport["quest:733"] = {
  hash = "3f8582",
  fullHash = "3f8582",
  text = "Scrounging. At Sigrun Ironhew's camp, defenses and supplies wait on scrap metal. She needs seven pieces, and nearby ogres carry plenty. Sigrun Ironhew needs materials for the camp's defenses and other needs. The Prospector worries about the camp's condition, so Sigrun wants to begin work soon. Scrap metal is what she lacks. Nearby ogres carry scrap metal, adding weight to talk of siege engines in the Badlands. Their main camp, Dustbelch Grotto, lies a long trek west of Sigrun's camp.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_733-40cc559777c364a0c9bb/1-0000.mp3", duration = 33.6979592, start = 0},
  },
}
P.transport["quest:734"] = {
  hash = "eaee35",
  fullHash = "eaee35",
  text = "This Is Going to Be Hard. In the Badlands, Lotwil Veriatus sends you to Lucien Tosselwrench for a needed cog #5. Bring it back to Lotwil. Lotwil Veriatus turns his attention to the shackles, then sends you to Lucien Tosselwrench. He needs a cog #5 and asks you to bring it back to him.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_734-952173c70921ede92958/1-0000.mp3", duration = 16.6661224, start = 0},
  },
}
P.transport["quest:735"] = {
  hash = "046386",
  fullHash = "046386",
  text = "The Star, the Hand and the Heart. In Ironforge, Gerrig Bonegrip offers Yagyin's Digest in exchange for three items of power. Their names are kept from listening ears and written in a note. Gerrig Bonegrip hears you ask for Yagyin's Digest and wonders whether you mean to begin a new chapter of the order somewhere. Gerrig decides it is not their place to ask. With an extra copy on hand, Gerrig believes those of the order should aid one another. So Gerrig asks you to bring three items of power. Their names stay unspoken in case someone is listening, and Gerrig writes them down. Gerrig's note names the Star of Xil'yeh, the Hand of Dagun and the Legacy Heart. Gerrig wants all three before handing over Yagyin's Digest.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_735-6b47c4f4f7ec7c1989df/1-0000.mp3", duration = 53.6032653, start = 0},
  },
}
P.transport["quest:736"] = {
  hash = "e8adca",
  fullHash = "e8adca",
  text = "The Star, the Hand and the Heart. In the Undercity, Keeper Bel'dugur tests those who seek to lead their own circle. To found a new chapter, they need Yagyin's Digest, but he asks for three unnamed items of power. Practitioners who hope to lead their own circle come to Keeper Bel'dugur in the Undercity. To found a chapter and gather followers, they need Yagyin's Digest, a work of ritual lore in his keeping. Bel'dugur will aid a brother, but first he asks for proof of worthiness before entrusting him with such knowledge. Keeper Bel'dugur asks for three items of power in exchange for Yagyin's Digest. Their names carry peril or sacred weight, so he will not speak them aloud. Instead, he writes them on a private note. Finding all three proves a practitioner worthy of founding a chapter of their own.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_736-6dca83aba4ce89dece43/1-0000.mp3", duration = 59.637551, start = 0},
  },
}
P.transport["quest:737"] = {
  hash = "1857e9",
  fullHash = "1857e9",
  text = "Forbidden Knowledge. Yagyin's Digest is in your care, bound for Theldurin the Lost and kept from unfriendly hands. Gerrig Bonegrip in Ironforge or Keeper Bel'dugur in the Undercity gives you Yagyin's Digest. Keep it from unfriendly hands as you carry it to Theldurin the Lost. It holds many truths, and truth has a way of burning.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_737-3f1e087d9c547998ec50/1-0000.mp3", duration = 24.5812245, start = 0},
  },
}
P.transport["quest:738"] = {
  hash = "7af582",
  fullHash = "7af582",
  text = "Find Agmond. Weeks have passed without word from Prospector Agmond at the Badlands digs. Prospector Ironband now needs you to find Agmond and bring back his report. Prospector Agmond oversaw the Badlands excavations southwest of Ironband. Ironband calls him a prospector no longer, for weeks have passed without word. He needs you to find Agmond and recover the report. Agmond was last heard from at the southernmost dig, a small outfit beyond Angor Fortress. Begin there.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_738-5452c16661fc573439b7/1-0000.mp3", duration = 30.2497959, start = 0},
  },
}
P.transport["quest:739"] = {
  hash = "343619",
  fullHash = "343619",
  text = "Murdaloc. Agmond lies dead in the Badlands, with Murdaloc scratched into the sandstone beside his hand. Slay his killer and carry word to Prospector Ironband in Loch Modan. Blood marks Agmond's trail from the west, crossing stone and sand. It shows how far the dwarf crawled before he died. Beside his still hand, one word is scratched into the Badlands sandstone: Murdaloc. Slay Agmond's killer and a number of Stonevault Bonesnappers, then carry the news to Prospector Ironband in Loch Modan.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_739-e8e8f69b7db2369d44f9/1-0000.mp3", duration = 33.1755102, start = 0},
  },
}
P.transport["quest:7541"] = {
  hash = "5bb5f4",
  fullHash = "5bb5f4",
  text = "Service to the Horde. In Orgrimmar, Zor Lonetree has received the jeweled pendant and has more to tell you about your service to the Horde. The jeweled pendant now rests with Zor Lonetree in Orgrimmar. Return to him to hear more about your service to the Horde.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7541-b00f480df7c941d48e61/1-0000.mp3", duration = 17.8677551, start = 0},
  },
}
P.transport["quest:762"] = {
  hash = "9ab557",
  fullHash = "9ab557",
  text = "An Ambassador of Evil. In the Badlands, Historian Karnik sends you after Ambassador Infernus. He wants you to carry proof of the kill to Advisor Belgrum in Ironforge. Ragnaros sent Ambassador Infernus to Angor Fortress to oversee the Shadowforge's hunt for lost artifacts in Uldaman. The search has already cost many dwarven lives, and more are dying. Karnik fears the Shadowforge could turn the artifacts against Ironforge. So he sends you back into the Badlands to destroy Infernus and carry Belgrum proof of your victory. Time is short. Ragnaros will not wait for the Shadowforge to prepare.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_762-c6e93b5e8b369cb0c92d/1-0000.mp3", duration = 40.6465306, start = 0},
  },
}
P.transport["quest:77"] = {
  hash = "0f9957",
  fullHash = "0f9957",
  text = "A Sticky Situation. Dran Droffers seeks the original packaging for Hinterlands Honey Ripple. Gilveradin Sunchaser has it and asks for two extra bottles; ten bottles wait in crates around the abandoned Horde base near Skulk Rock. Dran Droffers seeks Hinterlands Honey Ripple, and Gilveradin Sunchaser has its original packaging. Gilveradin offers to help in return for two extra bottles. Gather ten bottles and bring them back to the camp. Crates of Hinterlands Honey Ripple are scattered around the abandoned Horde base near Skulk Rock. Foul slimes and oozes cling to the ruins. Rumor says a master ooze leads them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_77-6be86d08c8b4412be2ce/1-0000.mp3", duration = 39.2620408, start = 0},
  },
}
P.transport["quest:7701"] = {
  hash = "087e93",
  fullHash = "087e93",
  text = "WANTED: Overseer Maltorius. In the Cauldron, a bounty calls for Overseer Maltorius's death. It names him a rogue Thorium Brotherhood agent and the newly hired commander of the Dark Iron Slag Pit crew. Overseer Oilfist orders his head brought to Lookout Captain Lolo Longstriker as proof. In the Cauldron's Slag Pit, you are sent to find and slay Overseer Maltorius. The notice calls him a traitorous Dark Iron dwarf. Bring his head to Lookout Captain Lolo Longstriker to claim the bounty.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7701-27aa8b3320e86b01133d/1-0000.mp3", duration = 33.1493878, start = 0},
  },
}
P.transport["quest:7704"] = {
  hash = "183778",
  fullHash = "183778",
  text = "Look at the Size of It!. In the Searing Gorge, you have a gigantic, ornate pillow once kept by Chambermaid Pillaclencher. Evonice Sootsmoker is sure to want it. Evonice Sootsmoker is sure to want Chambermaid Pillaclencher's gigantic, ornate pillow. Bring it to her in the Searing Gorge and see what she offers for your trouble.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7704-3e4aab2c917b74b51c67/1-0000.mp3", duration = 20.2971429, start = 0},
  },
}
P.transport["quest:7721"] = {
  hash = "6465a9",
  fullHash = "6465a9",
  text = "Fuel for the Zapping. On the Forgotten Coast, Zorbin Fandazzle puts his engineering shop to work in a poor place. The elementals trouble him, but their water cores can power the refining of the Ultra-Shrinker. Zorbin Fandazzle curses the unchecked power of elementalism and calls the coast's elementals pests. Yet he sees their water elemental cores as raw power for refining the Ultra-Shrinker. He asks you to fight the Sea Elementals and Sea Sprays along the coast. Keep their cores and bring them to him by the dock.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7721-2adcbae6083b00df644c/1-0000.mp3", duration = 31.7910204, start = 0},
  },
}
P.transport["quest:7722"] = {
  hash = "dca232",
  fullHash = "dca232",
  text = "What the Flux?. Master Smith Burninate seeks the fiery flux plans in the Slag Pit. Maltorius left their clan with the recipe, which Burninate values above a pristine arcane crystal, and believes the plans are near him. Master Smith Burninate says Maltorius betrayed their clan when he left with the fiery flux recipe. Burninate suspects that recipe helped Maltorius earn his new promotion among the Dark Irons. Now Burninate wants the secret plans returned. Master Smith Burninate believes the plans lie near Maltorius, deep in the Slag Pit. He wants you to carry the Secret Plans: Fiery Flux back to him.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7722-fdf4b52357719fd8f681/1-0000.mp3", duration = 42.8408163, start = 0},
  },
}
P.transport["quest:7723"] = {
  hash = "662743",
  fullHash = "662743",
  text = "Curse These Fat Fingers. In the Searing Gorge, Hansel Heavyhands can no longer deliver beatings as before. Swollen fingers leave Hansel asking you to pound the heavy war golems instead. Hansel Heavyhands blames the Searing Gorge climate and its thin air for swelling their fingers. They resemble huge Thelsamar blood sausages. With fingers like these, Hansel can no longer deliver beatings as before, so they need you to handle their business. Hansel wants you to pound the Gorge's heavy war golems hard. Twenty must be destroyed. They roam the areas around the Cauldron, and you return to Hansel once enough have fallen.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7723-74fc415dfdcc54cb8759/1-0000.mp3", duration = 40.8032653, start = 0},
  },
}
P.transport["quest:7724"] = {
  hash = "969cf9",
  fullHash = "969cf9",
  text = "Fiery Menace!. Hansel Heavyhands has another job for you in the Searing Gorge. Greater lava spiders are making trouble. Hansel Heavyhands has little time to rest or think on his life. Those in power keep giving him more work. Greater lava spiders are causing a ruckus, so Hansel would rather you deal with them. Oilfist says the greater lava spiders shoot fire from an awkward place. Their flames upset the children. Hansel wants you to kill twenty spiders on the plateaus and by the lava pools of the Searing Gorge.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7724-19f76f4b951a673d56c7/1-0000.mp3", duration = 34.7428571, start = 0},
  },
}
P.transport["quest:7725"] = {
  hash = "ceef25",
  fullHash = "ceef25",
  text = "Again With the Zapped Giants. At the Forgotten Coast docks, Zorbin Fandazzle has another offer for you. Bring him more residue from Feralas giants shrunk with the Ultra-Shrinker. He can pay far less this time, but promises to spread word of your service. Zorbin Fandazzle asks you to shrink giants in Feralas again and bring ten miniaturization residues to the Forgotten Coast docks. There is always room for more, even after your first haul.\n\nHe cannot offer nearly as much this time. Instead, he promises to praise your service among his goblin friends, who have quite large ears.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7725-64e97a195ab790eb6fbe/1-0000.mp3", duration = 36.7020408, start = 0},
  },
}
P.transport["quest:7726"] = {
  hash = "dfdc4b",
  fullHash = "dfdc4b",
  text = "Refuel for the Zapping. On the Forgotten Coast, Zorbin Fandazzle needs more water elemental cores. The shop is hard to establish, so the pay is small. Still, Zorbin promises to tell nearby folk of your help and says there are friends in the Cartel. Zorbin Fandazzle makes light of the heroic work of gathering goo from elemental beings. Then Zorbin asks if you want more of the same. Beneath the jest, Zorbin needs more water elemental cores.\n\nEstablishing a shop on the Forgotten Coast is a desperate business, so little can be given in return. Zorbin promises to tell everyone nearby how you helped, and says the promise is worth trusting because Zorbin knows people in the Cartel. Bring six cores from Sea Elementals and Sea Sprays on the Forgotten Coast to Zorbin near the dock.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7726-6d2c7bb12204eca6c50e/1-0000.mp3", duration = 47.6995918, start = 0},
  },
}
P.transport["quest:7727"] = {
  hash = "6f3fcf",
  fullHash = "6f3fcf",
  text = "Incendosaurs? Whateverosaur is More Like It. Hansel Heavyhands cannot fight with his feet in such disarray. So he sends you to slay twenty incendosaurs in the Slag Pit, where Scrange and Burninate want the lava pools cleared for expeditionary teams. Hansel Heavyhands cannot fight while his bunions are in such a state. Scrange and Burninate told him to kill the incendosaurs so expeditionary teams can explore the Slag Pit’s lava pools. Now he sends you in his place. The incendosaurs occupy the lava pools in the Slag Pit, within the Cauldron. Hansel wants twenty slain before you return.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7727-cbdbf6d13cc951585daa/1-0000.mp3", duration = 38.5828571, start = 0},
  },
}
P.transport["quest:7728"] = {
  hash = "5901b5",
  fullHash = "5901b5",
  text = "STOLEN: Smithing Tuyere and Lookout's Spyglass. In the Searing Gorge, the Thorium Brotherhood seeks two stolen tools: a tuyere and a Lookout's Spyglass. The Brotherhood is certain jealous, unscrupulous Dark Iron dwarves took them, and asks that whoever finds them bring them to Taskmaster Scrange for payment. The Thorium Brotherhood seeks a Lookout's Spyglass and a tuyere, both stolen. The spyglass is a fine tool for lookouts, and the tuyere is a smithing tool that cannot be replaced. The Brotherhood is certain Dark Iron dwarves took them. Whoever finds the tools should bring them to Taskmaster Scrange.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7728-0e9930381bfa2d73b2c6/1-0000.mp3", duration = 38.9746939, start = 0},
  },
}
P.transport["quest:7729"] = {
  hash = "6426a3",
  fullHash = "6426a3",
  text = "JOB OPPORTUNITY: Culling the Competition. In the Searing Gorge, Taskmaster Scrange wants you to thin the competition through bloody work. Taskmaster Scrange sends you through the gorge to kill fifteen Dark Iron Taskmasters and fifteen Dark Iron Slavers. Return when your clothes are bloody enough. You will know when that is, and you are not to ask.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7729-70b443be8a84f01cfac6/1-0000.mp3", duration = 18.7559184, start = 0},
  },
}
P.transport["quest:7730"] = {
  hash = "abfe04",
  fullHash = "abfe04",
  text = "Zukk'ash Infestation. At Camp Mojache, Hadoken Swiftstrider suspects the Zukk'ash south of the gnolls are driving them into a frenzy. He sends you to the Writhing Deep to thin their numbers and return with twenty carapaces. Hadoken Swiftstrider believes insect-like creatures live south of the gnolls. Whether they can think matters little to him. If they drive the gnolls into a frenzy against Camp Mojache, they threaten the camp as much as the gnolls do. So you enter their home, the Writhing Deep, to thin their numbers. Bring back twenty Zukk'ash carapaces as proof, and tell Hadoken what you find.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7730-4fc0a4b1b7f65ba8584d/1-0000.mp3", duration = 36.6236735, start = 0},
  },
}
P.transport["quest:7731"] = {
  hash = "ae692e",
  fullHash = "ae692e",
  text = "Stinglasher. In the Writhing Deep, Hadoken Swiftstrider's scout has found an insect far larger than the others. A scout has found a giant insect wandering the twisted terrain of the Writhing Deep. It seems to give off an aura unlike the others, and Hadoken Swiftstrider has named it Stinglasher. Hadoken wants its secretion glands brought straight to Camp Mojache. By studying the insect's innards, Hadoken hopes to learn how to deal with this new threat.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7731-bd729503a5d5275dbfe7/1-0000.mp3", duration = 28.7085714, start = 0},
  },
}
P.transport["quest:7732"] = {
  hash = "52a97e",
  fullHash = "52a97e",
  text = "Zukk'ash Report. At Camp Mojache, Hadoken Swiftstrider says your work against the Zukk'ash has gone doubly well, though danger remains. He asks you to carry the camp's report to Zilzibin Drumlore in Orgrimmar. Hadoken Swiftstrider has a document about what Camp Mojache has learned of the Zukk'ash insects. Their threat remains, so he asks you to take the report to Orgrimmar. Zilzibin Drumlore lives in the Drag and knows alien creatures like these. Hadoken hopes the camp's findings will prove useful.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7732-9c971bf61997575bf0ed/1-0000.mp3", duration = 33.8546939, start = 0},
  },
}
P.transport["quest:7733"] = {
  hash = "a317eb",
  fullHash = "a317eb",
  text = "Improved Quality. In northern Feralas, Pratt McGrubben wants tougher yeti hides from Rage Scar Hold. He asks you to bring ten to Feathermoon Stronghold. After The Mark of Quality, Pratt McGrubben has found finer hides. A tougher throng of yetis lives inside Rage Scar Hold in northern Feralas. Bring ten hides to Pratt at Feathermoon Stronghold, and he will pay handsomely. If these hides match the Feral Scar hides, they may prove as resilient as thorium.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7733-b05f257f08bfbf861c1e/1-0000.mp3", duration = 29.7795918, start = 0},
  },
}
P.transport["quest:7734"] = {
  hash = "bce2f0",
  fullHash = "bce2f0",
  text = "Improved Quality. At Camp Mojache, Jangdor Swiftstrider now seeks finer hides from the tougher yetis in Rage Scar Hold. After The Mark of Quality, Jangdor Swiftstrider has found a better source of hides. Tougher yetis roam inside Rage Scar Hold in northern Feralas. Bring ten hides to Camp Mojache, and Jangdor will pay handsomely. If they match the Feral Scar hides, they may prove as resilient as thorium.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7734-26fd203b4ee0c16e3e4c/1-0000.mp3", duration = 26.7755102, start = 0},
  },
}
P.transport["quest:7735"] = {
  hash = "c12506",
  fullHash = "c12506",
  text = "Pristine Yeti Hide. In Feralas, a hide from Rage Scar's yetis may catch Pratt McGrubben's eye. It is unusually thick and tough, and Pratt is looking to buy yeti hides. Among the hides from Rage Scar's yetis, this one is unusually thick and sturdy. Pratt McGrubben wants to buy yeti hides at Feathermoon Stronghold in Feralas, so this hide may interest him.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7735-46734828c0ed4ce74678/1-0000.mp3", duration = 23.6146939, start = 0},
  },
}
P.transport["quest:7736"] = {
  hash = "1497a1",
  fullHash = "1497a1",
  text = "Restoring Fiery Flux Supplies via Kingsblood. In the Searing Gorge, Master Smith Burninate needs more fiery flux after What the Flux?. He asks you for incendosaur scales, Kingsblood, and coal, and accepts all you can offer. Master Smith Burninate has little time for talk. His fiery flux is running low, so he asks you for two incendosaur scales, four Kingsblood, and coal. He will take all you can offer.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7736-22c3ea7bb53e2c806339/1-0000.mp3", duration = 25.9657143, start = 0},
  },
}
P.transport["quest:7738"] = {
  hash = "86a17f",
  fullHash = "86a17f",
  text = "Perfect Yeti Hide. At Camp Mojache, Jangdor Swiftstrider is buying yeti hides, and one you found may be perfect. It is thicker and tougher than the hides from the yetis of Rage Scar. The hide feels thicker and sturdier than those from the yetis of Rage Scar. Jangdor Swiftstrider at Camp Mojache in Feralas buys yeti hides. This one is worth bringing to him.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7738-fcc23a1e1f3a05285d11/1-0000.mp3", duration = 21.0808163, start = 0},
  },
}
P.transport["quest:777"] = {
  hash = "8f96d2",
  fullHash = "8f96d2",
  text = "This Is Going to Be Hard. Behind cover, Lucien Tosselwrench waits while you carry cog #5 to Lotwil Veriatus. Lucien Tosselwrench gives you the cog for Lotwil Veriatus. Then he waits behind cover and welcomes you to join him. Lotwil is still bent over the shackles when you arrive. Without looking up, he holds out his hand and waggles his fingers for the cog.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_777-6b6cf760fe76ce060755/1-0000.mp3", duration = 23.0661224, start = 0},
  },
}
P.transport["quest:778"] = {
  hash = "6bf157",
  fullHash = "6bf157",
  text = "This Is Going to Be Hard. In the Badlands, Lotwil Veriatus is ready to summon a powerful elemental. Lotwil calls out that the shackles are finished. The time has come. He asks Lucien and Servo to witness the summoning with you. Alchemy, engineering and the arcane come together in the shackles, and Lotwil expects a powerful elemental to answer on this groundbreaking day.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_778-ce5c72bfdaadabbd99e3/1-0000.mp3", duration = 25.1297959, start = 0},
  },
}
P.transport["quest:7807"] = {
  hash = "6a142a",
  fullHash = "6a142a",
  text = "A Donation of Wool. Across the realm, A Donation of Wool calls for aid to the Gnomeregan Exiles. Driven from Gnomeregan, they need wool cloth to sustain their displaced people. Sixty pieces earn formal recognition among the gnomes. Gnomeregan's fall to trogg invaders and radioactive contamination drove its surviving gnomes from their high-tech city. They now live as refugees, hosted chiefly by their dwarven cousins in Ironforge.\n\nOutside their ancestral halls, the Gnomeregan Exiles face severe strain in supplying their people. Regular drives for cloth and other basics help keep them clothed, supplied, and organized. The drive asks each volunteer for exactly sixty pieces of wool cloth. By gathering modest contributions from across the realm, the exiles can collect the textiles they need for bedding, bandages, and clothing without overburdening any one supplier. Those who aid their recovery receive formal recognition among their people.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7807-c3c1687b1ac7cb3accfc/1-0000.mp3", duration = 71.9934694, start = 0},
  },
}
P.transport["quest:7810"] = {
  hash = "22d31e",
  fullHash = "22d31e",
  text = "Arena Master. At the Stranglethorn Arena, Short John Mithril may know what more mastering its contests requires. You have gained something at Gurubashi, yet mastering the arena asks for more. Short John Mithril organizes the contests and may know what is needed. Find him inside the Stranglethorn Arena.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7810-bf8a7adddce06a7cfec1/1-0000.mp3", duration = 21.0285714, start = 0},
  },
}
P.transport["quest:7815"] = {
  hash = "7d0f21",
  fullHash = "7d0f21",
  text = "Snapjaws, Mon!. In Revantusk Village, Katoom the Angler asks you to deal with saltwater snapjaws ruining his fishing. He wants fifteen turtles killed. Katoom the Angler asks you to help him and his neighbours in Revantusk Village. Saltwater snapjaws may look harmless, but they make fishing hard. One tears his line and steals his bait before he can fish for five minutes. Katoom wants you to kill fifteen of the turtles.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7815-434b778c16bf01e7991c/1-0000.mp3", duration = 27.3240816, start = 0},
  },
}
P.transport["quest:7816"] = {
  hash = "5ca6da",
  fullHash = "5ca6da",
  text = "Gammerita, Mon!. At Revantusk Village, Katoom the Angler wants his best lure back from Gammerita, Mon!, who leads the saltwater snapjaws. Find her and recover it. Katoom says Gammerita, Mon! is no ordinary turtle. She leads the saltwater snapjaws, and he calls her a thief. She snapped his best lure off his line. Since then, the fish have not bitten as they once did. Katoom wants you to find Gammerita, Mon! and recover his lure from her stomach. She stays along the coast among the other turtles.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7816-204baaee2a9f10fbfc9d/1-0000.mp3", duration = 32.9142857, start = 0},
  },
}
P.transport["quest:782"] = {
  hash = "ab9c01",
  fullHash = "ab9c01",
  text = "Broken Alliances. Gorn sends you from Kargath to reclaim what the ogres took. He seeks to restore the Horde’s honor after its alliance with Deathwing. Boss Tho’grun, hired to find the Sign of the Earth, betrayed the Horde and kept it. During the Second War, the Horde fought beside Deathwing. His lieutenants Blacklash and Hematus were later imprisoned far to the east in Lethlor Ravine. Gorn believes these old, depraved allies must be silenced to restore the Horde’s honor.\n\nThe Horde needed the Sign of the Earth to open the drakes’ prison, so it hired ogre mercenaries led by Boss Tho’grun to find the sign. Tho’grun turned against the Horde, overwhelmed its forces and kept it. Gorn sends you southeast of Kargath to Camp Boff. Kill Tho’grun and bring back the Sign of the Earth. Gorn will be glad to see Tho’grun dead. The ogres no longer belong to the Horde.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_782-a57c9e0556fb02b99401/1-0000.mp3", duration = 60.4995918, start = 0},
  },
}
P.transport["quest:7828"] = {
  hash = "961386",
  fullHash = "961386",
  text = "Stalking the Stalkers. In Revantusk, Huntsman Markhor names the wolves threatening the village's hunters. He asks you to turn the hunt on them. The Hinterlands wilds have already claimed many trolls. Markhor counts Silvermane wolves among the greatest dangers to Revantusk's hunters. They hide among bushes and in the lay of the land, then pounce when the moment is right. He urges you to think as a Silvermane does and hunt the hunters. Every one must be put down. Markhor asks you to kill fifteen Silvermane Stalkers and fifteen Silvermane Howlers. They lurk in the Hinterlands wilds.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7828-da1c2a12d3590c13f786/1-0000.mp3", duration = 37.2244898, start = 0},
  },
}
P.transport["quest:7829"] = {
  hash = "dfc003",
  fullHash = "dfc003",
  text = "Hunt the Savages. In the Hinterlands, Huntsman Markhor sends you to hunt savage owlbeasts. He asks you to bring down twenty. Huntsman Markhor warns that savage owlbeasts are among the Hinterlands' most ornery creatures. Their claws and beaks have cost Revantusk many good warriors. He wants every owlbeast you see killed, until you can bear no more bloodshed. Then he will weigh and judge your contribution. Twenty must fall. Markhor counsels you to clear your mind of unclean thoughts and join with the wild. Savage owlbeasts roam the Hinterlands wilds.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7829-e8489c57f59d320ddd5e/1-0000.mp3", duration = 32.3918367, start = 0},
  },
}
P.transport["quest:7830"] = {
  hash = "c46dbc",
  fullHash = "c46dbc",
  text = "Avenging the Fallen. At Revantusk Village, Markhor turns his anger toward the Skylords. He asks you to slay a Razorbeak Skylord and bring him its plume. Huntsman Markhor of Revantusk Village resents the Wildhammer for training gryphons to slay trolls. He promises justice for the trolls, but first he wants you to strike at the Skylords, the Hinterlands' elder gryphons.\n\nSlay a Razorbeak Skylord and bring its plume back to Markhor. This rare breed lives in the wilds of the Hinterlands. Markhor blames it for breeding murderous young.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7830-61eb5bfbc4e2a8cb3f58/1-0000.mp3", duration = 39.9934694, start = 0},
  },
}
P.transport["quest:7839"] = {
  hash = "278e28",
  fullHash = "278e28",
  text = "Vilebranch Hooligans. In Revantusk Village, Smith Slagtree seeks tools stolen by Vilebranch trolls. A kind-hearted gnome gave him the set after saving his life when he was a young orc. Vilebranch trolls took Smith Slagtree's tools when they invaded Revantusk Village. He has spares, but the stolen set came from a kind-hearted gnome who saved his life when he was a young orc. The gift means the world to Slagtree, so he asks you to recover it. Markhor saw the tools near the temples of Agol'watha and Shaol'watha in the northeast of the Hinterlands. Slagtree also says to check Skulk Rock. The Vilebranch trolls there are ruthless and murderous.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7839-6594a191d3d3fec573d6/1-0000.mp3", duration = 37.877551, start = 0},
  },
}
P.transport["quest:7840"] = {
  hash = "37e1fb",
  fullHash = "37e1fb",
  text = "Lard Lost His Lunch. In the Hinterlands, Lard has run to Revantusk and left the picnic lunch behind. A Vilebranch struck Lard at a private picnic, and now Lard asks you to fetch the food from an island to the north. A Vilebranch struck Lard with a big stick at a secret picnic spot. By Lard's account, the troll was ugly and mean. Lard fled to Revantusk, leaving the lunch behind and fearing a return. Lard's picnic spot lies on an island to the north. Lard hopes you will find the lunch and bring it back. Take care around the Vilebranch trolls.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7840-8829bba08952723802cc/1-0000.mp3", duration = 35.4742857, start = 0},
  },
}
P.transport["quest:7841"] = {
  hash = "a28df5",
  fullHash = "a28df5",
  text = "Message to the Wildhammer. At Revantusk Village, Otho Moji'ko wants a message carried to the Wildhammer dwarves. Their new allies include the high elves, and Otho wants his warning written in the blood of the Highvale high elves at Quel'Danil Lodge. The Wildhammer are making alliances with the trolls' enemies, and now the high elves stand with them. Otho Moji'ko spits at the thought. He wants the dwarves warned in the blood of their new friends. Slaughter every Highvale high elf you find and leave the bodies as a warning.\n\nHighvale Outrunners, Scouts, Marksmen and Rangers gather at Quel'Danil Lodge, in the northwest of the Hinterlands.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7841-c54d748aae83a4356b37/1-0000.mp3", duration = 42.6318367, start = 0},
  },
}
P.transport["quest:7842"] = {
  hash = "f214bb",
  fullHash = "f214bb",
  text = "Another Message to the Wildhammer. At Revantusk Village, Otho Moji'ko sends another message to the Wildhammer. He sees their bond with gryphons as close as a troll and a mate, and means to turn it against them. After the Highvale high elves, Otho Moji'ko has another message for the Wildhammer. Their closeness with gryphons disgusts him, but he sees a use for it. Kill the gryphons you meet across the Hinterlands and gather their Long Elegant Feathers. Gryphons live in every region there. Otho will make his final message from the feathers.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7842-fad68afc42fed06ede96/1-0000.mp3", duration = 39.8367347, start = 0},
  },
}
P.transport["quest:7843"] = {
  hash = "407d05",
  fullHash = "407d05",
  text = "The Final Message to the Wildhammer. At Revantusk Village, Otho Moji'ko sends you west with a blood-soaked spear bound in gryphon feathers. The Wildhammer dwarves will find it planted beside the well at Aerie Peak's heart. After Another Message to the Wildhammer, Otho Moji'ko gives you a spear soaked in blood and bound with gryphon feathers. Carry it west to Aerie Peak and plant it beside the well at the town's heart. The Wildhammer dwarves will see that the trolls mean business. Furious dwarves and rowdy Alliance folk await you there, and Otho hopes you return alive.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7843-4b06d3991aa21a9c59f3/1-0000.mp3", duration = 39.0269388, start = 0},
  },
}
P.transport["quest:7844"] = {
  hash = "7c197c",
  fullHash = "7c197c",
  text = "Cannibalistic Cousins. In the Hinterlands, Mystic Yayo'jin asks you to strike at the Vilebranch near their temples. She calls them a depraved lot who prey on other trolls and humanoids. With Zul'jin away, the Revantusk are left to their own devices. Three troll tribes share the Hinterlands, though Mystic Yayo'jin says little binds them. The Vilebranch prey on other trolls and humanoids. Zul'jin could wipe them out with ease, but he is away. So the Revantusk are left to their own devices. Yayo'jin asks you to destroy the Vilebranch Scalpers and Soothsayers near the Shaol'watha and Agol'watha temples. The temples lie in the Hinterlands' north by northeast.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7844-b7578a9f999bde09786b/1-0000.mp3", duration = 45.8971429, start = 0},
  },
}
P.transport["quest:7845"] = {
  hash = "d0a9c6",
  fullHash = "d0a9c6",
  text = "Kidnapped Elder Torntusk!. At Revantusk Village, Primal Torntusk asks you to save her mate after a bold midnight raid. Her spies say Elder Torntusk is alive atop Jintha'alor. Vilebranch savages struck Revantusk Village at midnight and seized Elder Torntusk, Primal Torntusk's mate. Her spies say he is alive, held prisoner atop Jintha'alor, the Vilebranch capital in the southern Hinterlands. Primal Torntusk fears the village could not bear to lose him. Vile Priestess Hexx is said to be preparing Elder Torntusk for sacrifice to Hakkar, the faceless blood God.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7845-a077b919a5f1440cb7e6/1-0000.mp3", duration = 40.3591837, start = 0},
  },
}
P.transport["quest:7846"] = {
  hash = "91c923",
  fullHash = "91c923",
  text = "Recover the Key!. At Jintha'alor, Elder Torntusk is shackled and asks you to free him. Hitah'ya the Keeper holds his key in a guarded cave nearby. After Kidnapped Elder Torntusk!, you find Elder Torntusk shackled at Jintha'alor. Hitah'ya the Keeper keeps the key to his bindings in a nearby cave, where she is well guarded. Elder Torntusk asks you to kill her and bring back the key. Then he can loosen his shackles and return home.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7846-ceab71e58bdaedc94d96/1-0000.mp3", duration = 29.0481633, start = 0},
  },
}
P.transport["quest:7847"] = {
  hash = "2ce3b4",
  fullHash = "2ce3b4",
  text = "Return to Primal Torntusk. Elder Torntusk is free and sends you to Revantusk Village with word for his mate, Primal Torntusk. Elder Torntusk is free of his bindings and asks you to return to Revantusk Village. Tell his mate, Primal Torntusk, that he is coming home.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7847-7e091ab84a180985b327/1-0000.mp3", duration = 17.0318367, start = 0},
  },
}
P.transport["quest:7849"] = {
  hash = "2b586c",
  fullHash = "2b586c",
  text = "Separation Anxiety. Huntsman Markhor grieves for his twin, Malkhor, in Revantusk Village. The Vilebranch took Malkhor in the raid that took Torntusk's mate. Markhor believes Malkhor's soul can still be rescued, though his life is beyond saving. So he asks you to recover the remains. Many in Revantusk Village have lost loved ones to the wilds, Markhor says. His own grief is for his twin brother, Malkhor. The Vilebranch took Malkhor in the raid that took Torntusk's mate. His captors killed him swiftly and brutally; he was not fated to live. The Vilebranch fed Malkhor's remains to their oozes and wolves. Near the top of the temple of Jintha'alor are a refuse pit filled with oozes and a wolf den. His bones rest in a sludge pit near the top tier, while his skull lies on the tier itself. Markhor plans to carry the remains to Yayo'jin, who will prepare them for a proper burial.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7849-4cf69db6b1bcc355e534/1-0000.mp3", duration = 57.4693878, start = 0},
  },
}
P.transport["quest:7850"] = {
  hash = "624d38",
  fullHash = "624d38",
  text = "Dark Vessels. In Revantusk Village, Primal Torntusk says the Vilebranch fight with a fury beyond the natural. He blames Vile Priestess Hexx's foul magic and asks you to take the tainted blood vessels from Jintha'alor, so he can cleanse them. Across Jintha'alor, tainted blood vessels bear the power of the faceless blood God. That power strengthens the Vilebranch and drives them mad. Torntusk believes taking the vessels away and cleansing them will loosen the blood God's grip on the trolls.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7850-484e5e76f7b854988bfe/1-0000.mp3", duration = 32.1567347, start = 0},
  },
}
P.transport["quest:7861"] = {
  hash = "6998ff",
  fullHash = "6998ff",
  text = "Wanted: Vile Priestess Hexx and Her Minions. Primal Torntusk has sent you to Jintha'alor to bring Vile Priestess Hexx and her minions to justice. He offers a grand prize for slaying Hexx and her elite Aman'zasi guard. Primal Torntusk sends you after Vile Priestess Hexx and her minions. They are atop Jintha'alor in the Hinterlands, where Hexx's elite Aman'zasi guards stand with her. Slay them, then report to Torntusk at Revantusk Village.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7861-835e6e475938fd72ea67/1-0000.mp3", duration = 29.3093878, start = 0},
  },
}
P.transport["quest:7862"] = {
  hash = "7942dd",
  fullHash = "7942dd",
  text = "Job Opening: Guard Captain of Revantusk Village. Revantusk Village needs a new leader for its guard. Applicants must prove themselves against four kinds of Vilebranch and bring an application to Primal Torntusk. Guard Captain Malkhor has been lost, leaving Revantusk's guard without a captain once more. The notice calls on anyone who wants to lead the guard to complete its work and send an application to Primal Torntusk. To seek the captaincy, defeat Vilebranch Berserkers, Shadow Hunters, Blood Drinkers and Soul Eaters. Then return to Primal Torntusk in Revantusk Village.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7862-c1e2f932ce6073720eb2/1-0000.mp3", duration = 37.6163265, start = 0},
  },
}
P.transport["quest:793"] = {
  hash = "4033d2",
  fullHash = "4033d2",
  text = "Broken Alliances. Gorn sends you east into Lethlor Ravine to free two black drakes bound by the Seal of the Earth. This follows the first Broken Alliances. Three runestones keep the Seal of the Earth closed, one in each of Lethlor Ravine’s Diamond, Opal and Amethyst pillars. Gorn gives you the Sign of the Earth, which draws the stones out and opens the seal.\n\nCountless drakes live in the ravine, and Blacklash and Hematus are formidable foes. Gorn wants both dead, with their bindings brought back to him.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_793-c866668c955cd35a5683/1-0000.mp3", duration = 33.1493878, start = 0},
  },
}
P.transport["quest:79974"] = {
  hash = "f1c694",
  fullHash = "f1c694",
  text = "Wet Job. On a mountainside, Wet Job sends you to recover an emergency reserve stash. Someone prepared it for a hasty escape and hid it near a high cliffside perch. In dangerous country, a reserve can make a quick escape possible. You search the rugged heights for a stash someone left there in case plans went wrong. Its supplies are waiting to be recovered. The directions lead to a high mountain perch, described as carved from the waterfalls of time. There, at the eagle's nest, a weathered messenger bag lies partly buried in the earth. Inside, provisions and parchment have endured beneath the soil, protected by dwarven craft.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_79974-8794cf9b8bb41ad5329e/1-0000.mp3", duration = 41.1689796, start = 0},
  },
}
P.transport["quest:79976"] = {
  hash = "585308",
  fullHash = "585308",
  text = "This Must Be The Place. At This Must Be The Place, a camper has vanished moments before anyone could catch up. A torn note says the writer has taken their work underground to keep it from the wrong hands. Someone broke camp at this secluded spot only moments ago. An inadequately secured sleeping bag unrolls underfoot, while heavy canvas lies bundled over assorted gear. A small scrap of paper holds a hurried parting message, but whoever camped here has vanished before anyone could catch up.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_79976-646a787489e13d44304b/1-0000.mp3", duration = 29.7534694, start = 0},
  },
}
P.transport["quest:82"] = {
  hash = "3f1ca8",
  fullHash = "3f1ca8",
  text = "Noxious Lair Investigation. In the Noxious Lair, Centipaar bugs drain the pools that once lay there. Senior Surveyor Fizzledowser wants to learn who the enemy is, so you bring five insect parts to Alchemist Pestlezugg in Gadgetzan for examination. After the Gadgetzan Water Survey, Senior Surveyor Fizzledowser turns to reports of the bugs. They drain the pools that once lay where the Noxious Lair now stands. He knows little about them and wants to learn who the enemy is, so you gather five parts from the Centipaar in the Noxious Lair. Then you take them to Alchemist Pestlezugg in Gadgetzan for examination.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_82-1d947a45c40fd0cc36c3/1-0000.mp3", duration = 36.3885714, start = 0},
  },
}
P.transport["quest:8241"] = {
  hash = "532668",
  fullHash = "532668",
  text = "Restoring Fiery Flux Supplies via Iron. In the Searing Gorge, fiery flux is running low, and Master Smith Burninate needs more. After What the Flux?, Burninate asks for scales, iron bars, and coal, and will take all you can offer. Master Smith Burninate needs more fiery flux as the supply runs low. In the Searing Gorge, Burninate asks you for two incendosaur scales, four iron bars, and coal. All you can offer will be taken.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8241-e441853d925b8c58c5cf/1-0000.mp3", duration = 28.9436735, start = 0},
  },
}
P.transport["quest:8242"] = {
  hash = "b33607",
  fullHash = "b33607",
  text = "Restoring Fiery Flux Supplies via Heavy Leather. In the Searing Gorge, Master Smith Burninate needs more fiery flux supplies. After What the Flux?, he asks you for two incendosaur scales, ten pieces of heavy leather, and coal. Bring all you can offer. Master Smith Burninate needs more fiery flux in the Searing Gorge. The supply is running low, so he asks you for two incendosaur scales, ten pieces of heavy leather, and coal. Bring all you can offer.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8242-3402da26a9bd16e9ba20/1-0000.mp3", duration = 27.8726531, start = 0},
  },
}
P.transport["quest:8249"] = {
  hash = "f040de",
  fullHash = "f040de",
  text = "Junkboxes Needed. Fahrad keeps Ravenholdt supplied with locked boxes for rogue training. He trades specialized throwing knives for authentic heavy junkboxes, and his demand never ends. Ravenholdt Manor hides in the mountains above Hillsbrad Foothills, where training never ceases. Master thief Fahrad oversees the guild's operatives and prizes skill at picking locks. Zan supplies practice contraptions for new recruits. Fahrad finds them too crude for experienced thieves who must open stubborn mechanisms in the field. Fahrad pays for heavy junkboxes stolen from dangerous targets across Azeroth, and accepts them in batches. Only skilled thieves can lift the boxes from their marks in the wild, but anyone may bring them to the manor. Even boxes stripped of major valuables earn his favor and finely balanced throwing knives from the manor. A token coin must remain inside, to motivate the initiates.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8249-8a6071d081b5a72cddbb/1-0000.mp3", duration = 66.4816327, start = 0},
  },
}
P.transport["quest:8273"] = {
  hash = "b2a8c7",
  fullHash = "b2a8c7",
  text = "Oran's Gratitude. You bring Oran Snakewrithe a tablet, and Rin'ji's chain reaches its end. After Rin'ji's Secret, you carry the tablet to Oran Snakewrithe. You place it in his hands.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8273-2d74a74f01c435481d40/1-0000.mp3", duration = 13.2179592, start = 0},
  },
}
P.transport["quest:8312"] = {
  hash = "9c907b",
  fullHash = "9c907b",
  text = "Hallow's End Treats for Spoops!. For Hallow's End Treats for Spoops!, an ailing child asks travelers to gather holiday sweets. Innkeepers in the cities and Kali Remik in Sen'jin Village share treats, and Spoops offers magical candy in return. Spoops is too ill to join Hallow's End outdoors. While others celebrate, Spoops asks travelers to gather holiday treats. In return, Spoops offers candy that changes whoever eats it into strange shapes. Travelers can find holiday treats in settlements across the realm. Innkeepers in major cities ask visitors to perform tricks before sharing their sweets. Kali Remik also gives out treats in Sen'jin Village on the coast of Durotar.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8312-1b1c024ae1b4f8700838/1-0000.mp3", duration = 42.9453061, start = 0},
  },
}
P.transport["quest:836"] = {
  hash = "a5ad91",
  fullHash = "a5ad91",
  text = "Rescue OOX-09/HL!. Beyond Overlook Cliff, OOX-09/HL needs your help reaching the shore. Oglethorpe Obnoticus speaks through the fallen robot and asks you to escort it there. He waits in Booty Bay afterward. Oglethorpe's voice crackles from the robot again. OOX-09/HL needs an open, safe place for its lengthy take-off procedure, and the shoreline beyond Overlook Cliff will do. Its built-in cloaking cannot yet be used. Oglethorpe needs time to make it work again. When OOX-09/HL reaches the shore safely, Oglethorpe Obnoticus asks you to speak with him in Booty Bay.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_836-eca6deda360d34d99de6/1-0000.mp3", duration = 35.5265306, start = 0},
  },
}
P.transport["quest:841"] = {
  hash = "024d0f",
  fullHash = "024d0f",
  text = "Another Power Source?. In Gadgetzan, Chief Engineer Bilgewhizzle offers you another power source for ten Wastewander Water Pouches. Chief Engineer Bilgewhizzle believes the first power source ran out of time or was lost in the sand. Whatever happened, he has another one to sell you. Times are tough all around, so he asks for ten Wastewander Water Pouches.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_841-90db6178efc73f749532/1-0000.mp3", duration = 24.1110204, start = 0},
  },
}
P.transport["quest:847"] = {
  hash = "3487f8",
  fullHash = "3487f8",
  text = "Guile of the Raptor. Tor'gan's orb has filled Gor'mul with a raptor's essence. The power makes him wonder about shaman magic, and he will hear Tor'gan out for now. Power runs through Gor'mul, and he wonders if it is the shamans' power Tor'gan tried to show him. The thought interests him. So he asks you to tell Tor'gan he is convinced for now and will hear what Tor'gan has to say.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_847-a459b9a1273e35a15b36/1-0000.mp3", duration = 26.8016327, start = 0},
  },
}
P.transport["quest:8551"] = {
  hash = "f44169",
  fullHash = "f44169",
  text = "The Captain's Chest. Smotts' lost chest lies with a sea giant after a wreck near Booty Bay. Captain Hecklebury Smotts once sailed between Booty Bay and Ratchet in Kalimdor. Sea giants wrecked his ship and killed the crew, then sent him toward Booty Bay in a lifeboat. Gorlash took his Captain's Chest, and now Smotts wants it back. Captain Hecklebury Smotts once sailed between Booty Bay and Ratchet in Kalimdor, and earned a fine reputation. Then sea giants smashed his ship and killed the crew. They sent Smotts toward Booty Bay in a lifeboat, and he left his voyages and good name behind. Gorlash took Smotts' Captain's Chest, saying he wanted it for a snuffbox. The chest was Smotts' favorite, and a secret compartment held his greatest treasures. Smotts has heard that Gorlash roams the shore east of Booty Bay.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8551-2a9ab69205ee98792670/1-0000.mp3", duration = 50.9387755, start = 0},
  },
}
P.transport["quest:8552"] = {
  hash = "2349b8",
  fullHash = "2349b8",
  text = "The Monogrammed Sash. In Stranglethorn Vale, a lost sash bears initials that may lead to its owner. Finding the seafarer who lost it leads on to The Captain's Cutlass. You find a fine sash with the initials HS embroidered along its hem. Those two letters are the only clue to who lost it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8552-e0d9d5271db6850f73dc/1-0000.mp3", duration = 18.8604082, start = 0},
  },
}
P.transport["quest:8553"] = {
  hash = "2237ce",
  fullHash = "2237ce",
  text = "The Captain's Cutlass. Aboard Smotts' Revenge, Captain Hecklebury Smotts faces defeat at sea once more. Sea giants smash his second ship, kill its crew, and take his cutlass. He sends you to Sprogger, his former cook, to find the behemoth. After losing his first ship, Captain Hecklebury Smotts bought another and named it Smotts' Revenge. He gathered a new crew and provisions to hunt the sea giants who took his first vessel. The giants smashed the ship and killed the crew. Once more, Smotts was left adrift in a lifeboat, and Negolash took his cutlass in the attack. Captain Hecklebury Smotts wants his stolen cutlass back, so he turns to Sprogger. Sprogger was the cook aboard Smotts' Revenge and survived the attack. He can help you track down Negolash.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8553-42cf993720025485407d/1-0000.mp3", duration = 52.4538776, start = 0},
  },
}
P.transport["quest:8555"] = {
  hash = "fe758f",
  fullHash = "fe758f",
  text = "The Charge of the Dragonflights. In Tanaris, Anachronos meets you as the first part of the Scepter of the Shifting Sands draws to a close. The chain leads toward the opening of the Gates of Ahn'Qiraj. Anachronos meets you in Tanaris to close the first part of the Scepter of the Shifting Sands. The chain leads toward the opening of the Gates of Ahn'Qiraj.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8555-64e3254d4abd969f8926/1-0000.mp3", duration = 24.9208163, start = 0},
  },
}
P.transport["quest:8576"] = {
  hash = "de448e",
  fullHash = "de448e",
  text = "Translating the Ledger. You bring Azuregos's ledger to Narain Soothfancy, who must decipher its writing. What he finds may bring you closer to opening the Gates of Ahn'Qiraj. Azuregos's ledger is in your hands, and Narain Soothfancy must decipher it. You bring the ledger to him so he can learn what Azuregos wrote.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8576-fac744e458b131885db2/1-0000.mp3", duration = 21.3420408, start = 0},
  },
}
P.transport["quest:8577"] = {
  hash = "b95ebd",
  fullHash = "b95ebd",
  text = "Stewvul, Ex-B.F.F.. Narain cannot translate anything without the scrying goggles. Stewvul, Ex-B.F.F., has them, and you need to bring them back. Narain Soothfancy cannot translate anything without the scrying goggles. Stewvul was once Narain's best friend forever, but stole them a while ago. Then Stewvul broke Narain's heart in five places and abandoned Narain here. Narain's crystal ball points to two places where Stewvul might be. One is the Greymane Wall in Silverpine. The other lies beyond a portal. You need to find Stewvul and bring back the goggles.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8577-c6903c8ca0f5921063e1/1-0000.mp3", duration = 36.4146939, start = 0},
  },
}
P.transport["quest:8584"] = {
  hash = "157521",
  fullHash = "157521",
  text = "Never Ask Me About My Business. Narain Soothfancy sends you to Gadgetzan to find a chicken weighing five hundred pounds. At the inn, Dirge Quikcleave can point you toward one. Narain Soothfancy wants no more questions about his business. It deals in things beyond your understanding, so he keeps the plan to himself and leaves the fetching to you. He needs a chicken weighing five hundred pounds. Dirge Quikcleave at the Gadgetzan inn can point you toward one.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8584-c8888c5e758637eaef2c/1-0000.mp3", duration = 26.88, start = 0},
  },
}
P.transport["quest:8586"] = {
  hash = "fea619",
  fullHash = "fea619",
  text = "Dirge's Kickin' Chimaerok Chops. In Gadgetzan, Dirge Quikcleave has his recipe ready, but the meat needs attention soon. He asks you for twenty Goblin Rocket Fuel and twenty Deeprock Salt before it spoils. Dirge Quikcleave handles the spices himself, while the meat you brought him makes up the rest of the dish. He still needs twenty Goblin Rocket Fuel and twenty Deeprock Salt. With both in hand, the chicken can go back to Narain Soothfancy. Dirge urges you to hurry before the meat goes bad.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8586-0597d5158c099e5f0551/1-0000.mp3", duration = 30.0930612, start = 0},
  },
}
P.transport["quest:8587"] = {
  hash = "f06adb",
  fullHash = "f06adb",
  text = "Return to Narain. Dirge Quikcleave keeps his word, and you carry his five-hundred-pound chicken to Narain Soothfancy in Tanaris. Dirge's Kickin' Chimaerok Chops came before this delivery. Dirge Quikcleave hands over the chicken he promised. A goblin keeps his word, he says. He cannot guess why a gnome wants a bird that size, and grumbles that it must be for sleeping in. From there, you carry the chicken to Narain Soothfancy in Tanaris.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8587-26d45a4f380550511606/1-0000.mp3", duration = 29.204898, start = 0},
  },
}
P.transport["quest:8597"] = {
  hash = "fc0e60",
  fullHash = "fc0e60",
  text = "Draconic for Dummies. Narain Soothfancy wants you to find the book he hid on an island in the South Seas. First, find his crashed gyrocopter on Land's End Beach, then swim south. This follows Translating the Ledger. Narain Soothfancy says the book will come in handy, and he hid it where no one could hope to find it. He took a gyrocopter to reach the hiding place, then crashed on the beach on his way back. Narain says the crash gave him his super-gnomish psychic powers.\n\nThe wreck lies somewhere along Land's End Beach. From there, swim south. Narain is sure you will recognise the place at a glance. The book lies buried on an island in the South Seas.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8597-08628800210acb174047/1-0000.mp3", duration = 45.9493878, start = 0},
  },
}
P.transport["quest:8598"] = {
  hash = "ee5d49",
  fullHash = "ee5d49",
  text = "rAnS0m. At the freshly dug dirt in Tanaris, Narain Soothfancy’s book is gone, and a ransom note waits in its place. You carry the letter back to Narain after searching for the book in Draconic for Dummies. Made from scraps of type, the ransom note tells Narain Soothfancy that its writers have his precious book. They call him a gnome and promise he will see it again only if he follows their orders exactly. Three pages give detailed instructions, ending with a demand that he bring the money and come alone. You carry the letter to Narain in Tanaris.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8598-d68b8e05532376629be7/1-0000.mp3", duration = 39.2097959, start = 0},
  },
}
P.transport["quest:8599"] = {
  hash = "da5e06",
  fullHash = "da5e06",
  text = "Love Song for Narain. Meridith sends her love to Narain Soothfancy, and you carry her letter to him in Tanaris. She rescued the gnome from a crashed flying machine and asks you to seek his book, Draconic for Dummies. Meridith the Mermaiden seldom has visitors. Her last was the gnome she rescued from a crashed flying machine. The memory takes her gaze far away for a moment. Then she asks if you know Narain Soothfancy. She needs to tell him how she feels, and she is sure it is love. Meridith begs you to carry her message to him and promises to be forever in your debt.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8599-1739c963969bdb19b63f/1-0000.mp3", duration = 35.4220408, start = 0},
  },
}
P.transport["quest:8606"] = {
  hash = "a58800",
  fullHash = "a58800",
  text = "Decoy!. At the Winterspring handover, Narain Soothfancy means to deliver the ransom after a fashion. You carry Narain's disguise to the spot the booknappers named, following the ransom letter. The ransom note said Narain should make the delivery himself. He plans to do so after a fashion, and chooses you for the part. His special kit holds a turban, a robe, and a sack filled with rocks. You carry the disguise to the handover spot the booknappers named in Winterspring. When they arrive for the goods, Narain wants them snuffed out as a lesson in what comes of crossing him.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8606-27c21a66da67192d55cd/1-0000.mp3", duration = 43.6244898, start = 0},
  },
}
P.transport["quest:8682"] = {
  hash = "7c166d",
  fullHash = "7c166d",
  text = "Skyseer the Elder. During the Lunar Festival, Skyseer the Elder waits atop Freewind Post in Thousand Needles. Travelers come to honor the ancestors and receive his blessing. Wooden bluffs tower over Freewind Post. Elder Skyseer rests among them in a shaft of celestial light, near the bridges leading to the great mechanical lifts. Winds sweep across the mesas of Thousand Needles around his ghostly form. During the Lunar Festival, Elder Skyseer welcomes travelers who come to honor the past. He can guide them to his kin across Kalimdor, including Elder Morningdew and Elder Runetotem.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8682-8e75aa14b4765d632f69/1-0000.mp3", duration = 43.9902041, start = 0},
  },
}
P.transport["quest:8724"] = {
  hash = "b5c4be",
  fullHash = "b5c4be",
  text = "Morningdew the Elder. In Thousand Needles, pilgrims seek Morningdew the Elder beneath a beam of starlight during the Lunar Festival. She offers wisdom and directions to elders across Kalimdor. During the Lunar Festival, ancient ancestor spirits appear across Azeroth to bless travelers. In Thousand Needles, Morningdew the Elder stands beneath a shaft of lunar light, amid red stone and industrial noise. She urges mortal travelers to turn from earthly concerns and look to the stars. Morningdew points seekers toward the countless stars for answers to earthly mysteries. She also guides festival pilgrims to other honored spirits across the lands: Elder High Mountain, Elder Grimtotem, Elder Mistwalker, Elder Moonwarden, and Elder Windtotem.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8724-e3754e7dfcf55c6d7535/1-0000.mp3", duration = 48.9273469, start = 0},
  },
}
P.transport["quest:8728"] = {
  hash = "13eb62",
  fullHash = "13eb62",
  text = "The Good News and The Bad News. Narain Soothfancy has read the ledger and found good news and bad. He is nearly certain he can build the arcanite buoy you specified, but needs arcanite, elementium ore, and fine gems. The chicken, the goggles, and the second Draconic For Dummies book must all be done first. Narain Soothfancy studies the ledger and murmurs under his breath. He is ninety-nine percent sure he can build the arcanite buoy to your specifications. The materials are the bad news. He asks for twenty arcanite bars, ten elementium ore, ten Azerothian diamonds, and ten blue sapphires. Bring them, and he will craft the buoy.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8728-26fbf48a594bc67e823a/1-0000.mp3", duration = 41.0383673, start = 0},
  },
}
P.transport["quest:8742"] = {
  hash = "282dae",
  fullHash = "282dae",
  text = "The Might of Kalimdor. In Tanaris, Anachronos greets you in The Might of Kalimdor as the champion fate has awaited for a thousand years. He sees you leading your people into a new age. The Blue, Green and Red Scepter Shard forks are complete, bringing the Scepter of the Shifting Sands to its end. Anachronos speaks of a fate a thousand years in the making. The Old God trembles at your coming and fears your faith. Anachronos urges you to break C'Thun's prophecy, and you bring Kalimdor's strength with you. When you are ready, tell Anachronos, and he will place the Scepter of the Shifting Sands in your hands.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8742-f442e5010ee67092a132/1-0000.mp3", duration = 44.4865306, start = 0},
  },
}
P.transport["quest:88756"] = {
  hash = "44d80b",
  fullHash = "44d80b",
  text = "Bring Back a Bang. A construction site has lost blasting powder to Dark Iron dwarves camped east on Direforge Hill. Their marked barrels could bring danger to the surrounding lands. Dark Iron dwarves camp east on Direforge Hill. They raided a nearby construction site and carried its vital blasting powder back to their tents. Blasting powder in malicious Dark Iron hands threatens the surrounding lands. The stolen barrels bear red markings that set them apart from common supplies. Recover them before the dwarves put the powder to destructive use.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_88756-8c776ef6fffc4d5e012b/1-0000.mp3", duration = 35.2130612, start = 0},
  },
}
P.transport["quest:8921"] = {
  hash = "51db39",
  fullHash = "51db39",
  text = "The Ectoplasmic Distiller. In Gadgetzan, Mux Manascrambler lacks the funds and help to finish his extra-dimensional ghost revealer. He asks you for costly materials and forty gold to build its first piece, an ectoplasmic distiller. Mux Manascrambler welcomes your help with his ghost revealer, a machine meant to reach across dimensions. First, he needs a distiller to gather the fabric of death itself. Building it will be difficult. Mux asks for one delicate arcanite converter, four greater eternal essences, ten stonescale oil, twenty-five volcanic ash, and forty gold.\n\nThe volcanic ash must come from the lava pools of the Burning Steppes. It will make the distiller's filter. The materials are costly, but Mux says he needs every one.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8921-e5f919a3b886ceae8aaa/1-0000.mp3", duration = 47.0987755, start = 0},
  },
}
P.transport["quest:8922"] = {
  hash = "275427",
  fullHash = "275427",
  text = "A Supernatural Device. Deliana needs a way to speak with Anthion Harmon's ghost. You carry the collected blood to an engineer in Gadgetzan as payment for a device that speaks with the dead. Deliana seeks a way to reach Anthion Harmon, or rather his ghost. She has Mux Manascrambler in mind, an engineer who claims to have a machine for speaking with the dead. The blood you collected was meant for him all along. Carry it to Mux in Gadgetzan, in Tanaris, and give it to him for his services.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8922-726670d3a6a21f1fb917/1-0000.mp3", duration = 36.2318367, start = 0},
  },
}
P.transport["quest:8923"] = {
  hash = "944846",
  fullHash = "944846",
  text = "A Supernatural Device. In Gadgetzan, Mokvar sends you with venom for an engineer studying the dead. Mux Manascrambler is building a device to speak with them, and Mokvar hopes it can reach Anthion. Mokvar says you have shown courage by staying on, and more armor awaits those still willing to help. The venom you gathered is for Mux Manascrambler, an engineer who studies the supernatural and knows Mokvar. Mux is building a device to speak with the dead. Mokvar hopes it can reach Anthion and reveal more about his own situation. Carry the sealed container to Mux in Gadgetzan, in Tanaris.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8923-17736b41809661168326/1-0000.mp3", duration = 43.9902041, start = 0},
  },
}
P.transport["quest:8924"] = {
  hash = "3fd299",
  fullHash = "3fd299",
  text = "Hunting for Ectoplasm. Mux Manascrambler in Gadgetzan has his distiller ready, and now needs ectoplasm. You carry it to Silithus, Winterspring and the Eastern Plaguelands, gathering twelve of each kind from the incorporeal dead. This follows The Ectoplasmic Distiller. Mux Manascrambler is proud of his distiller, but the incorporeal dead are far from Gadgetzan. He believes climate changes the spectral fabric of the dead. In Silithus, tortured night elves yield scorched ectoplasm. In Winterspring, spirits of the highborne yield frozen ectoplasm.\n\nGhosts and banshees in the Eastern Plaguelands yield stable ectoplasm. Gather twelve of each kind. Mux says to set the distiller down nearby before harvesting, then bring it and the ectoplasm back to Gadgetzan.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8924-ab3ac7c254ba6db5fae2/1-0000.mp3", duration = 61.6228571, start = 0},
  },
}
P.transport["quest:8925"] = {
  hash = "52720f",
  fullHash = "52720f",
  text = "A Portable Power Source. Mux Manascrambler needs steady power for his ectoplasm. Rumour points to Magma Lord Bokk in the Burning Steppes, whose heart is a Magma Core, and Mux asks you to bring it to Gadgetzan. Mux Manascrambler needs power he can carry to keep the ectoplasm active. Rumour says Magma Lord Bokk, a mighty elemental, has a Magma Core for a heart. Its heat never ends. Bokk is said to dwell in the Burning Steppes, south of Blackrock Mountain and west of the Pillar of Ash. Mux wants you to bring the core to Gadgetzan to run his extra-dimensional ghost revealer.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8925-d6d8dd6f71c8777a5bb1/1-0000.mp3", duration = 36.4146939, start = 0},
  },
}
P.transport["quest:8928"] = {
  hash = "a6341b",
  fullHash = "a6341b",
  text = "A Shifty Merchant. In Gadgetzan, Mux Manascrambler has a core for his device but still needs a rod to carry its force without melting. He remembers an imp in Winterspring who offered an elemental rod, and regrets not buying it. You find the imp in a cave at Darkwhisper Gorge’s entrance and buy the Fel Elemental Rod. Mux Manascrambler has the core for his device, but still needs a rod that can carry its force without melting. After A Portable Power Source, he recalls an elemental rod an imp was selling in Winterspring. Mux regrets not buying it then.\n\nThe imp is in a cave at the entrance to Darkwhisper Gorge in southern Winterspring. You buy the Fel Elemental Rod and bring it to Mux in Gadgetzan. He says the imp quoted him forty gold and insists you pay no more.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8928-f2ce9b732ec6d88816c0/1-0000.mp3", duration = 48.5877551, start = 0},
  },
}
P.transport["quest:92432"] = {
  hash = "b51abc",
  fullHash = "b51abc",
  text = "An Alarming Request. In Southshore, Emissary Jacques warns that Dalaran is in danger. Its ley lines are disrupted, and its constructs have turned erratic and destructive. Archmage Modera sent Jacques to seek outside aid. You are to find her image beside Lordamere Lake, near Dalaran. Emissary Jacques brings troubling news from Dalaran. The city's ley lines are disrupted, and its constructs have turned erratic and destructive. No one knows why.\n\nThe high council ordered the matter kept private to spare the order shame. But Jacques says the charade cannot last while the city is being overrun. Jacques was sent by Archmage Modera to seek outside aid. You are to find her image beside Lordamere Lake, near Dalaran.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92432-341f27620b947d1db73f/1-0000.mp3", duration = 53.1330612, start = 0},
  },
}
P.transport["quest:92434"] = {
  hash = "569c34",
  fullHash = "569c34",
  text = "Blood in the Streets. Turmoil grips Dalaran after its barrier comes down. Once the patrols are dealt with, Magus Wordeen Voidglare sees a chance for the Horde to enter and learn the mages' secrets. You carry a key from the internment camp to the sewers on the city's northern edge. With the patrols dealt with, Magus Wordeen Voidglare says turmoil grips Dalaran since its barrier came down. He urges the Horde to enter and learn the mages' secrets while they can. You carry the key from the internment camp to the sewers on Dalaran's northern edge, by Lordamere Lake. Perhaps the mages left that disagreeable entrance unwarded.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92434-b388e0b68c8d4d9a6389/1-0000.mp3", duration = 41.2473469, start = 0},
  },
}
P.transport["quest:92456"] = {
  hash = "d7c6e2",
  fullHash = "d7c6e2",
  text = "A Green Sample. In Stormwind City, Shylamiir seeks a living plant from Dalaran’s guarded garden. The cutting is wanted for study of mana-fed growth, but it brings back a darker surprise. Shylamiir in Stormwind City seeks a traveler willing to enter restricted lands. The Kirin Tor’s interest in botany has caught Shylamiir’s attention, and a living plant from Dalaran’s central garden is wanted for study. The secluded sorcerers keep their borders closed to outsiders. Reaching the garden calls for someone able to slip past their defenses.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92456-ff7454bb0e67c5c6f7ff/1-0000.mp3", duration = 39.0530612, start = 0},
  },
}
P.transport["quest:92459"] = {
  hash = "000e73",
  fullHash = "000e73",
  text = "Friend of the Kirin Tor. In Dalaran, Modera sends you to carry word that the city is calming and its wards may come down. The Image of Archmage Modera says the council may dislike the subterfuge, but the results are plain. Dalaran is calming, and its wards may now be lowered. She sends you with this good word to Archmage Celindra in the Violet Citadel. For the journey, she gives you an arcane mote.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92459-5c212ea7930ca896a1ed/1-0000.mp3", duration = 27.8204082, start = 0},
  },
}
P.transport["quest:92519"] = {
  hash = "d0ac62",
  fullHash = "d0ac62",
  text = "Ward Restocking. At Hammerfall, Doctor Gregory Victor is short of remedies, antidotes, and elixirs for the infirmary. The missing tonics are at Go'Shek Farm. Doctor Gregory Victor tends Hammerfall’s wounded and ailing in the medical ward. The nearby Forsaken apothecary usually supplies the infirmary with remedies, antidotes, and elixirs. When those deliveries stop, Victor turns to capable travelers to keep the clinic stocked. Apothecary Jorell works in a cramped shack at Go'Shek Farm, south and west of Hammerfall. Doctor Victor says Jorell is often absent. The eccentric Forsaken chemist may neglect his duties or succumb to his own noxious concoctions. Couriers sent for the packaged tonics should find the medicine waiting, whether Jorell is there or not.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92519-5c4e6a879621c29847f9/1-0000.mp3", duration = 54.0473469, start = 0},
  },
}
P.transport["quest:93680"] = {
  hash = "bb9d2c",
  fullHash = "bb9d2c",
  text = "Key to the City. Wordeen seeks a way into Dalaran, now rebuilt on the Dark Lady’s doorstep. In Tarren Mill, Magus Wordeen Voidglare wants to learn more about the Kirin Tor. Their city, Dalaran, fell to the demonic Burning Legion in a single stroke from the arch demon Archimonde. The surviving mages became dispossessed vagabonds. Now they have rebuilt Dalaran on the Dark Lady’s very doorstep.\n\nWordeen sends you to search their camps. He hopes you will find an ancient tome, a secret relic, or something else that can get the Horde into the city unnoticed. What you bring back is a grimy Dalaran sewer key.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_93680-2e08ad08f40c60f5772f/1-0000.mp3", duration = 47.5167347, start = 0},
  },
}
P.transport["quest:96988"] = {
  hash = "7bb378",
  fullHash = "7bb378",
  text = "Source of Power. In Dalaran, rogue constructs have turned on their makers, and Doctor Martin Felben sees a chance for the Forsaken. He wants their arcane cores for his work in Undercity and hopes to catch the Dark Lady’s eye. Dalaran’s rogue arcane constructs are laying siege to the magi, and the Forsaken are eager to exploit the city’s turmoil. Doctor Martin Felben, an apothecary in Undercity, seeks to scavenge the cores that power the sentries rather than aid the besieged sorcerers. Dalaran has long guarded its magical research, but its vulnerable sentries now offer an opening to opportunistic researchers. Doctor Felben wants the cracked sentry cores to advance his standing within the Royal Apothecary Society. He hopes to infuse Forsaken abominations with volatile Dalaran construct magic and raise a devastating army of arcane-powered flesh beasts. Such a breakthrough, he believes, would win Lady Sylvanas Windrunner’s undivided attention and show his alchemical genius. He hopes to rise in the Society, where ruthless cunning and potent results dictate survival and rank.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_96988-b3005a79737bed83145b/1-0000.mp3", duration = 76.6693878, start = 0},
  },
}
P.transport["quest:97287"] = {
  hash = "52b78b",
  fullHash = "52b78b",
  text = "Shrewd Negotiations. After your infiltration of the mages' city, Magus Wordeen Voidglare sends you to Dalaran. Carry the arcane mote to Archmage Celindra; Wordeen believes the Kirin Tor will give anything to recover it. Magus Wordeen Voidglare says no order on Azeroth matches the Kirin Tor in arcane knowledge. Even his brilliant work pales beside their ancient wisdom. He believes the Horde should gain access to their exclusive order. So he sends you to Archmage Celindra in Dalaran with the mote you acquired. Wordeen believes the Kirin Tor will give anything to get it back.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_97287-456e2b562563fbbe4f84/1-0000.mp3", duration = 43.1804082, start = 0},
  },
}
P.transport["quest:97539"] = {
  hash = "1946dc",
  fullHash = "1946dc",
  text = "Silky Sutures. At Hammerfall, Doctor Gregory Victor is turning to spider silk as infirmary supplies dwindle. Siege damage remains unrepaired, and the outpost's guards and laborers still need care. Hammerfall endures in the Arathi Highlands, though siege damage still mars its defenses. Doctor Gregory Victor, the outpost's physician, sees the neglect as official policy. With little support and crumbling fortifications around him, he keeps the infirmary running. Its care helps laborers and sentinel guards stay on their feet and ready for conflict. Medical supplies are running low at Hammerfall, so Doctor Victor seeks another way to stitch wounds. Tough highland spider silk can be twisted into resilient sutures when bandages and ordinary thread are scarce. Victor jokes that infection is the least of a wounded soldier's worries. The silk gives the infirmary thread to patch up defenders in hostile territory. Doctor Gregory Victor greets travelers with dry jokes about grave prognoses and stitches made from spider silk. His humor masks the hard truth of running a frontline clinic while Hammerfall remains isolated. Regular aid is rare in the highlands, and travelers can help keep the clinic supplied. Victor relies on improvised remedies and determination to care for the wounded as the outpost decays around him.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_97539-5a253e376aca124bddd2/1-0000.mp3", duration = 93.7012245, start = 0},
  },
}
P.transport["quest:98248"] = {
  hash = "106e41",
  fullHash = "106e41",
  text = "Shipping Label. A torn manifest points couriers toward Durotar Supply and Logistics in the Barrens. The company depends on travelers to recover lost crates and return paperwork to its post west of the Crossroads, keeping supplies and trade moving across central Kalimdor. A torn manifest is fixed to a freshly restocked cargo crate. Its recipient's name has worn away, but the heading names Durotar Supply and Logistics, a freight company in Horde territory. Beside the writing, a rough map points couriers toward the company's staging grounds in the central plains. The notice welcomes travelers bringing stray containers, damaged goods, or proof of salvage to the trade outpost west of the Crossroads. Durotar Supply and Logistics depends on independent haulers to recover scattered freight across the Barrens. Those who help keep regional supplies moving receive compensation.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98248-278c031519eea426f234/1-0000.mp3", duration = 56.3461224, start = 0},
  },
}
P.transport["quest:98297"] = {
  hash = "e99774",
  fullHash = "e99774",
  text = "Stopping the Cycle. At the Dragonmaw Gates, warlocks are trying to enslave a red dragonspawn. Howin Kindfeather returns from a test flight with troubling news, and the Wildhammer will not let it happen again. Howin Kindfeather asks you to face the subdued dragonspawn at the Dragonmaw Gates. First, kill the warlocks holding it down. That should free it. Then put the dragonspawn out of its misery. Howin expects you to bring friends, for the Wildhammer will not let the Dragonmaw stand in their way.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98297-d883b5040813c1eb6d98/1-0000.mp3", duration = 32.8359184, start = 0},
  },
}
P.transport["quest:98895"] = {
  hash = "699096",
  fullHash = "699096",
  text = "Darkspear Islands Clash. Across the Darkspear Islands, Alliance forces are hard pressed. Without help at the front, they risk losing the whole archipelago to the fierce Darkspear Raiders. Open war now rages across the Darkspear Islands between the Alliance and the aggressive Darkspear Raiders. Alliance commanders fear their foothold in the archipelago will be overwhelmed without urgent reinforcements. So they call capable champions to the front to stem the attack. Alliance commanders need proven fighters willing to serve on the front lines. Warriors bring back Darkspear Islands Marks of Honor as proof of their service. The marks uphold discipline and honor those whose courage turns the battle.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98895-a49bf60e1f6de5474ec3/1-0000.mp3", duration = 46.9159184, start = 0},
  },
}
P.transport["quest:98896"] = {
  hash = "264223",
  fullHash = "264223",
  text = "Darkspear Islands Clash. Fighting rages across the Darkspear Islands Clash as Darkspear Raiders contest the archipelago. Fighters are called to rally their companions and stop enemy incursions across the islands. Darkspear Raiders skirmish across the beaches and interior of the islands. Forces sent there are urged to hold their ground as the campaign to secure a foothold in the archipelago continues. Commanders on the front line call for fighters to gather against the resilient raiders. Survival and victory depend on rallying nearby allies into a force that can withstand counterattacks. Together, they can rout fortified raiding bands and break their hold on the disputed island strongholds.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98896-4b315a6780cb0ae8c564/1-0000.mp3", duration = 49.5804082, start = 0},
  },
}
P.transport["quest:992"] = {
  hash = "b29eb3",
  fullHash = "b29eb3",
  text = "Gadgetzan Water Survey. Gadgetzan needs water, and Senior Surveyor Fizzledowser is searching the desert for a new source. The Gadgetzan Water Company has lost every well to the nomads, so Fizzledowser hires you to sample a pool near Sandsorrow Watch. The Gadgetzan Water Company has lost every well to the nomads. Now Senior Surveyor Fizzledowser hopes to find other free sources in the desert, but the search calls for a survey. The company needs a temporary junior-grade surveyor to help. Fizzledowser gives you an untapped dowsing widget and sends you to the pool near Sandsorrow Watch. It lies due west of Gadgetzan and south of Zul'Farrak, within view of nearby trolls. Use the widget to tap a water sample, then return it to Fizzledowser.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_992-9ebae2543e3b688c3970/1-0000.mp3", duration = 46.8897959, start = 0},
  },
}
